INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C1','math',5,2,'u2',2,'같은 수를 여러 번 더하기 — 분모가 같은 분수의 덧셈·뺄셈과 약분(기약분수)을 되짚고, 같은 분수를 여러 번 더하는 자리를 (분수)×(자연수)로 적으면 몇 번을 더하든 한 줄로 끝남을 알기',ARRAY['6수01-09']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C2','math',5,2,'u2',2,'(진분수)×(자연수) — 수직선에서 같은 분수씩 뛰어 세어 보고, 분모는 그대로 두고 분자와 자연수를 곱하며(한 칸의 크기는 그대로, 칸의 수만 늘어남) 약분은 곱하기 전·중·후 언제 해도 값이 같음을 알기',ARRAY['6수01-09']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C3','math',5,2,'u2',3,'(대분수)×(자연수) — 대분수를 자연수 부분과 진분수 부분으로 갈라 각각 곱해 더하거나, 가분수로 고쳐 분자와 자연수를 곱하고, 가분수로 고치기 전에 약분하면 자연수 부분이 빠져 틀림을 알기',ARRAY['6수01-09']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C4','math',5,2,'u2',4,'(자연수)×(진분수) — 「6의 ⟨2/3⟩」처럼 전체를 분모만큼 똑같이 나눈 것 중의 분자만큼을 구하는 곱셈임을 알고, 분모는 그대로 두고 자연수와 분자를 곱하며 ⟨3/5⟩ × 2와 2 × ⟨3/5⟩은 뜻은 달라도 값은 같음을 알기',ARRAY['6수01-09']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C5','math',5,2,'u2',5,'(자연수)×(대분수) — 직사각형을 둘로 갈라 더하거나 가분수로 고쳐 계산하고, 곱하는 수가 1보다 작으면 결과가 작아지고 1이면 그대로, 1보다 커야 커짐을 계산 전에 어림하기',ARRAY['6수01-09']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C6','math',5,2,'u2',6,'(진분수)×(진분수) — 전체를 가로·세로로 잘라 (분모×분모) 칸 가운데 (분자×분자) 칸임을 그림으로 알고, 분모는 분모끼리·분자는 분자끼리 곱하며 약분은 분자와 분모 사이에서만 함을 알기',ARRAY['6수01-09']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C7','math',5,2,'u2',7,'대분수끼리·세 분수의 곱셈 — 대분수는 가분수로 고치고 자연수는 분모가 1인 분수로 보아 분수가 몇 개든 분모끼리·분자끼리 곱하는 한 규칙으로 계산하고, 곱하는 순서를 바꾸어도 값이 같음을 알기',ARRAY['6수01-09']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u2-C8','math',5,2,'u2',8,'문제 해결 — 「전체의 몇 분의 몇 이상」 문제에서 없는 정보(전체 수)를 먼저 찾고, 최소로 필요한 수를 곱셈으로 구한 뒤 지금까지의 수를 빼서 더 필요한 수를 구하기',ARRAY['6수01-09']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X01','math',5,'u2',ARRAY['M5-2-u2-C2','M5-2-u2-C3','M5-2-u2-C4','M5-2-u2-C5']::text[],'(분수)×(자연수)에서 분모에도 자연수를 곱한다(⟨2/5⟩ × 4를 ⟨8/20⟩으로)','분모는 그대로 — 한 칸 크기는 안 변해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X02','math',5,'u2',ARRAY['M5-2-u2-C2','M5-2-u2-C4']::text[],'자연수를 분자가 아니라 분모에 곱한다(⟨2/5⟩ × 4를 ⟨2/20⟩으로)','자연수는 분자와 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X03','math',5,'u2',ARRAY['M5-2-u2-C1','M5-2-u2-C2']::text[],'같은 분수를 여러 번 더할 때 분모끼리도 더한다(⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩을 ⟨9/30⟩으로)','분모가 같으면 분자끼리만 더해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X04','math',5,'u2',ARRAY['M5-2-u2-C3','M5-2-u2-C5','M5-2-u2-C7']::text[],'대분수를 가분수로 잘못 고친다(자연수와 분자를 더하거나 곱하고 분모를 곱하지 않는다)','자연수 × 분모 + 분자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X05','math',5,'u2',ARRAY['M5-2-u2-C3','M5-2-u2-C5']::text[],'대분수와 자연수를 곱할 때 자연수 부분에만 또는 분수 부분에만 곱한다(⟨1 1/4⟩ × 3을 ⟨3 1/4⟩이나 ⟨1 3/4⟩으로)','자연수 부분도 분수 부분도 모두 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X06','math',5,'u2',ARRAY['M5-2-u2-C3','M5-2-u2-C7']::text[],'대분수를 가분수로 고치지 않고 먼저 약분해 자연수 부분이 약분에서 빠진다','약분은 가분수로 고친 뒤에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X07','math',5,'u2',ARRAY['M5-2-u2-C4','M5-2-u2-C5','M5-2-u2-C8']::text[],'「전체의 몇 분의 몇」을 구할 때 분모로 나누기만 하거나 분자만 곱한다(6의 ⟨2/3⟩을 2나 12로)','분모만큼 나눈 것 중의 분자만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X08','math',5,'u2',ARRAY['M5-2-u2-C4','M5-2-u2-C5','M5-2-u2-C6']::text[],'곱하면 언제나 커진다고 여긴다(1보다 작은 수를 곱해도 커진다고 본다)','1보다 작은 수를 곱하면 작아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X09','math',5,'u2',ARRAY['M5-2-u2-C6','M5-2-u2-C7']::text[],'(분수)×(분수)에서 분모는 그대로 두고 분자끼리만 곱한다(⟨4/5⟩ × ⟨2/3⟩을 ⟨8/5⟩로)','분모도 분모끼리 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X10','math',5,'u2',ARRAY['M5-2-u2-C6','M5-2-u2-C7']::text[],'분수끼리 곱할 때 분모와 분자를 엇갈려 곱하거나 분모·분자끼리 더한다','분모는 분모끼리, 분자는 분자끼리 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X11','math',5,'u2',ARRAY['M5-2-u2-C7']::text[],'대분수끼리 곱할 때 자연수 부분끼리, 분수 부분끼리 따로 곱한다(⟨3 1/2⟩ × ⟨1 4/5⟩를 ⟨3 4/10⟩으로)','대분수는 둘 다 가분수로 고쳐서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X12','math',5,'u2',ARRAY['M5-2-u2-C1','M5-2-u2-C2','M5-2-u2-C3','M5-2-u2-C5','M5-2-u2-C6','M5-2-u2-C7']::text[],'계산 마무리 실수 — 약분하지 않거나 기약분수가 아닌데 멈추거나, 가분수·대분수를 잘못 고친다','끝까지 약분하고 대분수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X13','math',5,'u2',ARRAY['M5-2-u2-C2','M5-2-u2-C6','M5-2-u2-C7']::text[],'약분을 분자끼리 또는 분모끼리 한다(같은 쪽끼리 약분한다)','약분은 분자와 분모 사이에서만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X14','math',5,'u2',ARRAY['M5-2-u2-C7']::text[],'자연수를 분수로 볼 때 분모가 1인 분수로 보지 못한다(2를 ⟨2/2⟩로 본다)','자연수 2 = ⟨2/1⟩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X15','math',5,'u2',ARRAY['M5-2-u2-C1','M5-2-u2-C2','M5-2-u2-C3','M5-2-u2-C4','M5-2-u2-C5','M5-2-u2-C6','M5-2-u2-C7']::text[],'문장에서 곱셈식을 세우지 못하고 덧셈 등 다른 연산을 쓴다','「몇 번」「몇 분의 몇」은 곱셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X16','math',5,'u2',ARRAY['M5-2-u2-C8']::text[],'문제 해결에서 필요한 정보(전체 수)를 놓치거나, 최소로 필요한 수를 구한 뒤 빼지 않는다(순서를 거꾸로 한다)','① 최소 수 구하기 → ② 빼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X17','math',5,'u2',ARRAY['M5-2-u2-C1','M5-2-u2-C2','M5-2-u2-C3','M5-2-u2-C4','M5-2-u2-C5','M5-2-u2-C6','M5-2-u2-C7','M5-2-u2-C8']::text[],'묻는 말을 거꾸로 읽거나 놓친다 — 잘못된↔알맞은, 큰↔작은, 분자↔분모·자연수 부분','물음의 「잘못·가장·분모」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X18','math',5,'u2',ARRAY['M5-2-u2-C4','M5-2-u2-C6','M5-2-u2-C1']::text[],'기준(전체)을 바꿔 읽는다 — 1이 아닌 전체의 몇 분의 몇이나 부분의 부분을 1이나 앞의 부분을 기준으로 읽는다(2 × ⟨1/5⟩을 ⟨1/5⟩로, ⟨1/4⟩의 ⟨1/3⟩을 ⟨1/3⟩로)','무엇의 몇 분의 몇인지 — 전체를 기준으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X19','math',5,'u2',ARRAY['M5-2-u2-C6','M5-2-u2-C7','M5-2-u2-C8']::text[],'「나머지」 「남은 것의」를 구할 때 1에서 빼거나 남은 양을 먼저 구하지 않고 주어진 분수를 그대로 곱한다(버스로 간 ⟨5/6⟩을 걸어서 간 거리로 곱함)','나머지는 1 − (주어진 분수)부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X20','math',5,'u2',ARRAY['M5-2-u2-C3','M5-2-u2-C5','M5-2-u2-C7']::text[],'정사각형의 둘레(한 변 × 4)와 넓이(한 변 × 한 변)를 섞어 쓴다','둘레는 네 변의 합, 넓이는 한 변 × 한 변') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u2-X21','math',5,'u2',ARRAY['M5-2-u2-C7','M5-2-u2-C5','M5-2-u2-C4']::text[],'시간을 분수로 나타낼 때 1분 = 60초, 1시간 = 60분을 기준으로 하지 않는다(5분 30초를 ⟨5 3/10⟩분으로)','30초는 60초 중의 30 — ⟨1/2⟩분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_basic#1','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C1',1,'mc','auto','⟨5/30⟩를 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X12']::text[],true,'{"seq":1,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"⟨5/30⟩를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨6/1⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/7⟩","mis":"M5-2-u2-X12"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","5와 30을 모두 5로 나눌 수 있어요 — 5 ÷ 5 = 1, 30 ÷ 5 = 6.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨5/30⟩ = ⟨1/6⟩."],"variant_rule":{"alt":[{"stem":"⟨27/36⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨4/3⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X12"},{"t":"1","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","27과 36을 모두 9로 나눌 수 있어요 — 27 ÷ 9 = 3, 36 ÷ 9 = 4.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨27/36⟩ = ⟨3/4⟩."]},{"stem":"⟨56/70⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨5/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨2/3⟩","mis":"M5-2-u2-X12"},{"t":"1","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","56과 70을 모두 14로 나눌 수 있어요 — 56 ÷ 14 = 4, 70 ÷ 14 = 5.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨56/70⟩ = ⟨4/5⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_basic#2','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C1',1,'mc','auto','⟨3/7⟩ + ⟨6/7⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X03','M5-2-u2-X12']::text[],true,'{"seq":2,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"⟨3/7⟩ + ⟨6/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 2/7⟩","correct":true},{"t":"⟨9/14⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 3/7⟩","mis":"M5-2-u2-X12"},{"t":"⟨2 2/7⟩","mis":"M5-2-u2-X12"}],"explanation":["분모가 같은 분수의 덧셈은 분모를 그대로 두고 분자끼리 더해요.","⟨3/7⟩ + ⟨6/7⟩ = ⟨9/7⟩예요.","가분수를 대분수로 고치면 ⟨9/7⟩ = ⟨1 2/7⟩예요."],"variant_rule":{"alt":[{"stem":"⟨4/7⟩ + ⟨4/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 1/7⟩","correct":true},{"t":"⟨8/14⟩","mis":"M5-2-u2-X03"},{"t":"⟨1 2/7⟩","mis":"M5-2-u2-X12"},{"t":"⟨2 1/7⟩","mis":"M5-2-u2-X12"}],"explanation":["분모가 같은 분수의 덧셈은 분모를 그대로 두고 분자끼리 더해요.","⟨4/7⟩ + ⟨4/7⟩ = ⟨8/7⟩이에요.","가분수를 대분수로 고치면 ⟨8/7⟩ = ⟨1 1/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_basic#3','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C1',1,'mc','auto','불꽃 축제 장소까지 전체 1 km예요. 지금까지 ⟨4/5⟩ km를 걸어왔다면 남은 길은 몇 km인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X01','M5-2-u2-X12']::text[],true,'{"seq":3,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"불꽃 축제 장소까지 전체 1 km예요. 지금까지 ⟨4/5⟩ km를 걸어왔다면 남은 길은 몇 km인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨4/5⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/4⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/5⟩","mis":"M5-2-u2-X12"}],"explanation":["1은 ⟨5/5⟩와 같아요.","남은 길은 ⟨5/5⟩ − ⟨4/5⟩ = ⟨1/5⟩이에요.","분모가 같으면 뺄셈도 분자끼리 해요 — ⟨1/5⟩ km."],"variant_rule":{"alt":[{"stem":"진단 평가예요. 빨간색 리본의 길이는 ⟨4 5/11⟩ m이고, 노란색 리본은 빨간색 리본보다 ⟨1 7/11⟩ m 더 짧아요. 노란색 리본은 몇 m인가요?","options":[{"t":"⟨2 9/11⟩","correct":true},{"t":"⟨3 2/11⟩","mis":"M5-2-u2-X17"},{"t":"⟨6 1/11⟩","mis":"M5-2-u2-X15"},{"t":"⟨2 2/11⟩","mis":"M5-2-u2-X12"}],"explanation":["더 짧으니 뺄셈이에요 — ⟨4 5/11⟩ − ⟨1 7/11⟩.","분수 부분끼리 뺄 수 없으니 ⟨4 5/11⟩ = ⟨3 16/11⟩으로 바꾸어요.","⟨3 16/11⟩ − ⟨1 7/11⟩ = ⟨2 9/11⟩ — 노란색 리본은 ⟨2 9/11⟩ m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_basic#4','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C1',1,'mc','auto','⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩을 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X15']::text[],true,'{"seq":4,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩을 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨3/10⟩ × 3","correct":true},{"t":"⟨3/10⟩ × 4","mis":"M5-2-u2-X17"},{"t":"⟨3/10⟩ + 3","mis":"M5-2-u2-X15"},{"t":"3 × 3","mis":"M5-2-u2-X15"}],"explanation":["⟨3/10⟩을 3번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩ = ⟨3/10⟩ × 3이에요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩ + ⟨1/4⟩ + ⟨1/4⟩을 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨1/4⟩ × 3","correct":true},{"t":"⟨1/4⟩ × 4","mis":"M5-2-u2-X17"},{"t":"⟨1/4⟩ + 3","mis":"M5-2-u2-X15"},{"t":"1 × 3","mis":"M5-2-u2-X15"}],"explanation":["⟨1/4⟩을 3번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨1/4⟩ + ⟨1/4⟩ + ⟨1/4⟩ = ⟨1/4⟩ × 3이에요."]},{"stem":"⟨2/5⟩ + ⟨2/5⟩ + ⟨2/5⟩ + ⟨2/5⟩를 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"⟨2/5⟩ × 4","correct":true},{"t":"⟨2/5⟩ × 5","mis":"M5-2-u2-X17"},{"t":"⟨2/5⟩ + 4","mis":"M5-2-u2-X15"},{"t":"2 × 4","mis":"M5-2-u2-X15"}],"explanation":["⟨2/5⟩를 4번 더했어요.","자연수에서 4 + 4 + 4를 4 × 3으로 적듯 같은 수를 여러 번 더하면 곱셈으로 적어요.","⟨2/5⟩ + ⟨2/5⟩ + ⟨2/5⟩ + ⟨2/5⟩ = ⟨2/5⟩ × 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_basic#5','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C1',2,'mc','auto','여울, 순달과 달곰이 딸기우유를 ⟨3/10⟩ L씩 남겼어요. 남긴 딸기우유는 모두 몇 L인가요?',ARRAY['M5-2-u2-X03','M5-2-u2-X17','M5-2-u2-X15']::text[],true,'{"seq":5,"concept":"M5-2-u2-C1","difficulty":2,"kind":"mc","stem":"여울, 순달과 달곰이 딸기우유를 ⟨3/10⟩ L씩 남겼어요. 남긴 딸기우유는 모두 몇 L인가요?","options":[{"t":"⟨9/10⟩","correct":true},{"t":"⟨9/30⟩","mis":"M5-2-u2-X03"},{"t":"⟨3/10⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X15"}],"explanation":["3명이 ⟨3/10⟩ L씩 남겼으니 ⟨3/10⟩을 3번 더해요.","곱셈으로 적으면 ⟨3/10⟩ × 3이에요.","⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩ = ⟨9/10⟩ — 모두 ⟨9/10⟩ L예요."],"variant_rule":{"alt":[{"stem":"여울, 순달, 달곰이 똑같이 ⟨3/10⟩ L씩 딸기우유를 남겼어요. 남긴 딸기우유를 구하는 식으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"⟨3/10⟩ + 3","correct":true},{"t":"⟨3/10⟩ × 3","mis":"M5-2-u2-X17"},{"t":"⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩","mis":"M5-2-u2-X17"},{"t":"3 × ⟨3/10⟩","mis":"M5-2-u2-X17"}],"explanation":["3명이 ⟨3/10⟩ L씩 남겼으니 ⟨3/10⟩을 3번 더해요.","같은 수를 여러 번 더한 것은 곱셈 ⟨3/10⟩ × 3으로 나타낼 수 있어요.","⟨3/10⟩에 3을 더하는 식은 뜻이 달라요 — 모두 ⟨9/10⟩ L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_basic#6','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C2',2,'mc','auto','운동회 응원 현수막을 만들려고 길이가 ⟨1/4⟩ m인 천 3장을 이어 붙였어요. 사용한 천은 모두 몇 m인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":6,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"운동회 응원 현수막을 만들려고 길이가 ⟨1/4⟩ m인 천 3장을 이어 붙였어요. 사용한 천은 모두 몇 m인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨3/12⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/12⟩","mis":"M5-2-u2-X02"},{"t":"1","mis":"M5-2-u2-X15"}],"explanation":["⟨1/4⟩ m짜리 천 3장이니 ⟨1/4⟩ × 3이에요.","분모는 그대로 두고 분자와 자연수를 곱해요.","⟨1/4⟩ × 3 = ⟨3/4⟩ — ⟨3/4⟩ m예요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"grp":1,"label":"⟨1/4⟩ m짜리 천 3장"}]},"variant_rule":{"alt":[{"stem":"형성 평가예요. 친환경 세제를 한 통에 ⟨3/5⟩ L씩 6통에 담았어요. 담은 세제는 모두 몇 L인가요?","options":[{"t":"⟨3 3/5⟩","correct":true},{"t":"⟨18/30⟩","mis":"M5-2-u2-X01"},{"t":"⟨3/30⟩","mis":"M5-2-u2-X02"},{"t":"⟨1 4/5⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨3/5⟩ L씩 6통이니 ⟨3/5⟩ × 6이에요.","⟨3/5⟩ × 6 = ⟨18/5⟩ = ⟨3 3/5⟩이에요.","분모 5는 그대로, 분자만 3 × 6 = 18 — 모두 ⟨3 3/5⟩ L예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"label":"한 통에 ⟨3/5⟩ L"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_basic#7','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C2',2,'mc','auto','수직선의 0에서 ⟨2/5⟩씩 4번 뛰어 세면 어느 수에 닿나요?',ARRAY['M5-2-u2-X01','M5-2-u2-X17']::text[],true,'{"seq":7,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"수직선의 0에서 ⟨2/5⟩씩 4번 뛰어 세면 어느 수에 닿나요?","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨8/20⟩","mis":"M5-2-u2-X01"},{"t":"⟨1 1/5⟩","mis":"M5-2-u2-X17"},{"t":"2","mis":"M5-2-u2-X17"}],"explanation":["⟨2/5⟩씩 4번 뛰어 세면 ⟨2/5⟩ → ⟨4/5⟩ → ⟨1 1/5⟩ → ⟨1 3/5⟩이에요.","식으로는 ⟨2/5⟩ × 4예요.","⟨2/5⟩ × 4 = ⟨8/5⟩ = ⟨1 3/5⟩이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":2,"label":"한 번에 ⟨2/5⟩씩"}]},"variant_rule":{"alt":[{"stem":"수직선의 0에서 ⟨1/4⟩씩 3번 뛰어 세면 어느 수에 닿나요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨3/12⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/2⟩","mis":"M5-2-u2-X17"},{"t":"1","mis":"M5-2-u2-X17"}],"explanation":["⟨1/4⟩씩 3번 뛰어 세면 ⟨1/4⟩ → ⟨1/2⟩ → ⟨3/4⟩이에요.","식으로는 ⟨1/4⟩ × 3이에요.","⟨1/4⟩ × 3 = ⟨3/4⟩이에요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"grp":1,"label":"⟨1/4⟩씩 뛰어 세기"}]}},{"stem":"수직선의 0에서 ⟨2/5⟩씩 2번 뛰어 세면 어느 수에 닿나요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨4/10⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/5⟩","mis":"M5-2-u2-X17"},{"t":"⟨1 1/5⟩","mis":"M5-2-u2-X17"}],"explanation":["⟨2/5⟩씩 2번 뛰어 세면 ⟨2/5⟩ → ⟨4/5⟩예요.","식으로는 ⟨2/5⟩ × 2예요.","⟨2/5⟩ × 2 = ⟨4/5⟩예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":4,"grp":2,"label":"⟨2/5⟩씩 뛰어 세기"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_basic#8','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C2',2,'mc','auto','⟨5/6⟩ × 7을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":8,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"⟨5/6⟩ × 7을 계산하면 얼마인가요?","options":[{"t":"⟨5 5/6⟩","correct":true},{"t":"⟨35/42⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/42⟩","mis":"M5-2-u2-X02"},{"t":"2","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨5/6⟩ × 7 = ⟨35/6⟩ = ⟨5 5/6⟩예요.","계산 결과는 ⟨5 5/6⟩예요."],"variant_rule":{"alt":[{"stem":"⟨7/12⟩ × 8을 계산하면 얼마인가요?","options":[{"t":"⟨4 2/3⟩","correct":true},{"t":"⟨56/96⟩","mis":"M5-2-u2-X01"},{"t":"⟨7/96⟩","mis":"M5-2-u2-X02"},{"t":"⟨1 1/4⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨7/12⟩ × 8 = ⟨56/12⟩ = ⟨14/3⟩ = ⟨4 2/3⟩예요.","계산 결과는 ⟨4 2/3⟩예요."]},{"stem":"⟨1/9⟩ × 5를 계산하면 얼마인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨5/45⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/45⟩","mis":"M5-2-u2-X02"},{"t":"⟨2/3⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨1/9⟩ × 5 = ⟨5/9⟩예요.","계산 결과는 ⟨5/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_basic#9','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C2',2,'mc','auto','⟨3/4⟩ × 2를 계산할 때 약분은 언제 해야 하나요?',ARRAY['M5-2-u2-X13','M5-2-u2-X12']::text[],true,'{"seq":9,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"⟨3/4⟩ × 2를 계산할 때 약분은 언제 해야 하나요?","options":[{"t":"곱하기 전·곱하는 중·곱한 뒤 언제 해도 값이 같다","correct":true},{"t":"반드시 곱한 뒤에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"반드시 곱하기 전에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"분수와 자연수를 곱할 때는 약분할 수 없다","mis":"M5-2-u2-X12"}],"explanation":["곱한 뒤 약분: ⟨3/4⟩ × 2 = ⟨6/4⟩ = ⟨3/2⟩이에요.","곱하기 전에 4와 2를 2로 약분해도 ⟨3/2⟩ × 1 = ⟨3/2⟩이에요.","언제 약분하든 값은 같아요."],"variant_rule":{"alt":[{"stem":"⟨7/12⟩ × 8을 계산할 때 약분은 언제 해야 하나요?","options":[{"t":"곱하기 전·곱하는 중·곱한 뒤 언제 해도 값이 같다","correct":true},{"t":"반드시 곱한 뒤에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"반드시 곱하기 전에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"분수와 자연수를 곱할 때는 약분할 수 없다","mis":"M5-2-u2-X12"}],"explanation":["곱한 뒤 약분: ⟨7/12⟩ × 8 = ⟨56/12⟩ = ⟨14/3⟩예요.","곱하기 전에 12와 8을 4로 약분해도 ⟨7/3⟩ × 2 = ⟨14/3⟩예요.","언제 약분하든 값은 같아요."]},{"stem":"⟨5/6⟩ × 8을 계산할 때 약분은 언제 해야 하나요?","options":[{"t":"곱하기 전·곱하는 중·곱한 뒤 언제 해도 값이 같다","correct":true},{"t":"반드시 곱한 뒤에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"반드시 곱하기 전에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"분수와 자연수를 곱할 때는 약분할 수 없다","mis":"M5-2-u2-X12"}],"explanation":["곱한 뒤 약분: ⟨5/6⟩ × 8 = ⟨40/6⟩ = ⟨20/3⟩이에요.","곱하기 전에 6과 8을 2로 약분해도 ⟨5/3⟩ × 4 = ⟨20/3⟩이에요.","언제 약분하든 값은 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_basic#10','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_basic','lesson_basic','M5-2-u2-C2',3,'mc','auto','수학익힘 문제예요. 한 변의 길이가 ⟨3/8⟩ cm인 정삼각형의 둘레는 몇 cm인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X01','M5-2-u2-X02']::text[],true,'{"seq":10,"concept":"M5-2-u2-C2","difficulty":3,"kind":"mc","stem":"수학익힘 문제예요. 한 변의 길이가 ⟨3/8⟩ cm인 정삼각형의 둘레는 몇 cm인가요?","options":[{"t":"⟨1 1/8⟩","correct":true},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X17"},{"t":"⟨9/24⟩","mis":"M5-2-u2-X01"},{"t":"⟨3/24⟩","mis":"M5-2-u2-X02"}],"explanation":["정삼각형은 세 변의 길이가 모두 같아요 — (둘레) = (한 변의 길이) × 3.","⟨3/8⟩ × 3 = ⟨9/8⟩ = ⟨1 1/8⟩이에요.","정삼각형의 둘레는 ⟨1 1/8⟩ cm예요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 선호는 우유를 매일 ⟨9/20⟩ L씩 마셔요. 선호가 5일 동안 마시는 우유는 모두 몇 L인가요?","options":[{"t":"⟨2 1/4⟩","correct":true},{"t":"⟨5 9/20⟩","mis":"M5-2-u2-X15"},{"t":"⟨45/100⟩","mis":"M5-2-u2-X01"},{"t":"⟨9/100⟩","mis":"M5-2-u2-X02"}],"explanation":["⟨9/20⟩ L씩 5일이니 ⟨9/20⟩ × 5예요.","⟨9/20⟩ × 5 = ⟨45/20⟩ = ⟨9/4⟩ = ⟨2 1/4⟩이에요.","5와 20을 먼저 약분해도 ⟨9/4⟩ = ⟨2 1/4⟩ L로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_challenge#1','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',2,'sa','auto','⟨5/6⟩ × 7을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u2-C2","difficulty":2,"kind":"sa","stem":"⟨5/6⟩ × 7을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨5/6⟩ × 7 = ⟨35/6⟩ = ⟨5 5/6⟩예요.","계산 결과는 ⟨5 5/6⟩예요.","그래서 자연수 부분은 5예요."],"mis":"M5-2-u2-X17","variant_rule":{"alt":[{"stem":"⟨7/12⟩ × 8을 계산하여 기약분수인 대분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨7/12⟩ × 8 = ⟨56/12⟩ = ⟨14/3⟩ = ⟨4 2/3⟩예요.","계산 결과는 ⟨4 2/3⟩예요.","그래서 분자는 2예요."]},{"stem":"⟨5/6⟩ × 8을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["⟨5/6⟩ × 8 = ⟨40/6⟩ = ⟨20/3⟩ = ⟨6 2/3⟩예요.","계산 결과는 ⟨6 2/3⟩예요.","그래서 자연수 부분은 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_challenge#2','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',2,'mc','auto','단원 평가예요. 땅콩이 한 봉지에 ⟨8/9⟩ kg씩 들어 있어요. 6봉지에 들어 있는 땅콩은 모두 몇 kg인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":2,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"단원 평가예요. 땅콩이 한 봉지에 ⟨8/9⟩ kg씩 들어 있어요. 6봉지에 들어 있는 땅콩은 모두 몇 kg인가요?","options":[{"t":"⟨5 1/3⟩","correct":true},{"t":"⟨48/54⟩","mis":"M5-2-u2-X01"},{"t":"⟨8/54⟩","mis":"M5-2-u2-X02"},{"t":"⟨1 5/9⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨8/9⟩ kg씩 6봉지이니 ⟨8/9⟩ × 6이에요.","9와 6을 3으로 약분하면 ⟨8/3⟩ × 2 = ⟨16/3⟩이에요.","⟨8/9⟩ × 6 = ⟨48/9⟩ = ⟨16/3⟩ = ⟨5 1/3⟩ — ⟨5 1/3⟩ kg이에요."],"variant_rule":{"alt":[{"stem":"형성 평가예요. ⟨2/7⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨6/7⟩","correct":true},{"t":"⟨6/21⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/21⟩","mis":"M5-2-u2-X02"},{"t":"⟨5/7⟩","mis":"M5-2-u2-X15"}],"explanation":["식은 ⟨2/7⟩ × 3이에요.","⟨2/7⟩ × 3 = ⟨6/7⟩이에요.","그래서 답은 ⟨6/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_challenge#3','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',3,'mc','auto','⟨5/8⟩ × 3을 두 가지로 계산했어요. ㉠ ⟨5/8⟩ × 3 = ⟨15/24⟩ = ⟨5/8⟩, ㉡ ⟨5/8⟩ × 3 = ⟨15/8⟩ = ⟨1 7/8⟩. 바르게 계산한 것은 어느 것인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X12']::text[],true,'{"seq":3,"concept":"M5-2-u2-C2","difficulty":3,"kind":"mc","stem":"⟨5/8⟩ × 3을 두 가지로 계산했어요. ㉠ ⟨5/8⟩ × 3 = ⟨15/24⟩ = ⟨5/8⟩, ㉡ ⟨5/8⟩ × 3 = ⟨15/8⟩ = ⟨1 7/8⟩. 바르게 계산한 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M5-2-u2-X01"},{"t":"㉠과 ㉡ 모두","mis":"M5-2-u2-X01"},{"t":"둘 다 아니다","mis":"M5-2-u2-X12"}],"explanation":["(진분수)×(자연수)는 분모는 그대로 두고 분자와 자연수를 곱해요.","⟨5/8⟩ × 3 = ⟨15/8⟩ = ⟨1 7/8⟩이에요.","㉠은 분모에도 3을 곱해 처음 수 ⟨5/8⟩로 돌아갔어요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ × 7을 두 가지로 계산했어요. ㉠ ⟨3/4⟩ × 7 = ⟨21/28⟩ = ⟨3/4⟩, ㉡ ⟨3/4⟩ × 7 = ⟨21/4⟩ = ⟨5 1/4⟩. 바르게 계산한 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M5-2-u2-X01"},{"t":"㉠과 ㉡ 모두","mis":"M5-2-u2-X01"},{"t":"둘 다 아니다","mis":"M5-2-u2-X12"}],"explanation":["(진분수)×(자연수)는 분모는 그대로 두고 분자와 자연수를 곱해요.","⟨3/4⟩ × 7 = ⟨21/4⟩ = ⟨5 1/4⟩이에요.","㉠은 분모에도 7을 곱해 처음 수 ⟨3/4⟩으로 돌아갔어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_challenge#4','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',3,'ox','auto','단원 평가예요. ⟨3/4⟩ × 7을 분모 4와 자연수 7을 곱해 「⟨3/4⟩ × 7 = ⟨3/28⟩」으로 계산했어요. 바르게 계산했나요?',ARRAY['M5-2-u2-X02']::text[],true,'{"seq":4,"concept":"M5-2-u2-C2","difficulty":3,"kind":"ox","stem":"단원 평가예요. ⟨3/4⟩ × 7을 분모 4와 자연수 7을 곱해 「⟨3/4⟩ × 7 = ⟨3/28⟩」으로 계산했어요. 바르게 계산했나요?","answer":"X","reason_options":[{"t":"자연수는 분자와 곱해야 하므로 ⟨3/4⟩ × 7 = ⟨21/4⟩ = ⟨5 1/4⟩이라서","correct":true},{"t":"분수에 자연수를 곱하면 분모가 커지므로","mis":"M5-2-u2-X02"}],"mis":"M5-2-u2-X02","explanation":["⟨3/4⟩ × 7은 ⟨3/4⟩을 7번 더한 것이에요.","분모가 같은 분수의 덧셈이라 분모는 그대로예요.","바르게 하면 ⟨3/4⟩ × 7 = ⟨21/4⟩ = ⟨5 1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. ⟨2/5⟩ × 4를 분모 5와 자연수 4를 곱해 「⟨2/5⟩ × 4 = ⟨2/20⟩」로 계산했어요. 바르게 계산했나요?","answer":"X","reason_options":[{"t":"자연수는 분자와 곱해야 하므로 ⟨2/5⟩ × 4 = ⟨8/5⟩ = ⟨1 3/5⟩이라서","correct":true},{"t":"분수에 자연수를 곱하면 분모가 커지므로","mis":"M5-2-u2-X02"}],"explanation":["⟨2/5⟩ × 4는 ⟨2/5⟩를 4번 더한 것이에요.","분모가 같은 분수의 덧셈이라 분모는 그대로예요.","바르게 하면 ⟨2/5⟩ × 4 = ⟨8/5⟩ = ⟨1 3/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_challenge#5','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',3,'mc','auto','계산 결과가 자연수인 것은 어느 것인가요?',ARRAY['M5-2-u2-X12']::text[],true,'{"seq":5,"concept":"M5-2-u2-C2","difficulty":3,"kind":"mc","stem":"계산 결과가 자연수인 것은 어느 것인가요?","options":[{"t":"⟨2/9⟩ × 18","correct":true},{"t":"⟨5/9⟩ × 21","mis":"M5-2-u2-X12"},{"t":"⟨7/12⟩ × 8","mis":"M5-2-u2-X12"},{"t":"⟨5/6⟩ × 7","mis":"M5-2-u2-X12"}],"explanation":["분자와 자연수를 곱한 수가 분모로 나누어떨어지면 자연수예요.","⟨2/9⟩ × 18 = 4, ⟨5/9⟩ × 21 = ⟨11 2/3⟩, ⟨7/12⟩ × 8 = ⟨4 2/3⟩, ⟨5/6⟩ × 7 = ⟨5 5/6⟩예요.","그래서 자연수인 것은 ⟨2/9⟩ × 18이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산 결과가 자연수인 것은 어느 것인가요?","options":[{"t":"⟨2/9⟩ × 18","correct":true},{"t":"⟨2/7⟩ × 3","mis":"M5-2-u2-X12"},{"t":"⟨5/6⟩ × 8","mis":"M5-2-u2-X12"},{"t":"⟨3/8⟩ × 3","mis":"M5-2-u2-X12"}],"explanation":["분자와 자연수를 곱한 수가 분모로 나누어떨어지면 자연수예요.","⟨2/9⟩ × 18 = 4, ⟨2/7⟩ × 3 = ⟨6/7⟩, ⟨5/6⟩ × 8 = ⟨6 2/3⟩, ⟨3/8⟩ × 3 = ⟨1 1/8⟩이에요.","그래서 자연수인 것은 ⟨2/9⟩ × 18이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_challenge#6','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',3,'mc','auto','수학익힘 문제예요. 친환경 가습기 한 개를 만드는 데 이끼가 ⟨5/16⟩ kg 필요해요. 친환경 가습기를 24개 만드는 데 필요한 이끼는 모두 몇 kg인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":6,"concept":"M5-2-u2-C2","difficulty":3,"kind":"mc","stem":"수학익힘 문제예요. 친환경 가습기 한 개를 만드는 데 이끼가 ⟨5/16⟩ kg 필요해요. 친환경 가습기를 24개 만드는 데 필요한 이끼는 모두 몇 kg인가요?","options":[{"t":"⟨7 1/2⟩","correct":true},{"t":"⟨120/384⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/384⟩","mis":"M5-2-u2-X02"},{"t":"⟨1 13/16⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨5/16⟩ kg씩 24개이니 ⟨5/16⟩ × 24예요.","16과 24를 8로 먼저 약분하면 ⟨5/2⟩ × 3 = ⟨15/2⟩예요.","⟨5/16⟩ × 24 = ⟨120/16⟩ = ⟨15/2⟩ = ⟨7 1/2⟩ — ⟨7 1/2⟩ kg이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 물이 ⟨1/5⟩ L씩 들어 있는 컵이 7개 있어요. 컵에 들어 있는 물은 모두 몇 L인가요?","options":[{"t":"⟨1 2/5⟩","correct":true},{"t":"⟨7/35⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/35⟩","mis":"M5-2-u2-X02"},{"t":"⟨1 3/5⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨1/5⟩ L씩 7컵이니 ⟨1/5⟩ × 7이에요.","⟨1/5⟩ × 7 = ⟨7/5⟩ = ⟨1 2/5⟩예요.","⟨1/5⟩이 7개 — 모두 ⟨1 2/5⟩ L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_challenge#7','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',3,'sa','auto','⟨1/4⟩ × □ = ⟨3/4⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C2","difficulty":3,"kind":"sa","stem":"⟨1/4⟩ × □ = ⟨3/4⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모는 그대로이고 분자만 1에서 3으로 바뀌었어요.","분자와 □를 곱해 3이 되어야 해요 — 1 × 3 = 3.","그래서 □는 3이에요."],"mis":"M5-2-u2-X01","variant_rule":{"alt":[{"stem":"⟨2/5⟩ × □ = ⟨8/5⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모는 그대로이고 분자만 2에서 8로 바뀌었어요.","분자와 □를 곱해 8이 되어야 해요 — 2 × 4 = 8.","그래서 □는 4예요."]},{"stem":"⟨3/5⟩ × □ = ⟨18/5⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분모는 그대로이고 분자만 3에서 18로 바뀌었어요.","분자와 □를 곱해 18이 되어야 해요 — 3 × 6 = 18.","그래서 □는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_challenge#8','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',4,'mc','auto','⟨3/5⟩ × 4와 ⟨3/4⟩ × 5 가운데 계산 결과가 더 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X01']::text[],true,'{"seq":8,"concept":"M5-2-u2-C2","difficulty":4,"kind":"mc","stem":"⟨3/5⟩ × 4와 ⟨3/4⟩ × 5 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨3/4⟩ × 5","correct":true},{"t":"⟨3/5⟩ × 4","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X01"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨3/5⟩ × 4 = ⟨2 2/5⟩예요.","⟨3/4⟩ × 5 = ⟨3 3/4⟩이에요.","⟨2 2/5⟩ < ⟨3 3/4⟩이라 ⟨3/4⟩ × 5가 더 커요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ × 7과 ⟨7/12⟩ × 8 가운데 계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"⟨5/6⟩ × 7","correct":true},{"t":"⟨7/12⟩ × 8","mis":"M5-2-u2-X17"},{"t":"두 곱이 같다","mis":"M5-2-u2-X01"},{"t":"계산하지 않으면 알 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨5/6⟩ × 7 = ⟨5 5/6⟩예요.","⟨7/12⟩ × 8 = ⟨4 2/3⟩예요.","⟨5 5/6⟩ > ⟨4 2/3⟩라 ⟨5/6⟩ × 7이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_challenge#9','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',4,'match','auto','곱셈식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u2-C2","difficulty":4,"kind":"match","stem":"곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"⟨1/9⟩ × 5","r":"⟨5/9⟩"},{"l":"⟨5/6⟩ × 7","r":"⟨5 5/6⟩"},{"l":"⟨7/12⟩ × 8","r":"⟨4 2/3⟩"}],"mis":"M5-2-u2-X01","explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨1/9⟩ × 5 = ⟨5/9⟩, ⟨5/6⟩ × 7 = ⟨35/6⟩ = ⟨5 5/6⟩, ⟨7/12⟩ × 8 = ⟨56/12⟩ = ⟨14/3⟩ = ⟨4 2/3⟩예요.","분모에 자연수를 곱하지 않도록 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"⟨2/7⟩ × 3","r":"⟨6/7⟩"},{"l":"⟨5/6⟩ × 8","r":"⟨6 2/3⟩"},{"l":"⟨3/5⟩ × 6","r":"⟨3 3/5⟩"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/7⟩ × 3 = ⟨6/7⟩, ⟨5/6⟩ × 8 = ⟨40/6⟩ = ⟨20/3⟩ = ⟨6 2/3⟩, ⟨3/5⟩ × 6 = ⟨18/5⟩ = ⟨3 3/5⟩이에요.","분모에 자연수를 곱하지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L02_challenge#10','math',5,2,'u2','L02','tb_g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',4,'essay','teacher','태하, 하연, 재우가 ⟨3/4⟩ × 2를 계산했어요. 태하는 분자와 자연수를 곱한 다음 약분했고, 하연이는 곱하는 과정에서 약분했고, 재우는 곱셈을 하기 전에 약분했어요. 세 친구의 계산을 식으로 쓰고, 계산 방법이 어떻게 다른지와 결과가 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C2","difficulty":4,"kind":"essay","stem":"태하, 하연, 재우가 ⟨3/4⟩ × 2를 계산했어요. 태하는 분자와 자연수를 곱한 다음 약분했고, 하연이는 곱하는 과정에서 약분했고, 재우는 곱셈을 하기 전에 약분했어요. 세 친구의 계산을 식으로 쓰고, 계산 방법이 어떻게 다른지와 결과가 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 태하는 ⟨3/4⟩ × 2 = ⟨6/4⟩ = ⟨3/2⟩ = ⟨1 1/2⟩로, 하연이는 분자 3 × 2를 쓰는 과정에서 2와 4를 약분해 ⟨3/2⟩ = ⟨1 1/2⟩로, 재우는 곱하기 전에 4와 2를 약분해 ⟨3/2⟩ × 1 = ⟨3/2⟩ = ⟨1 1/2⟩로 계산했다. 약분을 언제 하는지만 다르고, 분모와 분자를 같은 수로 나누는 약분은 값을 바꾸지 않으므로 세 결과는 모두 ⟨1 1/2⟩로 같다. 그중 자신에게 편리한 방법을 고르면 된다.","scoring_points":["세 친구의 식을 바르게 썼는가","약분하는 때(곱한 뒤·곱하는 중·곱하기 전)가 다르다고 밝혔는가","약분은 값을 바꾸지 않아 결과가 ⟨1 1/2⟩로 같다고 설명했는가"]},"explanation":["⟨3/4⟩ × 2 = ⟨6/4⟩ = ⟨3/2⟩ = ⟨1 1/2⟩이에요.","약분하는 때만 다르고 결과는 모두 ⟨1 1/2⟩이에요.","자신에게 편리한 방법을 골라 계산해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_basic#1','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',1,'mc','auto','⟨1 1/4⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X04']::text[],true,'{"seq":1,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"⟨1 1/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨5/4⟩","correct":true},{"t":"⟨4/5⟩","mis":"M5-2-u2-X17"},{"t":"⟨2/4⟩","mis":"M5-2-u2-X04"},{"t":"⟨1/4⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨4/4⟩예요 — 1 × 4 = 4.","여기에 ⟨1/4⟩을 더하면 분자는 4 + 1 = 5예요.","⟨1 1/4⟩ = ⟨5/4⟩예요."],"variant_rule":{"alt":[{"stem":"⟨1 3/5⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨8/5⟩","correct":true},{"t":"⟨5/8⟩","mis":"M5-2-u2-X17"},{"t":"⟨4/5⟩","mis":"M5-2-u2-X04"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨5/5⟩예요 — 1 × 5 = 5.","여기에 ⟨3/5⟩을 더하면 분자는 5 + 3 = 8이에요.","⟨1 3/5⟩ = ⟨8/5⟩이에요."]},{"stem":"⟨2 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/3⟩","correct":true},{"t":"⟨3/7⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/3⟩","mis":"M5-2-u2-X04"},{"t":"⟨2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 2는 ⟨6/3⟩이에요 — 2 × 3 = 6.","여기에 ⟨1/3⟩을 더하면 분자는 6 + 1 = 7이에요.","⟨2 1/3⟩ = ⟨7/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_basic#2','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',1,'mc','auto','사과 따기 체험에서 만든 사과주스를 ⟨1 1/4⟩ L짜리 병 3병에 가득 담았어요. 전체 양을 구하는 식은 어느 것인가요?',ARRAY['M5-2-u2-X15','M5-2-u2-X05','M5-2-u2-X17']::text[],true,'{"seq":2,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"사과 따기 체험에서 만든 사과주스를 ⟨1 1/4⟩ L짜리 병 3병에 가득 담았어요. 전체 양을 구하는 식은 어느 것인가요?","options":[{"t":"⟨1 1/4⟩ × 3","correct":true},{"t":"⟨1 1/4⟩ + 3","mis":"M5-2-u2-X15"},{"t":"1 × 3","mis":"M5-2-u2-X05"},{"t":"⟨1 1/4⟩ × 4","mis":"M5-2-u2-X17"}],"explanation":["⟨1 1/4⟩ L씩 3번이에요.","같은 수를 여러 번 더하는 것은 곱셈으로 나타내요.","식은 ⟨1 1/4⟩ × 3이에요."],"variant_rule":{"alt":[{"stem":"수학익힘 문제예요. 단감을 한 상자에 ⟨5 1/2⟩ kg씩 8상자 샀어요. 전체 양을 구하는 식은 어느 것인가요?","options":[{"t":"⟨5 1/2⟩ × 8","correct":true},{"t":"⟨5 1/2⟩ + 8","mis":"M5-2-u2-X15"},{"t":"5 × 8","mis":"M5-2-u2-X05"},{"t":"⟨5 1/2⟩ × 9","mis":"M5-2-u2-X17"}],"explanation":["⟨5 1/2⟩ kg씩 8번이에요.","같은 수를 여러 번 더하는 것은 곱셈으로 나타내요.","식은 ⟨5 1/2⟩ × 8이에요."]},{"stem":"단원 평가예요. 포도 한 상자의 무게는 ⟨3 5/8⟩ kg이에요. 포도 6상자의 전체 양을 구하는 식은 어느 것인가요?","options":[{"t":"⟨3 5/8⟩ × 6","correct":true},{"t":"⟨3 5/8⟩ + 6","mis":"M5-2-u2-X15"},{"t":"3 × 6","mis":"M5-2-u2-X05"},{"t":"⟨3 5/8⟩ × 7","mis":"M5-2-u2-X17"}],"explanation":["⟨3 5/8⟩ kg씩 6번이에요.","같은 수를 여러 번 더하는 것은 곱셈으로 나타내요.","식은 ⟨3 5/8⟩ × 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_basic#3','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',1,'mc','auto','⟨1 1/4⟩ × 3을 대분수의 자연수 부분과 분수 부분으로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X15']::text[],true,'{"seq":3,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"⟨1 1/4⟩ × 3을 대분수의 자연수 부분과 분수 부분으로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"1 × 3 + ⟨1/4⟩ × 3","correct":true},{"t":"1 × 3 + ⟨1/4⟩","mis":"M5-2-u2-X05"},{"t":"1 + ⟨1/4⟩ × 3","mis":"M5-2-u2-X05"},{"t":"1 × ⟨1/4⟩ × 3","mis":"M5-2-u2-X15"}],"explanation":["⟨1 1/4⟩은 1 + ⟨1/4⟩이에요.","자연수 부분과 분수 부분에 모두 3을 곱해 더해요.","1 × 3 + ⟨1/4⟩ × 3 = 3 + ⟨3/4⟩ = ⟨3 3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1 3/7⟩ × 2를 대분수의 자연수 부분과 분수 부분으로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"1 × 2 + ⟨3/7⟩ × 2","correct":true},{"t":"1 × 2 + ⟨3/7⟩","mis":"M5-2-u2-X05"},{"t":"1 + ⟨3/7⟩ × 2","mis":"M5-2-u2-X05"},{"t":"1 × ⟨3/7⟩ × 2","mis":"M5-2-u2-X15"}],"explanation":["⟨1 3/7⟩은 1 + ⟨3/7⟩이에요.","자연수 부분과 분수 부분에 모두 2를 곱해 더해요.","1 × 2 + ⟨3/7⟩ × 2 = 2 + ⟨6/7⟩ = ⟨2 6/7⟩이에요."]},{"stem":"⟨1 1/3⟩ × 2를 대분수의 자연수 부분과 분수 부분으로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"1 × 2 + ⟨1/3⟩ × 2","correct":true},{"t":"1 × 2 + ⟨1/3⟩","mis":"M5-2-u2-X05"},{"t":"1 + ⟨1/3⟩ × 2","mis":"M5-2-u2-X05"},{"t":"1 × ⟨1/3⟩ × 2","mis":"M5-2-u2-X15"}],"explanation":["⟨1 1/3⟩은 1 + ⟨1/3⟩이에요.","자연수 부분과 분수 부분에 모두 2를 곱해 더해요.","1 × 2 + ⟨1/3⟩ × 2 = 2 + ⟨2/3⟩ = ⟨2 2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_basic#4','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',1,'mc','auto','지난 시간에 배운 것이에요. ⟨1/8⟩ × 3을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":4,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"지난 시간에 배운 것이에요. ⟨1/8⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨3/8⟩","correct":true},{"t":"⟨3/24⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/24⟩","mis":"M5-2-u2-X02"},{"t":"⟨1/2⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨1/8⟩ × 3 = ⟨3/8⟩이에요.","계산 결과는 ⟨3/8⟩이에요."],"variant_rule":{"alt":[{"stem":"지난 시간에 배운 것이에요. ⟨4/5⟩ × 4를 계산하면 얼마인가요?","options":[{"t":"⟨3 1/5⟩","correct":true},{"t":"⟨16/20⟩","mis":"M5-2-u2-X01"},{"t":"⟨4/20⟩","mis":"M5-2-u2-X02"},{"t":"⟨1 3/5⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨4/5⟩ × 4 = ⟨16/5⟩ = ⟨3 1/5⟩이에요.","계산 결과는 ⟨3 1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_basic#5','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',2,'mc','auto','사과 따기 체험에서 만든 사과주스를 ⟨1 1/4⟩ L짜리 병에 가득 담았더니 3병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":5,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"사과 따기 체험에서 만든 사과주스를 ⟨1 1/4⟩ L짜리 병에 가득 담았더니 3병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨3 1/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["⟨1 1/4⟩ L씩 3병이니 ⟨1 1/4⟩ × 3이에요.","⟨1 1/4⟩ × 3 = ⟨5/4⟩ × 3 = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","모두 ⟨3 3/4⟩ L예요."],"variant_rule":{"alt":[{"stem":"수학익힘 문제예요. 단감을 한 상자에 ⟨5 1/2⟩ kg씩 8상자 샀어요. 산 단감의 무게는 모두 몇 kg인가요?","options":[{"t":"44","correct":true},{"t":"⟨40 1/2⟩","mis":"M5-2-u2-X05"},{"t":"9","mis":"M5-2-u2-X05"},{"t":"24","mis":"M5-2-u2-X04"}],"explanation":["⟨5 1/2⟩ kg씩 8상자이니 ⟨5 1/2⟩ × 8이에요.","⟨5 1/2⟩ × 8 = ⟨11/2⟩ × 8 = ⟨88/2⟩ = 44예요.","모두 44 kg — 결과가 자연수가 되기도 해요."]},{"stem":"단원 평가예요. 포도 한 상자의 무게는 ⟨3 5/8⟩ kg이에요. 포도 6상자는 모두 몇 kg인가요?","options":[{"t":"⟨21 3/4⟩","correct":true},{"t":"⟨18 5/8⟩","mis":"M5-2-u2-X05"},{"t":"⟨6 3/4⟩","mis":"M5-2-u2-X05"},{"t":"6","mis":"M5-2-u2-X04"}],"explanation":["⟨3 5/8⟩ kg씩 6상자이니 ⟨3 5/8⟩ × 6이에요.","⟨3 5/8⟩ × 6 = ⟨29/8⟩ × 6 = ⟨174/8⟩ = ⟨87/4⟩ = ⟨21 3/4⟩이에요.","포도 6상자는 ⟨21 3/4⟩ kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_basic#6','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',2,'mc','auto','⟨1 3/5⟩ × 2를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":6,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"⟨1 3/5⟩ × 2를 계산하면 얼마인가요?","options":[{"t":"⟨3 1/5⟩","correct":true},{"t":"⟨2 3/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/5⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨1 3/5⟩ × 2 = ⟨8/5⟩ × 2 = ⟨16/5⟩ = ⟨3 1/5⟩이에요.","계산 결과는 ⟨3 1/5⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ × 5를 계산하면 얼마인가요?","options":[{"t":"⟨11 2/3⟩","correct":true},{"t":"⟨10 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 2/3⟩","mis":"M5-2-u2-X05"},{"t":"5","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨2 1/3⟩ × 5 = ⟨7/3⟩ × 5 = ⟨35/3⟩ = ⟨11 2/3⟩예요.","계산 결과는 ⟨11 2/3⟩예요."]},{"stem":"⟨3 2/9⟩ × 6을 계산하면 얼마인가요?","options":[{"t":"⟨19 1/3⟩","correct":true},{"t":"⟨18 2/9⟩","mis":"M5-2-u2-X05"},{"t":"⟨4 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨3 2/9⟩ × 6 = ⟨29/9⟩ × 6 = ⟨174/9⟩ = ⟨58/3⟩ = ⟨19 1/3⟩이에요.","계산 결과는 ⟨19 1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_basic#7','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',2,'ox','auto','⟨1 1/4⟩ × 3 = ⟨3 1/4⟩이에요.',ARRAY['M5-2-u2-X05']::text[],true,'{"seq":7,"concept":"M5-2-u2-C3","difficulty":2,"kind":"ox","stem":"⟨1 1/4⟩ × 3 = ⟨3 1/4⟩이에요.","answer":"X","reason_options":[{"t":"분수 부분에도 3을 곱해 ⟨3 3/4⟩이 되므로","correct":true},{"t":"자연수 부분에만 곱하면 되므로","mis":"M5-2-u2-X05"}],"mis":"M5-2-u2-X05","explanation":["⟨1 1/4⟩ = 1 + ⟨1/4⟩이에요.","1 × 3 = 3, ⟨1/4⟩ × 3 = ⟨3/4⟩이에요.","⟨1 1/4⟩ × 3 = ⟨3 3/4⟩ — 분수 부분도 곱해야 해요."],"variant_rule":{"alt":[{"stem":"⟨1 1/4⟩ × 3은 ⟨1 1/4⟩ + ⟨1 1/4⟩ + ⟨1 1/4⟩과 같아요.","answer":"O","reason_options":[{"t":"같은 수를 세 번 더한 것을 곱셈으로 적은 것이므로","correct":true},{"t":"대분수는 곱셈으로 적을 수 없으므로","mis":"M5-2-u2-X15"}],"explanation":["⟨1 1/4⟩씩 세 번 뛰어 세면 ⟨1 1/4⟩ → ⟨2 2/4⟩ → ⟨3 3/4⟩이에요.","⟨1 1/4⟩ × 3 = ⟨3 3/4⟩이에요.","그래서 맞아요."]},{"stem":"대분수에 자연수를 곱하는 방법은 가르기와 가분수로 고치기 두 가지가 있고, 답은 같아요.","answer":"O","reason_options":[{"t":"같은 수를 다르게 계산했을 뿐이므로","correct":true},{"t":"가분수로 고치면 답이 더 커지므로","mis":"M5-2-u2-X12"}],"explanation":["가르기: 2 × 5 + ⟨1/3⟩ × 5 = ⟨11 2/3⟩예요.","가분수: ⟨7/3⟩ × 5 = ⟨35/3⟩ = ⟨11 2/3⟩예요.","두 방법 모두 ⟨11 2/3⟩ — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_basic#8','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',2,'mc','auto','형성 평가 보기처럼 대분수를 가분수로 고쳐 계산해요. ⟨2 4/7⟩ × 3을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":8,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"형성 평가 보기처럼 대분수를 가분수로 고쳐 계산해요. ⟨2 4/7⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨7 5/7⟩","correct":true},{"t":"⟨6 4/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 5/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 4/7⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨2 4/7⟩ × 3 = ⟨18/7⟩ × 3 = ⟨54/7⟩ = ⟨7 5/7⟩예요.","계산 결과는 ⟨7 5/7⟩예요."],"variant_rule":{"alt":[{"stem":"형성 평가 문제예요. ⟨3 2/5⟩ × 4를 계산하면 얼마인가요?","options":[{"t":"⟨13 3/5⟩","correct":true},{"t":"⟨12 2/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨4 3/5⟩","mis":"M5-2-u2-X05"},{"t":"4","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨3 2/5⟩ × 4 = ⟨17/5⟩ × 4 = ⟨68/5⟩ = ⟨13 3/5⟩이에요.","계산 결과는 ⟨13 3/5⟩이에요."]},{"stem":"형성 평가 문제예요. ⟨1 3/8⟩ × 6을 계산하면 얼마인가요?","options":[{"t":"⟨8 1/4⟩","correct":true},{"t":"⟨6 3/8⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/4⟩","mis":"M5-2-u2-X05"},{"t":"3","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨1 3/8⟩ × 6 = ⟨11/8⟩ × 6 = ⟨66/8⟩ = ⟨33/4⟩ = ⟨8 1/4⟩이에요.","계산 결과는 ⟨8 1/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_basic#9','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',2,'sa','auto','⟨3 2/9⟩ × 6을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u2-C3","difficulty":2,"kind":"sa","stem":"⟨3 2/9⟩ × 6을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["⟨3 2/9⟩ × 6 = ⟨29/9⟩ × 6 = ⟨174/9⟩ = ⟨58/3⟩ = ⟨19 1/3⟩이에요.","계산 결과는 ⟨19 1/3⟩이에요.","그래서 자연수 부분은 19예요."],"mis":"M5-2-u2-X05","variant_rule":{"alt":[{"stem":"⟨1 3/5⟩ × 2를 계산하여 기약분수인 대분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨1 3/5⟩ × 2 = ⟨8/5⟩ × 2 = ⟨16/5⟩ = ⟨3 1/5⟩이에요.","계산 결과는 ⟨3 1/5⟩이에요.","그래서 분자는 1이에요."]},{"stem":"⟨2 1/8⟩ × 4를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨2 1/8⟩ × 4 = ⟨17/8⟩ × 4 = ⟨68/8⟩ = ⟨17/2⟩ = ⟨8 1/2⟩이에요.","계산 결과는 ⟨8 1/2⟩이에요.","그래서 자연수 부분은 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_basic#10','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',3,'mc','auto','한 변의 길이가 ⟨9 3/8⟩ cm인 정사각형 모양 거울의 둘레는 몇 cm인가요?',ARRAY['M5-2-u2-X20','M5-2-u2-X05']::text[],true,'{"seq":10,"concept":"M5-2-u2-C3","difficulty":3,"kind":"mc","stem":"한 변의 길이가 ⟨9 3/8⟩ cm인 정사각형 모양 거울의 둘레는 몇 cm인가요?","options":[{"t":"⟨37 1/2⟩","correct":true},{"t":"⟨87 57/64⟩","mis":"M5-2-u2-X20"},{"t":"⟨18 3/4⟩","mis":"M5-2-u2-X20"},{"t":"⟨36 3/8⟩","mis":"M5-2-u2-X05"}],"explanation":["정사각형은 네 변의 길이가 모두 같아요 — (둘레) = (한 변의 길이) × 4.","⟨9 3/8⟩ × 4 = ⟨75/8⟩ × 4 = ⟨300/8⟩ = ⟨75/2⟩ = ⟨37 1/2⟩이에요.","둘레는 ⟨37 1/2⟩ cm예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 ⟨9 1/2⟩ m인 정사각형 모양 수영장의 둘레는 몇 m인가요?","options":[{"t":"38","correct":true},{"t":"⟨90 1/4⟩","mis":"M5-2-u2-X20"},{"t":"19","mis":"M5-2-u2-X20"},{"t":"⟨36 1/2⟩","mis":"M5-2-u2-X05"}],"explanation":["정사각형은 네 변의 길이가 모두 같아요 — (둘레) = (한 변의 길이) × 4.","⟨9 1/2⟩ × 4 = ⟨19/2⟩ × 4 = ⟨76/2⟩ = 38이에요.","둘레는 38 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_challenge#1','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',2,'sa','auto','⟨1 1/4⟩ × 3을 가분수로 고쳐 계산하고 기약분수인 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u2-C3","difficulty":2,"kind":"sa","stem":"⟨1 1/4⟩ × 3을 가분수로 고쳐 계산하고 기약분수인 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["⟨1 1/4⟩ = ⟨5/4⟩예요 — 1 × 4 + 1 = 5.","⟨5/4⟩ × 3 = ⟨15/4⟩예요.","그래서 분자는 15예요."],"mis":"M5-2-u2-X04","variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ × 5를 가분수로 고쳐 계산하고 기약분수인 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["⟨2 1/3⟩ = ⟨7/3⟩이에요 — 2 × 3 + 1 = 7.","⟨7/3⟩ × 5 = ⟨35/3⟩예요.","그래서 분자는 35예요."]},{"stem":"⟨3 2/9⟩ × 6을 가분수로 고쳐 계산하고 기약분수인 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["58"],"explanation":["⟨3 2/9⟩ = ⟨29/9⟩예요 — 3 × 9 + 2 = 29.","⟨29/9⟩ × 6 = ⟨174/9⟩ = ⟨58/3⟩이에요.","그래서 분자는 58이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_challenge#2','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',2,'mc','auto','단원 평가예요. 계산 결과가 ⟨2 5/7⟩ × 2와 다른 것은 어느 것인가요?',ARRAY['M5-2-u2-X05']::text[],true,'{"seq":2,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"단원 평가예요. 계산 결과가 ⟨2 5/7⟩ × 2와 다른 것은 어느 것인가요?","options":[{"t":"2 + ⟨5/7⟩ × 2","correct":true},{"t":"⟨2 5/7⟩ + ⟨2 5/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨19/7⟩ × 2","mis":"M5-2-u2-X05"},{"t":"2 × 2 + ⟨5/7⟩ × 2","mis":"M5-2-u2-X05"}],"explanation":["⟨2 5/7⟩ × 2 = ⟨19/7⟩ × 2 = ⟨38/7⟩ = ⟨5 3/7⟩이에요.","⟨2 5/7⟩ + ⟨2 5/7⟩, 2 × 2 + ⟨5/7⟩ × 2도 모두 ⟨5 3/7⟩이에요.","2 + ⟨5/7⟩ × 2는 자연수 부분 2에 2를 곱하지 않아 ⟨3 3/7⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 계산 결과가 다른 것은 어느 것인가요?","options":[{"t":"⟨1 3/4⟩ + ⟨1 3/4⟩ + ⟨1 3/4⟩","correct":true},{"t":"⟨1 3/4⟩ × 2","mis":"M5-2-u2-X15"},{"t":"1 × 2 + ⟨3/4⟩ × 2","mis":"M5-2-u2-X15"},{"t":"⟨7/4⟩ × 2","mis":"M5-2-u2-X15"}],"explanation":["⟨1 3/4⟩ × 2 = ⟨7/4⟩ × 2 = ⟨7/2⟩ = ⟨3 1/2⟩이에요.","1 × 2 + ⟨3/4⟩ × 2 = 2 + ⟨3/2⟩ = ⟨3 1/2⟩도 같아요.","⟨1 3/4⟩을 세 번 더하면 ⟨5 1/4⟩로 ⟨1 3/4⟩ × 3과 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_challenge#3','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',3,'mc','auto','어떤 친구가 ⟨1 1/6⟩ × 15를 「6과 15를 먼저 약분해 ⟨1 1/2⟩ × 5」로 고쳐 ⟨7 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X02','M5-2-u2-X12']::text[],true,'{"seq":3,"concept":"M5-2-u2-C3","difficulty":3,"kind":"mc","stem":"어떤 친구가 ⟨1 1/6⟩ × 15를 「6과 15를 먼저 약분해 ⟨1 1/2⟩ × 5」로 고쳐 ⟨7 1/2⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨1 1/6⟩에서 분모만 약분하면 자연수 부분 1은 약분되지 않은 채 남아 값이 달라져요.","먼저 가분수로 나타내요 — ⟨1 1/6⟩ = ⟨7/6⟩.","바르게 하면 ⟨1 1/6⟩ × 15 = ⟨7/6⟩ × 15 = ⟨105/6⟩ = ⟨35/2⟩ = ⟨17 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"어떤 친구가 ⟨1 3/8⟩ × 6을 「8과 6을 먼저 약분해 ⟨1 3/4⟩ × 3」으로 고쳐 ⟨5 1/4⟩로 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분자를 두 번 곱했다","mis":"M5-2-u2-X12"}],"explanation":["대분수 ⟨1 3/8⟩에서 분모만 약분하면 자연수 부분 1은 약분되지 않은 채 남아 값이 달라져요.","먼저 가분수로 나타내요 — ⟨1 3/8⟩ = ⟨11/8⟩.","바르게 하면 ⟨1 3/8⟩ × 6 = ⟨11/8⟩ × 6 = ⟨66/8⟩ = ⟨33/4⟩ = ⟨8 1/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_challenge#4','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',3,'error','auto','⟨1 1/4⟩ × 3을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X17']::text[],true,'{"seq":4,"concept":"M5-2-u2-C3","difficulty":3,"kind":"error","stem":"⟨1 1/4⟩ × 3을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「1 × 3만 하면 되니까 ⟨3 1/4⟩이야.」","correct":true,"mis_target":"M5-2-u2-X05"},{"t":"순달 — 「가분수로 고쳐 ⟨5/4⟩ × 3 = ⟨3 3/4⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「1 × 3 + ⟨1/4⟩ × 3 = ⟨3 3/4⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수 부분과 분수 부분이 함께 있는 수예요.","두 부분에 모두 3을 곱해야 해요 — ⟨1 1/4⟩ × 3 = ⟨5/4⟩ × 3 = ⟨15/4⟩ = ⟨3 3/4⟩.","여울은 자연수 부분에만 곱해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨3 2/9⟩ × 6을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「3 × 6만 하면 되니까 ⟨18 2/9⟩야.」","correct":true,"mis_target":"M5-2-u2-X05"},{"t":"순달 — 「가분수로 고쳐 ⟨29/9⟩ × 6 = ⟨19 1/3⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「3 × 6 + ⟨2/9⟩ × 6 = ⟨19 1/3⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수 부분과 분수 부분이 함께 있는 수예요.","두 부분에 모두 6을 곱해야 해요 — ⟨3 2/9⟩ × 6 = ⟨29/9⟩ × 6 = ⟨174/9⟩ = ⟨58/3⟩ = ⟨19 1/3⟩.","여울은 자연수 부분에만 곱해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_challenge#5','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',3,'sa','auto','⟨3 7/10⟩ × 4 > □일 때 □ 안에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u2-C3","difficulty":3,"kind":"sa","stem":"⟨3 7/10⟩ × 4 > □일 때 □ 안에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["먼저 곱을 구해요 — ⟨3 7/10⟩ × 4 = ⟨37/10⟩ × 4 = ⟨148/10⟩ = ⟨74/5⟩ = ⟨14 4/5⟩.","곱은 ⟨14 4/5⟩예요.","⟨14 4/5⟩보다 작은 자연수 가운데 가장 큰 수는 14예요."],"mis":"M5-2-u2-X17","variant_rule":{"alt":[{"stem":"⟨1 3/4⟩ × 6 < □일 때 □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["먼저 곱을 구해요 — ⟨1 3/4⟩ × 6 = ⟨7/4⟩ × 6 = ⟨42/4⟩ = ⟨21/2⟩ = ⟨10 1/2⟩.","곱은 ⟨10 1/2⟩이에요.","⟨10 1/2⟩보다 큰 자연수 가운데 가장 작은 수는 11이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_challenge#6','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',3,'mc','auto','단원 평가예요. ⟨2 1/3⟩ × 2 ○ 5 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X08','M5-2-u2-X17']::text[],true,'{"seq":6,"concept":"M5-2-u2-C3","difficulty":3,"kind":"mc","stem":"단원 평가예요. ⟨2 1/3⟩ × 2 ○ 5 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["⟨2 1/3⟩ × 2 = ⟨7/3⟩ × 2 = ⟨14/3⟩ = ⟨4 2/3⟩예요.","⟨4 2/3⟩ < 5예요.","⟨2 1/3⟩ × 2는 5보다 작아요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. ⟨1 3/8⟩ × 6 ○ 8 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M5-2-u2-X17"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["⟨1 3/8⟩ × 6 = ⟨11/8⟩ × 6 = ⟨66/8⟩ = ⟨33/4⟩ = ⟨8 1/4⟩이에요.","⟨8 1/4⟩ > 8이에요.","⟨1 3/8⟩ × 6은 8보다 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_challenge#7','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',3,'sa','auto','수학익힘 문제예요. 단감을 한 상자에 ⟨5 1/2⟩ kg씩 8상자 샀어요. 산 단감의 무게는 모두 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C3","difficulty":3,"kind":"sa","stem":"수학익힘 문제예요. 단감을 한 상자에 ⟨5 1/2⟩ kg씩 8상자 샀어요. 산 단감의 무게는 모두 몇 kg인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["⟨5 1/2⟩ × 8 = ⟨11/2⟩ × 8이에요.","2와 8을 약분하면 11 × 4 = 44예요.","산 단감은 모두 44 kg이에요."],"mis":"M5-2-u2-X05","variant_rule":{"alt":[{"stem":"문제로 마무리예요. 한 변의 길이가 ⟨9 1/2⟩ m인 정사각형 모양 수영장의 둘레는 몇 m인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["정사각형의 둘레는 (한 변의 길이) × 4예요.","⟨9 1/2⟩ × 4 = ⟨19/2⟩ × 4 = 38이에요.","수영장의 둘레는 38 m예요."]},{"stem":"⟨1 2/3⟩ × 6을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["⟨1 2/3⟩ = ⟨5/3⟩예요.","⟨5/3⟩ × 6 = ⟨30/3⟩ = 10이에요.","결과가 자연수 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_challenge#8','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',4,'mc','auto','사과주스 ⟨1 1/4⟩ L씩 3병을 수직선에 나타냈어요. 1씩 3번 뛰고, ⟨1/4⟩씩 3번 더 뛰었어요. 이 방법을 식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X15']::text[],true,'{"seq":8,"concept":"M5-2-u2-C3","difficulty":4,"kind":"mc","stem":"사과주스 ⟨1 1/4⟩ L씩 3병을 수직선에 나타냈어요. 1씩 3번 뛰고, ⟨1/4⟩씩 3번 더 뛰었어요. 이 방법을 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1 × 3 + ⟨1/4⟩ × 3","correct":true},{"t":"1 × 3 + ⟨1/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1/4⟩ × 3 + 1","mis":"M5-2-u2-X05"},{"t":"(1 + 3) × ⟨1/4⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨1 1/4⟩ = 1 + ⟨1/4⟩ — 자연수 부분과 진분수 부분으로 가를 수 있어요.","1씩 3번은 1 × 3, ⟨1/4⟩씩 3번은 ⟨1/4⟩ × 3이에요.","1 × 3 + ⟨1/4⟩ × 3 = 3 + ⟨3/4⟩ = ⟨3 3/4⟩ L예요."],"variant_rule":{"alt":[{"stem":"형성 평가예요. 수직선에서 ⟨1 3/7⟩씩 2번 뛰어 세었어요. 1씩 2번, ⟨3/7⟩씩 2번으로 나누어 나타낸 식은 어느 것인가요?","options":[{"t":"1 × 2 + ⟨3/7⟩ × 2","correct":true},{"t":"1 × 2 + ⟨3/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨3/7⟩ × 2 + 1","mis":"M5-2-u2-X05"},{"t":"(1 + 2) × ⟨3/7⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨1 3/7⟩ = 1 + ⟨3/7⟩이에요.","1씩 2번과 ⟨3/7⟩씩 2번을 더해요.","1 × 2 + ⟨3/7⟩ × 2 = 2 + ⟨6/7⟩ = ⟨2 6/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_challenge#9','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',4,'mc','auto','계산 결과가 자연수인 것은 어느 것인가요?',ARRAY['M5-2-u2-X12']::text[],true,'{"seq":9,"concept":"M5-2-u2-C3","difficulty":4,"kind":"mc","stem":"계산 결과가 자연수인 것은 어느 것인가요?","options":[{"t":"⟨5 2/3⟩ × 9","correct":true},{"t":"⟨1 3/8⟩ × 6","mis":"M5-2-u2-X12"},{"t":"⟨2 4/7⟩ × 3","mis":"M5-2-u2-X12"},{"t":"⟨3 2/5⟩ × 4","mis":"M5-2-u2-X12"}],"explanation":["⟨5 2/3⟩ × 9 = ⟨17/3⟩ × 9 = 51이에요.","⟨1 3/8⟩ × 6 = ⟨8 1/4⟩, ⟨2 4/7⟩ × 3 = ⟨7 5/7⟩, ⟨3 2/5⟩ × 4 = ⟨13 3/5⟩이에요.","가분수의 분자와 자연수를 곱한 수가 분모로 나누어떨어져야 자연수예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산 결과가 자연수인 것은 어느 것인가요?","options":[{"t":"⟨1 2/3⟩ × 6","correct":true},{"t":"⟨2 1/3⟩ × 5","mis":"M5-2-u2-X12"},{"t":"⟨3 2/9⟩ × 6","mis":"M5-2-u2-X12"},{"t":"⟨1 3/5⟩ × 2","mis":"M5-2-u2-X12"}],"explanation":["⟨1 2/3⟩ × 6 = ⟨5/3⟩ × 6 = 10이에요.","⟨2 1/3⟩ × 5 = ⟨11 2/3⟩, ⟨3 2/9⟩ × 6 = ⟨19 1/3⟩, ⟨1 3/5⟩ × 2 = ⟨3 1/5⟩이에요.","분자와 자연수의 곱이 분모로 나누어떨어지는지 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L03_challenge#10','math',5,2,'u2','L03','tb_g5_2_math_u2_L03_challenge','lesson_challenge','M5-2-u2-C3',4,'essay','teacher','잘못 계산한 곳을 찾아 바르게 계산해 보세요. 어떤 친구가 ⟨1 1/6⟩ × 15를 「6과 15를 먼저 3으로 약분하여 ⟨1 1/2⟩ × 5」로 바꾸어 계산했어요. 잘못된 까닭을 쓰고, 대분수를 가분수로 나타내어 바르게 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C3","difficulty":4,"kind":"essay","stem":"잘못 계산한 곳을 찾아 바르게 계산해 보세요. 어떤 친구가 ⟨1 1/6⟩ × 15를 「6과 15를 먼저 3으로 약분하여 ⟨1 1/2⟩ × 5」로 바꾸어 계산했어요. 잘못된 까닭을 쓰고, 대분수를 가분수로 나타내어 바르게 계산해 보세요.","answer_guide":{"answer":"예: 대분수 ⟨1 1/6⟩을 가분수로 나타내지 않고 분모 6과 15를 먼저 약분하면, 자연수 부분 1은 약분되지 않은 채 남아 값이 달라진다. 대분수를 가분수로 나타낸 후 약분해야 한다. ⟨1 1/6⟩ = ⟨7/6⟩이므로 ⟨7/6⟩ × 15 = ⟨35/2⟩ = ⟨17 1/2⟩이다.","scoring_points":["가분수로 나타내지 않고 먼저 약분해서 틀렸다고 썼는가","⟨1 1/6⟩ = ⟨7/6⟩로 고쳤는가","⟨17 1/2⟩(= ⟨35/2⟩)를 구했는가"]},"explanation":["먼저 약분하면 자연수 부분 1이 약분에서 빠져요.","⟨1 1/6⟩ = ⟨7/6⟩이에요.","⟨7/6⟩ × 15 = ⟨35/2⟩ = ⟨17 1/2⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_basic#1','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',1,'sa','auto','6 kg의 ⟨1/3⟩은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u2-C4","difficulty":1,"kind":"sa","stem":"6 kg의 ⟨1/3⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["6을 똑같이 3으로 나누면 한 묶음은 6 ÷ 3 = 2예요.","그중의 1이니 2 × 1 = 2예요.","식으로는 6 × ⟨1/3⟩ = ⟨6/3⟩ = 2예요."],"mis":"M5-2-u2-X07","asset":{"type":"fbar","bars":[{"den":6,"num":2,"grp":2,"label":"흙 6 kg을 똑같이 3묶음으로"}]},"variant_rule":{"alt":[{"stem":"6 kg의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["6을 똑같이 3으로 나누면 한 묶음은 6 ÷ 3 = 2예요.","그중의 2니 2 × 2 = 4예요.","식으로는 6 × ⟨2/3⟩ = ⟨12/3⟩ = 4예요."],"asset":{"type":"fbar","bars":[{"den":6,"num":4,"grp":2,"label":"흙 6 kg을 똑같이 3묶음으로"}]}},{"stem":"10개의 ⟨1/5⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["10을 똑같이 5로 나누면 한 묶음은 10 ÷ 5 = 2예요.","그중의 1이니 2 × 1 = 2예요.","식으로는 10 × ⟨1/5⟩ = ⟨10/5⟩ = 2예요."],"asset":{"type":"fbar","bars":[{"den":10,"num":2,"grp":2,"label":"바둑돌 10개를 똑같이 5묶음으로"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_basic#2','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',1,'mc','auto','6 × ⟨1/3⟩과 같은 뜻인 것은 어느 것인가요?',ARRAY['M5-2-u2-X07','M5-2-u2-X15']::text[],true,'{"seq":2,"concept":"M5-2-u2-C4","difficulty":1,"kind":"mc","stem":"6 × ⟨1/3⟩과 같은 뜻인 것은 어느 것인가요?","options":[{"t":"6을 똑같이 3으로 나눈 것 중의 1","correct":true},{"t":"6을 똑같이 1로 나눈 것 중의 3","mis":"M5-2-u2-X07"},{"t":"6을 3번 더한 것","mis":"M5-2-u2-X07"},{"t":"6에서 ⟨1/3⟩을 뺀 것","mis":"M5-2-u2-X15"}],"explanation":["「6의 ⟨1/3⟩」과 「6 × ⟨1/3⟩」은 같은 말이에요.","전체 6을 분모 3만큼 똑같이 나눈 것 중의 분자 1만큼이에요.","6 × ⟨1/3⟩ = ⟨6/3⟩ = 2예요."],"variant_rule":{"alt":[{"stem":"2 × ⟨3/5⟩과 같은 뜻인 것은 어느 것인가요?","options":[{"t":"2를 똑같이 5로 나눈 것 중의 3","correct":true},{"t":"2를 똑같이 3으로 나눈 것 중의 5","mis":"M5-2-u2-X07"},{"t":"2를 5번 더한 것","mis":"M5-2-u2-X07"},{"t":"2에서 ⟨3/5⟩을 뺀 것","mis":"M5-2-u2-X15"}],"explanation":["「2의 ⟨3/5⟩」과 「2 × ⟨3/5⟩」은 같은 말이에요.","전체 2를 분모 5만큼 똑같이 나눈 것 중의 분자 3만큼이에요.","2 × ⟨3/5⟩ = ⟨6/5⟩ = ⟨1 1/5⟩이에요."]},{"stem":"10 × ⟨2/5⟩와 같은 뜻인 것은 어느 것인가요?","options":[{"t":"10을 똑같이 5로 나눈 것 중의 2","correct":true},{"t":"10을 똑같이 2로 나눈 것 중의 5","mis":"M5-2-u2-X07"},{"t":"10을 5번 더한 것","mis":"M5-2-u2-X07"},{"t":"10에서 ⟨2/5⟩를 뺀 것","mis":"M5-2-u2-X15"}],"explanation":["「10의 ⟨2/5⟩」와 「10 × ⟨2/5⟩」는 같은 말이에요.","전체 10을 분모 5만큼 똑같이 나눈 것 중의 분자 2만큼이에요.","10 × ⟨2/5⟩ = ⟨20/5⟩ = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_basic#3','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',1,'mc','auto','수직선에서 0부터 2까지를 똑같이 5로 나누었어요. 2 × ⟨1/5⟩은 얼마인가요?',ARRAY['M5-2-u2-X18','M5-2-u2-X02','M5-2-u2-X10']::text[],true,'{"seq":3,"concept":"M5-2-u2-C4","difficulty":1,"kind":"mc","stem":"수직선에서 0부터 2까지를 똑같이 5로 나누었어요. 2 × ⟨1/5⟩은 얼마인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨1/5⟩","mis":"M5-2-u2-X18"},{"t":"⟨1/10⟩","mis":"M5-2-u2-X02"},{"t":"⟨5/2⟩","mis":"M5-2-u2-X10"}],"explanation":["2를 똑같이 5로 나눈 것 중의 1이에요.","1을 5칸으로 나누면 한 칸은 ⟨1/5⟩ — 그 칸이 2개예요.","2 × ⟨1/5⟩ = ⟨2/5⟩ — ⟨2/5⟩를 1의 ⟨1/5⟩로 읽지 않도록 해요."],"asset":{"type":"fbar","bars":[{"den":5,"num":1,"label":"2를 똑같이 5로 나눈 것 중의 1"},{"den":10,"num":2,"label":"작은 눈금 한 칸은 ⟨1/5⟩"}]},"variant_rule":{"alt":[{"stem":"수직선에서 0부터 3까지를 똑같이 4로 나누었어요. 3 × ⟨1/4⟩은 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨1/4⟩","mis":"M5-2-u2-X18"},{"t":"⟨1/12⟩","mis":"M5-2-u2-X02"},{"t":"⟨4/3⟩","mis":"M5-2-u2-X10"}],"explanation":["3을 똑같이 4로 나눈 것 중의 1이에요.","1을 4칸으로 나누면 한 칸은 ⟨1/4⟩ — 그 칸이 3개예요.","3 × ⟨1/4⟩ = ⟨3/4⟩ — ⟨3/4⟩을 1의 ⟨1/4⟩로 읽지 않도록 해요."],"asset":{"type":"fbar","bars":[{"den":4,"num":1,"label":"3을 똑같이 4로 나눈 것 중의 1"},{"den":12,"num":3,"label":"작은 눈금 한 칸은 ⟨1/4⟩"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_basic#4','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',1,'mc','auto','12 × ⟨1/4⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":4,"concept":"M5-2-u2-C4","difficulty":1,"kind":"mc","stem":"12 × ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"3","correct":true},{"t":"⟨12/48⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/48⟩","mis":"M5-2-u2-X02"},{"t":"⟨3 1/4⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","12 × ⟨1/4⟩ = ⟨12/4⟩ = 3이에요.","계산 결과는 3이에요."],"variant_rule":{"alt":[{"stem":"7 × ⟨3/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 1/5⟩","correct":true},{"t":"⟨21/35⟩","mis":"M5-2-u2-X01"},{"t":"⟨1 2/5⟩","mis":"M5-2-u2-X07"},{"t":"⟨3/35⟩","mis":"M5-2-u2-X02"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","7 × ⟨3/5⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요.","계산 결과는 ⟨4 1/5⟩이에요."]},{"stem":"9 × ⟨5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨7 1/2⟩","correct":true},{"t":"⟨45/54⟩","mis":"M5-2-u2-X01"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X07"},{"t":"⟨5/54⟩","mis":"M5-2-u2-X02"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","9 × ⟨5/6⟩ = ⟨45/6⟩ = ⟨15/2⟩ = ⟨7 1/2⟩이에요.","계산 결과는 ⟨7 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_basic#5','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',2,'mc','auto','흙 6 kg 가운데 누나는 ⟨1/3⟩을, 나는 ⟨2/3⟩를 써서 그릇을 만들었어요. 흙을 더 많이 쓴 사람과 그 양으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X07','M5-2-u2-X12']::text[],false,'{"seq":5,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"흙 6 kg 가운데 누나는 ⟨1/3⟩을, 나는 ⟨2/3⟩를 써서 그릇을 만들었어요. 흙을 더 많이 쓴 사람과 그 양으로 알맞은 것은 어느 것인가요?","options":[{"t":"나, 4 kg","correct":true},{"t":"누나, 2 kg","mis":"M5-2-u2-X17"},{"t":"나, ⟨2/3⟩ kg","mis":"M5-2-u2-X07"},{"t":"나, 5 kg","mis":"M5-2-u2-X12"}],"explanation":["누나: 6 × ⟨1/3⟩ = ⟨6/3⟩ = 2 kg이에요.","나: 6 × ⟨2/3⟩ = ⟨12/3⟩ = 4 kg이에요.","2 < 4라 내가 더 많이 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_basic#6','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',2,'mc','auto','들이가 4 L인 항아리에 간장이 ⟨5/12⟩만큼 들어 있어요. 항아리에 든 간장은 몇 L인가요?',ARRAY['M5-2-u2-X07','M5-2-u2-X17','M5-2-u2-X01']::text[],true,'{"seq":6,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"들이가 4 L인 항아리에 간장이 ⟨5/12⟩만큼 들어 있어요. 항아리에 든 간장은 몇 L인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-2-u2-X07"},{"t":"⟨5/12⟩","mis":"M5-2-u2-X17"},{"t":"⟨20/48⟩","mis":"M5-2-u2-X01"}],"explanation":["4 L의 ⟨5/12⟩만큼이니 4 × ⟨5/12⟩예요.","4 × ⟨5/12⟩ = ⟨20/12⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요.","항아리에는 간장 ⟨1 2/3⟩ L가 들어 있어요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 빵을 만들기 위해 밀가루 3 kg의 ⟨3/5⟩을 사용했어요. 사용한 밀가루는 몇 kg인가요?","options":[{"t":"⟨1 4/5⟩","correct":true},{"t":"⟨9/15⟩","mis":"M5-2-u2-X01"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X07"},{"t":"⟨3/15⟩","mis":"M5-2-u2-X02"}],"explanation":["3 kg의 ⟨3/5⟩이니 3 × ⟨3/5⟩이에요.","3 × ⟨3/5⟩ = ⟨9/5⟩ = ⟨1 4/5⟩예요.","사용한 밀가루는 ⟨1 4/5⟩ kg이에요."]},{"stem":"형성 평가예요. 이안이는 여름 방학 동안 책 25권을 읽었는데 그중 ⟨2/5⟩가 위인전이었어요. 이안이가 읽은 위인전은 몇 권인가요?","options":[{"t":"10","correct":true},{"t":"⟨50/125⟩","mis":"M5-2-u2-X01"},{"t":"5","mis":"M5-2-u2-X07"},{"t":"⟨2/125⟩","mis":"M5-2-u2-X02"}],"explanation":["25 권의 ⟨2/5⟩니 25 × ⟨2/5⟩예요.","25 × ⟨2/5⟩ = ⟨50/5⟩ = 10이에요.","이안이가 읽은 위인전은 10권이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_basic#7','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',2,'mc','auto','⟨3/5⟩ × 2와 2 × ⟨3/5⟩을 바르게 설명한 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X15','M5-2-u2-X07']::text[],false,'{"seq":7,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"⟨3/5⟩ × 2와 2 × ⟨3/5⟩을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"뜻은 다르지만 계산 결과는 같다","correct":true},{"t":"뜻도 같고 계산 결과도 같다","mis":"M5-2-u2-X17"},{"t":"뜻이 다르니 계산 결과도 다르다","mis":"M5-2-u2-X15"},{"t":"2 × ⟨3/5⟩은 계산할 수 없다","mis":"M5-2-u2-X07"}],"explanation":["⟨3/5⟩ × 2는 ⟨3/5⟩을 2번 더한 것이에요.","2 × ⟨3/5⟩은 2의 ⟨3/5⟩만큼이에요.","뜻은 다르지만 둘 다 ⟨1 1/5⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_basic#8','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',2,'mc','auto','형성 평가예요. 계산 결과가 다른 하나는 어느 것인가요?',ARRAY['M5-2-u2-X17']::text[],true,'{"seq":8,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"형성 평가예요. 계산 결과가 다른 하나는 어느 것인가요?","options":[{"t":"9 × ⟨5/6⟩","correct":true},{"t":"12 × ⟨2/9⟩","mis":"M5-2-u2-X17"},{"t":"4 × ⟨2/3⟩","mis":"M5-2-u2-X17"}],"explanation":["12 × ⟨2/9⟩ = ⟨24/9⟩ = ⟨8/3⟩ = ⟨2 2/3⟩예요.","4 × ⟨2/3⟩ = ⟨8/3⟩ = ⟨2 2/3⟩예요.","9 × ⟨5/6⟩ = ⟨45/6⟩ = ⟨15/2⟩ = ⟨7 1/2⟩ — 이것만 달라요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 12 × ⟨3/4⟩의 계산 결과는 어느 것인가요?","options":[{"t":"9","correct":true},{"t":"16","mis":"M5-2-u2-X02"},{"t":"3","mis":"M5-2-u2-X07"}],"explanation":["12를 똑같이 4로 나누면 한 묶음은 3이에요.","그중의 3묶음이니 3 × 3 = 9예요.","12 × ⟨3/4⟩ = ⟨36/4⟩ = 9 — 16은 12에 ⟨4/3⟩를 곱한 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_basic#9','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',2,'ox','auto','6 × ⟨2/3⟩ = 12예요.',ARRAY['M5-2-u2-X07']::text[],true,'{"seq":9,"concept":"M5-2-u2-C4","difficulty":2,"kind":"ox","stem":"6 × ⟨2/3⟩ = 12예요.","answer":"X","reason_options":[{"t":"6을 3으로 나눈 것 중의 2라서 4이므로","correct":true},{"t":"6에 분자 2를 곱하면 되므로","mis":"M5-2-u2-X07"}],"mis":"M5-2-u2-X07","explanation":["6을 똑같이 3으로 나누면 한 묶음은 2예요.","두 묶음은 2 + 2 = 4예요.","6 × ⟨2/3⟩ = ⟨12/3⟩ = 4예요."],"variant_rule":{"alt":[{"stem":"12 × ⟨1/4⟩은 12를 4로 나눈 것과 같아요.","answer":"O","reason_options":[{"t":"12의 ⟨1/4⟩은 12를 똑같이 4로 나눈 것 중의 1이므로","correct":true},{"t":"12에 4를 곱한 것이므로","mis":"M5-2-u2-X07"}],"explanation":["12를 똑같이 4로 나누면 한 묶음은 3이에요.","12 × ⟨1/4⟩ = 3이에요.","12 ÷ 4 = 3 — 맞아요."]},{"stem":"1시간의 ⟨1/5⟩은 12분이에요.","answer":"O","reason_options":[{"t":"60분의 ⟨1/5⟩은 60 ÷ 5 = 12분이므로","correct":true},{"t":"1시간은 100분이므로","mis":"M5-2-u2-X07"}],"explanation":["1시간은 60분이에요.","60 × ⟨1/5⟩ = 12예요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_basic#10','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',3,'sa','auto','수학익힘 문제예요. 재우는 텃밭에서 재배한 수세미 열매를 1시간의 ⟨1/5⟩ 동안 데쳤어요. 수세미 열매를 데친 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u2-C4","difficulty":3,"kind":"sa","stem":"수학익힘 문제예요. 재우는 텃밭에서 재배한 수세미 열매를 1시간의 ⟨1/5⟩ 동안 데쳤어요. 수세미 열매를 데친 시간은 몇 분인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["1시간은 60분이에요.","60 × ⟨1/5⟩ = ⟨60/5⟩ = 12예요.","수세미 열매를 데친 시간은 12분이에요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"문제로 마무리예요. 지한이는 토요일에 하루 24시간의 ⟨1/8⟩만큼 책을 읽었어요. 지한이가 토요일에 책을 읽은 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["하루는 24시간이에요.","24 × ⟨1/8⟩ = ⟨24/8⟩ = 3이에요.","지한이가 책을 읽은 시간은 3시간이에요."]},{"stem":"단원 평가예요. 떨어진 높이의 ⟨5/9⟩만큼 튀어 오르는 공을 높이가 72 cm인 곳에서 떨어뜨렸어요. 첫 번째로 튀어 오른 공의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["튀어 오른 높이는 72 cm의 ⟨5/9⟩예요.","72 × ⟨5/9⟩ = ⟨360/9⟩ = 40이에요.","첫 번째로 튀어 오른 높이는 40 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_challenge#1','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',2,'sa','auto','7 × ⟨3/5⟩을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u2-C4","difficulty":2,"kind":"sa","stem":"7 × ⟨3/5⟩을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["7 × ⟨3/5⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요.","계산 결과는 ⟨4 1/5⟩이에요.","그래서 자연수 부분은 4예요."],"mis":"M5-2-u2-X17","variant_rule":{"alt":[{"stem":"9 × ⟨5/6⟩를 계산하여 기약분수인 대분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["9 × ⟨5/6⟩ = ⟨45/6⟩ = ⟨15/2⟩ = ⟨7 1/2⟩이에요.","계산 결과는 ⟨7 1/2⟩이에요.","그래서 분자는 1이에요."]},{"stem":"14 × ⟨24/35⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["14 × ⟨24/35⟩ = ⟨336/35⟩ = ⟨48/5⟩ = ⟨9 3/5⟩이에요.","계산 결과는 ⟨9 3/5⟩이에요.","그래서 자연수 부분은 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_challenge#2','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',2,'mc','auto','2 × ⟨3/5⟩을 계산하는 과정으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X15','M5-2-u2-X01','M5-2-u2-X02']::text[],false,'{"seq":2,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"2 × ⟨3/5⟩을 계산하는 과정으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 × ⟨1/5⟩ × 3 = ⟨2/5⟩ × 3 = ⟨6/5⟩","correct":true},{"t":"2 × ⟨1/5⟩에 3을 더해 ⟨2/5⟩ + 3","mis":"M5-2-u2-X15"},{"t":"분모와 분자에 모두 2를 곱해 ⟨6/10⟩","mis":"M5-2-u2-X01"},{"t":"자연수 2를 분모에 곱해 ⟨3/10⟩","mis":"M5-2-u2-X02"}],"explanation":["2 × ⟨3/5⟩은 2 × ⟨1/5⟩의 3배예요.","2 × ⟨1/5⟩ = ⟨2/5⟩이고, ⟨2/5⟩ × 3 = ⟨6/5⟩이에요.","2 × ⟨3/5⟩ = ⟨6/5⟩ = ⟨1 1/5⟩ — 분모는 그대로 두고 자연수와 분자를 곱해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_challenge#3','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',3,'mc','auto','수학익힘 문제예요. 수 카드 5, 8, 9 가운데 2장을 골라 한 번씩만 써서 진분수를 만들고, 6 × (진분수)의 계산 결과가 가장 작게 하려고 해요. 가장 작은 계산 결과는 얼마인가요?',ARRAY['M5-2-u2-X17']::text[],false,'{"seq":3,"concept":"M5-2-u2-C4","difficulty":3,"kind":"mc","stem":"수학익힘 문제예요. 수 카드 5, 8, 9 가운데 2장을 골라 한 번씩만 써서 진분수를 만들고, 6 × (진분수)의 계산 결과가 가장 작게 하려고 해요. 가장 작은 계산 결과는 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨5 1/3⟩","mis":"M5-2-u2-X17"},{"t":"⟨3 3/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨6 3/4⟩","mis":"M5-2-u2-X17"}],"explanation":["같은 6에 곱하니 곱하는 진분수가 가장 작아야 해요.","만들 수 있는 진분수 ⟨5/8⟩, ⟨5/9⟩, ⟨8/9⟩ 가운데 가장 작은 것은 ⟨5/9⟩예요.","6 × ⟨5/9⟩ = ⟨30/9⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_challenge#4','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',3,'error','auto','6 × ⟨2/3⟩를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u2-X07','M5-2-u2-X17']::text[],true,'{"seq":4,"concept":"M5-2-u2-C4","difficulty":3,"kind":"error","stem":"6 × ⟨2/3⟩를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「6을 3으로 나누면 끝이니까 2야.」","correct":true,"mis_target":"M5-2-u2-X07"},{"t":"순달 — 「6의 ⟨2/3⟩이니까 4야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「6 × ⟨2/3⟩ = ⟨12/3⟩ = 4야.」","mis":"M5-2-u2-X17"}],"explanation":["6을 3으로 나눈 2는 한 묶음이에요.","그중의 2묶음이니 2 × 2 = 4예요.","여울은 한 묶음에서 멈춰 틀렸어요."],"variant_rule":{"alt":[{"stem":"12 × ⟨3/4⟩을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「12를 4로 나누면 끝이니까 3이야.」","correct":true,"mis_target":"M5-2-u2-X07"},{"t":"순달 — 「12의 ⟨3/4⟩이니까 9야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「12 × ⟨3/4⟩ = ⟨36/4⟩ = 9야.」","mis":"M5-2-u2-X17"}],"explanation":["12를 4로 나눈 3은 한 묶음이에요.","그중의 3묶음이니 3 × 3 = 9예요.","여울은 한 묶음에서 멈춰 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_challenge#5','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',3,'mc','auto','6 × ⟨1/3⟩은 6을 똑같이 3묶음으로 나누면 되지만, 2 × ⟨1/5⟩은 2를 똑같이 5묶음으로 나누기 어려워요. 2 × ⟨1/5⟩을 바르게 생각한 것은 어느 것인가요?',ARRAY['M5-2-u2-X18','M5-2-u2-X17','M5-2-u2-X15']::text[],false,'{"seq":5,"concept":"M5-2-u2-C4","difficulty":3,"kind":"mc","stem":"6 × ⟨1/3⟩은 6을 똑같이 3묶음으로 나누면 되지만, 2 × ⟨1/5⟩은 2를 똑같이 5묶음으로 나누기 어려워요. 2 × ⟨1/5⟩을 바르게 생각한 것은 어느 것인가요?","options":[{"t":"1을 각각 5칸으로 나누면 2는 10칸 — 그 가운데 2칸이라 ⟨2/5⟩","correct":true},{"t":"2를 5로 나누면 한 칸은 ⟨1/5⟩이라 ⟨1/5⟩","mis":"M5-2-u2-X18"},{"t":"5를 2로 나누어야 하니 ⟨5/2⟩","mis":"M5-2-u2-X17"},{"t":"나누어떨어지지 않으니 계산할 수 없다","mis":"M5-2-u2-X15"}],"explanation":["자연수가 분모의 배수가 아니면 1을 각각 분모만큼 나누어 생각해요.","1을 5칸으로 나누면 한 칸은 ⟨1/5⟩이고, 0부터 2까지는 10칸이에요.","2를 5로 나눈 한 묶음은 그중 2칸 — 2 × ⟨1/5⟩ = ⟨2/5⟩예요."],"asset":{"type":"fbar","bars":[{"den":10,"num":2,"label":"0부터 2까지 — 1을 각각 5칸으로"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_challenge#6','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',3,'sa','auto','바둑돌 10개를 똑같이 5묶음으로 나누었어요. 10 × ⟨2/5⟩는 바둑돌 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u2-C4","difficulty":3,"kind":"sa","stem":"바둑돌 10개를 똑같이 5묶음으로 나누었어요. 10 × ⟨2/5⟩는 바둑돌 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["10개를 똑같이 5묶음으로 나누면 한 묶음은 2개예요.","그중의 2묶음이니 2 × 2 = 4예요.","10 × ⟨2/5⟩ = ⟨20/5⟩ = 4(개)예요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"형성 평가예요. 책 25권 가운데 ⟨2/5⟩는 몇 권인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["25를 똑같이 5묶음으로 나누면 한 묶음은 5예요.","그중의 2묶음이니 5 × 2 = 10이에요.","25 × ⟨2/5⟩ = 10(권)이에요."]},{"stem":"단원 평가예요. 16 × ⟨3/4⟩을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["16을 똑같이 4묶음으로 나누면 한 묶음은 4예요.","그중의 3묶음이니 4 × 3 = 12예요.","16 × ⟨3/4⟩ = ⟨48/4⟩ = 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_challenge#7','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',3,'mc','auto','단원 평가예요. 2 × ⟨3/8⟩ ○ 1 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X08','M5-2-u2-X17']::text[],true,'{"seq":7,"concept":"M5-2-u2-C4","difficulty":3,"kind":"mc","stem":"단원 평가예요. 2 × ⟨3/8⟩ ○ 1 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["2 × ⟨3/8⟩ = ⟨6/8⟩ = ⟨3/4⟩이에요.","⟨3/4⟩ < 1이에요.","1보다 작은 ⟨3/8⟩을 곱해 2보다 작아졌고, 1보다도 작아요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 8 × ⟨3/4⟩ ○ 8 × ⟨1 1/10⟩ — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["8에 1보다 작은 ⟨3/4⟩을 곱하면 8보다 작아지고, 1보다 큰 ⟨1 1/10⟩을 곱하면 8보다 커져요.","8 × ⟨3/4⟩ = 6, 8 × ⟨1 1/10⟩ = ⟨8 4/5⟩예요.","6 < ⟨8 4/5⟩ — 계산하기 전에 곱하는 수로 어림할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_challenge#8','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',4,'sa','auto','6 × ⟨□/3⟩ = 4일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u2-C4","difficulty":4,"kind":"sa","stem":"6 × ⟨□/3⟩ = 4일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["2"],"explanation":["6을 똑같이 3으로 나누면 한 묶음은 2예요.","2묶음이 4니 □ = 4 ÷ 2 = 2예요.","6 × ⟨2/3⟩ = 4 — 맞아요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"16 × ⟨□/4⟩ = 12일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["3"],"explanation":["16을 똑같이 4로 나누면 한 묶음은 4예요.","3묶음이 12니 □ = 12 ÷ 4 = 3이에요.","16 × ⟨3/4⟩ = 12 — 맞아요."]},{"stem":"72 × ⟨□/9⟩ = 40일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["5"],"explanation":["72를 똑같이 9로 나누면 한 묶음은 8이에요.","5묶음이 40이니 □ = 40 ÷ 8 = 5예요.","72 × ⟨5/9⟩ = 40 — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_challenge#9','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',4,'mc','auto','수세미 열매를 1시간의 ⟨1/5⟩ 동안 데쳤고, 지한이는 하루의 ⟨1/8⟩만큼 책을 읽었어요. 두 시간을 바르게 견준 것은 어느 것인가요?',ARRAY['M5-2-u2-X18','M5-2-u2-X17']::text[],false,'{"seq":9,"concept":"M5-2-u2-C4","difficulty":4,"kind":"mc","stem":"수세미 열매를 1시간의 ⟨1/5⟩ 동안 데쳤고, 지한이는 하루의 ⟨1/8⟩만큼 책을 읽었어요. 두 시간을 바르게 견준 것은 어느 것인가요?","options":[{"t":"하루의 ⟨1/8⟩이 더 길다","correct":true},{"t":"1시간의 ⟨1/5⟩이 더 길다","mis":"M5-2-u2-X18"},{"t":"⟨1/5⟩이 ⟨1/8⟩보다 크니 두 시간은 같다","mis":"M5-2-u2-X18"},{"t":"두 시간은 같다","mis":"M5-2-u2-X17"}],"explanation":["1시간의 ⟨1/5⟩은 60 × ⟨1/5⟩ = 12(분)이에요.","하루의 ⟨1/8⟩은 24 × ⟨1/8⟩ = 3(시간)이고, 3시간은 180분이에요.","전체(기준)가 다르면 분수만 보고 견줄 수 없어요 — 하루의 ⟨1/8⟩이 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L04_challenge#10','math',5,2,'u2','L04','tb_g5_2_math_u2_L04_challenge','lesson_challenge','M5-2-u2-C4',4,'essay','teacher','도예가가 꿈인 나와 누나가 흙 6 kg으로 그릇을 만들었어요. 누나는 흙 6 kg의 ⟨1/3⟩을, 나는 6 kg의 ⟨2/3⟩를 사용했어요. 두 사람이 사용한 흙의 양을 「전체를 똑같이 나눈 것 중의 얼마」로 설명하며 구하고, ⟨3/5⟩ × 2와 2 × ⟨3/5⟩의 뜻과 계산 결과를 견주어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C4","difficulty":4,"kind":"essay","stem":"도예가가 꿈인 나와 누나가 흙 6 kg으로 그릇을 만들었어요. 누나는 흙 6 kg의 ⟨1/3⟩을, 나는 6 kg의 ⟨2/3⟩를 사용했어요. 두 사람이 사용한 흙의 양을 「전체를 똑같이 나눈 것 중의 얼마」로 설명하며 구하고, ⟨3/5⟩ × 2와 2 × ⟨3/5⟩의 뜻과 계산 결과를 견주어 써 보세요.","answer_guide":{"answer":"예: 전체 6을 똑같이 3으로 나눈 것 중의 1은 2이므로 누나는 6 × ⟨1/3⟩ = 2(kg)을 썼다. 6을 똑같이 3으로 나눈 것 중의 2는 4이므로 나는 6 × ⟨2/3⟩ = 4(kg)을 썼다. ⟨3/5⟩ × 2는 ⟨3/5⟩을 두 번 더한 것이고 2 × ⟨3/5⟩은 2의 ⟨3/5⟩만큼으로 뜻은 다르지만, 계산 결과는 둘 다 ⟨6/5⟩ = ⟨1 1/5⟩로 같다.","scoring_points":["6을 3으로 나눈 한 묶음 2를 찾았는가","누나 2 kg, 나 4 kg을 구했는가","두 곱셈의 뜻은 다르지만 결과는 ⟨1 1/5⟩로 같다고 썼는가"]},"explanation":["6을 똑같이 3으로 나누면 한 묶음은 2예요.","누나는 2 kg, 나는 4 kg을 썼어요.","⟨3/5⟩ × 2와 2 × ⟨3/5⟩은 뜻은 달라도 ⟨1 1/5⟩로 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_basic#1','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',1,'mc','auto','집 앞에 가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양의 텃밭이 있어요. 텃밭의 넓이를 구하는 식은 어느 것인가요?',ARRAY['M5-2-u2-X15','M5-2-u2-X17']::text[],true,'{"seq":1,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"집 앞에 가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양의 텃밭이 있어요. 텃밭의 넓이를 구하는 식은 어느 것인가요?","options":[{"t":"2 × ⟨1 2/5⟩","correct":true},{"t":"2 + ⟨1 2/5⟩","mis":"M5-2-u2-X15"},{"t":"(2 + ⟨1 2/5⟩) × 2","mis":"M5-2-u2-X15"},{"t":"⟨1 2/5⟩ × 2","mis":"M5-2-u2-X17"}],"explanation":["넓이는 (가로) × (세로)로 구해요.","두 길이를 곱하는 곱셈식이에요.","식은 2 × ⟨1 2/5⟩예요."],"variant_rule":{"alt":[{"stem":"형성 평가예요. 가로가 12 cm, 세로가 ⟨2 5/8⟩ cm인 직사각형의 넓이를 구하는 식은 어느 것인가요?","options":[{"t":"12 × ⟨2 5/8⟩","correct":true},{"t":"12 + ⟨2 5/8⟩","mis":"M5-2-u2-X15"},{"t":"(12 + ⟨2 5/8⟩) × 2","mis":"M5-2-u2-X15"},{"t":"⟨2 5/8⟩ × 2","mis":"M5-2-u2-X17"}],"explanation":["넓이는 (가로) × (세로)로 구해요.","두 길이를 곱하는 곱셈식이에요.","식은 12 × ⟨2 5/8⟩예요."]},{"stem":"수학익힘 문제예요. 밑변의 길이가 2 cm, 높이가 ⟨1 7/10⟩ cm인 평행사변형의 넓이를 구하는 식은 어느 것인가요?","options":[{"t":"2 × ⟨1 7/10⟩","correct":true},{"t":"2 + ⟨1 7/10⟩","mis":"M5-2-u2-X15"},{"t":"(2 + ⟨1 7/10⟩) × 2","mis":"M5-2-u2-X15"},{"t":"⟨1 7/10⟩ × 2","mis":"M5-2-u2-X17"}],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)로 구해요.","두 길이를 곱하는 곱셈식이에요.","식은 2 × ⟨1 7/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_basic#2','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',1,'mc','auto','2 × ⟨1 2/5⟩를 대분수를 둘로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X15']::text[],true,'{"seq":2,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"2 × ⟨1 2/5⟩를 대분수를 둘로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 × 1 + 2 × ⟨2/5⟩","correct":true},{"t":"2 × 1 + ⟨2/5⟩","mis":"M5-2-u2-X05"},{"t":"1 + 2 × ⟨2/5⟩","mis":"M5-2-u2-X05"},{"t":"2 × 1 × ⟨2/5⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨1 2/5⟩ = 1 + ⟨2/5⟩예요.","2를 두 부분에 모두 곱해 더해요.","2 × 1 + 2 × ⟨2/5⟩ = 2 + ⟨4/5⟩ = ⟨2 4/5⟩예요."],"variant_rule":{"alt":[{"stem":"3 × ⟨2 1/2⟩을 대분수를 둘로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 × 2 + 3 × ⟨1/2⟩","correct":true},{"t":"3 × 2 + ⟨1/2⟩","mis":"M5-2-u2-X05"},{"t":"2 + 3 × ⟨1/2⟩","mis":"M5-2-u2-X05"},{"t":"3 × 2 × ⟨1/2⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨2 1/2⟩ = 2 + ⟨1/2⟩이에요.","3을 두 부분에 모두 곱해 더해요.","3 × 2 + 3 × ⟨1/2⟩ = 6 + ⟨1 1/2⟩ = ⟨7 1/2⟩이에요."]},{"stem":"8 × ⟨1 5/6⟩를 대분수를 둘로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"8 × 1 + 8 × ⟨5/6⟩","correct":true},{"t":"8 × 1 + ⟨5/6⟩","mis":"M5-2-u2-X05"},{"t":"1 + 8 × ⟨5/6⟩","mis":"M5-2-u2-X05"},{"t":"8 × 1 × ⟨5/6⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨1 5/6⟩ = 1 + ⟨5/6⟩예요.","8을 두 부분에 모두 곱해 더해요.","8 × 1 + 8 × ⟨5/6⟩ = 8 + ⟨6 2/3⟩ = ⟨14 2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_basic#3','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',1,'mc','auto','5 × ⟨2/3⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":3,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"5 × ⟨2/3⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"5보다 작다","correct":true},{"t":"5보다 크다","mis":"M5-2-u2-X08"},{"t":"5와 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨2/3⟩가 1보다 작아요.","5 × ⟨2/3⟩ = ⟨3 1/3⟩이에요.","그래서 「5보다 작다」예요."],"variant_rule":{"alt":[{"stem":"5 × ⟨1 1/9⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"5보다 크다","correct":true},{"t":"5보다 작다","mis":"M5-2-u2-X08"},{"t":"5와 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨1 1/9⟩이 1보다 커요.","5 × ⟨1 1/9⟩ = ⟨5 5/9⟩예요.","그래서 「5보다 크다」예요."]},{"stem":"5 × ⟨19/20⟩의 계산 결과를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"5보다 작다","correct":true},{"t":"5보다 크다","mis":"M5-2-u2-X08"},{"t":"5와 같다","mis":"M5-2-u2-X08"},{"t":"0이 된다","mis":"M5-2-u2-X08"}],"explanation":["곱하는 수 ⟨19/20⟩가 1보다 작아요.","5 × ⟨19/20⟩ = ⟨4 3/4⟩이에요.","그래서 「5보다 작다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_basic#4','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',1,'mc','auto','지난 시간에 배운 것이에요. 3 × ⟨5/12⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X07','M5-2-u2-X02']::text[],true,'{"seq":4,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"지난 시간에 배운 것이에요. 3 × ⟨5/12⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨15/36⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/4⟩","mis":"M5-2-u2-X07"},{"t":"⟨5/36⟩","mis":"M5-2-u2-X02"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","3 × ⟨5/12⟩ = ⟨15/12⟩ = ⟨5/4⟩ = ⟨1 1/4⟩이에요.","계산 결과는 ⟨1 1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"지난 시간에 배운 것이에요. 12 × ⟨3/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 1/2⟩","correct":true},{"t":"⟨36/96⟩","mis":"M5-2-u2-X01"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X07"},{"t":"⟨3/96⟩","mis":"M5-2-u2-X02"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","12 × ⟨3/8⟩ = ⟨36/8⟩ = ⟨9/2⟩ = ⟨4 1/2⟩이에요.","계산 결과는 ⟨4 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_basic#5','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',2,'mc','auto','가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X15']::text[],true,'{"seq":5,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"⟨2 4/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 4/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨6 4/5⟩","mis":"M5-2-u2-X15"}],"explanation":["직사각형의 넓이는 (가로) × (세로) — 2 × ⟨1 2/5⟩예요.","세로를 1과 ⟨2/5⟩로 갈라 더하면 2 × 1 + 2 × ⟨2/5⟩ = 2 + ⟨4/5⟩예요.","2 × ⟨1 2/5⟩ = 2 × ⟨7/5⟩ = ⟨14/5⟩ = ⟨2 4/5⟩ — ⟨2 4/5⟩ m²예요."],"variant_rule":{"alt":[{"stem":"형성 평가예요. 가로가 12 cm, 세로가 ⟨2 5/8⟩ cm인 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"⟨31 1/2⟩","correct":true},{"t":"⟨29 1/4⟩","mis":"M5-2-u2-X15"},{"t":"⟨24 5/8⟩","mis":"M5-2-u2-X05"},{"t":"⟨9 1/2⟩","mis":"M5-2-u2-X05"}],"explanation":["직사각형의 넓이는 (가로) × (세로)예요.","12 × ⟨2 5/8⟩ = 12 × ⟨21/8⟩ = ⟨252/8⟩ = ⟨63/2⟩ = ⟨31 1/2⟩이에요.","넓이는 ⟨31 1/2⟩ cm²예요."]},{"stem":"수학익힘 문제예요. 밑변의 길이가 2 cm, 높이가 ⟨1 7/10⟩ cm인 평행사변형의 넓이는 몇 cm²인가요?","options":[{"t":"⟨3 2/5⟩","correct":true},{"t":"⟨3 7/10⟩","mis":"M5-2-u2-X15"},{"t":"⟨2 7/10⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 2/5⟩","mis":"M5-2-u2-X05"}],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","2 × ⟨1 7/10⟩ = 2 × ⟨17/10⟩ = ⟨34/10⟩ = ⟨17/5⟩ = ⟨3 2/5⟩예요.","넓이는 ⟨3 2/5⟩ cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_basic#6','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',2,'mc','auto','3 × ⟨2 1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":6,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"3 × ⟨2 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7 1/2⟩","correct":true},{"t":"⟨6 1/2⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/2⟩","mis":"M5-2-u2-X05"},{"t":"⟨4 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","3 × ⟨2 1/2⟩ = 3 × ⟨5/2⟩ = ⟨15/2⟩ = ⟨7 1/2⟩이에요.","계산 결과는 ⟨7 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"4 × ⟨3 2/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨13 1/7⟩","correct":true},{"t":"⟨12 2/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨4 1/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 6/7⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","4 × ⟨3 2/7⟩ = 4 × ⟨23/7⟩ = ⟨92/7⟩ = ⟨13 1/7⟩이에요.","계산 결과는 ⟨13 1/7⟩이에요."]},{"stem":"8 × ⟨1 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨14 2/3⟩","correct":true},{"t":"⟨8 5/6⟩","mis":"M5-2-u2-X05"},{"t":"⟨7 2/3⟩","mis":"M5-2-u2-X05"},{"t":"8","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","8 × ⟨1 5/6⟩ = 8 × ⟨11/6⟩ = ⟨88/6⟩ = ⟨44/3⟩ = ⟨14 2/3⟩예요.","계산 결과는 ⟨14 2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_basic#7','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',2,'mc','auto','계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":7,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?","options":[{"t":"5 × ⟨1 1/9⟩","correct":true},{"t":"5 × ⟨2/3⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X08"},{"t":"5 × ⟨19/20⟩","mis":"M5-2-u2-X08"}],"explanation":["5에 1보다 작은 수를 곱하면 5보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨1 1/9⟩뿐이에요.","그래서 5보다 큰 것은 5 × ⟨1 1/9⟩이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?","options":[{"t":"5 × ⟨2 1/5⟩","correct":true},{"t":"5 × ⟨1/2⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X08"},{"t":"5 × ⟨9/10⟩","mis":"M5-2-u2-X08"}],"explanation":["5에 1보다 작은 수를 곱하면 5보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨2 1/5⟩뿐이에요.","그래서 5보다 큰 것은 5 × ⟨2 1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_basic#8','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',2,'mc','auto','윤재는 쓰레기 2 kg을 주웠고, 수아는 윤재가 주운 쓰레기 무게의 ⟨1 3/4⟩배를 주웠어요. 수아가 주운 쓰레기는 모두 몇 kg인가요?',ARRAY['M5-2-u2-X15','M5-2-u2-X05']::text[],true,'{"seq":8,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"윤재는 쓰레기 2 kg을 주웠고, 수아는 윤재가 주운 쓰레기 무게의 ⟨1 3/4⟩배를 주웠어요. 수아가 주운 쓰레기는 모두 몇 kg인가요?","options":[{"t":"⟨3 1/2⟩","correct":true},{"t":"⟨3 3/4⟩","mis":"M5-2-u2-X15"},{"t":"⟨2 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/2⟩","mis":"M5-2-u2-X05"}],"explanation":["2 kg의 ⟨1 3/4⟩배는 2 × ⟨1 3/4⟩이에요.","2 × ⟨1 3/4⟩ = 2 × ⟨7/4⟩ = ⟨14/4⟩ = ⟨7/2⟩ = ⟨3 1/2⟩이에요.","수아가 주운 쓰레기는 ⟨3 1/2⟩ kg이에요."],"variant_rule":{"alt":[{"stem":"수학익힘 문제예요. 이서는 밤 4 kg을 주웠고, 시하는 이서가 주운 밤 무게의 ⟨1 5/8⟩배를 주웠어요. 시하가 주운 밤은 몇 kg인가요?","options":[{"t":"⟨6 1/2⟩","correct":true},{"t":"⟨5 5/8⟩","mis":"M5-2-u2-X15"},{"t":"⟨4 5/8⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/2⟩","mis":"M5-2-u2-X05"}],"explanation":["4 kg의 ⟨1 5/8⟩배는 4 × ⟨1 5/8⟩예요.","4 × ⟨1 5/8⟩ = 4 × ⟨13/8⟩ = ⟨52/8⟩ = ⟨13/2⟩ = ⟨6 1/2⟩이에요.","시하가 주운 밤은 ⟨6 1/2⟩ kg이에요."]},{"stem":"단원 평가예요. 민지는 철사를 24 m 가지고 있고, 윤호는 민지가 가진 철사의 ⟨1 3/8⟩배를 가지고 있어요. 윤호가 가진 철사는 몇 m인가요?","options":[{"t":"33","correct":true},{"t":"⟨25 3/8⟩","mis":"M5-2-u2-X15"},{"t":"⟨24 3/8⟩","mis":"M5-2-u2-X05"},{"t":"10","mis":"M5-2-u2-X05"}],"explanation":["24 m의 ⟨1 3/8⟩배는 24 × ⟨1 3/8⟩이에요.","24 × ⟨1 3/8⟩ = 24 × ⟨11/8⟩ = ⟨264/8⟩ = 33이에요.","윤호가 가진 철사는 33 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_basic#9','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',2,'ox','auto','곱셈을 하면 계산 결과는 언제나 처음 수보다 커져요.',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":9,"concept":"M5-2-u2-C5","difficulty":2,"kind":"ox","stem":"곱셈을 하면 계산 결과는 언제나 처음 수보다 커져요.","answer":"X","reason_options":[{"t":"1보다 작은 수를 곱하면 처음 수보다 작아지므로","correct":true},{"t":"곱셈은 늘 커지는 계산이므로","mis":"M5-2-u2-X08"}],"mis":"M5-2-u2-X08","explanation":["5 × ⟨2/3⟩ = ⟨10/3⟩ = ⟨3 1/3⟩이에요.","5보다 작아졌어요.","곱하는 수가 1보다 작으면 결과는 작아져요."],"variant_rule":{"alt":[{"stem":"2 × ⟨1 2/5⟩는 2 × 1과 2 × ⟨2/5⟩를 더한 것과 같아요.","answer":"O","reason_options":[{"t":"⟨1 2/5⟩ = 1 + ⟨2/5⟩이므로 둘로 갈라 곱해 더한 것이므로","correct":true},{"t":"대분수는 둘로 가를 수 없으므로","mis":"M5-2-u2-X05"}],"explanation":["⟨1 2/5⟩ = 1 + ⟨2/5⟩예요.","2 × 1 + 2 × ⟨2/5⟩ = 2 + ⟨4/5⟩ = ⟨2 4/5⟩예요.","그래서 맞아요."]},{"stem":"8 × ⟨3/4⟩의 계산 결과는 8보다 작아요.","answer":"O","reason_options":[{"t":"1보다 작은 ⟨3/4⟩을 곱했으므로","correct":true},{"t":"8에 3을 곱하므로","mis":"M5-2-u2-X08"}],"explanation":["8 × ⟨3/4⟩ = ⟨24/4⟩ = 6이에요.","6은 8보다 작아요.","곱셈은 곱하는 수만큼을 구하는 계산이에요 — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_basic#10','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_basic','lesson_basic','M5-2-u2-C5',3,'mc','auto','계산 결과가 3보다 작은 것을 모두 고른 것은 어느 것인가요? (3 × ⟨2/5⟩, ⟨7/8⟩ × 3, ⟨2 1/2⟩ × 3, 1 × 3)',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":10,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"계산 결과가 3보다 작은 것을 모두 고른 것은 어느 것인가요? (3 × ⟨2/5⟩, ⟨7/8⟩ × 3, ⟨2 1/2⟩ × 3, 1 × 3)","options":[{"t":"3 × ⟨2/5⟩, ⟨7/8⟩ × 3","correct":true},{"t":"3 × ⟨2/5⟩, ⟨7/8⟩ × 3, 1 × 3","mis":"M5-2-u2-X08"},{"t":"⟨2 1/2⟩ × 3, 1 × 3","mis":"M5-2-u2-X08"},{"t":"⟨7/8⟩ × 3","mis":"M5-2-u2-X08"}],"explanation":["3에 1보다 작은 수를 곱하면 3보다 작아지고, 1을 곱하면 3 그대로예요.","⟨2/5⟩와 ⟨7/8⟩은 1보다 작고, ⟨2 1/2⟩은 1보다 커요.","3보다 작은 것은 3 × ⟨2/5⟩, ⟨7/8⟩ × 3 — 1 × 3 = 3은 「작은 것」이 아니에요."],"variant_rule":{"alt":[{"stem":"형성 평가예요. 계산 결과가 6보다 큰 것을 모두 고른 것은 어느 것인가요? (6 × ⟨3/4⟩, 6 × ⟨1 8/9⟩, 6 × 1, 6 × ⟨2 1/3⟩)","options":[{"t":"6 × ⟨1 8/9⟩, 6 × ⟨2 1/3⟩","correct":true},{"t":"6 × ⟨1 8/9⟩, 6 × ⟨2 1/3⟩, 6 × 1","mis":"M5-2-u2-X08"},{"t":"6 × ⟨3/4⟩, 6 × 1","mis":"M5-2-u2-X08"},{"t":"6 × ⟨2 1/3⟩","mis":"M5-2-u2-X08"}],"explanation":["6에 1보다 큰 수를 곱하면 6보다 커져요.","⟨1 8/9⟩과 ⟨2 1/3⟩은 1보다 크고, ⟨3/4⟩은 1보다 작아요.","6 × 1 = 6은 6과 같아 「큰 것」이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_challenge#1','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',2,'sa','auto','4 × ⟨3 2/7⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u2-C5","difficulty":2,"kind":"sa","stem":"4 × ⟨3 2/7⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["4 × ⟨3 2/7⟩ = 4 × ⟨23/7⟩ = ⟨92/7⟩ = ⟨13 1/7⟩이에요.","계산 결과는 ⟨13 1/7⟩이에요.","그래서 자연수 부분은 13이에요."],"mis":"M5-2-u2-X05","variant_rule":{"alt":[{"stem":"8 × ⟨1 5/6⟩를 계산하여 기약분수인 대분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["8 × ⟨1 5/6⟩ = 8 × ⟨11/6⟩ = ⟨88/6⟩ = ⟨44/3⟩ = ⟨14 2/3⟩예요.","계산 결과는 ⟨14 2/3⟩예요.","그래서 분자는 2예요."]},{"stem":"5 × ⟨1 2/9⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["5 × ⟨1 2/9⟩ = 5 × ⟨11/9⟩ = ⟨55/9⟩ = ⟨6 1/9⟩이에요.","계산 결과는 ⟨6 1/9⟩이에요.","그래서 자연수 부분은 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_challenge#2','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',2,'mc','auto','단원 평가 보기처럼 대분수를 가분수로 나타낸 뒤 약분해요. 5 × ⟨1 2/15⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":2,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"단원 평가 보기처럼 대분수를 가분수로 나타낸 뒤 약분해요. 5 × ⟨1 2/15⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 2/3⟩","correct":true},{"t":"⟨5 2/15⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 2/3⟩","mis":"M5-2-u2-X05"},{"t":"1","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","5 × ⟨1 2/15⟩ = 5 × ⟨17/15⟩ = ⟨85/15⟩ = ⟨17/3⟩ = ⟨5 2/3⟩예요.","계산 결과는 ⟨5 2/3⟩예요."],"variant_rule":{"alt":[{"stem":"단원 평가 보기예요. 3 × ⟨1 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 1/2⟩","correct":true},{"t":"⟨3 5/6⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/2⟩","mis":"M5-2-u2-X05"},{"t":"3","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","3 × ⟨1 5/6⟩ = 3 × ⟨11/6⟩ = ⟨33/6⟩ = ⟨11/2⟩ = ⟨5 1/2⟩이에요.","계산 결과는 ⟨5 1/2⟩이에요."]},{"stem":"형성 평가예요. 6 × ⟨1 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"10","correct":true},{"t":"⟨6 2/3⟩","mis":"M5-2-u2-X05"},{"t":"5","mis":"M5-2-u2-X05"},{"t":"6","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","6 × ⟨1 2/3⟩ = 6 × ⟨5/3⟩ = ⟨30/3⟩ = 10이에요.","계산 결과는 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_challenge#3','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',3,'mc','auto','단원 평가예요. 어떤 친구가 20 × ⟨1 1/15⟩을 「20과 15를 먼저 5로 약분해 4 × ⟨4/3⟩」로 바꾸어 ⟨5 1/3⟩이라고 했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X02','M5-2-u2-X09','M5-2-u2-X08']::text[],false,'{"seq":3,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"단원 평가예요. 어떤 친구가 20 × ⟨1 1/15⟩을 「20과 15를 먼저 5로 약분해 4 × ⟨4/3⟩」로 바꾸어 ⟨5 1/3⟩이라고 했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대분수를 가분수로 나타내지 않고 먼저 약분했다","correct":true},{"t":"자연수를 분모에 곱했다","mis":"M5-2-u2-X02"},{"t":"분모끼리 곱하지 않았다","mis":"M5-2-u2-X09"},{"t":"곱하는 수가 1보다 커서 작아질 수 없다","mis":"M5-2-u2-X08"}],"explanation":["⟨1 1/15⟩에서 분모 15만 약분하면 자연수 부분 1이 약분에서 빠져 값이 달라져요.","먼저 가분수로 나타내요 — ⟨1 1/15⟩ = ⟨16/15⟩.","20 × ⟨16/15⟩ = ⟨64/3⟩ = ⟨21 1/3⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_challenge#4','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',3,'error','auto','2 × ⟨1 2/5⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X17']::text[],true,'{"seq":4,"concept":"M5-2-u2-C5","difficulty":3,"kind":"error","stem":"2 × ⟨1 2/5⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「2 × 1 = 2이니까 ⟨2 2/5⟩야.」","correct":true,"mis_target":"M5-2-u2-X05"},{"t":"순달 — 「2 × ⟨7/5⟩ = ⟨2 4/5⟩야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「2 × 1 + 2 × ⟨2/5⟩ = ⟨2 4/5⟩야.」","mis":"M5-2-u2-X17"}],"explanation":["⟨1 2/5⟩ = 1 + ⟨2/5⟩라 두 부분에 모두 2를 곱해야 해요.","2 × ⟨1 2/5⟩ = 2 × ⟨7/5⟩ = ⟨14/5⟩ = ⟨2 4/5⟩예요.","여울은 분수 부분에 곱하지 않아 틀렸어요."],"variant_rule":{"alt":[{"stem":"8 × ⟨1 5/6⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「8 × 1 = 8이니까 ⟨8 5/6⟩야.」","correct":true,"mis_target":"M5-2-u2-X05"},{"t":"순달 — 「8 × ⟨11/6⟩ = ⟨14 2/3⟩야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「8 × 1 + 8 × ⟨5/6⟩ = ⟨14 2/3⟩야.」","mis":"M5-2-u2-X17"}],"explanation":["⟨1 5/6⟩ = 1 + ⟨5/6⟩라 두 부분에 모두 8을 곱해야 해요.","8 × ⟨1 5/6⟩ = 8 × ⟨11/6⟩ = ⟨88/6⟩ = ⟨44/3⟩ = ⟨14 2/3⟩예요.","여울은 분수 부분에 곱하지 않아 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_challenge#5','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',3,'mc','auto','수학익힘 문제예요. 이서는 밤 4 kg을 주웠고, 시하는 이서가 주운 밤 무게의 ⟨1 5/8⟩배를 주웠어요. 누가 주운 밤이 몇 kg 더 무거운가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X16','M5-2-u2-X15']::text[],false,'{"seq":5,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"수학익힘 문제예요. 이서는 밤 4 kg을 주웠고, 시하는 이서가 주운 밤 무게의 ⟨1 5/8⟩배를 주웠어요. 누가 주운 밤이 몇 kg 더 무거운가요?","options":[{"t":"시하, ⟨2 1/2⟩ kg","correct":true},{"t":"이서, ⟨2 1/2⟩ kg","mis":"M5-2-u2-X17"},{"t":"시하, ⟨6 1/2⟩ kg","mis":"M5-2-u2-X16"},{"t":"시하, ⟨1 5/8⟩ kg","mis":"M5-2-u2-X15"}],"explanation":["시하가 주운 밤은 4 × ⟨1 5/8⟩ = 4 × ⟨13/8⟩ = ⟨13/2⟩ = ⟨6 1/2⟩(kg)이에요.","⟨1 5/8⟩배는 1보다 크니 시하가 더 많이 주웠어요.","⟨6 1/2⟩ − 4 = ⟨2 1/2⟩ — 시하가 ⟨2 1/2⟩ kg 더 무거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_challenge#6','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',3,'sa','auto','단원 평가 서술형이에요. 2 × ⟨3 1/2⟩ > □⟨4/5⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M5-2-u2-C5","difficulty":3,"kind":"sa","stem":"단원 평가 서술형이에요. 2 × ⟨3 1/2⟩ > □⟨4/5⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["2 × ⟨3 1/2⟩ = 2 × ⟨7/2⟩ = 7이에요.","7 > □⟨4/5⟩가 되려면 □는 6 이하 — 6이면 ⟨6 4/5⟩도 7보다 작아요.","□에는 1, 2, 3, 4, 5, 6이 들어가 모두 6개예요."],"mis":"M5-2-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_challenge#7','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',3,'mc','auto','계산하지 않고 어림해 보세요. 계산 결과가 가장 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":7,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"계산하지 않고 어림해 보세요. 계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"5 × ⟨1 1/9⟩","correct":true},{"t":"5 × ⟨2/3⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X08"},{"t":"5 × ⟨19/20⟩","mis":"M5-2-u2-X08"}],"explanation":["같은 5에 곱하니 곱하는 수가 클수록 결과도 커요.","곱하는 수 가운데 가장 큰 수는 ⟨1 1/9⟩이에요.","5 × ⟨1 1/9⟩ = ⟨5 5/9⟩ — 그래서 가장 큰 것은 5 × ⟨1 1/9⟩이에요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림해 보세요. 계산 결과가 가장 작은 것은 어느 것인가요?","options":[{"t":"5 × ⟨1/2⟩","correct":true},{"t":"5 × ⟨2 1/5⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X17"},{"t":"5 × ⟨9/10⟩","mis":"M5-2-u2-X17"}],"explanation":["같은 5에 곱하니 곱하는 수가 클수록 결과도 커요.","곱하는 수 가운데 가장 작은 수는 ⟨1/2⟩이에요.","5 × ⟨1/2⟩ = ⟨2 1/2⟩ — 그래서 가장 작은 것은 5 × ⟨1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_challenge#8','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',4,'mc','auto','「분수의 곱셈 카드 놀이」예요. 자연수 종이 2, 4, 9, 진분수 종이 ⟨1/3⟩, ⟨7/12⟩, ⟨5/6⟩, 대분수 종이 ⟨1 3/4⟩, ⟨3 1/2⟩, ⟨2 2/3⟩ 가운데 자연수 종이와 분수 종이를 1장씩 골라 (자연수)×(분수)를 만들어요. 계산 결과가 가장 큰 식은 어느 것인가요?',ARRAY['M5-2-u2-X17']::text[],true,'{"seq":8,"concept":"M5-2-u2-C5","difficulty":4,"kind":"mc","stem":"「분수의 곱셈 카드 놀이」예요. 자연수 종이 2, 4, 9, 진분수 종이 ⟨1/3⟩, ⟨7/12⟩, ⟨5/6⟩, 대분수 종이 ⟨1 3/4⟩, ⟨3 1/2⟩, ⟨2 2/3⟩ 가운데 자연수 종이와 분수 종이를 1장씩 골라 (자연수)×(분수)를 만들어요. 계산 결과가 가장 큰 식은 어느 것인가요?","options":[{"t":"9 × ⟨3 1/2⟩","correct":true},{"t":"9 × ⟨5/6⟩","mis":"M5-2-u2-X17"},{"t":"4 × ⟨3 1/2⟩","mis":"M5-2-u2-X17"},{"t":"9 × ⟨2 2/3⟩","mis":"M5-2-u2-X17"}],"explanation":["계산 결과를 크게 하려면 자연수도 분수도 가장 큰 수를 골라요.","가장 큰 자연수는 9, 가장 큰 분수는 ⟨3 1/2⟩이에요.","9 × ⟨3 1/2⟩ = 9 × ⟨7/2⟩ = ⟨63/2⟩ = ⟨31 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"「분수의 곱셈 카드 놀이」예요. 자연수 종이 2, 4, 9, 진분수 종이 ⟨1/3⟩, ⟨7/12⟩, ⟨5/6⟩, 대분수 종이 ⟨1 3/4⟩, ⟨3 1/2⟩, ⟨2 2/3⟩ 가운데 자연수 종이와 분수 종이를 1장씩 골라 (자연수)×(분수)를 만들어요. 계산 결과가 가장 작은 식은 어느 것인가요?","options":[{"t":"2 × ⟨1/3⟩","correct":true},{"t":"2 × ⟨7/12⟩","mis":"M5-2-u2-X17"},{"t":"9 × ⟨1/3⟩","mis":"M5-2-u2-X17"},{"t":"2 × ⟨1 3/4⟩","mis":"M5-2-u2-X17"}],"explanation":["계산 결과를 작게 하려면 자연수도 분수도 가장 작은 수를 골라요.","가장 작은 자연수는 2, 가장 작은 분수는 ⟨1/3⟩이에요.","2 × ⟨1/3⟩ = ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_challenge#9','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',4,'sa','auto','단원 평가예요. 어느 연극의 어린이 관람료는 8000원이고, 어른 관람료는 어린이 관람료의 ⟨1 1/5⟩배예요. 어른 관람료는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u2-C5","difficulty":4,"kind":"sa","stem":"단원 평가예요. 어느 연극의 어린이 관람료는 8000원이고, 어른 관람료는 어린이 관람료의 ⟨1 1/5⟩배예요. 어른 관람료는 얼마인가요? 숫자로 쓰세요.","answer":["9600"],"explanation":["8000원의 ⟨1 1/5⟩배는 8000 × ⟨1 1/5⟩이에요.","8000 × ⟨6/5⟩ = 1600 × 6 = 9600이에요.","어른 관람료는 9600원이에요."],"mis":"M5-2-u2-X15","variant_rule":{"alt":[{"stem":"단원 평가예요. 민지는 철사를 24 m 가지고 있고, 윤호는 민지가 가진 철사의 ⟨1 3/8⟩배를 가지고 있어요. 윤호가 가진 철사는 몇 m인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["24 m의 ⟨1 3/8⟩배는 24 × ⟨1 3/8⟩이에요.","24 × ⟨11/8⟩ = 3 × 11 = 33이에요.","윤호가 가진 철사는 33 m예요."]},{"stem":"단원 평가 서술형이에요. 일정한 빠르기로 한 시간에 80 km를 달리는 고속버스가 같은 빠르기로 3시간 30분 동안 쉬지 않고 달리면 몇 km를 달리나요? 숫자로 쓰세요.","answer":["280"],"explanation":["3시간 30분은 ⟨3 30/60⟩시간 = ⟨3 1/2⟩시간이에요.","80 × ⟨3 1/2⟩ = 80 × ⟨7/2⟩ = 280이에요.","고속버스는 280 km를 달려요 — 30분을 ⟨3/10⟩시간으로 보지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L05_challenge#10','math',5,2,'u2','L05','tb_g5_2_math_u2_L05_challenge','lesson_challenge','M5-2-u2-C5',4,'essay','teacher','친구가 「곱셈을 하면 계산 결과가 언제나 처음 수보다 커진다」고 말했어요. 5 × ⟨2/3⟩, 5 × 1, 5 × ⟨1 1/9⟩, 5 × ⟨19/20⟩를 예로 들어 친구의 말이 맞는지 판단하고, 계산하지 않고도 결과가 5보다 큰지 작은지 아는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C5","difficulty":4,"kind":"essay","stem":"친구가 「곱셈을 하면 계산 결과가 언제나 처음 수보다 커진다」고 말했어요. 5 × ⟨2/3⟩, 5 × 1, 5 × ⟨1 1/9⟩, 5 × ⟨19/20⟩를 예로 들어 친구의 말이 맞는지 판단하고, 계산하지 않고도 결과가 5보다 큰지 작은지 아는 방법을 써 보세요.","answer_guide":{"answer":"예: 친구의 말은 틀렸다. 5 × ⟨2/3⟩ = ⟨3 1/3⟩, 5 × ⟨19/20⟩ = ⟨4 3/4⟩으로 5보다 작고, 5 × 1 = 5로 그대로이며, 5 × ⟨1 1/9⟩ = ⟨5 5/9⟩로 5보다 크다. 5에 1보다 작은 수를 곱하면 5보다 작아지고, 1을 곱하면 5이며, 1보다 큰 수를 곱하면 5보다 커지므로 곱하는 수를 1과 견주면 계산하지 않고도 알 수 있다.","scoring_points":["친구의 말이 틀렸다고 판단했는가","네 곱셈의 결과를 5와 견주었는가","곱하는 수를 1과 견주면 된다고 썼는가"]},"explanation":["5 × ⟨2/3⟩ = ⟨3 1/3⟩ — 작아졌어요.","5 × 1 = 5, 5 × ⟨1 1/9⟩ = ⟨5 5/9⟩예요.","곱하는 수를 1과 견주면 결과를 어림할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_basic#1','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',1,'mc','auto','이사를 마치고 시루떡 전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩을 이웃집 친구에게 주었어요. 이웃집에 나누어 준 시루떡은 전체의 얼마인지 구하는 식은 어느 것인가요?',ARRAY['M5-2-u2-X15','M5-2-u2-X18']::text[],true,'{"seq":1,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"이사를 마치고 시루떡 전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩을 이웃집 친구에게 주었어요. 이웃집에 나누어 준 시루떡은 전체의 얼마인지 구하는 식은 어느 것인가요?","options":[{"t":"⟨1/4⟩ × ⟨1/3⟩","correct":true},{"t":"⟨1/4⟩ + ⟨1/3⟩","mis":"M5-2-u2-X15"},{"t":"⟨1/4⟩ − ⟨1/3⟩","mis":"M5-2-u2-X15"},{"t":"⟨1/4⟩ × 3","mis":"M5-2-u2-X18"}],"explanation":["「⟨1/4⟩ 중에서 ⟨1/3⟩」은 ⟨1/4⟩의 ⟨1/3⟩만큼이에요.","「~의 ~만큼」은 곱셈으로 나타내요.","식은 ⟨1/4⟩ × ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. 피자의 ⟨3/5⟩은 감자피자이고, 태오는 그중에서 ⟨1/3⟩을 먹을 거예요. 태오가 먹을 피자는 피자 전체의 얼마인지 구하는 식은 어느 것인가요?","options":[{"t":"⟨3/5⟩ × ⟨1/3⟩","correct":true},{"t":"⟨3/5⟩ + ⟨1/3⟩","mis":"M5-2-u2-X15"},{"t":"⟨3/5⟩ − ⟨1/3⟩","mis":"M5-2-u2-X15"},{"t":"⟨3/5⟩ × 3","mis":"M5-2-u2-X18"}],"explanation":["「⟨3/5⟩ 중에서 ⟨1/3⟩」은 ⟨3/5⟩의 ⟨1/3⟩만큼이에요.","「~의 ~만큼」은 곱셈으로 나타내요.","식은 ⟨3/5⟩ × ⟨1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_basic#2','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',1,'mc','auto','⟨1/4⟩ × ⟨1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X10']::text[],true,'{"seq":2,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"⟨1/4⟩ × ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/12⟩","correct":true},{"t":"⟨2/12⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/7⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/7⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 4등분 한 것 중의 1을 다시 3등분 해요.","전체는 4 × 3 = 12칸이 되고, 그중의 1칸이에요.","⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩이에요."],"asset":{"type":"fbar","bars":[{"den":4,"num":1,"label":"전체를 4등분 한 것 중의 1"},{"den":12,"num":1,"label":"그것을 다시 3등분 한 것 중의 1"}]},"variant_rule":{"alt":[{"stem":"⟨1/5⟩ × ⟨1/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/35⟩","correct":true},{"t":"⟨2/35⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/12⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/12⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 5등분 한 것 중의 1을 다시 7등분 해요.","전체는 5 × 7 = 35칸이 되고, 그중의 1칸이에요.","⟨1/5⟩ × ⟨1/7⟩ = ⟨1/35⟩이에요."],"asset":null},{"stem":"⟨1/3⟩ × ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/12⟩","correct":true},{"t":"⟨2/12⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/7⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/7⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 3등분 한 것 중의 1을 다시 4등분 해요.","전체는 3 × 4 = 12칸이 되고, 그중의 1칸이에요.","⟨1/3⟩ × ⟨1/4⟩ = ⟨1/12⟩이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_basic#3','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',1,'sa','auto','⟨4/5⟩ × ⟨2/3⟩를 그림으로 나타내려고 전체를 가로로 5등분, 세로로 3등분 했어요. 전체 칸의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u2-C6","difficulty":1,"kind":"sa","stem":"⟨4/5⟩ × ⟨2/3⟩를 그림으로 나타내려고 전체를 가로로 5등분, 세로로 3등분 했어요. 전체 칸의 수는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["전체 칸은 분모끼리 곱한 5 × 3 = 15칸이에요.","빗금 친 칸은 분자끼리 곱한 4 × 2 = 8칸이에요.","그래서 ⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요."],"mis":"M5-2-u2-X10","variant_rule":{"alt":[{"stem":"⟨4/5⟩ × ⟨2/3⟩를 그림으로 나타내려고 전체를 가로로 5등분, 세로로 3등분 했어요. 빗금 친 칸(곱에 해당하는 칸)의 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["전체 칸은 분모끼리 곱한 5 × 3 = 15칸이에요.","빗금 친 칸은 분자끼리 곱한 4 × 2 = 8칸이에요.","그래서 ⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요."]},{"stem":"⟨3/4⟩ × ⟨3/5⟩을 그림으로 나타내려고 전체를 가로로 4등분, 세로로 5등분 했어요. 빗금 친 칸(곱에 해당하는 칸)의 수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["전체 칸은 분모끼리 곱한 4 × 5 = 20칸이에요.","빗금 친 칸은 분자끼리 곱한 3 × 3 = 9칸이에요.","그래서 ⟨3/4⟩ × ⟨3/5⟩ = ⟨9/20⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_basic#4','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',1,'mc','auto','⟨4/5⟩ × ⟨2/3⟩처럼 (진분수)×(진분수)를 계산하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":4,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"⟨4/5⟩ × ⟨2/3⟩처럼 (진분수)×(진분수)를 계산하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"분모는 분모끼리, 분자는 분자끼리 곱한다","correct":true},{"t":"분모는 그대로 두고 분자끼리 곱한다","mis":"M5-2-u2-X09"},{"t":"분자는 그대로 두고 분모끼리 곱한다","mis":"M5-2-u2-X10"},{"t":"분모와 분자를 서로 엇갈려 곱한다","mis":"M5-2-u2-X10"}],"explanation":["⟨4/5⟩ × ⟨2/3⟩를 그림으로 그리면 가로 5등분, 세로 3등분 해서 전체는 5 × 3 = 15칸이에요.","빗금 친 칸은 4 × 2 = 8칸이에요.","⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩ — 분모끼리, 분자끼리 곱했어요."],"variant_rule":{"alt":[{"stem":"⟨9/10⟩ × ⟨5/6⟩처럼 (진분수)×(진분수)를 계산하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"분모는 분모끼리, 분자는 분자끼리 곱한다","correct":true},{"t":"분모는 그대로 두고 분자끼리 곱한다","mis":"M5-2-u2-X09"},{"t":"분자는 그대로 두고 분모끼리 곱한다","mis":"M5-2-u2-X10"},{"t":"분모와 분자를 서로 엇갈려 곱한다","mis":"M5-2-u2-X10"}],"explanation":["⟨9/10⟩ × ⟨5/6⟩를 그림으로 그리면 가로 10등분, 세로 6등분 해서 전체는 10 × 6 = 60칸이에요.","빗금 친 칸은 9 × 5 = 45칸이에요.","⟨9/10⟩ × ⟨5/6⟩ = ⟨45/60⟩ = ⟨3/4⟩ — 분모끼리, 분자끼리 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_basic#5','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',2,'mc','auto','이사한 뒤 시루떡 전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩을 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10','M5-2-u2-X17']::text[],true,'{"seq":5,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"이사한 뒤 시루떡 전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩을 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?","options":[{"t":"⟨1/12⟩","correct":true},{"t":"⟨1/4⟩","mis":"M5-2-u2-X09"},{"t":"⟨2/7⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X17"}],"explanation":["전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩이니 ⟨1/4⟩ × ⟨1/3⟩이에요.","⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩이에요.","전체의 ⟨1/12⟩이에요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. 피자의 ⟨3/5⟩은 감자피자이고, 태오는 그중에서 ⟨1/3⟩을 먹을 거예요. 태오가 먹을 피자는 피자 전체의 얼마인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-2-u2-X18"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨4/8⟩","mis":"M5-2-u2-X10"}],"explanation":["전체의 ⟨3/5⟩ 중에서 ⟨1/3⟩이니 ⟨3/5⟩ × ⟨1/3⟩이에요.","⟨3/5⟩ × ⟨1/3⟩ = ⟨3/15⟩ = ⟨1/5⟩이에요.","태오가 먹을 피자는 전체의 ⟨1/5⟩이에요."]},{"stem":"단원 평가예요. 현우네 학교 도서관에 있는 전체 책의 ⟨3/7⟩은 동화책이고, 현우는 그중 ⟨2/9⟩를 읽었어요. 현우가 읽은 동화책은 전체 책의 몇 분의 몇인가요?","options":[{"t":"⟨2/21⟩","correct":true},{"t":"⟨2/9⟩","mis":"M5-2-u2-X18"},{"t":"⟨6/7⟩","mis":"M5-2-u2-X09"},{"t":"⟨5/16⟩","mis":"M5-2-u2-X10"}],"explanation":["전체의 ⟨3/7⟩ 중에서 ⟨2/9⟩니 ⟨3/7⟩ × ⟨2/9⟩예요.","⟨3/7⟩ × ⟨2/9⟩ = ⟨6/63⟩ = ⟨2/21⟩예요.","현우가 읽은 동화책은 전체 책의 ⟨2/21⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_basic#6','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',2,'mc','auto','⟨4/5⟩ × ⟨2/3⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":6,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"⟨4/5⟩ × ⟨2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨8/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨6/8⟩","mis":"M5-2-u2-X10"},{"t":"⟨12/10⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요.","계산 결과는 ⟨8/15⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨3/8⟩ × ⟨5/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5/24⟩","correct":true},{"t":"⟨15/8⟩","mis":"M5-2-u2-X09"},{"t":"⟨8/17⟩","mis":"M5-2-u2-X10"},{"t":"⟨27/40⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨3/8⟩ × ⟨5/9⟩ = ⟨15/72⟩ = ⟨5/24⟩예요.","계산 결과는 ⟨5/24⟩예요."]},{"stem":"⟨6/7⟩ × ⟨3/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨9/28⟩","correct":true},{"t":"⟨18/7⟩","mis":"M5-2-u2-X09"},{"t":"⟨9/15⟩","mis":"M5-2-u2-X10"},{"t":"⟨48/21⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨6/7⟩ × ⟨3/8⟩ = ⟨18/56⟩ = ⟨9/28⟩예요.","계산 결과는 ⟨9/28⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_basic#7','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',2,'mc','auto','해온, 주이, 연우가 ⟨9/10⟩ × ⟨5/6⟩를 계산했어요. 해온이는 곱한 다음 약분했고, 주이는 곱하는 과정에서, 연우는 곱하기 전에 약분했어요. 세 친구의 계산 결과를 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u2-X12','M5-2-u2-X13']::text[],false,'{"seq":7,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"해온, 주이, 연우가 ⟨9/10⟩ × ⟨5/6⟩를 계산했어요. 해온이는 곱한 다음 약분했고, 주이는 곱하는 과정에서, 연우는 곱하기 전에 약분했어요. 세 친구의 계산 결과를 바르게 말한 것은 어느 것인가요?","options":[{"t":"세 친구의 결과는 모두 ⟨3/4⟩으로 같다","correct":true},{"t":"약분을 일찍 한 연우의 결과가 가장 작다","mis":"M5-2-u2-X12"},{"t":"해온이만 ⟨45/60⟩라 결과가 다르다","mis":"M5-2-u2-X12"},{"t":"곱하기 전에는 약분할 수 없어 연우가 틀렸다","mis":"M5-2-u2-X13"}],"explanation":["해온: ⟨9/10⟩ × ⟨5/6⟩ = ⟨45/60⟩ = ⟨3/4⟩이에요.","연우: 9와 6, 5와 10을 먼저 약분하면 ⟨3/2⟩ × ⟨1/2⟩ = ⟨3/4⟩이에요.","약분한 때가 달라도 결과는 ⟨3/4⟩으로 같아요 — ⟨45/60⟩도 한 번 더 약분하면 ⟨3/4⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_basic#8','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',2,'mc','auto','⟨4/5⟩ × ⟨2/3⟩의 계산 결과와 ⟨4/5⟩의 크기를 바르게 견준 것은 어느 것인가요?',ARRAY['M5-2-u2-X08','M5-2-u2-X17']::text[],true,'{"seq":8,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"⟨4/5⟩ × ⟨2/3⟩의 계산 결과와 ⟨4/5⟩의 크기를 바르게 견준 것은 어느 것인가요?","options":[{"t":"⟨4/5⟩ × ⟨2/3⟩ < ⟨4/5⟩","correct":true},{"t":"⟨4/5⟩ × ⟨2/3⟩ > ⟨4/5⟩","mis":"M5-2-u2-X08"},{"t":"⟨4/5⟩ × ⟨2/3⟩ = ⟨4/5⟩","mis":"M5-2-u2-X08"},{"t":"견줄 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요.","1보다 작은 ⟨2/3⟩를 곱했으니 ⟨4/5⟩보다 작아져요.","⟨8/15⟩ < ⟨4/5⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3/8⟩ × ⟨5/9⟩의 계산 결과와 ⟨3/8⟩의 크기를 바르게 견준 것은 어느 것인가요?","options":[{"t":"⟨3/8⟩ × ⟨5/9⟩ < ⟨3/8⟩","correct":true},{"t":"⟨3/8⟩ × ⟨5/9⟩ > ⟨3/8⟩","mis":"M5-2-u2-X08"},{"t":"⟨3/8⟩ × ⟨5/9⟩ = ⟨3/8⟩","mis":"M5-2-u2-X08"},{"t":"견줄 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨3/8⟩ × ⟨5/9⟩ = ⟨5/24⟩예요.","1보다 작은 ⟨5/9⟩를 곱했으니 ⟨3/8⟩보다 작아져요.","⟨5/24⟩ < ⟨3/8⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_basic#9','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',2,'ox','auto','⟨4/5⟩ × ⟨2/3⟩ = ⟨8/5⟩이에요.',ARRAY['M5-2-u2-X09']::text[],true,'{"seq":9,"concept":"M5-2-u2-C6","difficulty":2,"kind":"ox","stem":"⟨4/5⟩ × ⟨2/3⟩ = ⟨8/5⟩이에요.","answer":"X","reason_options":[{"t":"분모도 분모끼리 곱해 ⟨8/15⟩이므로","correct":true},{"t":"분모는 그대로 두고 분자끼리 곱하므로","mis":"M5-2-u2-X09"}],"mis":"M5-2-u2-X09","explanation":["분모는 분모끼리 곱해 5 × 3 = 15예요.","분자는 4 × 2 = 8이에요.","⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩이에요.","answer":"O","reason_options":[{"t":"4등분 한 것을 다시 3등분 하면 12칸 중 1칸이므로","correct":true},{"t":"분모끼리 더해 7칸 중 1칸이므로","mis":"M5-2-u2-X10"}],"explanation":["가로 4번, 세로 3번 잘라 12칸이에요.","그중의 1칸이에요.","⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩ — 맞아요."]},{"stem":"⟨1/5⟩ × ⟨1/7⟩ = ⟨2/35⟩예요.","answer":"X","reason_options":[{"t":"분자끼리 곱하면 1 × 1 = 1이라 ⟨1/35⟩이므로","correct":true},{"t":"분자끼리 더해 2가 되므로","mis":"M5-2-u2-X10"}],"explanation":["분모끼리 5 × 7 = 35예요.","분자끼리 1 × 1 = 1이에요.","⟨1/5⟩ × ⟨1/7⟩ = ⟨1/35⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_basic#10','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_basic','lesson_basic','M5-2-u2-C6',3,'match','auto','계산 결과가 같은 것끼리 이으세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u2-C6","difficulty":3,"kind":"match","stem":"계산 결과가 같은 것끼리 이으세요.","pairs":[{"l":"⟨1/6⟩ × ⟨1/5⟩","r":"⟨1/2⟩ × ⟨1/15⟩"},{"l":"⟨1/10⟩ × ⟨1/4⟩","r":"⟨1/8⟩ × ⟨1/5⟩"},{"l":"⟨1/4⟩ × ⟨1/5⟩","r":"⟨1/2⟩ × ⟨1/3⟩ × ⟨3/10⟩"}],"mis":"M5-2-u2-X10","explanation":["단위분수끼리 곱하면 분자는 1, 분모는 분모끼리의 곱이에요.","⟨1/6⟩ × ⟨1/5⟩ = ⟨1/30⟩ = ⟨1/2⟩ × ⟨1/15⟩, ⟨1/10⟩ × ⟨1/4⟩ = ⟨1/40⟩ = ⟨1/8⟩ × ⟨1/5⟩이에요.","⟨1/4⟩ × ⟨1/5⟩ = ⟨1/20⟩ = ⟨1/2⟩ × ⟨1/3⟩ × ⟨3/10⟩이에요."],"variant_rule":{"alt":[{"stem":"곱셈식과 계산 결과(기약분수)를 알맞게 이으세요.","pairs":[{"l":"⟨1/5⟩ × ⟨1/7⟩","r":"⟨1/35⟩"},{"l":"⟨3/8⟩ × ⟨5/9⟩","r":"⟨5/24⟩"},{"l":"⟨6/7⟩ × ⟨3/8⟩","r":"⟨9/28⟩"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨1/5⟩ × ⟨1/7⟩ = ⟨1/35⟩, ⟨3/8⟩ × ⟨5/9⟩ = ⟨15/72⟩ = ⟨5/24⟩, ⟨6/7⟩ × ⟨3/8⟩ = ⟨18/56⟩ = ⟨9/28⟩예요.","분모를 그대로 두지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_challenge#1','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',2,'sa','auto','⟨9/10⟩ × ⟨5/6⟩를 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u2-C6","difficulty":2,"kind":"sa","stem":"⟨9/10⟩ × ⟨5/6⟩를 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨9/10⟩ × ⟨5/6⟩ = ⟨45/60⟩ = ⟨3/4⟩이에요.","계산 결과는 ⟨3/4⟩이에요.","그래서 분모는 4예요."],"mis":"M5-2-u2-X12","variant_rule":{"alt":[{"stem":"⟨3/8⟩ × ⟨5/9⟩를 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["⟨3/8⟩ × ⟨5/9⟩ = ⟨15/72⟩ = ⟨5/24⟩예요.","계산 결과는 ⟨5/24⟩예요.","그래서 분모는 24예요."]},{"stem":"⟨5/6⟩ × ⟨3/7⟩을 계산하여 기약분수로 나타냈을 때 분모는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["⟨5/6⟩ × ⟨3/7⟩ = ⟨15/42⟩ = ⟨5/14⟩예요.","계산 결과는 ⟨5/14⟩예요.","그래서 분모는 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_challenge#2','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',2,'mc','auto','단원 평가예요. 계산 결과가 큰 것부터 차례로 기호를 쓴 것은 어느 것인가요? ㉠ ⟨1/5⟩ × ⟨1/7⟩ ㉡ ⟨1/9⟩ × ⟨1/3⟩ ㉢ ⟨1/6⟩ × ⟨1/6⟩ ㉣ ⟨1/11⟩ × ⟨1/2⟩',ARRAY['M5-2-u2-X17','M5-2-u2-X10']::text[],false,'{"seq":2,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"단원 평가예요. 계산 결과가 큰 것부터 차례로 기호를 쓴 것은 어느 것인가요? ㉠ ⟨1/5⟩ × ⟨1/7⟩ ㉡ ⟨1/9⟩ × ⟨1/3⟩ ㉢ ⟨1/6⟩ × ⟨1/6⟩ ㉣ ⟨1/11⟩ × ⟨1/2⟩","options":[{"t":"㉣, ㉡, ㉠, ㉢","correct":true},{"t":"㉢, ㉠, ㉡, ㉣","mis":"M5-2-u2-X17"},{"t":"㉠, ㉡, ㉢, ㉣","mis":"M5-2-u2-X17"},{"t":"㉣, ㉢, ㉡, ㉠","mis":"M5-2-u2-X10"}],"explanation":["㉠ ⟨1/35⟩, ㉡ ⟨1/27⟩, ㉢ ⟨1/36⟩, ㉣ ⟨1/22⟩이에요.","단위분수는 분모가 작을수록 커요.","22 < 27 < 35 < 36이라 ㉣, ㉡, ㉠, ㉢ 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_challenge#3','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',3,'error','auto','⟨4/5⟩ × ⟨2/3⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X17']::text[],true,'{"seq":3,"concept":"M5-2-u2-C6","difficulty":3,"kind":"error","stem":"⟨4/5⟩ × ⟨2/3⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「분모는 그대로 두고 분자끼리 곱해 ⟨8/5⟩이야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"순달 — 「⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「전체 15칸 중 8칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요.","여울은 분모를 그대로 두어 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ × ⟨3/5⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「분모는 그대로 두고 분자끼리 곱해 ⟨9/4⟩야.」","correct":true,"mis_target":"M5-2-u2-X09"},{"t":"순달 — 「⟨3/4⟩ × ⟨3/5⟩ = ⟨9/20⟩야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「전체 20칸 중 9칸이야.」","mis":"M5-2-u2-X17"}],"explanation":["분수끼리 곱할 때는 분모도 분모끼리 곱해요.","⟨3/4⟩ × ⟨3/5⟩ = ⟨9/20⟩예요.","여울은 분모를 그대로 두어 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_challenge#4','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',3,'error','auto','⟨6/7⟩ × ⟨3/8⟩을 곱하기 전에 약분하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u2-X13','M5-2-u2-X17']::text[],false,'{"seq":4,"concept":"M5-2-u2-C6","difficulty":3,"kind":"error","stem":"⟨6/7⟩ × ⟨3/8⟩을 곱하기 전에 약분하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「분자 6과 분자 3을 약분해도 돼.」","correct":true,"mis_target":"M5-2-u2-X13"},{"t":"순달 — 「분자 6과 분모 8을 약분해도 돼.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「약분하지 않고 곱한 뒤 기약분수로 나타내도 돼.」","mis":"M5-2-u2-X17"}],"explanation":["약분은 분자와 분모를 같은 수로 나누는 것이라 분자와 분모 사이에서만 해요.","분자끼리 나누면 값이 달라져요.","바르게 하면 ⟨6/7⟩ × ⟨3/8⟩ = ⟨18/56⟩ = ⟨9/28⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_challenge#5','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',3,'mc','auto','단원 평가예요. 은정이는 ⟨2/3⟩ × ⟨1/9⟩, 준상이는 ⟨4/9⟩ × ⟨1/2⟩, 주원이는 ⟨5/6⟩ × ⟨4/15⟩를 계산했어요. 계산 결과가 다른 친구는 누구인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X09']::text[],false,'{"seq":5,"concept":"M5-2-u2-C6","difficulty":3,"kind":"mc","stem":"단원 평가예요. 은정이는 ⟨2/3⟩ × ⟨1/9⟩, 준상이는 ⟨4/9⟩ × ⟨1/2⟩, 주원이는 ⟨5/6⟩ × ⟨4/15⟩를 계산했어요. 계산 결과가 다른 친구는 누구인가요?","options":[{"t":"은정","correct":true},{"t":"준상","mis":"M5-2-u2-X17"},{"t":"주원","mis":"M5-2-u2-X17"},{"t":"세 친구 모두 같다","mis":"M5-2-u2-X09"}],"explanation":["은정: ⟨2/3⟩ × ⟨1/9⟩ = ⟨2/27⟩예요.","준상: ⟨4/9⟩ × ⟨1/2⟩ = ⟨4/18⟩ = ⟨2/9⟩, 주원: ⟨5/6⟩ × ⟨4/15⟩ = ⟨20/90⟩ = ⟨2/9⟩예요.","결과가 다른 친구는 은정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_challenge#6','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',3,'mc','auto','단원 평가예요. 은서는 집에서 ⟨14/15⟩ km 떨어진 서점에 가는데 전체 거리의 ⟨5/6⟩는 버스를 타고 나머지는 걸어서 갔어요. 은서가 걸어서 간 거리는 몇 km인가요?',ARRAY['M5-2-u2-X19','M5-2-u2-X15','M5-2-u2-X18']::text[],false,'{"seq":6,"concept":"M5-2-u2-C6","difficulty":3,"kind":"mc","stem":"단원 평가예요. 은서는 집에서 ⟨14/15⟩ km 떨어진 서점에 가는데 전체 거리의 ⟨5/6⟩는 버스를 타고 나머지는 걸어서 갔어요. 은서가 걸어서 간 거리는 몇 km인가요?","options":[{"t":"⟨7/45⟩","correct":true},{"t":"⟨7/9⟩","mis":"M5-2-u2-X19"},{"t":"⟨1/10⟩","mis":"M5-2-u2-X15"},{"t":"⟨1/6⟩","mis":"M5-2-u2-X18"}],"explanation":["걸어서 간 거리는 전체 거리의 나머지 1 − ⟨5/6⟩ = ⟨1/6⟩이에요.","⟨14/15⟩ × ⟨1/6⟩ = ⟨14/90⟩ = ⟨7/45⟩이에요.","⟨5/6⟩를 곱하면 버스로 간 거리 ⟨7/9⟩ km예요 — 묻는 것은 걸어서 간 거리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_challenge#7','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',3,'mc','auto','단원 평가예요. ⟨1/12⟩, ⟨1/4⟩, ⟨1/9⟩, ⟨1/6⟩ 가운데 가장 큰 수와 가장 작은 수의 곱은 얼마인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X10']::text[],false,'{"seq":7,"concept":"M5-2-u2-C6","difficulty":3,"kind":"mc","stem":"단원 평가예요. ⟨1/12⟩, ⟨1/4⟩, ⟨1/9⟩, ⟨1/6⟩ 가운데 가장 큰 수와 가장 작은 수의 곱은 얼마인가요?","options":[{"t":"⟨1/48⟩","correct":true},{"t":"⟨1/24⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/16⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/108⟩","mis":"M5-2-u2-X17"}],"explanation":["단위분수는 분모가 작을수록 커요 — 가장 큰 수는 ⟨1/4⟩, 가장 작은 수는 ⟨1/12⟩이에요.","⟨1/4⟩ × ⟨1/12⟩ = ⟨1/48⟩이에요.","분모끼리 더하지 않고 곱해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_challenge#8','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',4,'sa','auto','⟨1/□⟩ × ⟨1/3⟩ = ⟨1/12⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u2-C6","difficulty":4,"kind":"sa","stem":"⟨1/□⟩ × ⟨1/3⟩ = ⟨1/12⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["단위분수끼리 곱하면 분모끼리 곱해요.","□ × 3 = 12이어야 해요.","12 ÷ 3 = 4니 □는 4예요."],"mis":"M5-2-u2-X10","variant_rule":{"alt":[{"stem":"⟨1/□⟩ × ⟨1/7⟩ = ⟨1/35⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["단위분수끼리 곱하면 분모끼리 곱해요.","□ × 7 = 35이어야 해요.","35 ÷ 7 = 5니 □는 5예요."]},{"stem":"⟨1/□⟩ × ⟨1/5⟩ = ⟨1/30⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["단위분수끼리 곱하면 분모끼리 곱해요.","□ × 5 = 30이어야 해요.","30 ÷ 5 = 6이니 □는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_challenge#9','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',4,'mc','auto','문제로 마무리예요. ⟨15/16⟩ × ⟨4/9⟩와 계산 결과가 같은 것은 어느 것인가요?',ARRAY['M5-2-u2-X10','M5-2-u2-X17']::text[],true,'{"seq":9,"concept":"M5-2-u2-C6","difficulty":4,"kind":"mc","stem":"문제로 마무리예요. ⟨15/16⟩ × ⟨4/9⟩와 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"⟨5/36⟩ × 3","correct":true},{"t":"⟨1/4⟩ × ⟨1/5⟩","mis":"M5-2-u2-X10"},{"t":"11 × ⟨3/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/2⟩ × ⟨1/3⟩ × ⟨3/10⟩","mis":"M5-2-u2-X17"}],"explanation":["⟨15/16⟩ × ⟨4/9⟩ = ⟨60/144⟩ = ⟨5/12⟩예요.","⟨5/36⟩ × 3 = ⟨15/36⟩ = ⟨5/12⟩예요.","두 식의 결과가 ⟨5/12⟩로 같아요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. ⟨1/4⟩ × ⟨1/5⟩과 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"⟨1/2⟩ × ⟨1/3⟩ × ⟨3/10⟩","correct":true},{"t":"⟨15/16⟩ × ⟨4/9⟩","mis":"M5-2-u2-X10"},{"t":"6 × ⟨1 3/8⟩","mis":"M5-2-u2-X17"},{"t":"⟨5/36⟩ × 3","mis":"M5-2-u2-X17"}],"explanation":["⟨1/4⟩ × ⟨1/5⟩ = ⟨1/20⟩이에요.","⟨1/2⟩ × ⟨1/3⟩ × ⟨3/10⟩ = ⟨3/60⟩ = ⟨1/20⟩이에요.","두 식의 결과가 ⟨1/20⟩로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L06_challenge#10','math',5,2,'u2','L06','tb_g5_2_math_u2_L06_challenge','lesson_challenge','M5-2-u2-C6',4,'essay','teacher','⟨4/5⟩ × ⟨2/3⟩를 그림으로 설명하려고 해요. 전체를 어떻게 나누고 어디에 빗금을 치는지, 전체 칸과 빗금 친 칸이 몇 칸인지 쓰고, 분모는 분모끼리·분자는 분자끼리 곱하는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C6","difficulty":4,"kind":"essay","stem":"⟨4/5⟩ × ⟨2/3⟩를 그림으로 설명하려고 해요. 전체를 어떻게 나누고 어디에 빗금을 치는지, 전체 칸과 빗금 친 칸이 몇 칸인지 쓰고, 분모는 분모끼리·분자는 분자끼리 곱하는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 전체를 5등분 한 것 중의 4만큼인 ⟨4/5⟩를 나타낸 뒤, 그것을 다시 각각 3등분 한 것 중의 2만큼에 빗금을 친다. 전체는 5 × 3 = 15칸이고 빗금 친 칸은 4 × 2 = 8칸이므로 ⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이다. 전체를 두 번 나누었으므로 전체 칸 수는 분모끼리의 곱, 빗금 친 칸 수는 분자끼리의 곱이 된다.","scoring_points":["⟨4/5⟩를 다시 3등분 한 것 중의 2에 빗금을 친다고 썼는가","전체 15칸, 빗금 친 8칸을 구했는가","⟨8/15⟩을 구하고 분모끼리·분자끼리 곱하는 까닭을 썼는가"]},"explanation":["전체는 5 × 3 = 15칸이에요.","빗금 친 칸은 4 × 2 = 8칸이에요.","⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_basic#1','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',1,'sa','auto','⟨3 1/2⟩을 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u2-C7","difficulty":1,"kind":"sa","stem":"⟨3 1/2⟩을 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수 3은 ⟨6/2⟩이에요.","분자는 3 × 2 + 1 = 7이에요.","⟨3 1/2⟩ = ⟨7/2⟩이에요."],"mis":"M5-2-u2-X04","variant_rule":{"alt":[{"stem":"⟨1 4/5⟩를 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["자연수 1은 ⟨5/5⟩예요.","분자는 1 × 5 + 4 = 9예요.","⟨1 4/5⟩ = ⟨9/5⟩예요."]},{"stem":"⟨2 2/5⟩를 가분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["자연수 2는 ⟨10/5⟩이에요.","분자는 2 × 5 + 2 = 12예요.","⟨2 2/5⟩ = ⟨12/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_basic#2','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',1,'mc','auto','자연수 2를 분모가 1인 분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X14']::text[],true,'{"seq":2,"concept":"M5-2-u2-C7","difficulty":1,"kind":"mc","stem":"자연수 2를 분모가 1인 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨2/1⟩","correct":true},{"t":"⟨2/2⟩","mis":"M5-2-u2-X14"},{"t":"⟨1/2⟩","mis":"M5-2-u2-X14"},{"t":"⟨2/10⟩","mis":"M5-2-u2-X14"}],"explanation":["분모가 1인 분수는 「1로 나눈 것」이라 분자 그대로예요.","2 = ⟨2/1⟩예요.","⟨2/2⟩는 1, ⟨1/2⟩은 1보다 작은 수라 2가 아니에요."],"variant_rule":{"alt":[{"stem":"자연수 5를 분모가 1인 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨5/1⟩","correct":true},{"t":"⟨5/5⟩","mis":"M5-2-u2-X14"},{"t":"⟨1/5⟩","mis":"M5-2-u2-X14"},{"t":"⟨5/10⟩","mis":"M5-2-u2-X14"}],"explanation":["분모가 1인 분수는 「1로 나눈 것」이라 분자 그대로예요.","5 = ⟨5/1⟩예요.","⟨5/5⟩는 1, ⟨1/5⟩은 1보다 작은 수라 5가 아니에요."]},{"stem":"자연수 7을 분모가 1인 분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/1⟩","correct":true},{"t":"⟨7/7⟩","mis":"M5-2-u2-X14"},{"t":"⟨1/7⟩","mis":"M5-2-u2-X14"},{"t":"⟨7/10⟩","mis":"M5-2-u2-X14"}],"explanation":["분모가 1인 분수는 「1로 나눈 것」이라 분자 그대로예요.","7 = ⟨7/1⟩이에요.","⟨7/7⟩은 1, ⟨1/7⟩은 1보다 작은 수라 7이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_basic#3','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C5',1,'mc','auto','지난 시간에 배운 것이에요. 4 × ⟨1 2/3⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":3,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"지난 시간에 배운 것이에요. 4 × ⟨1 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 2/3⟩","correct":true},{"t":"⟨4 2/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 2/3⟩","mis":"M5-2-u2-X05"},{"t":"4","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","4 × ⟨1 2/3⟩ = 4 × ⟨5/3⟩ = ⟨20/3⟩ = ⟨6 2/3⟩예요.","계산 결과는 ⟨6 2/3⟩예요."],"variant_rule":{"alt":[{"stem":"지난 시간에 배운 것이에요. 2 × ⟨2 3/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5 1/5⟩","correct":true},{"t":"⟨4 3/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/5⟩","mis":"M5-2-u2-X05"},{"t":"2","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","2 × ⟨2 3/5⟩ = 2 × ⟨13/5⟩ = ⟨26/5⟩ = ⟨5 1/5⟩이에요.","계산 결과는 ⟨5 1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_basic#4','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',1,'mc','auto','⟨3 1/2⟩ × ⟨1 4/5⟩를 어떻게 계산하면 좋을까요?',ARRAY['M5-2-u2-X11','M5-2-u2-X05','M5-2-u2-X10']::text[],false,'{"seq":4,"concept":"M5-2-u2-C7","difficulty":1,"kind":"mc","stem":"⟨3 1/2⟩ × ⟨1 4/5⟩를 어떻게 계산하면 좋을까요?","options":[{"t":"두 대분수를 가분수로 나타낸 다음 분모끼리, 분자끼리 곱한다","correct":true},{"t":"자연수끼리 3 × 1, 분수끼리 ⟨1/2⟩ × ⟨4/5⟩를 곱해 더한다","mis":"M5-2-u2-X11"},{"t":"자연수 부분은 그대로 두고 분수 부분끼리만 곱한다","mis":"M5-2-u2-X05"},{"t":"분모와 분자를 엇갈려 곱한다","mis":"M5-2-u2-X10"}],"explanation":["대분수는 자연수와 진분수가 더해진 수라 그대로는 분모끼리·분자끼리 곱할 수 없어요.","⟨3 1/2⟩ = ⟨7/2⟩, ⟨1 4/5⟩ = ⟨9/5⟩로 나타내요.","⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩ = ⟨6 3/10⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_basic#5','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',2,'mc','auto','⟨3 1/2⟩ × ⟨1 4/5⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X04']::text[],true,'{"seq":5,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"⟨3 1/2⟩ × ⟨1 4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 3/10⟩","correct":true},{"t":"⟨3 2/5⟩","mis":"M5-2-u2-X11"},{"t":"⟨3 3/5⟩","mis":"M5-2-u2-X04"},{"t":"⟨3 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨3 1/2⟩ × ⟨1 4/5⟩ = ⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩ = ⟨6 3/10⟩이에요.","계산 결과는 ⟨6 3/10⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 2/5⟩ × ⟨1 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 1/5⟩","correct":true},{"t":"⟨2 3/10⟩","mis":"M5-2-u2-X11"},{"t":"⟨1 2/5⟩","mis":"M5-2-u2-X04"},{"t":"⟨2 2/5⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨2 2/5⟩ × ⟨1 3/4⟩ = ⟨12/5⟩ × ⟨7/4⟩ = ⟨84/20⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요.","계산 결과는 ⟨4 1/5⟩이에요."]},{"stem":"⟨1 7/25⟩ × ⟨5/12⟩를 계산하면 얼마인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨1 7/60⟩","mis":"M5-2-u2-X05"},{"t":"⟨2/15⟩","mis":"M5-2-u2-X04"},{"t":"⟨1/5⟩","mis":"M5-2-u2-X06"}],"explanation":["대분수를 가분수로 나타낸 다음 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨1 7/25⟩ × ⟨5/12⟩ = ⟨32/25⟩ × ⟨5/12⟩ = ⟨160/300⟩ = ⟨8/15⟩이에요.","계산 결과는 ⟨8/15⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_basic#6','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',2,'mc','auto','재영이는 공원을 ⟨1 3/4⟩ km 걸었고, 하은이는 재영이가 걸은 거리의 ⟨1 3/7⟩배만큼 걸었어요. 하은이가 걸은 거리는 몇 km인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X04']::text[],true,'{"seq":6,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"재영이는 공원을 ⟨1 3/4⟩ km 걸었고, 하은이는 재영이가 걸은 거리의 ⟨1 3/7⟩배만큼 걸었어요. 하은이가 걸은 거리는 몇 km인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨1 9/28⟩","mis":"M5-2-u2-X11"},{"t":"⟨1 3/7⟩","mis":"M5-2-u2-X04"},{"t":"1","mis":"M5-2-u2-X04"}],"explanation":["⟨1 3/4⟩의 ⟨1 3/7⟩배이니 ⟨1 3/4⟩ × ⟨1 3/7⟩이에요.","⟨1 3/4⟩ × ⟨1 3/7⟩ = ⟨7/4⟩ × ⟨10/7⟩ = ⟨70/28⟩ = ⟨5/2⟩ = ⟨2 1/2⟩이에요.","하은이가 걸은 거리는 ⟨2 1/2⟩ km예요."],"variant_rule":{"alt":[{"stem":"형성 평가예요. 지오의 가방 무게는 ⟨2 4/5⟩ kg이에요. 이수의 가방 무게는 지오의 가방 무게의 ⟨1 5/7⟩배일 때 이수의 가방 무게는 몇 kg인가요?","options":[{"t":"⟨4 4/5⟩","correct":true},{"t":"⟨2 4/7⟩","mis":"M5-2-u2-X11"},{"t":"⟨2 2/35⟩","mis":"M5-2-u2-X04"},{"t":"⟨2 2/5⟩","mis":"M5-2-u2-X04"}],"explanation":["⟨2 4/5⟩의 ⟨1 5/7⟩배이니 ⟨2 4/5⟩ × ⟨1 5/7⟩예요.","⟨2 4/5⟩ × ⟨1 5/7⟩ = ⟨14/5⟩ × ⟨12/7⟩ = ⟨168/35⟩ = ⟨24/5⟩ = ⟨4 4/5⟩예요.","이수의 가방 무게는 ⟨4 4/5⟩ kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_basic#7','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',2,'mc','auto','⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X12']::text[],true,'{"seq":7,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5/21⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-2-u2-X17"},{"t":"⟨10/21⟩","mis":"M5-2-u2-X17"},{"t":"⟨1 5/21⟩","mis":"M5-2-u2-X12"}],"explanation":["분수가 셋이어도 대분수는 가분수로, 자연수는 분모가 1인 분수로 보고 분모끼리·분자끼리 곱해요.","⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩ = ⟨10/42⟩ = ⟨5/21⟩예요.","계산 결과는 ⟨5/21⟩예요."],"variant_rule":{"alt":[{"stem":"⟨7/9⟩ × ⟨3/16⟩ × ⟨4/21⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1/36⟩","correct":true},{"t":"⟨7/48⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/28⟩","mis":"M5-2-u2-X17"},{"t":"⟨1 1/36⟩","mis":"M5-2-u2-X12"}],"explanation":["분수가 셋이어도 대분수는 가분수로, 자연수는 분모가 1인 분수로 보고 분모끼리·분자끼리 곱해요.","⟨7/9⟩ × ⟨3/16⟩ × ⟨4/21⟩ = ⟨84/3024⟩ = ⟨1/36⟩이에요.","계산 결과는 ⟨1/36⟩이에요."]},{"stem":"⟨7/9⟩ × ⟨2/3⟩ × ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7/54⟩","correct":true},{"t":"⟨14/27⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/6⟩","mis":"M5-2-u2-X17"},{"t":"⟨1 7/54⟩","mis":"M5-2-u2-X12"}],"explanation":["분수가 셋이어도 대분수는 가분수로, 자연수는 분모가 1인 분수로 보고 분모끼리·분자끼리 곱해요.","⟨7/9⟩ × ⟨2/3⟩ × ⟨1/4⟩ = ⟨14/108⟩ = ⟨7/54⟩이에요.","계산 결과는 ⟨7/54⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_basic#8','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',2,'mc','auto','2 × ⟨5/9⟩ × ⟨3/4⟩을 계산하는 순서를 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X10']::text[],true,'{"seq":8,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"2 × ⟨5/9⟩ × ⟨3/4⟩을 계산하는 순서를 바르게 말한 것은 어느 것인가요?","options":[{"t":"앞에서부터 곱해도, 뒤의 두 수를 먼저 곱해도 답이 같다","correct":true},{"t":"반드시 앞의 두 수부터 곱해야 답이 맞다","mis":"M5-2-u2-X17"},{"t":"뒤의 두 수를 먼저 곱하면 답이 달라진다","mis":"M5-2-u2-X17"},{"t":"세 분수는 한꺼번에 곱할 수 없다","mis":"M5-2-u2-X10"}],"explanation":["앞에서부터: 2 × ⟨5/9⟩ = ⟨1 1/9⟩, 여기에 ⟨3/4⟩을 곱해요.","뒤부터: ⟨5/9⟩ × ⟨3/4⟩ = ⟨5/12⟩를 먼저 구해요.","어느 쪽이든 2 × ⟨5/9⟩ × ⟨3/4⟩ = ⟨5/6⟩예요."],"variant_rule":{"alt":[{"stem":"5 × ⟨7/10⟩ × ⟨3/14⟩을 계산하는 순서를 바르게 말한 것은 어느 것인가요?","options":[{"t":"앞에서부터 곱해도, 뒤의 두 수를 먼저 곱해도 답이 같다","correct":true},{"t":"반드시 앞의 두 수부터 곱해야 답이 맞다","mis":"M5-2-u2-X17"},{"t":"뒤의 두 수를 먼저 곱하면 답이 달라진다","mis":"M5-2-u2-X17"},{"t":"세 분수는 한꺼번에 곱할 수 없다","mis":"M5-2-u2-X10"}],"explanation":["앞에서부터: 5 × ⟨7/10⟩ = ⟨3 1/2⟩, 여기에 ⟨3/14⟩을 곱해요.","뒤부터: ⟨7/10⟩ × ⟨3/14⟩ = ⟨3/20⟩을 먼저 구해요.","어느 쪽이든 5 × ⟨7/10⟩ × ⟨3/14⟩ = ⟨3/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_basic#9','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',2,'ox','auto','⟨3 1/2⟩ × ⟨1 4/5⟩ = ⟨3 4/10⟩예요.',ARRAY['M5-2-u2-X11']::text[],true,'{"seq":9,"concept":"M5-2-u2-C7","difficulty":2,"kind":"ox","stem":"⟨3 1/2⟩ × ⟨1 4/5⟩ = ⟨3 4/10⟩예요.","answer":"X","reason_options":[{"t":"가분수로 고쳐 계산하면 ⟨6 3/10⟩이므로","correct":true},{"t":"자연수끼리 3 × 1, 분수끼리 곱하면 되므로","mis":"M5-2-u2-X11"}],"mis":"M5-2-u2-X11","explanation":["자연수끼리·분수끼리 따로 곱하면 빠지는 부분이 생겨요.","⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩이에요.","바른 답은 ⟨6 3/10⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/2⟩ × ⟨2/3⟩ × ⟨5/7⟩는 앞의 두 수만 곱하면 끝나요.","answer":"X","reason_options":[{"t":"세 분수 모두 분모끼리·분자끼리 곱해야 하므로","correct":true},{"t":"세 번째 수는 더하면 되므로","mis":"M5-2-u2-X17"}],"explanation":["⟨1/2⟩ × ⟨2/3⟩ = ⟨1/3⟩이에요.","여기에 ⟨5/7⟩를 곱해야 해요.","⟨1/3⟩ × ⟨5/7⟩ = ⟨5/21⟩예요."]},{"stem":"세 분수의 곱셈은 먼저 약분한 다음 한 번에 곱해도 답이 같아요.","answer":"O","reason_options":[{"t":"분모끼리·분자끼리 곱하는 한 규칙 위에 있으므로","correct":true},{"t":"약분은 두 수 사이에서만 할 수 있으므로","mis":"M5-2-u2-X13"}],"explanation":["5 × ⟨7/10⟩ × ⟨3/14⟩에서 5 = ⟨5/1⟩로 봐요.","약분하면 ⟨1/1⟩ × ⟨1/2⟩ × ⟨3/2⟩이에요.","5 × ⟨7/10⟩ × ⟨3/14⟩ = ⟨3/4⟩ — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_basic#10','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_basic','lesson_basic','M5-2-u2-C7',3,'sa','auto','5학년 학생 160명 가운데 ⟨5/8⟩가 남학생이고, 남학생 가운데 ⟨3/5⟩이 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u2-C7","difficulty":3,"kind":"sa","stem":"5학년 학생 160명 가운데 ⟨5/8⟩가 남학생이고, 남학생 가운데 ⟨3/5⟩이 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["남학생은 160 × ⟨5/8⟩ = 100명이에요.","그 가운데 ⟨3/5⟩이니 100 × ⟨3/5⟩ = 60명이에요.","한 번에 160 × ⟨5/8⟩ × ⟨3/5⟩ = 60으로 구해도 같아요."],"mis":"M5-2-u2-X15","variant_rule":{"alt":[{"stem":"단원 평가예요. 선아네 학교 도서관에 있는 책 300권 중에서 ⟨1/3⟩은 과학책이에요. 선아는 과학책 중에서 ⟨3/5⟩을 읽었다면 선아가 읽은 과학책은 몇 권인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["과학책은 300 × ⟨1/3⟩ = 100(권)이에요.","그중 ⟨3/5⟩이니 100 × ⟨3/5⟩ = 60(권)이에요.","한 식으로 300 × ⟨1/3⟩ × ⟨3/5⟩ = 60으로 구해도 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_challenge#1','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',2,'sa','auto','⟨3 1/2⟩ × ⟨1 4/5⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u2-C7","difficulty":2,"kind":"sa","stem":"⟨3 1/2⟩ × ⟨1 4/5⟩를 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["⟨3 1/2⟩ × ⟨1 4/5⟩ = ⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩ = ⟨6 3/10⟩이에요.","계산 결과는 ⟨6 3/10⟩이에요.","그래서 자연수 부분은 6이에요."],"mis":"M5-2-u2-X11","variant_rule":{"alt":[{"stem":"⟨2 2/5⟩ × ⟨1 3/4⟩을 계산하여 기약분수인 대분수로 나타냈을 때 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨2 2/5⟩ × ⟨1 3/4⟩ = ⟨12/5⟩ × ⟨7/4⟩ = ⟨84/20⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요.","계산 결과는 ⟨4 1/5⟩이에요.","그래서 자연수 부분은 4예요."]},{"stem":"⟨3 2/3⟩ × ⟨1 1/8⟩을 계산하여 기약분수인 대분수로 나타냈을 때 분자는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["⟨3 2/3⟩ × ⟨1 1/8⟩ = ⟨11/3⟩ × ⟨9/8⟩ = ⟨99/24⟩ = ⟨33/8⟩ = ⟨4 1/8⟩이에요.","계산 결과는 ⟨4 1/8⟩이에요.","그래서 분자는 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_challenge#2','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',2,'mc','auto','「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨12 2/3⟩ × ⟨2 5/8⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X04']::text[],true,'{"seq":2,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨12 2/3⟩ × ⟨2 5/8⟩를 계산하면 얼마인가요?","options":[{"t":"⟨33 1/4⟩","correct":true},{"t":"⟨24 5/12⟩","mis":"M5-2-u2-X11"},{"t":"⟨12 1/4⟩","mis":"M5-2-u2-X04"},{"t":"⟨11 1/12⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨12 2/3⟩ × ⟨2 5/8⟩ = ⟨38/3⟩ × ⟨21/8⟩ = ⟨798/24⟩ = ⟨133/4⟩ = ⟨33 1/4⟩이에요.","계산 결과는 ⟨33 1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨5 1/5⟩ × ⟨1 2/13⟩를 계산하면 얼마인가요?","options":[{"t":"6","correct":true},{"t":"⟨5 2/65⟩","mis":"M5-2-u2-X11"},{"t":"⟨1 5/13⟩","mis":"M5-2-u2-X04"},{"t":"⟨1 1/5⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨5 1/5⟩ × ⟨1 2/13⟩ = ⟨26/5⟩ × ⟨15/13⟩ = ⟨390/65⟩ = 6이에요.","계산 결과는 6이에요."]},{"stem":"단원 평가예요. ⟨3 3/8⟩ × ⟨1 8/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨6 3/8⟩","correct":true},{"t":"⟨3 1/3⟩","mis":"M5-2-u2-X11"},{"t":"⟨1 5/12⟩","mis":"M5-2-u2-X04"},{"t":"⟨3 3/8⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨3 3/8⟩ × ⟨1 8/9⟩ = ⟨27/8⟩ × ⟨17/9⟩ = ⟨459/72⟩ = ⟨51/8⟩ = ⟨6 3/8⟩이에요.","계산 결과는 ⟨6 3/8⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_challenge#3','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',3,'error','auto','⟨3 1/2⟩ × ⟨1 4/5⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X17']::text[],true,'{"seq":3,"concept":"M5-2-u2-C7","difficulty":3,"kind":"error","stem":"⟨3 1/2⟩ × ⟨1 4/5⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「자연수끼리 3 × 1, 분수끼리 ⟨1/2⟩ × ⟨4/5⟩ 해서 ⟨3 2/5⟩야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"순달 — 「가분수로 고쳐 ⟨7/2⟩ × ⟨9/5⟩ = ⟨6 3/10⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「⟨3 1/2⟩ × ⟨1 4/5⟩의 답은 ⟨6 3/10⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨3 1/2⟩ × ⟨1 4/5⟩ = ⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩ = ⟨6 3/10⟩이에요.","여울은 부분끼리 따로 곱해서 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨2 2/5⟩ × ⟨1 3/4⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「자연수끼리 2 × 1, 분수끼리 ⟨2/5⟩ × ⟨3/4⟩ 해서 ⟨2 3/10⟩이야.」","correct":true,"mis_target":"M5-2-u2-X11"},{"t":"순달 — 「가분수로 고쳐 ⟨12/5⟩ × ⟨7/4⟩ = ⟨4 1/5⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「⟨2 2/5⟩ × ⟨1 3/4⟩의 답은 ⟨4 1/5⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수는 자연수와 분수가 더해진 수라 따로 곱하면 빠지는 부분이 생겨요.","바르게 하면 ⟨2 2/5⟩ × ⟨1 3/4⟩ = ⟨12/5⟩ × ⟨7/4⟩ = ⟨84/20⟩ = ⟨21/5⟩ = ⟨4 1/5⟩이에요.","여울은 부분끼리 따로 곱해서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_challenge#4','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',3,'error','auto','문제로 마무리예요. 현주는 「⟨3 2/5⟩ × ⟨5/8⟩ = 3 × ⟨1/4⟩ = ⟨3/4⟩」으로, 태성이는 「⟨3/10⟩ × ⟨4/9⟩ = ⟨2/15⟩」로 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X06','M5-2-u2-X13']::text[],false,'{"seq":4,"concept":"M5-2-u2-C7","difficulty":3,"kind":"error","stem":"문제로 마무리예요. 현주는 「⟨3 2/5⟩ × ⟨5/8⟩ = 3 × ⟨1/4⟩ = ⟨3/4⟩」으로, 태성이는 「⟨3/10⟩ × ⟨4/9⟩ = ⟨2/15⟩」로 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"현주 — 대분수를 가분수로 나타내지 않고 약분했어요.","correct":true,"mis_target":"M5-2-u2-X06"},{"t":"태성 — 분자 4와 분모 10을 약분하면 안 돼요.","mis":"M5-2-u2-X13"},{"t":"두 친구 모두 바르게 계산했어요.","mis":"M5-2-u2-X06"}],"explanation":["현주는 대분수 ⟨3 2/5⟩를 그대로 두고 5와 5, 2와 8을 약분해 틀렸어요.","바르게 하면 ⟨3 2/5⟩ × ⟨5/8⟩ = ⟨17/5⟩ × ⟨5/8⟩ = ⟨17/8⟩ = ⟨2 1/8⟩이에요.","태성이는 분자와 분모 사이에서 약분해 ⟨2/15⟩로 바르게 계산했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_challenge#5','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',3,'mc','auto','수학익힘 문제예요. 1분에 ⟨4 2/3⟩ L씩 물이 일정하게 나오는 수도꼭지를 5분 30초 동안 틀어 놓았어요. 받을 수 있는 물은 몇 L인가요?',ARRAY['M5-2-u2-X21','M5-2-u2-X17']::text[],false,'{"seq":5,"concept":"M5-2-u2-C7","difficulty":3,"kind":"mc","stem":"수학익힘 문제예요. 1분에 ⟨4 2/3⟩ L씩 물이 일정하게 나오는 수도꼭지를 5분 30초 동안 틀어 놓았어요. 받을 수 있는 물은 몇 L인가요?","options":[{"t":"⟨25 2/3⟩","correct":true},{"t":"⟨24 11/15⟩","mis":"M5-2-u2-X21"},{"t":"⟨23 1/3⟩","mis":"M5-2-u2-X17"},{"t":"140","mis":"M5-2-u2-X21"}],"explanation":["1분은 60초이니 30초는 ⟨30/60⟩분 = ⟨1/2⟩분, 5분 30초는 ⟨5 1/2⟩분이에요.","⟨4 2/3⟩ × ⟨5 1/2⟩ = ⟨14/3⟩ × ⟨11/2⟩ = ⟨77/3⟩ = ⟨25 2/3⟩예요.","받을 수 있는 물은 ⟨25 2/3⟩ L예요 — 30초를 ⟨3/10⟩분으로 보지 않도록 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_challenge#6','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',3,'sa','auto','단원 평가예요. ⟨1 3/5⟩ × ⟨4 1/6⟩ > □⟨1/3⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M5-2-u2-C7","difficulty":3,"kind":"sa","stem":"단원 평가예요. ⟨1 3/5⟩ × ⟨4 1/6⟩ > □⟨1/3⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["⟨1 3/5⟩ × ⟨4 1/6⟩ = ⟨8/5⟩ × ⟨25/6⟩ = ⟨20/3⟩ = ⟨6 2/3⟩예요.","⟨6 2/3⟩ > □⟨1/3⟩이 되려면 □는 6 이하예요 — ⟨6 1/3⟩ < ⟨6 2/3⟩.","□에는 1부터 6까지 들어가 모두 6개예요."],"mis":"M5-2-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_challenge#7','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',3,'mc','auto','단원 평가예요. 수 카드 3, 4, 9를 한 번씩만 이용하여 대분수를 만들었어요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 곱은 얼마인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X17','M5-2-u2-X15']::text[],true,'{"seq":7,"concept":"M5-2-u2-C7","difficulty":3,"kind":"mc","stem":"단원 평가예요. 수 카드 3, 4, 9를 한 번씩만 이용하여 대분수를 만들었어요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 곱은 얼마인가요?","options":[{"t":"⟨33 7/12⟩","correct":true},{"t":"⟨27 1/3⟩","mis":"M5-2-u2-X11"},{"t":"⟨42 1/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨13 7/36⟩","mis":"M5-2-u2-X15"}],"explanation":["가장 큰 대분수는 ⟨9 3/4⟩, 가장 작은 대분수는 ⟨3 4/9⟩예요.","⟨9 3/4⟩ × ⟨3 4/9⟩ = ⟨39/4⟩ × ⟨31/9⟩ = ⟨1209/36⟩ = ⟨403/12⟩ = ⟨33 7/12⟩이에요.","곱은 ⟨33 7/12⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 수 카드 8, 3, 9를 한 번씩만 이용하여 만들 수 있는 가장 큰 대분수와 4의 곱은 얼마인가요?","options":[{"t":"⟨37 1/2⟩","correct":true},{"t":"⟨33 1/3⟩","mis":"M5-2-u2-X17"},{"t":"⟨15 5/9⟩","mis":"M5-2-u2-X17"},{"t":"⟨13 3/8⟩","mis":"M5-2-u2-X15"}],"explanation":["가장 큰 대분수는 자연수 부분에 가장 큰 수 9를 놓고 남은 두 수로 진분수 ⟨3/8⟩을 만든 ⟨9 3/8⟩이에요.","⟨9 3/8⟩ × 4 = ⟨75/8⟩ × 4 = ⟨300/8⟩ = ⟨75/2⟩ = ⟨37 1/2⟩이에요.","곱은 ⟨37 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_challenge#8','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',4,'sa','auto','단원 평가예요. 태희는 색종이 50장 중에서 어제 ⟨1/5⟩을 사용했고, 오늘은 남은 색종이의 ⟨5/8⟩를 사용했어요. 태희가 어제와 오늘 사용한 색종이는 모두 몇 장인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u2-C7","difficulty":4,"kind":"sa","stem":"단원 평가예요. 태희는 색종이 50장 중에서 어제 ⟨1/5⟩을 사용했고, 오늘은 남은 색종이의 ⟨5/8⟩를 사용했어요. 태희가 어제와 오늘 사용한 색종이는 모두 몇 장인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["어제 사용한 색종이는 50 × ⟨1/5⟩ = 10(장)이고, 남은 색종이는 50 − 10 = 40(장)이에요.","오늘은 남은 40장의 ⟨5/8⟩ — 40 × ⟨5/8⟩ = 25(장)이에요.","모두 10 + 25 = 35(장)이에요. 오늘 몫을 50장에 곱하지 않도록 해요."],"mis":"M5-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_challenge#9','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',4,'mc','auto','「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 활동을 바꾸어 계산 결과가 어떤 수보다 크면 파란색, 작으면 주황색, 같으면 초록색으로 칠하기로 했어요. 「1보다 크면 파란색」일 때 파란색으로 칠하는 칸은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],false,'{"seq":9,"concept":"M5-2-u2-C7","difficulty":4,"kind":"mc","stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 활동을 바꾸어 계산 결과가 어떤 수보다 크면 파란색, 작으면 주황색, 같으면 초록색으로 칠하기로 했어요. 「1보다 크면 파란색」일 때 파란색으로 칠하는 칸은 어느 것인가요?","options":[{"t":"⟨4/5⟩ × 3","correct":true},{"t":"⟨2/9⟩ × 4","mis":"M5-2-u2-X08"},{"t":"⟨1/2⟩ × ⟨4/7⟩","mis":"M5-2-u2-X08"},{"t":"⟨1/5⟩ × ⟨1/6⟩","mis":"M5-2-u2-X08"}],"explanation":["⟨4/5⟩ × 3 = ⟨12/5⟩ = ⟨2 2/5⟩ — 1보다 커요.","⟨2/9⟩ × 4 = ⟨8/9⟩, ⟨1/2⟩ × ⟨4/7⟩ = ⟨2/7⟩, ⟨1/5⟩ × ⟨1/6⟩ = ⟨1/30⟩ — 모두 1보다 작아요.","진분수끼리 곱하면 1보다 작아지고, 진분수에 자연수를 곱하면 1을 넘을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L07_challenge#10','math',5,2,'u2','L07','tb_g5_2_math_u2_L07_challenge','lesson_challenge','M5-2-u2-C7',4,'essay','teacher','⟨3 1/2⟩ × ⟨1 4/5⟩를 계산하는 과정을 쓰고, 자연수끼리(3 × 1), 분수끼리(⟨1/2⟩ × ⟨4/5⟩) 따로 곱하면 안 되는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C7","difficulty":4,"kind":"essay","stem":"⟨3 1/2⟩ × ⟨1 4/5⟩를 계산하는 과정을 쓰고, 자연수끼리(3 × 1), 분수끼리(⟨1/2⟩ × ⟨4/5⟩) 따로 곱하면 안 되는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 대분수를 가분수로 나타내면 ⟨3 1/2⟩ = ⟨7/2⟩, ⟨1 4/5⟩ = ⟨9/5⟩이다. 분모끼리, 분자끼리 곱하면 ⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩ = ⟨6 3/10⟩이다. 자연수끼리, 분수끼리만 곱하면 3과 ⟨4/10⟩를 더한 ⟨3 4/10⟩가 되는데, 3 × ⟨4/5⟩이나 ⟨1/2⟩ × 1처럼 곱해야 할 부분이 빠져 실제 값 ⟨6 3/10⟩보다 작아진다. 그래서 대분수는 가분수로 나타낸 다음 곱해야 한다.","scoring_points":["두 대분수를 ⟨7/2⟩, ⟨9/5⟩로 나타냈는가","⟨6 3/10⟩(= ⟨63/10⟩)을 구했는가","따로 곱하면 빠지는 부분이 생겨 값이 작아진다고 설명했는가"]},"explanation":["⟨3 1/2⟩ = ⟨7/2⟩, ⟨1 4/5⟩ = ⟨9/5⟩예요.","⟨7/2⟩ × ⟨9/5⟩ = ⟨63/10⟩ = ⟨6 3/10⟩이에요.","따로 곱하면 빠지는 부분이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_basic#1','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',1,'mc','auto','서연이네 마을에서는 비어 있는 공간을 공공 도서관, 어린이 놀이방, 수영장 가운데 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 만들려고 해요. 현재까지 158명이 공공 도서관을 만드는 것에 동의했어요. 이 문제에서 구하려는 것은 무엇인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X16']::text[],true,'{"seq":1,"concept":"M5-2-u2-C8","difficulty":1,"kind":"mc","stem":"서연이네 마을에서는 비어 있는 공간을 공공 도서관, 어린이 놀이방, 수영장 가운데 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 만들려고 해요. 현재까지 158명이 공공 도서관을 만드는 것에 동의했어요. 이 문제에서 구하려는 것은 무엇인가요?","options":[{"t":"공공 도서관을 만들려면 적어도 몇 명이 더 동의해야 하는지","correct":true},{"t":"현재까지 동의한 주민 수","mis":"M5-2-u2-X17"},{"t":"아직 동의하지 않은 주민 수","mis":"M5-2-u2-X16"},{"t":"마을 전체 주민 수","mis":"M5-2-u2-X17"}],"explanation":["물음은 「적어도 몇 명이 더 동의해야 하나요?」예요.","현재까지 동의한 수나 전체 주민 수는 알고 있거나 찾아야 하는 정보예요.","구하려는 것은 더 동의해야 하는 최소 주민 수예요."],"variant_rule":{"alt":[{"stem":"준기네 마을에서는 함께하는 공간을 전체 주민의 ⟨3/5⟩ 이상이 동의한 곳으로 만들려고 해요. 이 마을의 전체 주민 430명 가운데 현재까지 195명이 수영장을 만드는 것에 동의했어요. 이 문제에서 구하려는 것은 무엇인가요?","options":[{"t":"수영장을 만들려면 적어도 몇 명이 더 동의해야 하는지","correct":true},{"t":"현재까지 동의한 주민 수","mis":"M5-2-u2-X17"},{"t":"아직 동의하지 않은 주민 수","mis":"M5-2-u2-X16"},{"t":"마을 전체 주민 수","mis":"M5-2-u2-X17"}],"explanation":["물음은 「적어도 몇 명이 더 동의해야 하나요?」예요.","현재까지 동의한 수나 전체 주민 수는 알고 있거나 찾아야 하는 정보예요.","구하려는 것은 더 동의해야 하는 최소 주민 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_basic#2','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',1,'mc','auto','서연이네 마을에서는 비어 있는 공간을 공공 도서관, 어린이 놀이방, 수영장 가운데 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 만들려고 해요. 현재까지 158명이 공공 도서관을 만드는 것에 동의했어요. 알고 있는 것을 바르게 고른 것은 어느 것인가요?',ARRAY['M5-2-u2-X16','M5-2-u2-X17']::text[],false,'{"seq":2,"concept":"M5-2-u2-C8","difficulty":1,"kind":"mc","stem":"서연이네 마을에서는 비어 있는 공간을 공공 도서관, 어린이 놀이방, 수영장 가운데 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 만들려고 해요. 현재까지 158명이 공공 도서관을 만드는 것에 동의했어요. 알고 있는 것을 바르게 고른 것은 어느 것인가요?","options":[{"t":"전체 주민의 ⟨2/3⟩ 이상이 동의해야 하고, 현재까지 158명이 동의했다","correct":true},{"t":"전체 주민은 270명이고, 158명이 더 동의해야 한다","mis":"M5-2-u2-X16"},{"t":"현재까지 ⟨2/3⟩명이 동의했다","mis":"M5-2-u2-X17"},{"t":"158명의 ⟨2/3⟩가 동의해야 한다","mis":"M5-2-u2-X16"}],"explanation":["문제에 나온 것은 「전체 주민의 ⟨2/3⟩ 이상」과 「현재까지 158명이 동의」예요.","전체 주민 수는 문제에 없어요 — 더 알아야 하는 것이에요.","알고 있는 것과 더 알아야 하는 것을 가려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_basic#3','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',1,'mc','auto','서연이네 마을에서는 비어 있는 공간을 공공 도서관, 어린이 놀이방, 수영장 가운데 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 만들려고 해요. 현재까지 158명이 공공 도서관을 만드는 것에 동의했어요. 문제를 해결하기 위해 더 알아야 하는 것을 찾으면 어느 것인가요?',ARRAY['M5-2-u2-X16','M5-2-u2-X17']::text[],false,'{"seq":3,"concept":"M5-2-u2-C8","difficulty":1,"kind":"mc","stem":"서연이네 마을에서는 비어 있는 공간을 공공 도서관, 어린이 놀이방, 수영장 가운데 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 만들려고 해요. 현재까지 158명이 공공 도서관을 만드는 것에 동의했어요. 문제를 해결하기 위해 더 알아야 하는 것을 찾으면 어느 것인가요?","options":[{"t":"서연이네 마을 주민은 모두 270명이다","correct":true},{"t":"어린이 놀이방을 만드는 것에 동의한 주민은 30명이다","mis":"M5-2-u2-X16"},{"t":"가장 적은 주민이 동의한 장소는 수영장이다","mis":"M5-2-u2-X16"},{"t":"공공 도서관을 만드는 것에 동의한 주민은 158명이다","mis":"M5-2-u2-X17"}],"explanation":["「전체 주민의 ⟨2/3⟩」를 구하려면 전체 주민 수가 있어야 해요.","어린이 놀이방·수영장 이야기는 공공 도서관 문제에 필요 없는 정보예요.","더 알아야 하는 것은 「서연이네 마을 주민은 모두 270명」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_basic#4','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',1,'sa','auto','서연이네 마을 전체 주민은 270명이에요. 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u2-C8","difficulty":1,"kind":"sa","stem":"서연이네 마을 전체 주민은 270명이에요. 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["180"],"explanation":["전체 270명의 ⟨2/3⟩ 이상이에요.","270 × ⟨2/3⟩ = 180(명)이에요.","적어도 180명이 동의해야 해요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 430명이에요. 전체 주민의 ⟨3/5⟩ 이상이 동의해야 수영장을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["258"],"explanation":["전체 430명의 ⟨3/5⟩ 이상이에요.","430 × ⟨3/5⟩ = 258(명)이에요.","적어도 258명이 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_basic#5','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',2,'sa','auto','서연이네 마을 전체 주민은 270명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 158명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u2-C8","difficulty":2,"kind":"sa","stem":"서연이네 마을 전체 주민은 270명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 158명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["22"],"explanation":["① 최소로 동의해야 하는 수: 270 × ⟨2/3⟩ = 180(명)이에요.","② 지금까지 158명이 동의했으니 180 − 158 = 22(명)이에요.","적어도 22명이 더 동의해야 해요."],"mis":"M5-2-u2-X16","variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 430명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 수영장을 만들 수 있어요. 지금까지 195명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["63"],"explanation":["① 최소로 동의해야 하는 수: 430 × ⟨3/5⟩ = 258(명)이에요.","② 지금까지 195명이 동의했으니 258 − 195 = 63(명)이에요.","적어도 63명이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_basic#6','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',2,'mc','auto','서연이네 마을에서 「전체 주민의 몇 분의 몇 이상이 동의해야 공공 도서관을 만들 때, 적어도 몇 명이 더 동의해야 하는지」 구하는 순서로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X16','M5-2-u2-X07']::text[],true,'{"seq":6,"concept":"M5-2-u2-C8","difficulty":2,"kind":"mc","stem":"서연이네 마을에서 「전체 주민의 몇 분의 몇 이상이 동의해야 공공 도서관을 만들 때, 적어도 몇 명이 더 동의해야 하는지」 구하는 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"최소로 동의해야 하는 수를 곱셈으로 구한 뒤 동의한 수를 뺀다","correct":true},{"t":"동의한 수를 먼저 더한 뒤 전체로 나눈다","mis":"M5-2-u2-X16"},{"t":"전체 주민 수에서 동의한 수를 먼저 뺀다","mis":"M5-2-u2-X16"},{"t":"동의한 수에 분수를 곱한다","mis":"M5-2-u2-X07"}],"explanation":["① (전체 주민 수) × (분수)로 최소로 동의해야 하는 수를 구해요.","② 거기에서 지금까지 동의한 수를 빼요.","서연이네 마을 문제도 이 순서로 풀어요."],"variant_rule":{"alt":[{"stem":"준기네 마을에서 「전체 주민의 몇 분의 몇 이상이 동의해야 수영장을 만들 때, 적어도 몇 명이 더 동의해야 하는지」 구하는 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"최소로 동의해야 하는 수를 곱셈으로 구한 뒤 동의한 수를 뺀다","correct":true},{"t":"동의한 수를 먼저 더한 뒤 전체로 나눈다","mis":"M5-2-u2-X16"},{"t":"전체 주민 수에서 동의한 수를 먼저 뺀다","mis":"M5-2-u2-X16"},{"t":"동의한 수에 분수를 곱한다","mis":"M5-2-u2-X07"}],"explanation":["① (전체 주민 수) × (분수)로 최소로 동의해야 하는 수를 구해요.","② 거기에서 지금까지 동의한 수를 빼요.","준기네 마을 문제도 이 순서로 풀어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_basic#7','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',2,'error','auto','서연이네 마을 전체 주민 270명의 ⟨2/3⟩ 이상이 동의해야 하고, 지금까지 158명이 동의했어요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?',ARRAY['M5-2-u2-X16','M5-2-u2-X17']::text[],true,'{"seq":7,"concept":"M5-2-u2-C8","difficulty":2,"kind":"error","stem":"서연이네 마을 전체 주민 270명의 ⟨2/3⟩ 이상이 동의해야 하고, 지금까지 158명이 동의했어요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?","options":[{"t":"여울 — 「270 − 158 = 112명이 더 동의해야 해.」","correct":true,"mis_target":"M5-2-u2-X16"},{"t":"순달 — 「270 × ⟨2/3⟩ = 180명이 동의해야 해.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「180 − 158 = 22명이 더 동의해야 해.」","mis":"M5-2-u2-X17"}],"explanation":["먼저 최소로 동의해야 하는 수 270 × ⟨2/3⟩ = 180(명)을 구해요.","그다음 180 − 158 = 22(명)이에요.","여울은 전체에서 바로 빼서 「아직 동의하지 않은 수」를 구했어요."],"variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민 430명의 ⟨3/5⟩ 이상이 동의해야 하고, 지금까지 195명이 동의했어요. 친구들의 풀이 가운데 잘못된 것은 누구의 것인가요?","options":[{"t":"여울 — 「430 − 195 = 235명이 더 동의해야 해.」","correct":true,"mis_target":"M5-2-u2-X16"},{"t":"순달 — 「430 × ⟨3/5⟩ = 258명이 동의해야 해.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「258 − 195 = 63명이 더 동의해야 해.」","mis":"M5-2-u2-X17"}],"explanation":["먼저 최소로 동의해야 하는 수 430 × ⟨3/5⟩ = 258(명)을 구해요.","그다음 258 − 195 = 63(명)이에요.","여울은 전체에서 바로 빼서 「아직 동의하지 않은 수」를 구했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_basic#8','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',2,'sa','auto','서연이네 마을 전체 주민은 270명이고, 지금까지 158명이 공공 도서관 만들기에 동의했어요. 아직 동의하지 않은 주민은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u2-C8","difficulty":2,"kind":"sa","stem":"서연이네 마을 전체 주민은 270명이고, 지금까지 158명이 공공 도서관 만들기에 동의했어요. 아직 동의하지 않은 주민은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["112"],"explanation":["아직 동의하지 않은 주민은 전체에서 동의한 수를 빼요.","270 − 158 = 112(명)이에요.","「더 동의해야 하는 수」와 다른 물음이에요 — 112명."],"mis":"M5-2-u2-X17","variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 430명이고, 지금까지 195명이 수영장 만들기에 동의했어요. 아직 동의하지 않은 주민은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["235"],"explanation":["아직 동의하지 않은 주민은 전체에서 동의한 수를 빼요.","430 − 195 = 235(명)이에요.","「더 동의해야 하는 수」와 다른 물음이에요 — 235명."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_basic#9','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',2,'ox','auto','「전체의 ⟨2/3⟩ 이상」을 구할 때는 곱셈을 써요.',ARRAY['M5-2-u2-X15']::text[],true,'{"seq":9,"concept":"M5-2-u2-C8","difficulty":2,"kind":"ox","stem":"「전체의 ⟨2/3⟩ 이상」을 구할 때는 곱셈을 써요.","answer":"O","reason_options":[{"t":"전체의 ⟨2/3⟩는 (전체) × ⟨2/3⟩이므로","correct":true},{"t":"전체에 3을 더해야 하므로","mis":"M5-2-u2-X15"}],"mis":"M5-2-u2-X15","explanation":["전체 270명의 ⟨2/3⟩는 270 × ⟨2/3⟩예요.","270 × ⟨2/3⟩ = 180이에요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"전체 주민 수를 몰라도 적어도 몇 명이 더 동의해야 하는지 구할 수 있어요.","answer":"X","reason_options":[{"t":"전체 주민 수가 있어야 최소로 필요한 수를 곱셈으로 구할 수 있으므로","correct":true},{"t":"동의한 수만 알면 되므로","mis":"M5-2-u2-X16"}],"explanation":["최소로 동의해야 하는 수는 (전체) × (분수)예요.","전체를 모르면 곱셈을 할 수 없어요.","없는 정보부터 찾아야 해요."]},{"stem":"「⟨3/5⟩ 이상」이면 전체의 ⟨3/5⟩과 같은 수만큼 동의해도 돼요.","answer":"O","reason_options":[{"t":"「이상」은 그 수를 포함하므로","correct":true},{"t":"「이상」은 그 수보다 반드시 커야 하므로","mis":"M5-2-u2-X17"}],"explanation":["「이상」은 기준이 되는 수를 포함해요.","전체의 ⟨3/5⟩과 같은 수만큼 동의하면 조건을 채워요.","그래서 「적어도」 그 수만큼이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_basic#10','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_basic','lesson_basic','M5-2-u2-C8',3,'mc','auto','서연이네 마을은 주민 270명 가운데 ⟨2/3⟩ 이상, 준기네 마을은 주민 430명 가운데 ⟨3/5⟩ 이상이 동의해야 해요. 지금까지 각각 158명, 195명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X16']::text[],false,'{"seq":10,"concept":"M5-2-u2-C8","difficulty":3,"kind":"mc","stem":"서연이네 마을은 주민 270명 가운데 ⟨2/3⟩ 이상, 준기네 마을은 주민 430명 가운데 ⟨3/5⟩ 이상이 동의해야 해요. 지금까지 각각 158명, 195명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"준기네 마을","correct":true},{"t":"서연이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["서연이네 마을: 270 × ⟨2/3⟩ = 180, 180 − 158 = 22(명)이에요.","준기네 마을: 430 × ⟨3/5⟩ = 258, 258 − 195 = 63(명)이에요.","준기네 마을에서 더 많이 더 동의해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_challenge#1','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',2,'mc','auto','서연이네 마을 전체 주민은 270명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 158명이 동의했다면 공공 도서관을 만들 수 있나요?',ARRAY['M5-2-u2-X16','M5-2-u2-X07']::text[],true,'{"seq":1,"concept":"M5-2-u2-C8","difficulty":2,"kind":"mc","stem":"서연이네 마을 전체 주민은 270명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 158명이 동의했다면 공공 도서관을 만들 수 있나요?","options":[{"t":"아직 만들 수 없다","correct":true},{"t":"만들 수 있다","mis":"M5-2-u2-X16"},{"t":"전체 주민이 모두 동의해야 만들 수 있다","mis":"M5-2-u2-X07"},{"t":"동의한 수만으로는 알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["최소로 동의해야 하는 수는 270 × ⟨2/3⟩ = 180(명)이에요.","지금까지 158명이 동의했어요.","22명이 더 필요해 아직 만들 수 없어요."],"variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 430명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 수영장을 만들 수 있어요. 지금까지 195명이 동의했다면 수영장을 만들 수 있나요?","options":[{"t":"아직 만들 수 없다","correct":true},{"t":"만들 수 있다","mis":"M5-2-u2-X16"},{"t":"전체 주민이 모두 동의해야 만들 수 있다","mis":"M5-2-u2-X07"},{"t":"동의한 수만으로는 알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["최소로 동의해야 하는 수는 430 × ⟨3/5⟩ = 258(명)이에요.","지금까지 195명이 동의했어요.","63명이 더 필요해 아직 만들 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_challenge#2','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',2,'sa','auto','서연이네 마을은 주민 270명 가운데 ⟨2/3⟩ 이상, 준기네 마을은 주민 430명 가운데 ⟨3/5⟩ 이상이 동의해야 해요. 지금까지 각각 158명, 195명이 동의했어요. 두 마을에서 적어도 더 동의해야 하는 사람은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M5-2-u2-C8","difficulty":2,"kind":"sa","stem":"서연이네 마을은 주민 270명 가운데 ⟨2/3⟩ 이상, 준기네 마을은 주민 430명 가운데 ⟨3/5⟩ 이상이 동의해야 해요. 지금까지 각각 158명, 195명이 동의했어요. 두 마을에서 적어도 더 동의해야 하는 사람은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["서연이네 마을: 270 × ⟨2/3⟩ = 180, 180 − 158 = 22(명)이에요.","준기네 마을: 430 × ⟨3/5⟩ = 258, 258 − 195 = 63(명)이에요.","모두 22 + 63 = 85(명)이에요."],"mis":"M5-2-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_challenge#3','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',3,'mc','auto','서연이네 마을에서는 비어 있는 공간을 공공 도서관, 어린이 놀이방, 수영장 가운데 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 만들려고 해요. 현재까지 158명이 공공 도서관을 만드는 것에 동의했어요. 서연이네 마을 주민은 모두 270명이고, 어린이 놀이방을 만드는 것에 동의한 주민은 30명이에요. 공공 도서관 문제를 푸는 데 필요 없는 정보는 어느 것인가요?',ARRAY['M5-2-u2-X16']::text[],false,'{"seq":3,"concept":"M5-2-u2-C8","difficulty":3,"kind":"mc","stem":"서연이네 마을에서는 비어 있는 공간을 공공 도서관, 어린이 놀이방, 수영장 가운데 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 만들려고 해요. 현재까지 158명이 공공 도서관을 만드는 것에 동의했어요. 서연이네 마을 주민은 모두 270명이고, 어린이 놀이방을 만드는 것에 동의한 주민은 30명이에요. 공공 도서관 문제를 푸는 데 필요 없는 정보는 어느 것인가요?","options":[{"t":"어린이 놀이방에 동의한 주민 30명","correct":true},{"t":"전체 주민 270명","mis":"M5-2-u2-X16"},{"t":"전체 주민의 ⟨2/3⟩ 이상","mis":"M5-2-u2-X16"},{"t":"공공 도서관에 동의한 주민 158명","mis":"M5-2-u2-X16"}],"explanation":["공공 도서관 문제에는 전체 주민 수, ⟨2/3⟩, 동의한 158명이 필요해요.","270 × ⟨2/3⟩ = 180, 180 − 158 = 22(명)으로 풀 수 있어요.","어린이 놀이방에 동의한 30명은 쓰지 않는 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_challenge#4','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',3,'mc','auto','준기네 마을에서는 함께하는 공간을 전체 주민의 ⟨3/5⟩ 이상이 동의한 곳으로 만들려고 해요. 이 마을의 전체 주민 430명 가운데 현재까지 195명이 수영장을 만드는 것에 동의했어요. 적어도 몇 명이 더 동의해야 하는지 한 식으로 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u2-X16','M5-2-u2-X15']::text[],true,'{"seq":4,"concept":"M5-2-u2-C8","difficulty":3,"kind":"mc","stem":"준기네 마을에서는 함께하는 공간을 전체 주민의 ⟨3/5⟩ 이상이 동의한 곳으로 만들려고 해요. 이 마을의 전체 주민 430명 가운데 현재까지 195명이 수영장을 만드는 것에 동의했어요. 적어도 몇 명이 더 동의해야 하는지 한 식으로 나타낸 것은 어느 것인가요?","options":[{"t":"430 × ⟨3/5⟩ − 195","correct":true},{"t":"(430 − 195) × ⟨3/5⟩","mis":"M5-2-u2-X16"},{"t":"430 − 195 × ⟨3/5⟩","mis":"M5-2-u2-X16"},{"t":"430 × ⟨3/5⟩ + 195","mis":"M5-2-u2-X15"}],"explanation":["먼저 최소로 동의해야 하는 수 430 × ⟨3/5⟩을 구해요.","거기에서 현재까지 동의한 195명을 빼요.","430 × ⟨3/5⟩ − 195 = 258 − 195 = 63(명)이에요."],"variant_rule":{"alt":[{"stem":"서연이네 마을에서는 비어 있는 공간을 공공 도서관, 어린이 놀이방, 수영장 가운데 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 만들려고 해요. 현재까지 158명이 공공 도서관을 만드는 것에 동의했어요. 서연이네 마을 주민은 모두 270명이에요. 적어도 몇 명이 더 동의해야 하는지 한 식으로 나타낸 것은 어느 것인가요?","options":[{"t":"270 × ⟨2/3⟩ − 158","correct":true},{"t":"(270 − 158) × ⟨2/3⟩","mis":"M5-2-u2-X16"},{"t":"270 − 158 × ⟨2/3⟩","mis":"M5-2-u2-X16"},{"t":"270 × ⟨2/3⟩ + 158","mis":"M5-2-u2-X15"}],"explanation":["먼저 최소로 동의해야 하는 수 270 × ⟨2/3⟩를 구해요.","거기에서 현재까지 동의한 158명을 빼요.","270 × ⟨2/3⟩ − 158 = 180 − 158 = 22(명)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_challenge#5','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',3,'mc','auto','수학익힘 문제예요. 혜지네 학교 5학년 전체 학생 160명 가운데 ⟨5/8⟩는 남학생이고, 그중 ⟨3/5⟩은 야구를 좋아해요. 야구를 좋아하는 5학년 남학생 수를 구하는 식은 어느 것인가요?',ARRAY['M5-2-u2-X15','M5-2-u2-X16']::text[],true,'{"seq":5,"concept":"M5-2-u2-C8","difficulty":3,"kind":"mc","stem":"수학익힘 문제예요. 혜지네 학교 5학년 전체 학생 160명 가운데 ⟨5/8⟩는 남학생이고, 그중 ⟨3/5⟩은 야구를 좋아해요. 야구를 좋아하는 5학년 남학생 수를 구하는 식은 어느 것인가요?","options":[{"t":"160 × ⟨5/8⟩ × ⟨3/5⟩","correct":true},{"t":"160 × ⟨5/8⟩ + ⟨3/5⟩","mis":"M5-2-u2-X15"},{"t":"160 × ⟨3/5⟩","mis":"M5-2-u2-X16"},{"t":"160 − ⟨5/8⟩ × ⟨3/5⟩","mis":"M5-2-u2-X15"}],"explanation":["남학생은 160 × ⟨5/8⟩ = 100(명)이에요.","그중 ⟨3/5⟩이니 100 × ⟨3/5⟩ = 60(명)이에요.","한 식으로 160 × ⟨5/8⟩ × ⟨3/5⟩ = 60이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 선아네 학교 도서관에 있는 책 300권 중에서 ⟨1/3⟩은 과학책이고, 선아는 과학책 중에서 ⟨3/5⟩을 읽었어요. 선아가 읽은 과학책 수를 구하는 식은 어느 것인가요?","options":[{"t":"300 × ⟨1/3⟩ × ⟨3/5⟩","correct":true},{"t":"300 × ⟨1/3⟩ + ⟨3/5⟩","mis":"M5-2-u2-X15"},{"t":"300 × ⟨3/5⟩","mis":"M5-2-u2-X16"},{"t":"300 − ⟨1/3⟩ × ⟨3/5⟩","mis":"M5-2-u2-X15"}],"explanation":["과학책은 300 × ⟨1/3⟩ = 100(권)이에요.","그중 ⟨3/5⟩이니 100 × ⟨3/5⟩ = 60(권)이에요.","한 식으로 300 × ⟨1/3⟩ × ⟨3/5⟩ = 60이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_challenge#6','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',3,'mc','auto','단원 평가예요. 은서는 집에서 ⟨14/15⟩ km 떨어진 서점에 가는데 전체 거리의 ⟨5/6⟩는 버스를 타고 나머지는 걸어서 갔어요. 걸어서 간 거리를 구하려고 할 때 먼저 알아야 하는 것은 어느 것인가요?',ARRAY['M5-2-u2-X19','M5-2-u2-X15','M5-2-u2-X18']::text[],false,'{"seq":6,"concept":"M5-2-u2-C8","difficulty":3,"kind":"mc","stem":"단원 평가예요. 은서는 집에서 ⟨14/15⟩ km 떨어진 서점에 가는데 전체 거리의 ⟨5/6⟩는 버스를 타고 나머지는 걸어서 갔어요. 걸어서 간 거리를 구하려고 할 때 먼저 알아야 하는 것은 어느 것인가요?","options":[{"t":"걸어서 간 거리는 전체 거리의 ⟨1/6⟩이라는 것","correct":true},{"t":"걸어서 간 거리는 전체 거리의 ⟨5/6⟩라는 것","mis":"M5-2-u2-X19"},{"t":"걸어서 간 거리는 ⟨14/15⟩ − ⟨5/6⟩ km라는 것","mis":"M5-2-u2-X15"},{"t":"버스를 탄 거리는 ⟨5/6⟩ km라는 것","mis":"M5-2-u2-X18"}],"explanation":["버스로 간 것이 전체의 ⟨5/6⟩이면 나머지는 1 − ⟨5/6⟩ = ⟨1/6⟩이에요.","걸어서 간 거리는 ⟨14/15⟩ × ⟨1/6⟩ = ⟨7/45⟩(km)예요.","「나머지」는 1에서 주어진 분수를 빼서 먼저 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_challenge#7','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',3,'sa','auto','단원 평가예요. 태희는 색종이 50장 중에서 어제 ⟨1/5⟩을 사용했고, 오늘은 남은 색종이의 ⟨5/8⟩를 사용했어요. 오늘 사용한 색종이는 몇 장인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M5-2-u2-C8","difficulty":3,"kind":"sa","stem":"단원 평가예요. 태희는 색종이 50장 중에서 어제 ⟨1/5⟩을 사용했고, 오늘은 남은 색종이의 ⟨5/8⟩를 사용했어요. 오늘 사용한 색종이는 몇 장인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["어제 사용한 색종이는 50 × ⟨1/5⟩ = 10(장)이에요.","남은 색종이는 50 − 10 = 40(장)이에요.","오늘은 40 × ⟨5/8⟩ = 25(장)을 사용했어요."],"mis":"M5-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_challenge#8','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',4,'sa','auto','조건을 바꾸어 새로운 문제를 만들었어요. 서연이네 마을 주민 270명 가운데 현재까지 158명이 공공 도서관에 동의했는데, 조건을 「전체 주민의 ⟨2/3⟩ 이상」에서 준기네 마을처럼 「전체 주민의 ⟨3/5⟩ 이상」으로 바꾸면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u2-C8","difficulty":4,"kind":"sa","stem":"조건을 바꾸어 새로운 문제를 만들었어요. 서연이네 마을 주민 270명 가운데 현재까지 158명이 공공 도서관에 동의했는데, 조건을 「전체 주민의 ⟨2/3⟩ 이상」에서 준기네 마을처럼 「전체 주민의 ⟨3/5⟩ 이상」으로 바꾸면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["최소로 동의해야 하는 수: 270 × ⟨3/5⟩ = 162(명)이에요.","162 − 158 = 4(명)이에요.","조건이 ⟨2/3⟩일 때의 22명보다 적어져요 — ⟨3/5⟩ < ⟨2/3⟩이라서예요."],"mis":"M5-2-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_challenge#9','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',4,'sa','auto','서연이네 마을에서는 비어 있는 공간을 공공 도서관, 어린이 놀이방, 수영장 가운데 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 만들려고 해요. 현재까지 158명이 공공 도서관을 만드는 것에 동의했어요. 서연이네 마을 주민은 모두 270명이고, 어린이 놀이방을 만드는 것에 동의한 주민은 30명이에요. 공공 도서관 대신 어린이 놀이방을 만들려면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u2-C8","difficulty":4,"kind":"sa","stem":"서연이네 마을에서는 비어 있는 공간을 공공 도서관, 어린이 놀이방, 수영장 가운데 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 만들려고 해요. 현재까지 158명이 공공 도서관을 만드는 것에 동의했어요. 서연이네 마을 주민은 모두 270명이고, 어린이 놀이방을 만드는 것에 동의한 주민은 30명이에요. 공공 도서관 대신 어린이 놀이방을 만들려면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["150"],"explanation":["어느 장소든 최소로 동의해야 하는 수는 270 × ⟨2/3⟩ = 180(명)이에요.","어린이 놀이방에는 30명이 동의했으니 180 − 30 = 150(명)이에요.","같은 조건이라도 현재까지 동의한 수가 다르면 더 필요한 수가 달라져요."],"mis":"M5-2-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_L08_challenge#10','math',5,2,'u2','L08','tb_g5_2_math_u2_L08_challenge','lesson_challenge','M5-2-u2-C8',4,'essay','teacher','서연이네 마을에서는 비어 있는 공간을 공공 도서관, 어린이 놀이방, 수영장 가운데 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 만들려고 해요. 현재까지 158명이 공공 도서관을 만드는 것에 동의했어요. 서연이네 마을 주민은 모두 270명이에요. 공공 도서관을 만들려면 적어도 몇 명이 더 동의해야 하는지 푸는 순서대로 식을 쓰고, 처음 문제에 전체 주민 수가 없을 때 해결할 수 없는 까닭도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C8","difficulty":4,"kind":"essay","stem":"서연이네 마을에서는 비어 있는 공간을 공공 도서관, 어린이 놀이방, 수영장 가운데 전체 주민의 ⟨2/3⟩ 이상이 동의한 곳으로 만들려고 해요. 현재까지 158명이 공공 도서관을 만드는 것에 동의했어요. 서연이네 마을 주민은 모두 270명이에요. 공공 도서관을 만들려면 적어도 몇 명이 더 동의해야 하는지 푸는 순서대로 식을 쓰고, 처음 문제에 전체 주민 수가 없을 때 해결할 수 없는 까닭도 써 보세요.","answer_guide":{"answer":"예: ① 최소로 동의해야 하는 주민 수는 270 × ⟨2/3⟩ = 180(명)이다. ② 현재까지 158명이 동의했으므로 180 − 158 = 22(명)이 더 동의해야 한다. 「전체 주민의 ⟨2/3⟩」는 (전체 주민 수) × ⟨2/3⟩로 구하므로 전체 주민 수를 모르면 최소로 동의해야 하는 수를 구할 수 없어 문제를 해결할 수 없다.","scoring_points":["270 × ⟨2/3⟩ = 180(명)을 구했는가","180 − 158 = 22(명)을 구했는가","전체 주민 수가 있어야 곱셈을 할 수 있다고 썼는가"]},"explanation":["270 × ⟨2/3⟩ = 180(명)이에요.","180 − 158 = 22(명)이에요.","전체 주민 수를 알아야 「전체의 ⟨2/3⟩」를 구할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#1','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C2',1,'mc','auto','문제로 마무리예요. ⟨4/7⟩ × 3을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":1,"concept":"M5-2-u2-C2","difficulty":1,"kind":"mc","stem":"문제로 마무리예요. ⟨4/7⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨1 5/7⟩","correct":true},{"t":"⟨12/21⟩","mis":"M5-2-u2-X01"},{"t":"⟨4/21⟩","mis":"M5-2-u2-X02"},{"t":"1","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨4/7⟩ × 3 = ⟨12/7⟩ = ⟨1 5/7⟩예요.","계산 결과는 ⟨1 5/7⟩예요."],"variant_rule":{"alt":[{"stem":"형성 평가예요. ⟨2/7⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨6/7⟩","correct":true},{"t":"⟨6/21⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/21⟩","mis":"M5-2-u2-X02"},{"t":"⟨5/7⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/7⟩ × 3 = ⟨6/7⟩이에요.","계산 결과는 ⟨6/7⟩이에요."]},{"stem":"단원 평가예요. ⟨1/5⟩ × 4를 계산하면 얼마인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨4/20⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/20⟩","mis":"M5-2-u2-X02"},{"t":"1","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨1/5⟩ × 4 = ⟨4/5⟩예요.","계산 결과는 ⟨4/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#2','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C5',1,'mc','auto','문제로 마무리예요. 5 × ⟨1 2/9⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":2,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"문제로 마무리예요. 5 × ⟨1 2/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 1/9⟩","correct":true},{"t":"⟨5 2/9⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/9⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","5 × ⟨1 2/9⟩ = 5 × ⟨11/9⟩ = ⟨55/9⟩ = ⟨6 1/9⟩이에요.","계산 결과는 ⟨6 1/9⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 6 × ⟨3 1/3⟩을 계산하면 얼마인가요?","options":[{"t":"20","correct":true},{"t":"⟨18 1/3⟩","mis":"M5-2-u2-X05"},{"t":"5","mis":"M5-2-u2-X05"},{"t":"8","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","6 × ⟨3 1/3⟩ = 6 × ⟨10/3⟩ = ⟨60/3⟩ = 20이에요.","계산 결과는 20이에요."]},{"stem":"단원 평가예요. 4 × ⟨1 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"6","correct":true},{"t":"⟨4 1/2⟩","mis":"M5-2-u2-X05"},{"t":"3","mis":"M5-2-u2-X05"},{"t":"4","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","4 × ⟨1 1/2⟩ = 4 × ⟨3/2⟩ = ⟨12/2⟩ = 6이에요.","계산 결과는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#3','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C2',1,'mc','auto','문제로 마무리예요. ⟨5/21⟩ × 7을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":3,"concept":"M5-2-u2-C2","difficulty":1,"kind":"mc","stem":"문제로 마무리예요. ⟨5/21⟩ × 7을 계산하면 얼마인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨35/147⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/147⟩","mis":"M5-2-u2-X02"},{"t":"⟨4/7⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨5/21⟩ × 7 = ⟨35/21⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요.","계산 결과는 ⟨1 2/3⟩예요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. ⟨1 9/11⟩ × 5를 계산하면 얼마인가요?","options":[{"t":"⟨9 1/11⟩","correct":true},{"t":"⟨5 9/11⟩","mis":"M5-2-u2-X05"},{"t":"⟨5 1/11⟩","mis":"M5-2-u2-X05"},{"t":"⟨4 6/11⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨1 9/11⟩ × 5 = ⟨20/11⟩ × 5 = ⟨100/11⟩ = ⟨9 1/11⟩이에요.","계산 결과는 ⟨9 1/11⟩이에요."]},{"stem":"문제로 마무리예요. 4 × ⟨1 7/12⟩을 계산하면 얼마인가요?","options":[{"t":"⟨6 1/3⟩","correct":true},{"t":"⟨4 7/12⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","4 × ⟨1 7/12⟩ = 4 × ⟨19/12⟩ = ⟨76/12⟩ = ⟨19/3⟩ = ⟨6 1/3⟩이에요.","계산 결과는 ⟨6 1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#4','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C1',1,'mc','auto','불꽃 축제 장소까지 전체 1 km예요. 지금까지 ⟨4/5⟩ km를 걸어왔다면 남은 길은 몇 km인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X01','M5-2-u2-X12']::text[],true,'{"seq":4,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"불꽃 축제 장소까지 전체 1 km예요. 지금까지 ⟨4/5⟩ km를 걸어왔다면 남은 길은 몇 km인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨4/5⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/4⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/5⟩","mis":"M5-2-u2-X12"}],"explanation":["1은 ⟨5/5⟩와 같아요.","남은 길은 ⟨5/5⟩ − ⟨4/5⟩ = ⟨1/5⟩이에요.","분모가 같으면 뺄셈도 분자끼리 해요 — ⟨1/5⟩ km."],"variant_rule":{"alt":[{"stem":"⟨5/30⟩를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨6/1⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/7⟩","mis":"M5-2-u2-X12"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","5와 30을 모두 5로 나눌 수 있어요 — 5 ÷ 5 = 1, 30 ÷ 5 = 6.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨5/30⟩ = ⟨1/6⟩."]},{"stem":"⟨27/36⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨4/3⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X12"},{"t":"1","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","27과 36을 모두 9로 나눌 수 있어요 — 27 ÷ 9 = 3, 36 ÷ 9 = 4.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨27/36⟩ = ⟨3/4⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#5','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C7',1,'mc','auto','문제로 마무리예요. 빈칸에 알맞은 수를 써넣어요. 2에 ⟨5/8⟩를 곱한 수를 첫째 빈칸에, 그 수에 ⟨2 2/5⟩를 곱한 수를 둘째 빈칸에 써요. 둘째 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X11','M5-2-u2-X15']::text[],true,'{"seq":5,"concept":"M5-2-u2-C7","difficulty":1,"kind":"mc","stem":"문제로 마무리예요. 빈칸에 알맞은 수를 써넣어요. 2에 ⟨5/8⟩를 곱한 수를 첫째 빈칸에, 그 수에 ⟨2 2/5⟩를 곱한 수를 둘째 빈칸에 써요. 둘째 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"3","correct":true},{"t":"⟨1 1/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨2 1/10⟩","mis":"M5-2-u2-X11"},{"t":"⟨3 13/20⟩","mis":"M5-2-u2-X15"}],"explanation":["첫째 빈칸: 2 × ⟨5/8⟩ = ⟨10/8⟩ = ⟨5/4⟩ = ⟨1 1/4⟩이에요.","둘째 빈칸: ⟨1 1/4⟩ × ⟨2 2/5⟩ = ⟨5/4⟩ × ⟨12/5⟩ = ⟨60/20⟩ = 3이에요.","대분수끼리는 가분수로 나타내어 곱해요 — 둘째 빈칸은 3이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. ⟨3 1/2⟩ × ⟨2 3/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨8 1/2⟩","correct":true},{"t":"⟨6 3/14⟩","mis":"M5-2-u2-X11"},{"t":"⟨4 6/7⟩","mis":"M5-2-u2-X04"},{"t":"⟨2 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨3 1/2⟩ × ⟨2 3/7⟩ = ⟨7/2⟩ × ⟨17/7⟩ = ⟨119/14⟩ = ⟨17/2⟩ = ⟨8 1/2⟩이에요.","계산 결과는 ⟨8 1/2⟩이에요."]},{"stem":"단원 평가예요. 4 × ⟨2 1/12⟩을 계산하면 얼마인가요?","options":[{"t":"⟨8 1/3⟩","correct":true},{"t":"⟨8 1/12⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/3⟩","mis":"M5-2-u2-X05"},{"t":"1","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","4 × ⟨2 1/12⟩ = 4 × ⟨25/12⟩ = ⟨100/12⟩ = ⟨25/3⟩ = ⟨8 1/3⟩이에요.","계산 결과는 ⟨8 1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#6','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C7',1,'match','auto','문제로 마무리예요. 계산 결과가 같은 것끼리 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u2-C7","difficulty":1,"kind":"match","stem":"문제로 마무리예요. 계산 결과가 같은 것끼리 이으세요.","pairs":[{"l":"6 × ⟨1 3/8⟩","r":"11 × ⟨3/4⟩"},{"l":"⟨5/36⟩ × 3","r":"⟨15/16⟩ × ⟨4/9⟩"},{"l":"⟨1/2⟩ × ⟨1/3⟩ × ⟨3/10⟩","r":"⟨1/4⟩ × ⟨1/5⟩"}],"mis":"M5-2-u2-X12","explanation":["6 × ⟨1 3/8⟩ = ⟨33/4⟩ = ⟨8 1/4⟩, 11 × ⟨3/4⟩ = ⟨33/4⟩ = ⟨8 1/4⟩이에요.","⟨5/36⟩ × 3 = ⟨5/12⟩, ⟨15/16⟩ × ⟨4/9⟩ = ⟨5/12⟩예요.","⟨1/2⟩ × ⟨1/3⟩ × ⟨3/10⟩ = ⟨1/20⟩, ⟨1/4⟩ × ⟨1/5⟩ = ⟨1/20⟩ — 약분하거나 대분수로 나타내어 견줘요."],"variant_rule":{"alt":[{"stem":"형성 평가 「(분수)×(자연수)를 계산해요」예요. 곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"⟨2/7⟩ × 3","r":"⟨6/7⟩"},{"l":"⟨5/6⟩ × 8","r":"⟨6 2/3⟩"},{"l":"⟨3/5⟩ × 6","r":"⟨3 3/5⟩"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/7⟩ × 3 = ⟨6/7⟩, ⟨5/6⟩ × 8 = ⟨40/6⟩ = ⟨20/3⟩ = ⟨6 2/3⟩, ⟨3/5⟩ × 6 = ⟨18/5⟩ = ⟨3 3/5⟩이에요.","분모에 자연수를 곱하지 않도록 해요."]},{"stem":"형성 평가 「(자연수)×(분수)를 계산해요」예요. 곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"12 × ⟨2/9⟩","r":"⟨2 2/3⟩"},{"l":"9 × ⟨5/6⟩","r":"⟨7 1/2⟩"},{"l":"3 × ⟨1/4⟩","r":"⟨3/4⟩"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","12 × ⟨2/9⟩ = ⟨24/9⟩ = ⟨8/3⟩ = ⟨2 2/3⟩, 9 × ⟨5/6⟩ = ⟨45/6⟩ = ⟨15/2⟩ = ⟨7 1/2⟩, 3 × ⟨1/4⟩ = ⟨3/4⟩이에요.","자연수를 분모에 곱하지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#7','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C4',1,'sa','auto','문제로 마무리예요. 지한이는 토요일에 하루 24시간의 ⟨1/8⟩만큼 책을 읽었어요. 지한이가 토요일에 책을 읽은 시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C4","difficulty":1,"kind":"sa","stem":"문제로 마무리예요. 지한이는 토요일에 하루 24시간의 ⟨1/8⟩만큼 책을 읽었어요. 지한이가 토요일에 책을 읽은 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["하루는 24시간이에요.","24 × ⟨1/8⟩ = ⟨24/8⟩ = 3이에요.","지한이가 책을 읽은 시간은 3시간이에요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"형성 평가예요. 이안이는 여름 방학 동안 책 25권을 읽었는데 그중 ⟨2/5⟩가 위인전이었어요. 이안이가 읽은 위인전은 몇 권인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["25권의 ⟨2/5⟩는 25 × ⟨2/5⟩예요.","25 × ⟨2/5⟩ = ⟨50/5⟩ = 10이에요.","이안이가 읽은 위인전은 10권이에요."]},{"stem":"수학익힘 문제예요. 재우는 수세미 열매를 1시간의 ⟨1/5⟩ 동안 데쳤어요. 수세미 열매를 데친 시간은 몇 분인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["1시간은 60분이에요.","60 × ⟨1/5⟩ = ⟨60/5⟩ = 12예요.","데친 시간은 12분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#8','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C6',1,'mc','auto','문제로 마무리예요. 피자의 ⟨3/5⟩은 감자피자이고, 태오는 그중에서 ⟨1/3⟩을 먹을 거예요. 태오가 먹을 피자는 피자 전체의 얼마인가요?',ARRAY['M5-2-u2-X18','M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":8,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"문제로 마무리예요. 피자의 ⟨3/5⟩은 감자피자이고, 태오는 그중에서 ⟨1/3⟩을 먹을 거예요. 태오가 먹을 피자는 피자 전체의 얼마인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-2-u2-X18"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨4/8⟩","mis":"M5-2-u2-X10"}],"explanation":["전체의 ⟨3/5⟩ 중에서 ⟨1/3⟩이니 ⟨3/5⟩ × ⟨1/3⟩이에요.","⟨3/5⟩ × ⟨1/3⟩ = ⟨3/15⟩ = ⟨1/5⟩이에요.","태오가 먹을 피자는 전체의 ⟨1/5⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 현우네 학교 도서관에 있는 전체 책의 ⟨3/7⟩은 동화책이고, 현우는 그중 ⟨2/9⟩를 읽었어요. 현우가 읽은 동화책은 전체 책의 몇 분의 몇인가요?","options":[{"t":"⟨2/21⟩","correct":true},{"t":"⟨2/9⟩","mis":"M5-2-u2-X18"},{"t":"⟨6/7⟩","mis":"M5-2-u2-X09"},{"t":"⟨5/16⟩","mis":"M5-2-u2-X10"}],"explanation":["전체의 ⟨3/7⟩ 중에서 ⟨2/9⟩니 ⟨3/7⟩ × ⟨2/9⟩예요.","⟨3/7⟩ × ⟨2/9⟩ = ⟨6/63⟩ = ⟨2/21⟩예요.","현우가 읽은 동화책은 전체 책의 ⟨2/21⟩예요."]},{"stem":"이사한 뒤 시루떡 전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩을 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?","options":[{"t":"⟨1/12⟩","correct":true},{"t":"⟨1/4⟩","mis":"M5-2-u2-X09"},{"t":"⟨2/7⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X17"}],"explanation":["전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩이니 ⟨1/4⟩ × ⟨1/3⟩이에요.","⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩이에요.","전체의 ⟨1/12⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#9','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C7',2,'error','auto','문제로 마무리예요. 현주는 「⟨3 2/5⟩ × ⟨5/8⟩ = 3 × ⟨1/4⟩ = ⟨3/4⟩」으로, 태성이는 「⟨3/10⟩ × ⟨4/9⟩ = ⟨2/15⟩」로 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X06','M5-2-u2-X13']::text[],true,'{"seq":9,"concept":"M5-2-u2-C7","difficulty":2,"kind":"error","stem":"문제로 마무리예요. 현주는 「⟨3 2/5⟩ × ⟨5/8⟩ = 3 × ⟨1/4⟩ = ⟨3/4⟩」으로, 태성이는 「⟨3/10⟩ × ⟨4/9⟩ = ⟨2/15⟩」로 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"현주 — 대분수를 가분수로 나타내지 않고 약분했어요.","correct":true,"mis_target":"M5-2-u2-X06"},{"t":"태성 — 분자 4와 분모 10을 약분하면 안 돼요.","mis":"M5-2-u2-X13"},{"t":"두 친구 모두 바르게 계산했어요.","mis":"M5-2-u2-X06"}],"explanation":["현주는 대분수 ⟨3 2/5⟩를 그대로 두고 5와 5, 2와 8을 약분해 틀렸어요.","바르게 하면 ⟨3 2/5⟩ × ⟨5/8⟩ = ⟨17/5⟩ × ⟨5/8⟩ = ⟨17/8⟩ = ⟨2 1/8⟩이에요.","태성이는 분자와 분모 사이에서 약분해 ⟨2/15⟩로 바르게 계산했어요."],"variant_rule":{"alt":[{"stem":"⟨1 1/6⟩ × 15를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「6과 15를 먼저 약분해 ⟨1 1/2⟩ × 5 = ⟨7 1/2⟩이야.」","correct":true,"mis_target":"M5-2-u2-X06"},{"t":"순달 — 「⟨7/6⟩ × 15 = ⟨35/2⟩ = ⟨17 1/2⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「가분수로 나타낸 뒤 6과 15를 3으로 약분하면 ⟨7/2⟩ × 5 = ⟨17 1/2⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수를 가분수로 나타내지 않고 먼저 약분하면 자연수 부분 1이 약분에서 빠져요.","⟨1 1/6⟩ × 15 = ⟨7/6⟩ × 15 = ⟨35/2⟩ = ⟨17 1/2⟩이에요.","여울이가 가분수로 나타내기 전에 약분해 틀렸어요."]},{"stem":"20 × ⟨1 1/15⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「20과 15를 먼저 약분해 4 × ⟨4/3⟩ = ⟨5 1/3⟩이야.」","correct":true,"mis_target":"M5-2-u2-X06"},{"t":"순달 — 「20 × ⟨16/15⟩ = ⟨64/3⟩ = ⟨21 1/3⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「20 × 1 + 20 × ⟨1/15⟩ = 20 + ⟨4/3⟩ = ⟨21 1/3⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["⟨1 1/15⟩의 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","20 × ⟨1 1/15⟩ = 20 × ⟨16/15⟩ = ⟨64/3⟩ = ⟨21 1/3⟩이에요.","여울이가 대분수를 가분수로 나타내기 전에 약분해 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#10','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C4',2,'mc','auto','「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 12 × ⟨3/8⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X07','M5-2-u2-X02']::text[],true,'{"seq":10,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 12 × ⟨3/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 1/2⟩","correct":true},{"t":"⟨36/96⟩","mis":"M5-2-u2-X01"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X07"},{"t":"⟨3/96⟩","mis":"M5-2-u2-X02"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","12 × ⟨3/8⟩ = ⟨36/8⟩ = ⟨9/2⟩ = ⟨4 1/2⟩이에요.","계산 결과는 ⟨4 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨5 2/3⟩ × 9를 계산하면 얼마인가요?","options":[{"t":"51","correct":true},{"t":"⟨45 2/3⟩","mis":"M5-2-u2-X05"},{"t":"11","mis":"M5-2-u2-X05"},{"t":"21","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨5 2/3⟩ × 9 = ⟨17/3⟩ × 9 = ⟨153/3⟩ = 51이에요.","계산 결과는 51이에요."]},{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 10 × ⟨1 2/5⟩를 계산하면 얼마인가요?","options":[{"t":"14","correct":true},{"t":"⟨10 2/5⟩","mis":"M5-2-u2-X05"},{"t":"5","mis":"M5-2-u2-X05"},{"t":"6","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","10 × ⟨1 2/5⟩ = 10 × ⟨7/5⟩ = ⟨70/5⟩ = 14예요.","계산 결과는 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#11','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C3',2,'mc','auto','「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨3 5/6⟩ × 8을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":11,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨3 5/6⟩ × 8을 계산하면 얼마인가요?","options":[{"t":"⟨30 2/3⟩","correct":true},{"t":"⟨24 5/6⟩","mis":"M5-2-u2-X05"},{"t":"⟨9 2/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨10 2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨3 5/6⟩ × 8 = ⟨23/6⟩ × 8 = ⟨184/6⟩ = ⟨92/3⟩ = ⟨30 2/3⟩예요.","계산 결과는 ⟨30 2/3⟩예요."],"variant_rule":{"alt":[{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 5 × ⟨2 3/10⟩을 계산하면 얼마인가요?","options":[{"t":"⟨11 1/2⟩","correct":true},{"t":"⟨10 3/10⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/2⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","5 × ⟨2 3/10⟩ = 5 × ⟨23/10⟩ = ⟨115/10⟩ = ⟨23/2⟩ = ⟨11 1/2⟩이에요.","계산 결과는 ⟨11 1/2⟩이에요."]},{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨4/7⟩ × ⟨5/12⟩ × ⟨14/15⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2/9⟩","correct":true},{"t":"⟨5/21⟩","mis":"M5-2-u2-X17"},{"t":"⟨7/18⟩","mis":"M5-2-u2-X17"},{"t":"⟨1 2/9⟩","mis":"M5-2-u2-X12"}],"explanation":["분수가 셋이어도 대분수는 가분수로, 자연수는 분모가 1인 분수로 보고 분모끼리·분자끼리 곱해요.","⟨4/7⟩ × ⟨5/12⟩ × ⟨14/15⟩ = ⟨280/1260⟩ = ⟨2/9⟩예요.","계산 결과는 ⟨2/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#12','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C5',2,'mc','auto','단원 평가예요. 8 × ⟨3/4⟩ ○ 8 × ⟨1 1/10⟩ — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X08','M5-2-u2-X17']::text[],true,'{"seq":12,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"단원 평가예요. 8 × ⟨3/4⟩ ○ 8 × ⟨1 1/10⟩ — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["8 × ⟨3/4⟩ = ⟨24/4⟩ = 6이에요.","8 × ⟨1 1/10⟩ = 8 × ⟨11/10⟩ = ⟨88/10⟩ = ⟨44/5⟩ = ⟨8 4/5⟩예요.","8에 1보다 작은 수를 곱하면 8보다 작고, 1보다 큰 수를 곱하면 8보다 커요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. ⟨2 1/3⟩ × 2 ○ 5 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["⟨2 1/3⟩ × 2 = ⟨7/3⟩ × 2 = ⟨14/3⟩ = ⟨4 2/3⟩예요.","⟨4 2/3⟩ < 5예요.","⟨4 2/3⟩는 5보다 작아요."]},{"stem":"단원 평가예요. 2 × ⟨3/8⟩ ○ 1 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["2 × ⟨3/8⟩ = ⟨6/8⟩ = ⟨3/4⟩이에요.","⟨3/4⟩ < 1이에요.","1보다 작은 ⟨3/8⟩을 곱해 1보다도 작아졌어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#13','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C3',2,'mc','auto','단원 평가예요. 계산 결과가 ⟨2 5/7⟩ × 2와 다른 것은 어느 것인가요?',ARRAY['M5-2-u2-X05']::text[],true,'{"seq":13,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"단원 평가예요. 계산 결과가 ⟨2 5/7⟩ × 2와 다른 것은 어느 것인가요?","options":[{"t":"2 + ⟨5/7⟩ × 2","correct":true},{"t":"⟨2 5/7⟩ + ⟨2 5/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨19/7⟩ × 2","mis":"M5-2-u2-X05"},{"t":"2 × 2 + ⟨5/7⟩ × 2","mis":"M5-2-u2-X05"}],"explanation":["⟨2 5/7⟩ × 2 = ⟨19/7⟩ × 2 = ⟨38/7⟩ = ⟨5 3/7⟩이에요.","⟨2 5/7⟩ + ⟨2 5/7⟩, 2 × 2 + ⟨5/7⟩ × 2도 모두 ⟨5 3/7⟩이에요.","2 + ⟨5/7⟩ × 2는 자연수 부분 2에 2를 곱하지 않아 ⟨3 3/7⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 계산 결과가 다른 것은 어느 것인가요?","options":[{"t":"⟨1 3/4⟩ + ⟨1 3/4⟩ + ⟨1 3/4⟩","correct":true},{"t":"⟨1 3/4⟩ × 2","mis":"M5-2-u2-X15"},{"t":"1 × 2 + ⟨3/4⟩ × 2","mis":"M5-2-u2-X15"},{"t":"⟨7/4⟩ × 2","mis":"M5-2-u2-X15"}],"explanation":["⟨1 3/4⟩ × 2 = ⟨7/4⟩ × 2 = ⟨7/2⟩ = ⟨3 1/2⟩이에요.","1 × 2 + ⟨3/4⟩ × 2 = 2 + ⟨3/2⟩ = ⟨3 1/2⟩도 같아요.","⟨1 3/4⟩을 세 번 더하면 ⟨5 1/4⟩이에요."]},{"stem":"단원 평가예요. ⟨1 1/3⟩ × 2를 두 가지 방법으로 계산하려고 해요. 계산 결과가 ⟨1 1/3⟩ × 2와 다른 것은 어느 것인가요?","options":[{"t":"1 × 2 + ⟨1/3⟩","correct":true},{"t":"1 × 2 + ⟨1/3⟩ × 2","mis":"M5-2-u2-X05"},{"t":"⟨4/3⟩ × 2","mis":"M5-2-u2-X05"},{"t":"⟨1 1/3⟩ + ⟨1 1/3⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨1 1/3⟩ × 2 = 1 × 2 + ⟨1/3⟩ × 2 = 2 + ⟨2/3⟩ = ⟨2 2/3⟩예요.","⟨4/3⟩ × 2 = ⟨8/3⟩ = ⟨2 2/3⟩, ⟨1 1/3⟩ + ⟨1 1/3⟩ = ⟨2 2/3⟩도 같아요.","1 × 2 + ⟨1/3⟩은 분수 부분에 2를 곱하지 않아 ⟨2 1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#14','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C5',2,'mc','auto','계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":14,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?","options":[{"t":"5 × ⟨1 1/9⟩","correct":true},{"t":"5 × ⟨2/3⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X08"},{"t":"5 × ⟨19/20⟩","mis":"M5-2-u2-X08"}],"explanation":["5에 1보다 작은 수를 곱하면 5보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨1 1/9⟩뿐이에요.","그래서 5보다 큰 것은 5 × ⟨1 1/9⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?","options":[{"t":"5 × ⟨2 1/5⟩","correct":true},{"t":"5 × ⟨1/2⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X08"},{"t":"5 × ⟨9/10⟩","mis":"M5-2-u2-X08"}],"explanation":["5에 1보다 작은 수를 곱하면 5보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨2 1/5⟩뿐이에요.","그래서 5보다 큰 것은 5 × ⟨2 1/5⟩이에요."]},{"stem":"⟨4/5⟩ × ⟨2/3⟩의 계산 결과와 ⟨4/5⟩의 크기를 바르게 견준 것은 어느 것인가요?","options":[{"t":"⟨4/5⟩ × ⟨2/3⟩ < ⟨4/5⟩","correct":true},{"t":"⟨4/5⟩ × ⟨2/3⟩ > ⟨4/5⟩","mis":"M5-2-u2-X08"},{"t":"⟨4/5⟩ × ⟨2/3⟩ = ⟨4/5⟩","mis":"M5-2-u2-X08"},{"t":"견줄 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요.","1보다 작은 ⟨2/3⟩를 곱했으니 ⟨4/5⟩보다 작아져요.","⟨8/15⟩ < ⟨4/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#15','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C6',2,'mc','auto','단원 평가예요. 계산 결과가 큰 것부터 차례로 기호를 쓴 것은 어느 것인가요? ㉠ ⟨1/5⟩ × ⟨1/7⟩ ㉡ ⟨1/9⟩ × ⟨1/3⟩ ㉢ ⟨1/6⟩ × ⟨1/6⟩ ㉣ ⟨1/11⟩ × ⟨1/2⟩',ARRAY['M5-2-u2-X17','M5-2-u2-X10']::text[],true,'{"seq":15,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"단원 평가예요. 계산 결과가 큰 것부터 차례로 기호를 쓴 것은 어느 것인가요? ㉠ ⟨1/5⟩ × ⟨1/7⟩ ㉡ ⟨1/9⟩ × ⟨1/3⟩ ㉢ ⟨1/6⟩ × ⟨1/6⟩ ㉣ ⟨1/11⟩ × ⟨1/2⟩","options":[{"t":"㉣, ㉡, ㉠, ㉢","correct":true},{"t":"㉢, ㉠, ㉡, ㉣","mis":"M5-2-u2-X17"},{"t":"㉠, ㉡, ㉢, ㉣","mis":"M5-2-u2-X17"},{"t":"㉣, ㉢, ㉡, ㉠","mis":"M5-2-u2-X10"}],"explanation":["㉠ ⟨1/35⟩, ㉡ ⟨1/27⟩, ㉢ ⟨1/36⟩, ㉣ ⟨1/22⟩이에요.","단위분수는 분모가 작을수록 커요.","22 < 27 < 35 < 36이라 ㉣, ㉡, ㉠, ㉢ 차례예요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. ⟨1/12⟩, ⟨1/4⟩, ⟨1/9⟩, ⟨1/6⟩ 가운데 가장 큰 수와 가장 작은 수의 곱은 얼마인가요?","options":[{"t":"⟨1/48⟩","correct":true},{"t":"⟨1/24⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/16⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/108⟩","mis":"M5-2-u2-X17"}],"explanation":["가장 큰 수는 ⟨1/4⟩, 가장 작은 수는 ⟨1/12⟩이에요.","⟨1/4⟩ × ⟨1/12⟩ = ⟨1/48⟩이에요.","단위분수는 분모가 작을수록 커요."]},{"stem":"단원 평가예요. ⟨2 1/6⟩, ⟨1 4/5⟩, ⟨4 1/3⟩ 가운데 가장 큰 수와 가장 작은 수의 곱은 얼마인가요?","options":[{"t":"⟨7 4/5⟩","correct":true},{"t":"⟨4 4/15⟩","mis":"M5-2-u2-X11"},{"t":"⟨9 7/18⟩","mis":"M5-2-u2-X17"},{"t":"⟨6 2/15⟩","mis":"M5-2-u2-X15"}],"explanation":["가장 큰 수는 ⟨4 1/3⟩, 가장 작은 수는 ⟨1 4/5⟩예요.","⟨4 1/3⟩ × ⟨1 4/5⟩ = ⟨13/3⟩ × ⟨9/5⟩ = ⟨117/15⟩ = ⟨39/5⟩ = ⟨7 4/5⟩예요.","대분수끼리는 가분수로 나타내어 곱해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#16','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C3',2,'mc','auto','사과 따기 체험에서 만든 사과주스를 ⟨1 1/4⟩ L짜리 병에 가득 담았더니 3병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":16,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"사과 따기 체험에서 만든 사과주스를 ⟨1 1/4⟩ L짜리 병에 가득 담았더니 3병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨3 1/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["⟨1 1/4⟩ L씩 3병이니 ⟨1 1/4⟩ × 3이에요.","⟨1 1/4⟩ × 3 = ⟨5/4⟩ × 3 = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","모두 ⟨3 3/4⟩ L예요."],"variant_rule":{"alt":[{"stem":"들이가 4 L인 항아리에 간장이 ⟨5/12⟩만큼 들어 있어요. 항아리에 든 간장은 몇 L인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-2-u2-X07"},{"t":"⟨5/12⟩","mis":"M5-2-u2-X17"},{"t":"⟨20/48⟩","mis":"M5-2-u2-X01"}],"explanation":["4 L의 ⟨5/12⟩만큼이니 4 × ⟨5/12⟩예요.","4 × ⟨5/12⟩ = ⟨20/12⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요.","항아리에는 간장 ⟨1 2/3⟩ L가 들어 있어요."]},{"stem":"가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"⟨2 4/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 4/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨6 4/5⟩","mis":"M5-2-u2-X15"}],"explanation":["직사각형의 넓이는 (가로) × (세로) — 2 × ⟨1 2/5⟩예요.","세로를 1과 ⟨2/5⟩로 갈라 더하면 2 × 1 + 2 × ⟨2/5⟩ = 2 + ⟨4/5⟩예요.","2 × ⟨1 2/5⟩ = 2 × ⟨7/5⟩ = ⟨14/5⟩ = ⟨2 4/5⟩ — ⟨2 4/5⟩ m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#17','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C3',3,'mc','auto','문제로 마무리예요. 한 변의 길이가 ⟨9 1/2⟩ m인 정사각형 모양의 수영장의 둘레는 몇 m인가요?',ARRAY['M5-2-u2-X20','M5-2-u2-X05']::text[],true,'{"seq":17,"concept":"M5-2-u2-C3","difficulty":3,"kind":"mc","stem":"문제로 마무리예요. 한 변의 길이가 ⟨9 1/2⟩ m인 정사각형 모양의 수영장의 둘레는 몇 m인가요?","options":[{"t":"38","correct":true},{"t":"⟨90 1/4⟩","mis":"M5-2-u2-X20"},{"t":"19","mis":"M5-2-u2-X20"},{"t":"⟨36 1/2⟩","mis":"M5-2-u2-X05"}],"explanation":["정사각형은 네 변의 길이가 모두 같아요 — (둘레) = (한 변의 길이) × 4.","⟨9 1/2⟩ × 4 = ⟨19/2⟩ × 4 = ⟨76/2⟩ = 38이에요.","둘레는 38 m예요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. 한 변의 길이가 ⟨9 1/2⟩ m인 정사각형 모양의 수영장이 있어요. 수영장의 넓이는 몇 m²인가요?","options":[{"t":"⟨90 1/4⟩","correct":true},{"t":"38","mis":"M5-2-u2-X20"},{"t":"⟨81 1/4⟩","mis":"M5-2-u2-X11"},{"t":"⟨47 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["정사각형의 넓이는 (한 변의 길이) × (한 변의 길이)예요.","⟨9 1/2⟩ × ⟨9 1/2⟩ = ⟨19/2⟩ × ⟨19/2⟩ = ⟨361/4⟩ = ⟨90 1/4⟩이에요.","넓이는 ⟨90 1/4⟩ m²예요 — 둘레 38 m와 다른 값이에요."]},{"stem":"한 변의 길이가 ⟨9 3/8⟩ cm인 정사각형 모양 거울의 둘레는 몇 cm인가요?","options":[{"t":"⟨37 1/2⟩","correct":true},{"t":"⟨87 57/64⟩","mis":"M5-2-u2-X20"},{"t":"⟨18 3/4⟩","mis":"M5-2-u2-X20"},{"t":"⟨36 3/8⟩","mis":"M5-2-u2-X05"}],"explanation":["정사각형은 네 변의 길이가 모두 같아요 — (둘레) = (한 변의 길이) × 4.","⟨9 3/8⟩ × 4 = ⟨75/8⟩ × 4 = ⟨300/8⟩ = ⟨75/2⟩ = ⟨37 1/2⟩이에요.","둘레는 ⟨37 1/2⟩ cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#18','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C5',3,'sa','auto','단원 평가예요. 2 × ⟨3 1/2⟩ > □⟨4/5⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M5-2-u2-C5","difficulty":3,"kind":"sa","stem":"단원 평가예요. 2 × ⟨3 1/2⟩ > □⟨4/5⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["2 × ⟨3 1/2⟩ = 2 × ⟨7/2⟩ = 7이에요.","□가 6이면 ⟨6 4/5⟩ < 7이에요.","□에는 1부터 6까지 — 모두 6개예요."],"mis":"M5-2-u2-X17","variant_rule":{"alt":[{"stem":"단원 평가예요. ⟨1 3/5⟩ × ⟨4 1/6⟩ > □⟨1/3⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["⟨1 3/5⟩ × ⟨4 1/6⟩ = ⟨8/5⟩ × ⟨25/6⟩ = ⟨20/3⟩ = ⟨6 2/3⟩예요.","□가 6이면 ⟨6 1/3⟩ < ⟨6 2/3⟩예요.","□에는 1부터 6까지 — 모두 6개예요."]},{"stem":"수학익힘 문제예요. ⟨3 7/10⟩ × 4 > □일 때 □ 안에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["먼저 곱을 구해요 — ⟨3 7/10⟩ × 4 = ⟨37/10⟩ × 4 = ⟨148/10⟩ = ⟨74/5⟩ = ⟨14 4/5⟩.","곱은 ⟨14 4/5⟩예요.","⟨14 4/5⟩보다 작은 자연수 가운데 가장 큰 수는 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#19','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C7',3,'mc','auto','단원 평가예요. 수 카드 8, 3, 9를 한 번씩만 이용하여 만들 수 있는 가장 큰 대분수와 4의 곱은 얼마인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X15']::text[],true,'{"seq":19,"concept":"M5-2-u2-C7","difficulty":3,"kind":"mc","stem":"단원 평가예요. 수 카드 8, 3, 9를 한 번씩만 이용하여 만들 수 있는 가장 큰 대분수와 4의 곱은 얼마인가요?","options":[{"t":"⟨37 1/2⟩","correct":true},{"t":"⟨33 1/3⟩","mis":"M5-2-u2-X17"},{"t":"⟨15 5/9⟩","mis":"M5-2-u2-X17"},{"t":"⟨13 3/8⟩","mis":"M5-2-u2-X15"}],"explanation":["가장 큰 대분수는 자연수 부분에 가장 큰 수 9를 놓고 남은 두 수로 진분수 ⟨3/8⟩을 만든 ⟨9 3/8⟩이에요.","⟨9 3/8⟩ × 4 = ⟨75/8⟩ × 4 = ⟨300/8⟩ = ⟨75/2⟩ = ⟨37 1/2⟩이에요.","곱은 ⟨37 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 수 카드 3, 4, 9를 한 번씩만 이용하여 대분수를 만들었어요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 곱은 얼마인가요?","options":[{"t":"⟨33 7/12⟩","correct":true},{"t":"⟨27 1/3⟩","mis":"M5-2-u2-X11"},{"t":"⟨42 1/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨13 7/36⟩","mis":"M5-2-u2-X15"}],"explanation":["가장 큰 대분수는 ⟨9 3/4⟩, 가장 작은 대분수는 ⟨3 4/9⟩예요.","⟨9 3/4⟩ × ⟨3 4/9⟩ = ⟨39/4⟩ × ⟨31/9⟩ = ⟨1209/36⟩ = ⟨403/12⟩ = ⟨33 7/12⟩이에요.","곱은 ⟨33 7/12⟩이에요."]},{"stem":"「분수의 곱셈 카드 놀이」예요. 자연수 종이 2, 4, 9, 진분수 종이 ⟨1/3⟩, ⟨7/12⟩, ⟨5/6⟩, 대분수 종이 ⟨1 3/4⟩, ⟨3 1/2⟩, ⟨2 2/3⟩ 가운데 자연수 종이와 분수 종이를 1장씩 골라 (자연수)×(분수)를 만들어요. 계산 결과가 가장 큰 식은 어느 것인가요?","options":[{"t":"9 × ⟨3 1/2⟩","correct":true},{"t":"9 × ⟨5/6⟩","mis":"M5-2-u2-X17"},{"t":"4 × ⟨3 1/2⟩","mis":"M5-2-u2-X17"},{"t":"9 × ⟨2 2/3⟩","mis":"M5-2-u2-X17"}],"explanation":["계산 결과를 크게 하려면 자연수도 분수도 가장 큰 수를 골라요.","가장 큰 자연수는 9, 가장 큰 분수는 ⟨3 1/2⟩이에요.","9 × ⟨3 1/2⟩ = 9 × ⟨7/2⟩ = ⟨63/2⟩ = ⟨31 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#20','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C6',3,'mc','auto','단원 평가예요. 은서는 집에서 ⟨14/15⟩ km 떨어진 서점에 가는데 전체 거리의 ⟨5/6⟩는 버스를 타고 나머지는 걸어서 갔어요. 은서가 걸어서 간 거리는 몇 km인가요?',ARRAY['M5-2-u2-X19','M5-2-u2-X15','M5-2-u2-X18']::text[],true,'{"seq":20,"concept":"M5-2-u2-C6","difficulty":3,"kind":"mc","stem":"단원 평가예요. 은서는 집에서 ⟨14/15⟩ km 떨어진 서점에 가는데 전체 거리의 ⟨5/6⟩는 버스를 타고 나머지는 걸어서 갔어요. 은서가 걸어서 간 거리는 몇 km인가요?","options":[{"t":"⟨7/45⟩","correct":true},{"t":"⟨7/9⟩","mis":"M5-2-u2-X19"},{"t":"⟨1/10⟩","mis":"M5-2-u2-X15"},{"t":"⟨1/6⟩","mis":"M5-2-u2-X18"}],"explanation":["걸어서 간 거리는 전체 거리의 나머지 1 − ⟨5/6⟩ = ⟨1/6⟩이에요.","⟨14/15⟩ × ⟨1/6⟩ = ⟨14/90⟩ = ⟨7/45⟩이에요.","⟨5/6⟩를 곱하면 버스로 간 거리 ⟨7/9⟩ km예요 — 묻는 것은 걸어서 간 거리예요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 태희는 색종이 50장 중에서 어제 ⟨1/5⟩을 사용했고, 오늘은 남은 색종이의 ⟨5/8⟩를 사용했어요. 태희가 어제와 오늘 사용한 색종이는 모두 몇 장인가요?","options":[{"t":"35","correct":true},{"t":"25","mis":"M5-2-u2-X17"},{"t":"15","mis":"M5-2-u2-X12"},{"t":"40","mis":"M5-2-u2-X17"}],"explanation":["어제: 50 × ⟨1/5⟩ = 10(장), 남은 색종이: 50 − 10 = 40(장)이에요.","오늘: 40 × ⟨5/8⟩ = 25(장)이에요.","모두 10 + 25 = 35(장)이에요."]},{"stem":"수학익힘 문제예요. 이서는 밤 4 kg을 주웠고, 시하는 이서가 주운 밤 무게의 ⟨1 5/8⟩배를 주웠어요. 누가 주운 밤이 몇 kg 더 무거운가요?","options":[{"t":"시하, ⟨2 1/2⟩ kg","correct":true},{"t":"이서, ⟨2 1/2⟩ kg","mis":"M5-2-u2-X17"},{"t":"시하, ⟨6 1/2⟩ kg","mis":"M5-2-u2-X16"},{"t":"시하, ⟨1 5/8⟩ kg","mis":"M5-2-u2-X15"}],"explanation":["시하가 주운 밤은 4 × ⟨1 5/8⟩ = 4 × ⟨13/8⟩ = ⟨13/2⟩ = ⟨6 1/2⟩(kg)이에요.","⟨1 5/8⟩배는 1보다 크니 시하가 더 많이 주웠어요.","⟨6 1/2⟩ − 4 = ⟨2 1/2⟩ — 시하가 ⟨2 1/2⟩ kg 더 무거워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#21','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C7',3,'mc','auto','수학익힘 문제예요. 1분에 ⟨4 2/3⟩ L씩 물이 일정하게 나오는 수도꼭지를 5분 30초 동안 틀어 놓았어요. 받을 수 있는 물은 몇 L인가요?',ARRAY['M5-2-u2-X21','M5-2-u2-X17']::text[],true,'{"seq":21,"concept":"M5-2-u2-C7","difficulty":3,"kind":"mc","stem":"수학익힘 문제예요. 1분에 ⟨4 2/3⟩ L씩 물이 일정하게 나오는 수도꼭지를 5분 30초 동안 틀어 놓았어요. 받을 수 있는 물은 몇 L인가요?","options":[{"t":"⟨25 2/3⟩","correct":true},{"t":"⟨24 11/15⟩","mis":"M5-2-u2-X21"},{"t":"⟨23 1/3⟩","mis":"M5-2-u2-X17"},{"t":"140","mis":"M5-2-u2-X21"}],"explanation":["1분은 60초이니 30초는 ⟨30/60⟩분 = ⟨1/2⟩분, 5분 30초는 ⟨5 1/2⟩분이에요.","⟨4 2/3⟩ × ⟨5 1/2⟩ = ⟨14/3⟩ × ⟨11/2⟩ = ⟨77/3⟩ = ⟨25 2/3⟩예요.","받을 수 있는 물은 ⟨25 2/3⟩ L예요 — 30초를 ⟨3/10⟩분으로 보지 않도록 해요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 일정한 빠르기로 한 시간에 80 km를 달리는 고속버스가 같은 빠르기로 3시간 30분 동안 쉬지 않고 달리면 몇 km를 달리나요?","options":[{"t":"280","correct":true},{"t":"264","mis":"M5-2-u2-X21"},{"t":"240","mis":"M5-2-u2-X17"},{"t":"2400","mis":"M5-2-u2-X21"}],"explanation":["1시간은 60분이니 30분은 ⟨1/2⟩시간, 3시간 30분은 ⟨3 1/2⟩시간이에요.","80 × ⟨3 1/2⟩ = 80 × ⟨7/2⟩ = 280이에요.","30분을 ⟨3/10⟩시간으로 보면 264 km가 되어 틀려요."]},{"stem":"수세미 열매를 1시간의 ⟨1/5⟩ 동안 데쳤고, 지한이는 하루 24시간의 ⟨1/8⟩만큼 책을 읽었어요. 두 시간을 바르게 견준 것은 어느 것인가요?","options":[{"t":"하루의 ⟨1/8⟩이 더 길다","correct":true},{"t":"1시간의 ⟨1/5⟩이 더 길다","mis":"M5-2-u2-X18"},{"t":"⟨1/5⟩이 ⟨1/8⟩보다 크니 두 시간은 같다","mis":"M5-2-u2-X18"},{"t":"두 시간은 같다","mis":"M5-2-u2-X17"}],"explanation":["1시간의 ⟨1/5⟩은 60 × ⟨1/5⟩ = 12(분)이에요.","하루의 ⟨1/8⟩은 24 × ⟨1/8⟩ = 3(시간) — 180분이에요.","전체(기준)가 다르면 분수만 견주어서는 안 돼요 — 하루의 ⟨1/8⟩이 더 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#22','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C8',3,'sa','auto','서연이네 마을 전체 주민은 270명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 158명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M5-2-u2-C8","difficulty":3,"kind":"sa","stem":"서연이네 마을 전체 주민은 270명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 158명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["22"],"explanation":["① 최소로 동의해야 하는 수: 270 × ⟨2/3⟩ = 180(명)이에요.","② 지금까지 158명이 동의했으니 180 − 158 = 22(명)이에요.","적어도 22명이 더 동의해야 해요."],"mis":"M5-2-u2-X16","variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 430명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 수영장을 만들 수 있어요. 지금까지 195명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["63"],"explanation":["① 최소로 동의해야 하는 수: 430 × ⟨3/5⟩ = 258(명)이에요.","② 지금까지 195명이 동의했으니 258 − 195 = 63(명)이에요.","적어도 63명이 더 동의해야 해요."]},{"stem":"서연이네 마을 전체 주민은 270명이에요. 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["180"],"explanation":["전체 270명의 ⟨2/3⟩ 이상이에요.","270 × ⟨2/3⟩ = 180(명)이에요.","적어도 180명이 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#23','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C6',4,'sa','auto','⟨1/□⟩ × ⟨1/3⟩ = ⟨1/12⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M5-2-u2-C6","difficulty":4,"kind":"sa","stem":"⟨1/□⟩ × ⟨1/3⟩ = ⟨1/12⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["단위분수끼리 곱하면 분모끼리 곱해요.","□ × 3 = 12이어야 해요.","12 ÷ 3 = 4니 □는 4예요."],"mis":"M5-2-u2-X10","variant_rule":{"alt":[{"stem":"16 × ⟨□/4⟩ = 12일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["3"],"explanation":["16을 똑같이 4로 나누면 한 묶음은 4예요.","3묶음이 12니 □ = 12 ÷ 4 = 3이에요.","16 × ⟨3/4⟩ = 12 — 맞아요."]},{"stem":"⟨2/5⟩ × □ = ⟨8/5⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모는 그대로이고 분자만 2에서 8로 바뀌었어요.","분자와 □를 곱해 8이 되어야 해요 — 2 × 4 = 8.","그래서 □는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#24','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C7',4,'essay','teacher','문제로 마무리예요. 현주는 ⟨3 2/5⟩ × ⟨5/8⟩를 「3 × ⟨1/4⟩ = ⟨3/4⟩」으로 계산했어요. 잘못 계산한 까닭을 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u2-C7","difficulty":4,"kind":"essay","stem":"문제로 마무리예요. 현주는 ⟨3 2/5⟩ × ⟨5/8⟩를 「3 × ⟨1/4⟩ = ⟨3/4⟩」으로 계산했어요. 잘못 계산한 까닭을 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 현주는 대분수 ⟨3 2/5⟩를 가분수로 나타내지 않고 분모 5와 분자 5, 분자 2와 분모 8을 약분해서 틀렸다. 대분수를 가분수로 나타낸 다음 약분해야 한다. ⟨3 2/5⟩ = ⟨17/5⟩이므로 ⟨17/5⟩ × ⟨5/8⟩ = ⟨17/8⟩ = ⟨2 1/8⟩이다.","scoring_points":["대분수를 가분수로 나타내지 않고 약분했다고 썼는가","⟨3 2/5⟩ = ⟨17/5⟩로 나타냈는가","⟨2 1/8⟩(= ⟨17/8⟩)을 구했는가"]},"explanation":["대분수 그대로 약분하면 안 돼요.","⟨3 2/5⟩ = ⟨17/5⟩이에요.","⟨17/5⟩ × ⟨5/8⟩ = ⟨17/8⟩ = ⟨2 1/8⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_a#25','math',5,2,'u2','','tb_g5_2_math_u2_review_a','unit_review','M5-2-u2-C8',4,'essay','teacher','준기네 마을에서는 함께하는 공간을 전체 주민의 ⟨3/5⟩ 이상이 동의한 곳으로 만들려고 해요. 이 마을의 전체 주민 430명 가운데 현재까지 195명이 수영장을 만드는 것에 동의했어요. 수영장을 만들려면 적어도 몇 명이 더 동의해야 하는지 구하려는 것, 알고 있는 것을 쓰고, 해결 과정을 식으로 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u2-C8","difficulty":4,"kind":"essay","stem":"준기네 마을에서는 함께하는 공간을 전체 주민의 ⟨3/5⟩ 이상이 동의한 곳으로 만들려고 해요. 이 마을의 전체 주민 430명 가운데 현재까지 195명이 수영장을 만드는 것에 동의했어요. 수영장을 만들려면 적어도 몇 명이 더 동의해야 하는지 구하려는 것, 알고 있는 것을 쓰고, 해결 과정을 식으로 설명해 보세요.","answer_guide":{"answer":"예: 구하려는 것은 수영장을 만들려면 적어도 몇 명이 더 동의해야 하는지이다. 알고 있는 것은 전체 주민 430명의 ⟨3/5⟩ 이상이 동의해야 한다는 것과 현재까지 195명이 동의했다는 것이다. 최소로 동의해야 하는 주민은 430 × ⟨3/5⟩ = 258(명)이고, 258 − 195 = 63(명)이 더 동의해야 한다.","scoring_points":["구하려는 것과 알고 있는 것을 바르게 썼는가","430 × ⟨3/5⟩ = 258(명)을 구했는가","258 − 195 = 63(명)을 구했는가"]},"explanation":["430 × ⟨3/5⟩ = 258(명)이에요.","258 − 195 = 63(명)이에요.","최소 수를 구한 뒤 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#1','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C2',1,'mc','auto','형성 평가예요. ⟨2/7⟩ × 3을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":1,"concept":"M5-2-u2-C2","difficulty":1,"kind":"mc","stem":"형성 평가예요. ⟨2/7⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨6/7⟩","correct":true},{"t":"⟨6/21⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/21⟩","mis":"M5-2-u2-X02"},{"t":"⟨5/7⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/7⟩ × 3 = ⟨6/7⟩이에요.","계산 결과는 ⟨6/7⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. ⟨1/5⟩ × 4를 계산하면 얼마인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨4/20⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/20⟩","mis":"M5-2-u2-X02"},{"t":"1","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨1/5⟩ × 4 = ⟨4/5⟩예요.","계산 결과는 ⟨4/5⟩예요."]},{"stem":"단원 평가예요. 9 × ⟨4/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 1/7⟩","correct":true},{"t":"⟨36/63⟩","mis":"M5-2-u2-X01"},{"t":"⟨1 2/7⟩","mis":"M5-2-u2-X07"},{"t":"⟨4/63⟩","mis":"M5-2-u2-X02"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","9 × ⟨4/7⟩ = ⟨36/7⟩ = ⟨5 1/7⟩이에요.","계산 결과는 ⟨5 1/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#2','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C5',1,'mc','auto','단원 평가예요. 6 × ⟨3 1/3⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":2,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"단원 평가예요. 6 × ⟨3 1/3⟩을 계산하면 얼마인가요?","options":[{"t":"20","correct":true},{"t":"⟨18 1/3⟩","mis":"M5-2-u2-X05"},{"t":"5","mis":"M5-2-u2-X05"},{"t":"8","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","6 × ⟨3 1/3⟩ = 6 × ⟨10/3⟩ = ⟨60/3⟩ = 20이에요.","계산 결과는 20이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 4 × ⟨1 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"6","correct":true},{"t":"⟨4 1/2⟩","mis":"M5-2-u2-X05"},{"t":"3","mis":"M5-2-u2-X05"},{"t":"4","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","4 × ⟨1 1/2⟩ = 4 × ⟨3/2⟩ = ⟨12/2⟩ = 6이에요.","계산 결과는 6이에요."]},{"stem":"단원 평가예요. ⟨1 5/9⟩ × 12를 계산하면 얼마인가요?","options":[{"t":"⟨18 2/3⟩","correct":true},{"t":"⟨12 5/9⟩","mis":"M5-2-u2-X05"},{"t":"⟨7 2/3⟩","mis":"M5-2-u2-X05"},{"t":"8","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨1 5/9⟩ × 12 = ⟨14/9⟩ × 12 = ⟨168/9⟩ = ⟨56/3⟩ = ⟨18 2/3⟩예요.","계산 결과는 ⟨18 2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#3','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C3',1,'mc','auto','문제로 마무리예요. ⟨1 9/11⟩ × 5를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":3,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"문제로 마무리예요. ⟨1 9/11⟩ × 5를 계산하면 얼마인가요?","options":[{"t":"⟨9 1/11⟩","correct":true},{"t":"⟨5 9/11⟩","mis":"M5-2-u2-X05"},{"t":"⟨5 1/11⟩","mis":"M5-2-u2-X05"},{"t":"⟨4 6/11⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨1 9/11⟩ × 5 = ⟨20/11⟩ × 5 = ⟨100/11⟩ = ⟨9 1/11⟩이에요.","계산 결과는 ⟨9 1/11⟩이에요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. 4 × ⟨1 7/12⟩을 계산하면 얼마인가요?","options":[{"t":"⟨6 1/3⟩","correct":true},{"t":"⟨4 7/12⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","4 × ⟨1 7/12⟩ = 4 × ⟨19/12⟩ = ⟨76/12⟩ = ⟨19/3⟩ = ⟨6 1/3⟩이에요.","계산 결과는 ⟨6 1/3⟩이에요."]},{"stem":"문제로 마무리예요. ⟨2/3⟩ × ⟨9/14⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨18/3⟩","mis":"M5-2-u2-X09"},{"t":"⟨11/17⟩","mis":"M5-2-u2-X10"},{"t":"⟨28/27⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨2/3⟩ × ⟨9/14⟩ = ⟨18/42⟩ = ⟨3/7⟩이에요.","계산 결과는 ⟨3/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#4','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C1',1,'mc','auto','⟨5/30⟩를 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X12']::text[],true,'{"seq":4,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"⟨5/30⟩를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨6/1⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/7⟩","mis":"M5-2-u2-X12"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","5와 30을 모두 5로 나눌 수 있어요 — 5 ÷ 5 = 1, 30 ÷ 5 = 6.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨5/30⟩ = ⟨1/6⟩."],"variant_rule":{"alt":[{"stem":"⟨27/36⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨4/3⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X12"},{"t":"1","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","27과 36을 모두 9로 나눌 수 있어요 — 27 ÷ 9 = 3, 36 ÷ 9 = 4.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨27/36⟩ = ⟨3/4⟩."]},{"stem":"⟨56/70⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨5/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨2/3⟩","mis":"M5-2-u2-X12"},{"t":"1","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","56과 70을 모두 14로 나눌 수 있어요 — 56 ÷ 14 = 4, 70 ÷ 14 = 5.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨56/70⟩ = ⟨4/5⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#5','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C7',1,'mc','auto','단원 평가예요. ⟨3 1/2⟩ × ⟨2 3/7⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X04']::text[],true,'{"seq":5,"concept":"M5-2-u2-C7","difficulty":1,"kind":"mc","stem":"단원 평가예요. ⟨3 1/2⟩ × ⟨2 3/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨8 1/2⟩","correct":true},{"t":"⟨6 3/14⟩","mis":"M5-2-u2-X11"},{"t":"⟨4 6/7⟩","mis":"M5-2-u2-X04"},{"t":"⟨2 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨3 1/2⟩ × ⟨2 3/7⟩ = ⟨7/2⟩ × ⟨17/7⟩ = ⟨119/14⟩ = ⟨17/2⟩ = ⟨8 1/2⟩이에요.","계산 결과는 ⟨8 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 4 × ⟨2 1/12⟩을 계산하면 얼마인가요?","options":[{"t":"⟨8 1/3⟩","correct":true},{"t":"⟨8 1/12⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/3⟩","mis":"M5-2-u2-X05"},{"t":"1","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","4 × ⟨2 1/12⟩ = 4 × ⟨25/12⟩ = ⟨100/12⟩ = ⟨25/3⟩ = ⟨8 1/3⟩이에요.","계산 결과는 ⟨8 1/3⟩이에요."]},{"stem":"단원 평가예요. 3 × ⟨5/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨15/27⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X07"},{"t":"⟨5/27⟩","mis":"M5-2-u2-X02"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","3 × ⟨5/9⟩ = ⟨15/9⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요.","계산 결과는 ⟨1 2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#6','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C2',1,'match','auto','형성 평가 「(분수)×(자연수)를 계산해요」예요. 곱셈식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u2-C2","difficulty":1,"kind":"match","stem":"형성 평가 「(분수)×(자연수)를 계산해요」예요. 곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"⟨2/7⟩ × 3","r":"⟨6/7⟩"},{"l":"⟨5/6⟩ × 8","r":"⟨6 2/3⟩"},{"l":"⟨3/5⟩ × 6","r":"⟨3 3/5⟩"}],"mis":"M5-2-u2-X01","explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/7⟩ × 3 = ⟨6/7⟩, ⟨5/6⟩ × 8 = ⟨40/6⟩ = ⟨20/3⟩ = ⟨6 2/3⟩, ⟨3/5⟩ × 6 = ⟨18/5⟩ = ⟨3 3/5⟩이에요.","분모에 자연수를 곱하지 않도록 해요."],"variant_rule":{"alt":[{"stem":"형성 평가 「(자연수)×(분수)를 계산해요」예요. 곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"12 × ⟨2/9⟩","r":"⟨2 2/3⟩"},{"l":"9 × ⟨5/6⟩","r":"⟨7 1/2⟩"},{"l":"3 × ⟨1/4⟩","r":"⟨3/4⟩"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","12 × ⟨2/9⟩ = ⟨24/9⟩ = ⟨8/3⟩ = ⟨2 2/3⟩, 9 × ⟨5/6⟩ = ⟨45/6⟩ = ⟨15/2⟩ = ⟨7 1/2⟩, 3 × ⟨1/4⟩ = ⟨3/4⟩이에요.","자연수를 분모에 곱하지 않도록 해요."]},{"stem":"단원 평가예요. 곱셈식과 계산 결과(기약분수)를 알맞게 이으세요.","pairs":[{"l":"⟨1/5⟩ × ⟨1/7⟩","r":"⟨1/35⟩"},{"l":"⟨3/8⟩ × ⟨5/9⟩","r":"⟨5/24⟩"},{"l":"⟨5/6⟩ × ⟨3/7⟩","r":"⟨5/14⟩"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨1/5⟩ × ⟨1/7⟩ = ⟨1/35⟩, ⟨3/8⟩ × ⟨5/9⟩ = ⟨15/72⟩ = ⟨5/24⟩, ⟨5/6⟩ × ⟨3/7⟩ = ⟨15/42⟩ = ⟨5/14⟩예요.","분모를 그대로 두지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#7','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C4',1,'sa','auto','형성 평가예요. 이안이는 여름 방학 동안 책 25권을 읽었는데 그중 ⟨2/5⟩가 위인전이었어요. 이안이가 읽은 위인전은 몇 권인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C4","difficulty":1,"kind":"sa","stem":"형성 평가예요. 이안이는 여름 방학 동안 책 25권을 읽었는데 그중 ⟨2/5⟩가 위인전이었어요. 이안이가 읽은 위인전은 몇 권인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["25권의 ⟨2/5⟩는 25 × ⟨2/5⟩예요.","25 × ⟨2/5⟩ = ⟨50/5⟩ = 10이에요.","이안이가 읽은 위인전은 10권이에요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"수학익힘 문제예요. 재우는 수세미 열매를 1시간의 ⟨1/5⟩ 동안 데쳤어요. 수세미 열매를 데친 시간은 몇 분인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["1시간은 60분이에요.","60 × ⟨1/5⟩ = ⟨60/5⟩ = 12예요.","데친 시간은 12분이에요."]},{"stem":"단원 평가예요. 떨어진 높이의 ⟨5/9⟩만큼 튀어 오르는 공을 높이가 72 cm인 곳에서 떨어뜨렸어요. 첫 번째로 튀어 오른 공의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["튀어 오른 높이는 72 cm의 ⟨5/9⟩예요.","72 × ⟨5/9⟩ = ⟨360/9⟩ = 40이에요.","튀어 오른 높이는 40 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#8','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C6',1,'mc','auto','단원 평가예요. 현우네 학교 도서관에 있는 전체 책의 ⟨3/7⟩은 동화책이고, 현우는 그중 ⟨2/9⟩를 읽었어요. 현우가 읽은 동화책은 전체 책의 몇 분의 몇인가요?',ARRAY['M5-2-u2-X18','M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":8,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"단원 평가예요. 현우네 학교 도서관에 있는 전체 책의 ⟨3/7⟩은 동화책이고, 현우는 그중 ⟨2/9⟩를 읽었어요. 현우가 읽은 동화책은 전체 책의 몇 분의 몇인가요?","options":[{"t":"⟨2/21⟩","correct":true},{"t":"⟨2/9⟩","mis":"M5-2-u2-X18"},{"t":"⟨6/7⟩","mis":"M5-2-u2-X09"},{"t":"⟨5/16⟩","mis":"M5-2-u2-X10"}],"explanation":["전체의 ⟨3/7⟩ 중에서 ⟨2/9⟩니 ⟨3/7⟩ × ⟨2/9⟩예요.","⟨3/7⟩ × ⟨2/9⟩ = ⟨6/63⟩ = ⟨2/21⟩예요.","현우가 읽은 동화책은 전체 책의 ⟨2/21⟩예요."],"variant_rule":{"alt":[{"stem":"이사한 뒤 시루떡 전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩을 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?","options":[{"t":"⟨1/12⟩","correct":true},{"t":"⟨1/4⟩","mis":"M5-2-u2-X09"},{"t":"⟨2/7⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X17"}],"explanation":["전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩이니 ⟨1/4⟩ × ⟨1/3⟩이에요.","⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩이에요.","전체의 ⟨1/12⟩이에요."]},{"stem":"형성 평가예요. 전체를 4등분 한 것 중의 3만큼을 다시 5등분 한 것 중의 3만큼에 빗금을 쳤어요. 빗금 친 부분은 전체의 얼마인가요?","options":[{"t":"⟨9/20⟩","correct":true},{"t":"⟨3/5⟩","mis":"M5-2-u2-X18"},{"t":"⟨9/4⟩","mis":"M5-2-u2-X09"},{"t":"⟨6/9⟩","mis":"M5-2-u2-X10"}],"explanation":["전체의 ⟨3/4⟩ 중에서 ⟨3/5⟩이니 ⟨3/4⟩ × ⟨3/5⟩이에요.","⟨3/4⟩ × ⟨3/5⟩ = ⟨9/20⟩예요.","빗금 친 부분은 전체의 ⟨9/20⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#9','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C3',2,'error','auto','⟨1 1/6⟩ × 15를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X06','M5-2-u2-X17']::text[],true,'{"seq":9,"concept":"M5-2-u2-C3","difficulty":2,"kind":"error","stem":"⟨1 1/6⟩ × 15를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「6과 15를 먼저 약분해 ⟨1 1/2⟩ × 5 = ⟨7 1/2⟩이야.」","correct":true,"mis_target":"M5-2-u2-X06"},{"t":"순달 — 「⟨7/6⟩ × 15 = ⟨35/2⟩ = ⟨17 1/2⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「가분수로 나타낸 뒤 6과 15를 3으로 약분하면 ⟨7/2⟩ × 5 = ⟨17 1/2⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수를 가분수로 나타내지 않고 먼저 약분하면 자연수 부분 1이 약분에서 빠져요.","⟨1 1/6⟩ × 15 = ⟨7/6⟩ × 15 = ⟨35/2⟩ = ⟨17 1/2⟩이에요.","여울이가 가분수로 나타내기 전에 약분해 틀렸어요."],"variant_rule":{"alt":[{"stem":"20 × ⟨1 1/15⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「20과 15를 먼저 약분해 4 × ⟨4/3⟩ = ⟨5 1/3⟩이야.」","correct":true,"mis_target":"M5-2-u2-X06"},{"t":"순달 — 「20 × ⟨16/15⟩ = ⟨64/3⟩ = ⟨21 1/3⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「20 × 1 + 20 × ⟨1/15⟩ = 20 + ⟨4/3⟩ = ⟨21 1/3⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["⟨1 1/15⟩의 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","20 × ⟨1 1/15⟩ = 20 × ⟨16/15⟩ = ⟨64/3⟩ = ⟨21 1/3⟩이에요.","여울이가 대분수를 가분수로 나타내기 전에 약분해 틀렸어요."]},{"stem":"⟨2 1/10⟩ × ⟨1 2/7⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「10과 2를 먼저 약분해 ⟨11/5⟩ × ⟨8/7⟩ = ⟨2 18/35⟩이야.」","correct":true,"mis_target":"M5-2-u2-X06"},{"t":"순달 — 「⟨21/10⟩ × ⟨9/7⟩ = ⟨27/10⟩ = ⟨2 7/10⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「가분수로 나타낸 뒤 21과 7, 9와 10을 살펴 약분하면 ⟨3/10⟩ × 9 = ⟨2 7/10⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수를 가분수로 나타내기 전에 약분하면 값이 달라져요.","⟨2 1/10⟩ × ⟨1 2/7⟩ = ⟨21/10⟩ × ⟨9/7⟩ = ⟨27/10⟩ = ⟨2 7/10⟩이에요.","여울이가 가분수로 나타내기 전에 약분해 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#10','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C3',2,'mc','auto','「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨5 2/3⟩ × 9를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":10,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨5 2/3⟩ × 9를 계산하면 얼마인가요?","options":[{"t":"51","correct":true},{"t":"⟨45 2/3⟩","mis":"M5-2-u2-X05"},{"t":"11","mis":"M5-2-u2-X05"},{"t":"21","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨5 2/3⟩ × 9 = ⟨17/3⟩ × 9 = ⟨153/3⟩ = 51이에요.","계산 결과는 51이에요."],"variant_rule":{"alt":[{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 10 × ⟨1 2/5⟩를 계산하면 얼마인가요?","options":[{"t":"14","correct":true},{"t":"⟨10 2/5⟩","mis":"M5-2-u2-X05"},{"t":"5","mis":"M5-2-u2-X05"},{"t":"6","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","10 × ⟨1 2/5⟩ = 10 × ⟨7/5⟩ = ⟨70/5⟩ = 14예요.","계산 결과는 14예요."]},{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨4/5⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨2 2/5⟩","correct":true},{"t":"⟨12/15⟩","mis":"M5-2-u2-X01"},{"t":"⟨4/15⟩","mis":"M5-2-u2-X02"},{"t":"⟨1 2/5⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨4/5⟩ × 3 = ⟨12/5⟩ = ⟨2 2/5⟩예요.","계산 결과는 ⟨2 2/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#11','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C5',2,'mc','auto','「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 5 × ⟨2 3/10⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":11,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 5 × ⟨2 3/10⟩을 계산하면 얼마인가요?","options":[{"t":"⟨11 1/2⟩","correct":true},{"t":"⟨10 3/10⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/2⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","5 × ⟨2 3/10⟩ = 5 × ⟨23/10⟩ = ⟨115/10⟩ = ⟨23/2⟩ = ⟨11 1/2⟩이에요.","계산 결과는 ⟨11 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨4/7⟩ × ⟨5/12⟩ × ⟨14/15⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2/9⟩","correct":true},{"t":"⟨5/21⟩","mis":"M5-2-u2-X17"},{"t":"⟨7/18⟩","mis":"M5-2-u2-X17"},{"t":"⟨1 2/9⟩","mis":"M5-2-u2-X12"}],"explanation":["분수가 셋이어도 대분수는 가분수로, 자연수는 분모가 1인 분수로 보고 분모끼리·분자끼리 곱해요.","⟨4/7⟩ × ⟨5/12⟩ × ⟨14/15⟩ = ⟨280/1260⟩ = ⟨2/9⟩예요.","계산 결과는 ⟨2/9⟩예요."]},{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨1/5⟩ × ⟨1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/30⟩","correct":true},{"t":"⟨1/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨2/11⟩","mis":"M5-2-u2-X10"},{"t":"⟨6/5⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨1/5⟩ × ⟨1/6⟩ = ⟨1/30⟩이에요.","계산 결과는 ⟨1/30⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#12','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C3',2,'mc','auto','단원 평가예요. ⟨2 1/3⟩ × 2 ○ 5 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X08','M5-2-u2-X17']::text[],true,'{"seq":12,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"단원 평가예요. ⟨2 1/3⟩ × 2 ○ 5 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["⟨2 1/3⟩ × 2 = ⟨7/3⟩ × 2 = ⟨14/3⟩ = ⟨4 2/3⟩예요.","⟨4 2/3⟩ < 5예요.","⟨4 2/3⟩는 5보다 작아요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 2 × ⟨3/8⟩ ○ 1 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["2 × ⟨3/8⟩ = ⟨6/8⟩ = ⟨3/4⟩이에요.","⟨3/4⟩ < 1이에요.","1보다 작은 ⟨3/8⟩을 곱해 1보다도 작아졌어요."]},{"stem":"수업 전 확인 문제예요. ⟨3/5⟩ × 4 ○ ⟨3/4⟩ × 5 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["⟨3/5⟩ × 4 = ⟨12/5⟩ = ⟨2 2/5⟩예요.","⟨3/4⟩ × 5 = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","⟨2 2/5⟩ < ⟨3 3/4⟩ — 대분수로 나타내어 견줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#13','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C3',2,'mc','auto','단원 평가예요. 계산 결과가 다른 것은 어느 것인가요?',ARRAY['M5-2-u2-X15']::text[],true,'{"seq":13,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"단원 평가예요. 계산 결과가 다른 것은 어느 것인가요?","options":[{"t":"⟨1 3/4⟩ + ⟨1 3/4⟩ + ⟨1 3/4⟩","correct":true},{"t":"⟨1 3/4⟩ × 2","mis":"M5-2-u2-X15"},{"t":"1 × 2 + ⟨3/4⟩ × 2","mis":"M5-2-u2-X15"},{"t":"⟨7/4⟩ × 2","mis":"M5-2-u2-X15"}],"explanation":["⟨1 3/4⟩ × 2 = ⟨7/4⟩ × 2 = ⟨7/2⟩ = ⟨3 1/2⟩이에요.","1 × 2 + ⟨3/4⟩ × 2 = 2 + ⟨3/2⟩ = ⟨3 1/2⟩도 같아요.","⟨1 3/4⟩을 세 번 더하면 ⟨5 1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. ⟨1 1/3⟩ × 2를 두 가지 방법으로 계산하려고 해요. 계산 결과가 ⟨1 1/3⟩ × 2와 다른 것은 어느 것인가요?","options":[{"t":"1 × 2 + ⟨1/3⟩","correct":true},{"t":"1 × 2 + ⟨1/3⟩ × 2","mis":"M5-2-u2-X05"},{"t":"⟨4/3⟩ × 2","mis":"M5-2-u2-X05"},{"t":"⟨1 1/3⟩ + ⟨1 1/3⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨1 1/3⟩ × 2 = 1 × 2 + ⟨1/3⟩ × 2 = 2 + ⟨2/3⟩ = ⟨2 2/3⟩예요.","⟨4/3⟩ × 2 = ⟨8/3⟩ = ⟨2 2/3⟩, ⟨1 1/3⟩ + ⟨1 1/3⟩ = ⟨2 2/3⟩도 같아요.","1 × 2 + ⟨1/3⟩은 분수 부분에 2를 곱하지 않아 ⟨2 1/3⟩이에요."]},{"stem":"단원 평가예요. 은정이는 ⟨2/3⟩ × ⟨1/9⟩, 준상이는 ⟨4/9⟩ × ⟨1/2⟩, 주원이는 ⟨5/6⟩ × ⟨4/15⟩를 계산했어요. 계산 결과가 다른 친구는 누구인가요?","options":[{"t":"은정","correct":true},{"t":"준상","mis":"M5-2-u2-X17"},{"t":"주원","mis":"M5-2-u2-X17"},{"t":"세 친구 모두 같다","mis":"M5-2-u2-X09"}],"explanation":["은정: ⟨2/3⟩ × ⟨1/9⟩ = ⟨2/27⟩예요.","준상: ⟨4/9⟩ × ⟨1/2⟩ = ⟨2/9⟩, 주원: ⟨5/6⟩ × ⟨4/15⟩ = ⟨2/9⟩예요.","결과가 다른 친구는 은정이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#14','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C5',2,'mc','auto','단원 평가예요. 계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?',ARRAY['M5-2-u2-X08']::text[],true,'{"seq":14,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"단원 평가예요. 계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?","options":[{"t":"5 × ⟨2 1/5⟩","correct":true},{"t":"5 × ⟨1/2⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X08"},{"t":"5 × ⟨9/10⟩","mis":"M5-2-u2-X08"}],"explanation":["5에 1보다 작은 수를 곱하면 5보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨2 1/5⟩뿐이에요.","그래서 5보다 큰 것은 5 × ⟨2 1/5⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨4/5⟩ × ⟨2/3⟩의 계산 결과와 ⟨4/5⟩의 크기를 바르게 견준 것은 어느 것인가요?","options":[{"t":"⟨4/5⟩ × ⟨2/3⟩ < ⟨4/5⟩","correct":true},{"t":"⟨4/5⟩ × ⟨2/3⟩ > ⟨4/5⟩","mis":"M5-2-u2-X08"},{"t":"⟨4/5⟩ × ⟨2/3⟩ = ⟨4/5⟩","mis":"M5-2-u2-X08"},{"t":"견줄 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요.","1보다 작은 ⟨2/3⟩를 곱했으니 ⟨4/5⟩보다 작아져요.","⟨8/15⟩ < ⟨4/5⟩예요."]},{"stem":"⟨3/8⟩ × ⟨5/9⟩의 계산 결과와 ⟨3/8⟩의 크기를 바르게 견준 것은 어느 것인가요?","options":[{"t":"⟨3/8⟩ × ⟨5/9⟩ < ⟨3/8⟩","correct":true},{"t":"⟨3/8⟩ × ⟨5/9⟩ > ⟨3/8⟩","mis":"M5-2-u2-X08"},{"t":"⟨3/8⟩ × ⟨5/9⟩ = ⟨3/8⟩","mis":"M5-2-u2-X08"},{"t":"견줄 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨3/8⟩ × ⟨5/9⟩ = ⟨5/24⟩예요.","1보다 작은 ⟨5/9⟩를 곱했으니 ⟨3/8⟩보다 작아져요.","⟨5/24⟩ < ⟨3/8⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#15','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C6',2,'mc','auto','단원 평가예요. ⟨1/12⟩, ⟨1/4⟩, ⟨1/9⟩, ⟨1/6⟩ 가운데 가장 큰 수와 가장 작은 수의 곱은 얼마인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X10']::text[],true,'{"seq":15,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"단원 평가예요. ⟨1/12⟩, ⟨1/4⟩, ⟨1/9⟩, ⟨1/6⟩ 가운데 가장 큰 수와 가장 작은 수의 곱은 얼마인가요?","options":[{"t":"⟨1/48⟩","correct":true},{"t":"⟨1/24⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/16⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/108⟩","mis":"M5-2-u2-X17"}],"explanation":["가장 큰 수는 ⟨1/4⟩, 가장 작은 수는 ⟨1/12⟩이에요.","⟨1/4⟩ × ⟨1/12⟩ = ⟨1/48⟩이에요.","단위분수는 분모가 작을수록 커요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. ⟨2 1/6⟩, ⟨1 4/5⟩, ⟨4 1/3⟩ 가운데 가장 큰 수와 가장 작은 수의 곱은 얼마인가요?","options":[{"t":"⟨7 4/5⟩","correct":true},{"t":"⟨4 4/15⟩","mis":"M5-2-u2-X11"},{"t":"⟨9 7/18⟩","mis":"M5-2-u2-X17"},{"t":"⟨6 2/15⟩","mis":"M5-2-u2-X15"}],"explanation":["가장 큰 수는 ⟨4 1/3⟩, 가장 작은 수는 ⟨1 4/5⟩예요.","⟨4 1/3⟩ × ⟨1 4/5⟩ = ⟨13/3⟩ × ⟨9/5⟩ = ⟨117/15⟩ = ⟨39/5⟩ = ⟨7 4/5⟩예요.","대분수끼리는 가분수로 나타내어 곱해요."]},{"stem":"수학익힘 문제예요. 수 카드 5, 8, 9 가운데 2장을 골라 진분수를 만들어 6 × (진분수)의 계산 결과가 가장 작게 하려고 해요. 가장 작은 계산 결과는 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨5 1/3⟩","mis":"M5-2-u2-X17"},{"t":"⟨3 3/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨6 3/4⟩","mis":"M5-2-u2-X17"}],"explanation":["곱하는 진분수가 가장 작아야 해요 — ⟨5/8⟩, ⟨5/9⟩, ⟨8/9⟩ 가운데 ⟨5/9⟩예요.","6 × ⟨5/9⟩ = ⟨30/9⟩ = ⟨10/3⟩이에요.","가장 작은 계산 결과는 ⟨3 1/3⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#16','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C4',2,'mc','auto','들이가 4 L인 항아리에 간장이 ⟨5/12⟩만큼 들어 있어요. 항아리에 든 간장은 몇 L인가요?',ARRAY['M5-2-u2-X07','M5-2-u2-X17','M5-2-u2-X01']::text[],true,'{"seq":16,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"들이가 4 L인 항아리에 간장이 ⟨5/12⟩만큼 들어 있어요. 항아리에 든 간장은 몇 L인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-2-u2-X07"},{"t":"⟨5/12⟩","mis":"M5-2-u2-X17"},{"t":"⟨20/48⟩","mis":"M5-2-u2-X01"}],"explanation":["4 L의 ⟨5/12⟩만큼이니 4 × ⟨5/12⟩예요.","4 × ⟨5/12⟩ = ⟨20/12⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요.","항아리에는 간장 ⟨1 2/3⟩ L가 들어 있어요."],"variant_rule":{"alt":[{"stem":"가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"⟨2 4/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 4/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨6 4/5⟩","mis":"M5-2-u2-X15"}],"explanation":["직사각형의 넓이는 (가로) × (세로) — 2 × ⟨1 2/5⟩예요.","세로를 1과 ⟨2/5⟩로 갈라 더하면 2 × 1 + 2 × ⟨2/5⟩ = 2 + ⟨4/5⟩예요.","2 × ⟨1 2/5⟩ = 2 × ⟨7/5⟩ = ⟨14/5⟩ = ⟨2 4/5⟩ — ⟨2 4/5⟩ m²예요."]},{"stem":"재영이는 공원을 ⟨1 3/4⟩ km 걸었고, 하은이는 재영이가 걸은 거리의 ⟨1 3/7⟩배만큼 걸었어요. 하은이가 걸은 거리는 몇 km인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨1 9/28⟩","mis":"M5-2-u2-X11"},{"t":"⟨1 3/7⟩","mis":"M5-2-u2-X04"},{"t":"1","mis":"M5-2-u2-X04"}],"explanation":["⟨1 3/4⟩의 ⟨1 3/7⟩배이니 ⟨1 3/4⟩ × ⟨1 3/7⟩이에요.","⟨1 3/4⟩ × ⟨1 3/7⟩ = ⟨7/4⟩ × ⟨10/7⟩ = ⟨70/28⟩ = ⟨5/2⟩ = ⟨2 1/2⟩이에요.","하은이가 걸은 거리는 ⟨2 1/2⟩ km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#17','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C7',3,'mc','auto','문제로 마무리예요. 한 변의 길이가 ⟨9 1/2⟩ m인 정사각형 모양의 수영장이 있어요. 수영장의 넓이는 몇 m²인가요?',ARRAY['M5-2-u2-X20','M5-2-u2-X11','M5-2-u2-X04']::text[],true,'{"seq":17,"concept":"M5-2-u2-C7","difficulty":3,"kind":"mc","stem":"문제로 마무리예요. 한 변의 길이가 ⟨9 1/2⟩ m인 정사각형 모양의 수영장이 있어요. 수영장의 넓이는 몇 m²인가요?","options":[{"t":"⟨90 1/4⟩","correct":true},{"t":"38","mis":"M5-2-u2-X20"},{"t":"⟨81 1/4⟩","mis":"M5-2-u2-X11"},{"t":"⟨47 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["정사각형의 넓이는 (한 변의 길이) × (한 변의 길이)예요.","⟨9 1/2⟩ × ⟨9 1/2⟩ = ⟨19/2⟩ × ⟨19/2⟩ = ⟨361/4⟩ = ⟨90 1/4⟩이에요.","넓이는 ⟨90 1/4⟩ m²예요 — 둘레 38 m와 다른 값이에요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 ⟨9 3/8⟩ cm인 정사각형 모양 거울의 둘레는 몇 cm인가요?","options":[{"t":"⟨37 1/2⟩","correct":true},{"t":"⟨87 57/64⟩","mis":"M5-2-u2-X20"},{"t":"⟨18 3/4⟩","mis":"M5-2-u2-X20"},{"t":"⟨36 3/8⟩","mis":"M5-2-u2-X05"}],"explanation":["정사각형은 네 변의 길이가 모두 같아요 — (둘레) = (한 변의 길이) × 4.","⟨9 3/8⟩ × 4 = ⟨75/8⟩ × 4 = ⟨300/8⟩ = ⟨75/2⟩ = ⟨37 1/2⟩이에요.","둘레는 ⟨37 1/2⟩ cm예요."]},{"stem":"단원 평가예요. 가로가 ⟨19 1/3⟩ cm, 세로가 12 cm인 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"232","correct":true},{"t":"⟨62 2/3⟩","mis":"M5-2-u2-X20"},{"t":"⟨228 1/3⟩","mis":"M5-2-u2-X05"},{"t":"23","mis":"M5-2-u2-X05"}],"explanation":["직사각형의 넓이는 (가로) × (세로)예요.","⟨19 1/3⟩ × 12 = ⟨58/3⟩ × 12 = ⟨696/3⟩ = 232예요.","넓이는 232 cm²예요 — 둘레와 헷갈리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#18','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C7',3,'sa','auto','단원 평가예요. ⟨1 3/5⟩ × ⟨4 1/6⟩ > □⟨1/3⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M5-2-u2-C7","difficulty":3,"kind":"sa","stem":"단원 평가예요. ⟨1 3/5⟩ × ⟨4 1/6⟩ > □⟨1/3⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["⟨1 3/5⟩ × ⟨4 1/6⟩ = ⟨8/5⟩ × ⟨25/6⟩ = ⟨20/3⟩ = ⟨6 2/3⟩예요.","□가 6이면 ⟨6 1/3⟩ < ⟨6 2/3⟩예요.","□에는 1부터 6까지 — 모두 6개예요."],"mis":"M5-2-u2-X17","variant_rule":{"alt":[{"stem":"수학익힘 문제예요. ⟨3 7/10⟩ × 4 > □일 때 □ 안에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["먼저 곱을 구해요 — ⟨3 7/10⟩ × 4 = ⟨37/10⟩ × 4 = ⟨148/10⟩ = ⟨74/5⟩ = ⟨14 4/5⟩.","곱은 ⟨14 4/5⟩예요.","⟨14 4/5⟩보다 작은 자연수 가운데 가장 큰 수는 14예요."]},{"stem":"수업 전 확인 문제예요. ⟨1 3/4⟩ × 6 < □일 때 □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["먼저 곱을 구해요 — ⟨1 3/4⟩ × 6 = ⟨7/4⟩ × 6 = ⟨42/4⟩ = ⟨21/2⟩ = ⟨10 1/2⟩.","곱은 ⟨10 1/2⟩이에요.","⟨10 1/2⟩보다 큰 자연수 가운데 가장 작은 수는 11이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#19','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C7',3,'mc','auto','단원 평가예요. 수 카드 3, 4, 9를 한 번씩만 이용하여 대분수를 만들었어요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 곱은 얼마인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X17','M5-2-u2-X15']::text[],true,'{"seq":19,"concept":"M5-2-u2-C7","difficulty":3,"kind":"mc","stem":"단원 평가예요. 수 카드 3, 4, 9를 한 번씩만 이용하여 대분수를 만들었어요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 곱은 얼마인가요?","options":[{"t":"⟨33 7/12⟩","correct":true},{"t":"⟨27 1/3⟩","mis":"M5-2-u2-X11"},{"t":"⟨42 1/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨13 7/36⟩","mis":"M5-2-u2-X15"}],"explanation":["가장 큰 대분수는 ⟨9 3/4⟩, 가장 작은 대분수는 ⟨3 4/9⟩예요.","⟨9 3/4⟩ × ⟨3 4/9⟩ = ⟨39/4⟩ × ⟨31/9⟩ = ⟨1209/36⟩ = ⟨403/12⟩ = ⟨33 7/12⟩이에요.","곱은 ⟨33 7/12⟩이에요."],"variant_rule":{"alt":[{"stem":"「분수의 곱셈 카드 놀이」예요. 자연수 종이 2, 4, 9, 진분수 종이 ⟨1/3⟩, ⟨7/12⟩, ⟨5/6⟩, 대분수 종이 ⟨1 3/4⟩, ⟨3 1/2⟩, ⟨2 2/3⟩ 가운데 자연수 종이와 분수 종이를 1장씩 골라 (자연수)×(분수)를 만들어요. 계산 결과가 가장 큰 식은 어느 것인가요?","options":[{"t":"9 × ⟨3 1/2⟩","correct":true},{"t":"9 × ⟨5/6⟩","mis":"M5-2-u2-X17"},{"t":"4 × ⟨3 1/2⟩","mis":"M5-2-u2-X17"},{"t":"9 × ⟨2 2/3⟩","mis":"M5-2-u2-X17"}],"explanation":["계산 결과를 크게 하려면 자연수도 분수도 가장 큰 수를 골라요.","가장 큰 자연수는 9, 가장 큰 분수는 ⟨3 1/2⟩이에요.","9 × ⟨3 1/2⟩ = 9 × ⟨7/2⟩ = ⟨63/2⟩ = ⟨31 1/2⟩이에요."]},{"stem":"「분수의 곱셈 카드 놀이」예요. 자연수 종이 2, 4, 9, 진분수 종이 ⟨1/3⟩, ⟨7/12⟩, ⟨5/6⟩, 대분수 종이 ⟨1 3/4⟩, ⟨3 1/2⟩, ⟨2 2/3⟩ 가운데 자연수 종이와 분수 종이를 1장씩 골라 (자연수)×(분수)를 만들어요. 계산 결과가 가장 작은 식은 어느 것인가요?","options":[{"t":"2 × ⟨1/3⟩","correct":true},{"t":"2 × ⟨7/12⟩","mis":"M5-2-u2-X17"},{"t":"9 × ⟨1/3⟩","mis":"M5-2-u2-X17"},{"t":"2 × ⟨1 3/4⟩","mis":"M5-2-u2-X17"}],"explanation":["계산 결과를 작게 하려면 자연수도 분수도 가장 작은 수를 골라요.","가장 작은 자연수는 2, 가장 작은 분수는 ⟨1/3⟩이에요.","2 × ⟨1/3⟩ = ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#20','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C7',3,'mc','auto','단원 평가예요. 태희는 색종이 50장 중에서 어제 ⟨1/5⟩을 사용했고, 오늘은 남은 색종이의 ⟨5/8⟩를 사용했어요. 태희가 어제와 오늘 사용한 색종이는 모두 몇 장인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X12']::text[],true,'{"seq":20,"concept":"M5-2-u2-C7","difficulty":3,"kind":"mc","stem":"단원 평가예요. 태희는 색종이 50장 중에서 어제 ⟨1/5⟩을 사용했고, 오늘은 남은 색종이의 ⟨5/8⟩를 사용했어요. 태희가 어제와 오늘 사용한 색종이는 모두 몇 장인가요?","options":[{"t":"35","correct":true},{"t":"25","mis":"M5-2-u2-X17"},{"t":"15","mis":"M5-2-u2-X12"},{"t":"40","mis":"M5-2-u2-X17"}],"explanation":["어제: 50 × ⟨1/5⟩ = 10(장), 남은 색종이: 50 − 10 = 40(장)이에요.","오늘: 40 × ⟨5/8⟩ = 25(장)이에요.","모두 10 + 25 = 35(장)이에요."],"variant_rule":{"alt":[{"stem":"수학익힘 문제예요. 이서는 밤 4 kg을 주웠고, 시하는 이서가 주운 밤 무게의 ⟨1 5/8⟩배를 주웠어요. 누가 주운 밤이 몇 kg 더 무거운가요?","options":[{"t":"시하, ⟨2 1/2⟩ kg","correct":true},{"t":"이서, ⟨2 1/2⟩ kg","mis":"M5-2-u2-X17"},{"t":"시하, ⟨6 1/2⟩ kg","mis":"M5-2-u2-X16"},{"t":"시하, ⟨1 5/8⟩ kg","mis":"M5-2-u2-X15"}],"explanation":["시하가 주운 밤은 4 × ⟨1 5/8⟩ = 4 × ⟨13/8⟩ = ⟨13/2⟩ = ⟨6 1/2⟩(kg)이에요.","⟨1 5/8⟩배는 1보다 크니 시하가 더 많이 주웠어요.","⟨6 1/2⟩ − 4 = ⟨2 1/2⟩ — 시하가 ⟨2 1/2⟩ kg 더 무거워요."]},{"stem":"단원 평가예요. 선아네 학교 도서관에 있는 책 300권 중에서 ⟨1/3⟩은 과학책이에요. 선아는 과학책 중에서 ⟨3/5⟩을 읽었다면 선아가 읽은 과학책은 몇 권인가요?","options":[{"t":"60","correct":true},{"t":"100","mis":"M5-2-u2-X17"},{"t":"180","mis":"M5-2-u2-X18"},{"t":"40","mis":"M5-2-u2-X17"}],"explanation":["과학책은 300 × ⟨1/3⟩ = 100(권)이에요.","선아가 읽은 과학책은 100 × ⟨3/5⟩ = 60(권)이에요.","300 × ⟨3/5⟩ = 180은 전체 책의 ⟨3/5⟩이에요 — 「과학책 중에서」를 놓치지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#21','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C5',3,'mc','auto','단원 평가예요. 일정한 빠르기로 한 시간에 80 km를 달리는 고속버스가 같은 빠르기로 3시간 30분 동안 쉬지 않고 달리면 몇 km를 달리나요?',ARRAY['M5-2-u2-X21','M5-2-u2-X17']::text[],true,'{"seq":21,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"단원 평가예요. 일정한 빠르기로 한 시간에 80 km를 달리는 고속버스가 같은 빠르기로 3시간 30분 동안 쉬지 않고 달리면 몇 km를 달리나요?","options":[{"t":"280","correct":true},{"t":"264","mis":"M5-2-u2-X21"},{"t":"240","mis":"M5-2-u2-X17"},{"t":"2400","mis":"M5-2-u2-X21"}],"explanation":["1시간은 60분이니 30분은 ⟨1/2⟩시간, 3시간 30분은 ⟨3 1/2⟩시간이에요.","80 × ⟨3 1/2⟩ = 80 × ⟨7/2⟩ = 280이에요.","30분을 ⟨3/10⟩시간으로 보면 264 km가 되어 틀려요."],"variant_rule":{"alt":[{"stem":"수세미 열매를 1시간의 ⟨1/5⟩ 동안 데쳤고, 지한이는 하루 24시간의 ⟨1/8⟩만큼 책을 읽었어요. 두 시간을 바르게 견준 것은 어느 것인가요?","options":[{"t":"하루의 ⟨1/8⟩이 더 길다","correct":true},{"t":"1시간의 ⟨1/5⟩이 더 길다","mis":"M5-2-u2-X18"},{"t":"⟨1/5⟩이 ⟨1/8⟩보다 크니 두 시간은 같다","mis":"M5-2-u2-X18"},{"t":"두 시간은 같다","mis":"M5-2-u2-X17"}],"explanation":["1시간의 ⟨1/5⟩은 60 × ⟨1/5⟩ = 12(분)이에요.","하루의 ⟨1/8⟩은 24 × ⟨1/8⟩ = 3(시간) — 180분이에요.","전체(기준)가 다르면 분수만 견주어서는 안 돼요 — 하루의 ⟨1/8⟩이 더 길어요."]},{"stem":"수학익힘 문제예요. 혜지네 학교 5학년 전체 학생 160명 가운데 ⟨5/8⟩는 남학생이고, 그중 ⟨3/5⟩은 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요?","options":[{"t":"60","correct":true},{"t":"100","mis":"M5-2-u2-X17"},{"t":"96","mis":"M5-2-u2-X18"},{"t":"40","mis":"M5-2-u2-X17"}],"explanation":["남학생은 160 × ⟨5/8⟩ = 100(명)이에요.","그중 ⟨3/5⟩이니 100 × ⟨3/5⟩ = 60(명)이에요.","160 × ⟨5/8⟩ × ⟨3/5⟩ = 60 — 세 수를 한 번에 곱해도 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#22','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C8',3,'sa','auto','준기네 마을 전체 주민은 430명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 수영장을 만들 수 있어요. 지금까지 195명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M5-2-u2-C8","difficulty":3,"kind":"sa","stem":"준기네 마을 전체 주민은 430명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 수영장을 만들 수 있어요. 지금까지 195명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["63"],"explanation":["① 최소로 동의해야 하는 수: 430 × ⟨3/5⟩ = 258(명)이에요.","② 지금까지 195명이 동의했으니 258 − 195 = 63(명)이에요.","적어도 63명이 더 동의해야 해요."],"mis":"M5-2-u2-X16","variant_rule":{"alt":[{"stem":"서연이네 마을 전체 주민은 270명이에요. 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["180"],"explanation":["전체 270명의 ⟨2/3⟩ 이상이에요.","270 × ⟨2/3⟩ = 180(명)이에요.","적어도 180명이 동의해야 해요."]},{"stem":"준기네 마을 전체 주민은 430명이에요. 전체 주민의 ⟨3/5⟩ 이상이 동의해야 수영장을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["258"],"explanation":["전체 430명의 ⟨3/5⟩ 이상이에요.","430 × ⟨3/5⟩ = 258(명)이에요.","적어도 258명이 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#23','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C4',4,'sa','auto','16 × ⟨□/4⟩ = 12일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M5-2-u2-C4","difficulty":4,"kind":"sa","stem":"16 × ⟨□/4⟩ = 12일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["3"],"explanation":["16을 똑같이 4로 나누면 한 묶음은 4예요.","3묶음이 12니 □ = 12 ÷ 4 = 3이에요.","16 × ⟨3/4⟩ = 12 — 맞아요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"⟨2/5⟩ × □ = ⟨8/5⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모는 그대로이고 분자만 2에서 8로 바뀌었어요.","분자와 □를 곱해 8이 되어야 해요 — 2 × 4 = 8.","그래서 □는 4예요."]},{"stem":"72 × ⟨□/9⟩ = 40일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["5"],"explanation":["72를 똑같이 9로 나누면 한 묶음은 8이에요.","5묶음이 40이니 □ = 40 ÷ 8 = 5예요.","72 × ⟨5/9⟩ = 40 — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#24','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C5',4,'essay','teacher','단원 평가예요. 2 × ⟨3 1/2⟩ > □⟨4/5⟩일 때 □ 안에 들어갈 수 있는 자연수는 모두 몇 개인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u2-C5","difficulty":4,"kind":"essay","stem":"단원 평가예요. 2 × ⟨3 1/2⟩ > □⟨4/5⟩일 때 □ 안에 들어갈 수 있는 자연수는 모두 몇 개인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 2 × ⟨3 1/2⟩ = 2 × ⟨7/2⟩ = 7이다. 7 > □⟨4/5⟩가 되려면 □는 7보다 작은 자연수여야 하고, □ = 6일 때 ⟨6 4/5⟩도 7보다 작다. 따라서 □ 안에 들어갈 수 있는 자연수는 1, 2, 3, 4, 5, 6으로 모두 6개이다.","scoring_points":["2 × ⟨3 1/2⟩ = 7을 구했는가","□는 6 이하라고 판단했는가","6개를 구했는가"]},"explanation":["2 × ⟨3 1/2⟩ = 7이에요.","⟨6 4/5⟩ < 7이라 6까지 들어가요.","1부터 6까지 — 모두 6개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_b#25','math',5,2,'u2','','tb_g5_2_math_u2_review_b','unit_review','M5-2-u2-C3',4,'essay','teacher','사과 따기 체험에서 만든 사과주스를 ⟨1 1/4⟩ L짜리 병 3병에 가득 담았어요. 만든 사과주스의 양을 두 가지 방법(자연수 부분과 진분수 부분에 각각 곱하여 더하기, 가분수로 나타내어 곱하기)으로 구하고 결과를 견주어 보세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u2-C3","difficulty":4,"kind":"essay","stem":"사과 따기 체험에서 만든 사과주스를 ⟨1 1/4⟩ L짜리 병 3병에 가득 담았어요. 만든 사과주스의 양을 두 가지 방법(자연수 부분과 진분수 부분에 각각 곱하여 더하기, 가분수로 나타내어 곱하기)으로 구하고 결과를 견주어 보세요.","answer_guide":{"answer":"예: 첫째 방법 — ⟨1 1/4⟩ × 3 = 1 × 3 + ⟨1/4⟩ × 3 = 3 + ⟨3/4⟩ = ⟨3 3/4⟩이다. 둘째 방법 — ⟨1 1/4⟩ × 3 = ⟨5/4⟩ × 3 = ⟨15/4⟩ = ⟨3 3/4⟩이다. 두 방법의 결과가 ⟨3 3/4⟩ L로 같다.","scoring_points":["자연수 부분과 진분수 부분에 각각 곱해 ⟨3 3/4⟩을 구했는가","가분수 ⟨5/4⟩로 나타내어 ⟨15/4⟩를 구했는가","두 결과가 같다고 견주었는가"]},"explanation":["1 × 3 + ⟨1/4⟩ × 3 = ⟨3 3/4⟩이에요.","⟨5/4⟩ × 3 = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","두 방법 모두 ⟨3 3/4⟩ L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#1','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C2',1,'mc','auto','단원 평가예요. ⟨1/5⟩ × 4를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":1,"concept":"M5-2-u2-C2","difficulty":1,"kind":"mc","stem":"단원 평가예요. ⟨1/5⟩ × 4를 계산하면 얼마인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨4/20⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/20⟩","mis":"M5-2-u2-X02"},{"t":"1","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨1/5⟩ × 4 = ⟨4/5⟩예요.","계산 결과는 ⟨4/5⟩예요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 9 × ⟨4/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 1/7⟩","correct":true},{"t":"⟨36/63⟩","mis":"M5-2-u2-X01"},{"t":"⟨1 2/7⟩","mis":"M5-2-u2-X07"},{"t":"⟨4/63⟩","mis":"M5-2-u2-X02"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","9 × ⟨4/7⟩ = ⟨36/7⟩ = ⟨5 1/7⟩이에요.","계산 결과는 ⟨5 1/7⟩이에요."]},{"stem":"문제로 마무리예요. ⟨4/7⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨1 5/7⟩","correct":true},{"t":"⟨12/21⟩","mis":"M5-2-u2-X01"},{"t":"⟨4/21⟩","mis":"M5-2-u2-X02"},{"t":"1","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨4/7⟩ × 3 = ⟨12/7⟩ = ⟨1 5/7⟩예요.","계산 결과는 ⟨1 5/7⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#2','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C5',1,'mc','auto','단원 평가예요. 4 × ⟨1 1/2⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":2,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"단원 평가예요. 4 × ⟨1 1/2⟩을 계산하면 얼마인가요?","options":[{"t":"6","correct":true},{"t":"⟨4 1/2⟩","mis":"M5-2-u2-X05"},{"t":"3","mis":"M5-2-u2-X05"},{"t":"4","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","4 × ⟨1 1/2⟩ = 4 × ⟨3/2⟩ = ⟨12/2⟩ = 6이에요.","계산 결과는 6이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. ⟨1 5/9⟩ × 12를 계산하면 얼마인가요?","options":[{"t":"⟨18 2/3⟩","correct":true},{"t":"⟨12 5/9⟩","mis":"M5-2-u2-X05"},{"t":"⟨7 2/3⟩","mis":"M5-2-u2-X05"},{"t":"8","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨1 5/9⟩ × 12 = ⟨14/9⟩ × 12 = ⟨168/9⟩ = ⟨56/3⟩ = ⟨18 2/3⟩예요.","계산 결과는 ⟨18 2/3⟩예요."]},{"stem":"문제로 마무리예요. 5 × ⟨1 2/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 1/9⟩","correct":true},{"t":"⟨5 2/9⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/9⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","5 × ⟨1 2/9⟩ = 5 × ⟨11/9⟩ = ⟨55/9⟩ = ⟨6 1/9⟩이에요.","계산 결과는 ⟨6 1/9⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#3','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C5',1,'mc','auto','문제로 마무리예요. 4 × ⟨1 7/12⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":3,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"문제로 마무리예요. 4 × ⟨1 7/12⟩을 계산하면 얼마인가요?","options":[{"t":"⟨6 1/3⟩","correct":true},{"t":"⟨4 7/12⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","4 × ⟨1 7/12⟩ = 4 × ⟨19/12⟩ = ⟨76/12⟩ = ⟨19/3⟩ = ⟨6 1/3⟩이에요.","계산 결과는 ⟨6 1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. ⟨2/3⟩ × ⟨9/14⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨18/3⟩","mis":"M5-2-u2-X09"},{"t":"⟨11/17⟩","mis":"M5-2-u2-X10"},{"t":"⟨28/27⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨2/3⟩ × ⟨9/14⟩ = ⟨18/42⟩ = ⟨3/7⟩이에요.","계산 결과는 ⟨3/7⟩이에요."]},{"stem":"문제로 마무리예요. ⟨5/21⟩ × 7을 계산하면 얼마인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨35/147⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/147⟩","mis":"M5-2-u2-X02"},{"t":"⟨4/7⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨5/21⟩ × 7 = ⟨35/21⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요.","계산 결과는 ⟨1 2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#4','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C1',1,'mc','auto','⟨27/36⟩을 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X12']::text[],true,'{"seq":4,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"⟨27/36⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨4/3⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X12"},{"t":"1","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","27과 36을 모두 9로 나눌 수 있어요 — 27 ÷ 9 = 3, 36 ÷ 9 = 4.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨27/36⟩ = ⟨3/4⟩."],"variant_rule":{"alt":[{"stem":"⟨56/70⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨5/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨2/3⟩","mis":"M5-2-u2-X12"},{"t":"1","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","56과 70을 모두 14로 나눌 수 있어요 — 56 ÷ 14 = 4, 70 ÷ 14 = 5.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨56/70⟩ = ⟨4/5⟩."]},{"stem":"불꽃 축제 장소까지 전체 1 km예요. 지금까지 ⟨4/5⟩ km를 걸어왔다면 남은 길은 몇 km인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨4/5⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/4⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/5⟩","mis":"M5-2-u2-X12"}],"explanation":["1은 ⟨5/5⟩와 같아요.","남은 길은 ⟨5/5⟩ − ⟨4/5⟩ = ⟨1/5⟩이에요.","분모가 같으면 뺄셈도 분자끼리 해요 — ⟨1/5⟩ km."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#5','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C5',1,'mc','auto','단원 평가예요. 4 × ⟨2 1/12⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":5,"concept":"M5-2-u2-C5","difficulty":1,"kind":"mc","stem":"단원 평가예요. 4 × ⟨2 1/12⟩을 계산하면 얼마인가요?","options":[{"t":"⟨8 1/3⟩","correct":true},{"t":"⟨8 1/12⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/3⟩","mis":"M5-2-u2-X05"},{"t":"1","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","4 × ⟨2 1/12⟩ = 4 × ⟨25/12⟩ = ⟨100/12⟩ = ⟨25/3⟩ = ⟨8 1/3⟩이에요.","계산 결과는 ⟨8 1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 3 × ⟨5/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨15/27⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X07"},{"t":"⟨5/27⟩","mis":"M5-2-u2-X02"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","3 × ⟨5/9⟩ = ⟨15/9⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요.","계산 결과는 ⟨1 2/3⟩예요."]},{"stem":"문제로 마무리예요. 빈칸에 알맞은 수를 써넣어요. 2에 ⟨5/8⟩를 곱한 수를 첫째 빈칸에, 그 수에 ⟨2 2/5⟩를 곱한 수를 둘째 빈칸에 써요. 둘째 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"3","correct":true},{"t":"⟨1 1/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨2 1/10⟩","mis":"M5-2-u2-X11"},{"t":"⟨3 13/20⟩","mis":"M5-2-u2-X15"}],"explanation":["첫째 빈칸: 2 × ⟨5/8⟩ = ⟨10/8⟩ = ⟨5/4⟩ = ⟨1 1/4⟩이에요.","둘째 빈칸: ⟨1 1/4⟩ × ⟨2 2/5⟩ = ⟨5/4⟩ × ⟨12/5⟩ = ⟨60/20⟩ = 3이에요.","대분수끼리는 가분수로 나타내어 곱해요 — 둘째 빈칸은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#6','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C4',1,'match','auto','형성 평가 「(자연수)×(분수)를 계산해요」예요. 곱셈식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u2-C4","difficulty":1,"kind":"match","stem":"형성 평가 「(자연수)×(분수)를 계산해요」예요. 곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"12 × ⟨2/9⟩","r":"⟨2 2/3⟩"},{"l":"9 × ⟨5/6⟩","r":"⟨7 1/2⟩"},{"l":"3 × ⟨1/4⟩","r":"⟨3/4⟩"}],"mis":"M5-2-u2-X07","explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","12 × ⟨2/9⟩ = ⟨24/9⟩ = ⟨8/3⟩ = ⟨2 2/3⟩, 9 × ⟨5/6⟩ = ⟨45/6⟩ = ⟨15/2⟩ = ⟨7 1/2⟩, 3 × ⟨1/4⟩ = ⟨3/4⟩이에요.","자연수를 분모에 곱하지 않도록 해요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 곱셈식과 계산 결과(기약분수)를 알맞게 이으세요.","pairs":[{"l":"⟨1/5⟩ × ⟨1/7⟩","r":"⟨1/35⟩"},{"l":"⟨3/8⟩ × ⟨5/9⟩","r":"⟨5/24⟩"},{"l":"⟨5/6⟩ × ⟨3/7⟩","r":"⟨5/14⟩"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨1/5⟩ × ⟨1/7⟩ = ⟨1/35⟩, ⟨3/8⟩ × ⟨5/9⟩ = ⟨15/72⟩ = ⟨5/24⟩, ⟨5/6⟩ × ⟨3/7⟩ = ⟨15/42⟩ = ⟨5/14⟩예요.","분모를 그대로 두지 않도록 해요."]},{"stem":"문제로 마무리예요. 계산 결과가 같은 것끼리 이으세요.","pairs":[{"l":"6 × ⟨1 3/8⟩","r":"11 × ⟨3/4⟩"},{"l":"⟨5/36⟩ × 3","r":"⟨15/16⟩ × ⟨4/9⟩"},{"l":"⟨1/2⟩ × ⟨1/3⟩ × ⟨3/10⟩","r":"⟨1/4⟩ × ⟨1/5⟩"}],"explanation":["6 × ⟨1 3/8⟩ = ⟨33/4⟩ = ⟨8 1/4⟩, 11 × ⟨3/4⟩ = ⟨33/4⟩ = ⟨8 1/4⟩이에요.","⟨5/36⟩ × 3 = ⟨5/12⟩, ⟨15/16⟩ × ⟨4/9⟩ = ⟨5/12⟩예요.","⟨1/2⟩ × ⟨1/3⟩ × ⟨3/10⟩ = ⟨1/20⟩, ⟨1/4⟩ × ⟨1/5⟩ = ⟨1/20⟩ — 약분하거나 대분수로 나타내어 견줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#7','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C4',1,'sa','auto','수학익힘 문제예요. 재우는 수세미 열매를 1시간의 ⟨1/5⟩ 동안 데쳤어요. 수세미 열매를 데친 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C4","difficulty":1,"kind":"sa","stem":"수학익힘 문제예요. 재우는 수세미 열매를 1시간의 ⟨1/5⟩ 동안 데쳤어요. 수세미 열매를 데친 시간은 몇 분인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["1시간은 60분이에요.","60 × ⟨1/5⟩ = ⟨60/5⟩ = 12예요.","데친 시간은 12분이에요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"단원 평가예요. 떨어진 높이의 ⟨5/9⟩만큼 튀어 오르는 공을 높이가 72 cm인 곳에서 떨어뜨렸어요. 첫 번째로 튀어 오른 공의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["튀어 오른 높이는 72 cm의 ⟨5/9⟩예요.","72 × ⟨5/9⟩ = ⟨360/9⟩ = 40이에요.","튀어 오른 높이는 40 cm예요."]},{"stem":"문제로 마무리예요. 지한이는 토요일에 하루 24시간의 ⟨1/8⟩만큼 책을 읽었어요. 지한이가 토요일에 책을 읽은 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["하루는 24시간이에요.","24 × ⟨1/8⟩ = ⟨24/8⟩ = 3이에요.","지한이가 책을 읽은 시간은 3시간이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#8','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C6',1,'mc','auto','이사한 뒤 시루떡 전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩을 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10','M5-2-u2-X17']::text[],true,'{"seq":8,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"이사한 뒤 시루떡 전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩을 이웃집에 나누어 주었어요. 이웃집에 준 시루떡은 전체의 얼마인가요?","options":[{"t":"⟨1/12⟩","correct":true},{"t":"⟨1/4⟩","mis":"M5-2-u2-X09"},{"t":"⟨2/7⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X17"}],"explanation":["전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩이니 ⟨1/4⟩ × ⟨1/3⟩이에요.","⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩이에요.","전체의 ⟨1/12⟩이에요."],"variant_rule":{"alt":[{"stem":"형성 평가예요. 전체를 4등분 한 것 중의 3만큼을 다시 5등분 한 것 중의 3만큼에 빗금을 쳤어요. 빗금 친 부분은 전체의 얼마인가요?","options":[{"t":"⟨9/20⟩","correct":true},{"t":"⟨3/5⟩","mis":"M5-2-u2-X18"},{"t":"⟨9/4⟩","mis":"M5-2-u2-X09"},{"t":"⟨6/9⟩","mis":"M5-2-u2-X10"}],"explanation":["전체의 ⟨3/4⟩ 중에서 ⟨3/5⟩이니 ⟨3/4⟩ × ⟨3/5⟩이에요.","⟨3/4⟩ × ⟨3/5⟩ = ⟨9/20⟩예요.","빗금 친 부분은 전체의 ⟨9/20⟩예요."]},{"stem":"문제로 마무리예요. 피자의 ⟨3/5⟩은 감자피자이고, 태오는 그중에서 ⟨1/3⟩을 먹을 거예요. 태오가 먹을 피자는 피자 전체의 얼마인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-2-u2-X18"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨4/8⟩","mis":"M5-2-u2-X10"}],"explanation":["전체의 ⟨3/5⟩ 중에서 ⟨1/3⟩이니 ⟨3/5⟩ × ⟨1/3⟩이에요.","⟨3/5⟩ × ⟨1/3⟩ = ⟨3/15⟩ = ⟨1/5⟩이에요.","태오가 먹을 피자는 전체의 ⟨1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#9','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C5',2,'error','auto','20 × ⟨1 1/15⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X06','M5-2-u2-X17']::text[],true,'{"seq":9,"concept":"M5-2-u2-C5","difficulty":2,"kind":"error","stem":"20 × ⟨1 1/15⟩을 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「20과 15를 먼저 약분해 4 × ⟨4/3⟩ = ⟨5 1/3⟩이야.」","correct":true,"mis_target":"M5-2-u2-X06"},{"t":"순달 — 「20 × ⟨16/15⟩ = ⟨64/3⟩ = ⟨21 1/3⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「20 × 1 + 20 × ⟨1/15⟩ = 20 + ⟨4/3⟩ = ⟨21 1/3⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["⟨1 1/15⟩의 분모만 약분하면 자연수 부분 1이 약분에서 빠져요.","20 × ⟨1 1/15⟩ = 20 × ⟨16/15⟩ = ⟨64/3⟩ = ⟨21 1/3⟩이에요.","여울이가 대분수를 가분수로 나타내기 전에 약분해 틀렸어요."],"variant_rule":{"alt":[{"stem":"⟨2 1/10⟩ × ⟨1 2/7⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「10과 2를 먼저 약분해 ⟨11/5⟩ × ⟨8/7⟩ = ⟨2 18/35⟩이야.」","correct":true,"mis_target":"M5-2-u2-X06"},{"t":"순달 — 「⟨21/10⟩ × ⟨9/7⟩ = ⟨27/10⟩ = ⟨2 7/10⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「가분수로 나타낸 뒤 21과 7, 9와 10을 살펴 약분하면 ⟨3/10⟩ × 9 = ⟨2 7/10⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수를 가분수로 나타내기 전에 약분하면 값이 달라져요.","⟨2 1/10⟩ × ⟨1 2/7⟩ = ⟨21/10⟩ × ⟨9/7⟩ = ⟨27/10⟩ = ⟨2 7/10⟩이에요.","여울이가 가분수로 나타내기 전에 약분해 틀렸어요."]},{"stem":"문제로 마무리예요. 현주는 「⟨3 2/5⟩ × ⟨5/8⟩ = 3 × ⟨1/4⟩ = ⟨3/4⟩」으로, 태성이는 「⟨3/10⟩ × ⟨4/9⟩ = ⟨2/15⟩」로 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"현주 — 대분수를 가분수로 나타내지 않고 약분했어요.","correct":true,"mis_target":"M5-2-u2-X06"},{"t":"태성 — 분자 4와 분모 10을 약분하면 안 돼요.","mis":"M5-2-u2-X13"},{"t":"두 친구 모두 바르게 계산했어요.","mis":"M5-2-u2-X06"}],"explanation":["현주는 대분수 ⟨3 2/5⟩를 그대로 두고 5와 5, 2와 8을 약분해 틀렸어요.","바르게 하면 ⟨3 2/5⟩ × ⟨5/8⟩ = ⟨17/5⟩ × ⟨5/8⟩ = ⟨17/8⟩ = ⟨2 1/8⟩이에요.","태성이는 분자와 분모 사이에서 약분해 ⟨2/15⟩로 바르게 계산했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#10','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C5',2,'mc','auto','「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 10 × ⟨1 2/5⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":10,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 10 × ⟨1 2/5⟩를 계산하면 얼마인가요?","options":[{"t":"14","correct":true},{"t":"⟨10 2/5⟩","mis":"M5-2-u2-X05"},{"t":"5","mis":"M5-2-u2-X05"},{"t":"6","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","10 × ⟨1 2/5⟩ = 10 × ⟨7/5⟩ = ⟨70/5⟩ = 14예요.","계산 결과는 14예요."],"variant_rule":{"alt":[{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨4/5⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨2 2/5⟩","correct":true},{"t":"⟨12/15⟩","mis":"M5-2-u2-X01"},{"t":"⟨4/15⟩","mis":"M5-2-u2-X02"},{"t":"⟨1 2/5⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨4/5⟩ × 3 = ⟨12/5⟩ = ⟨2 2/5⟩예요.","계산 결과는 ⟨2 2/5⟩예요."]},{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 12 × ⟨3/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 1/2⟩","correct":true},{"t":"⟨36/96⟩","mis":"M5-2-u2-X01"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X07"},{"t":"⟨3/96⟩","mis":"M5-2-u2-X02"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","12 × ⟨3/8⟩ = ⟨36/8⟩ = ⟨9/2⟩ = ⟨4 1/2⟩이에요.","계산 결과는 ⟨4 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#11','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C7',2,'mc','auto','「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨4/7⟩ × ⟨5/12⟩ × ⟨14/15⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X12']::text[],true,'{"seq":11,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨4/7⟩ × ⟨5/12⟩ × ⟨14/15⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2/9⟩","correct":true},{"t":"⟨5/21⟩","mis":"M5-2-u2-X17"},{"t":"⟨7/18⟩","mis":"M5-2-u2-X17"},{"t":"⟨1 2/9⟩","mis":"M5-2-u2-X12"}],"explanation":["분수가 셋이어도 대분수는 가분수로, 자연수는 분모가 1인 분수로 보고 분모끼리·분자끼리 곱해요.","⟨4/7⟩ × ⟨5/12⟩ × ⟨14/15⟩ = ⟨280/1260⟩ = ⟨2/9⟩예요.","계산 결과는 ⟨2/9⟩예요."],"variant_rule":{"alt":[{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨1/5⟩ × ⟨1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/30⟩","correct":true},{"t":"⟨1/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨2/11⟩","mis":"M5-2-u2-X10"},{"t":"⟨6/5⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨1/5⟩ × ⟨1/6⟩ = ⟨1/30⟩이에요.","계산 결과는 ⟨1/30⟩이에요."]},{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨3 5/6⟩ × 8을 계산하면 얼마인가요?","options":[{"t":"⟨30 2/3⟩","correct":true},{"t":"⟨24 5/6⟩","mis":"M5-2-u2-X05"},{"t":"⟨9 2/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨10 2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨3 5/6⟩ × 8 = ⟨23/6⟩ × 8 = ⟨184/6⟩ = ⟨92/3⟩ = ⟨30 2/3⟩예요.","계산 결과는 ⟨30 2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#12','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C4',2,'mc','auto','단원 평가예요. 2 × ⟨3/8⟩ ○ 1 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X08','M5-2-u2-X17']::text[],true,'{"seq":12,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"단원 평가예요. 2 × ⟨3/8⟩ ○ 1 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["2 × ⟨3/8⟩ = ⟨6/8⟩ = ⟨3/4⟩이에요.","⟨3/4⟩ < 1이에요.","1보다 작은 ⟨3/8⟩을 곱해 1보다도 작아졌어요."],"variant_rule":{"alt":[{"stem":"수업 전 확인 문제예요. ⟨3/5⟩ × 4 ○ ⟨3/4⟩ × 5 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["⟨3/5⟩ × 4 = ⟨12/5⟩ = ⟨2 2/5⟩예요.","⟨3/4⟩ × 5 = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","⟨2 2/5⟩ < ⟨3 3/4⟩ — 대분수로 나타내어 견줘요."]},{"stem":"단원 평가예요. 8 × ⟨3/4⟩ ○ 8 × ⟨1 1/10⟩ — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["8 × ⟨3/4⟩ = ⟨24/4⟩ = 6이에요.","8 × ⟨1 1/10⟩ = 8 × ⟨11/10⟩ = ⟨88/10⟩ = ⟨44/5⟩ = ⟨8 4/5⟩예요.","8에 1보다 작은 수를 곱하면 8보다 작고, 1보다 큰 수를 곱하면 8보다 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#13','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C3',2,'mc','auto','단원 평가예요. ⟨1 1/3⟩ × 2를 두 가지 방법으로 계산하려고 해요. 계산 결과가 ⟨1 1/3⟩ × 2와 다른 것은 어느 것인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X15']::text[],true,'{"seq":13,"concept":"M5-2-u2-C3","difficulty":2,"kind":"mc","stem":"단원 평가예요. ⟨1 1/3⟩ × 2를 두 가지 방법으로 계산하려고 해요. 계산 결과가 ⟨1 1/3⟩ × 2와 다른 것은 어느 것인가요?","options":[{"t":"1 × 2 + ⟨1/3⟩","correct":true},{"t":"1 × 2 + ⟨1/3⟩ × 2","mis":"M5-2-u2-X05"},{"t":"⟨4/3⟩ × 2","mis":"M5-2-u2-X05"},{"t":"⟨1 1/3⟩ + ⟨1 1/3⟩","mis":"M5-2-u2-X15"}],"explanation":["⟨1 1/3⟩ × 2 = 1 × 2 + ⟨1/3⟩ × 2 = 2 + ⟨2/3⟩ = ⟨2 2/3⟩예요.","⟨4/3⟩ × 2 = ⟨8/3⟩ = ⟨2 2/3⟩, ⟨1 1/3⟩ + ⟨1 1/3⟩ = ⟨2 2/3⟩도 같아요.","1 × 2 + ⟨1/3⟩은 분수 부분에 2를 곱하지 않아 ⟨2 1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 은정이는 ⟨2/3⟩ × ⟨1/9⟩, 준상이는 ⟨4/9⟩ × ⟨1/2⟩, 주원이는 ⟨5/6⟩ × ⟨4/15⟩를 계산했어요. 계산 결과가 다른 친구는 누구인가요?","options":[{"t":"은정","correct":true},{"t":"준상","mis":"M5-2-u2-X17"},{"t":"주원","mis":"M5-2-u2-X17"},{"t":"세 친구 모두 같다","mis":"M5-2-u2-X09"}],"explanation":["은정: ⟨2/3⟩ × ⟨1/9⟩ = ⟨2/27⟩예요.","준상: ⟨4/9⟩ × ⟨1/2⟩ = ⟨2/9⟩, 주원: ⟨5/6⟩ × ⟨4/15⟩ = ⟨2/9⟩예요.","결과가 다른 친구는 은정이에요."]},{"stem":"단원 평가예요. 계산 결과가 ⟨2 5/7⟩ × 2와 다른 것은 어느 것인가요?","options":[{"t":"2 + ⟨5/7⟩ × 2","correct":true},{"t":"⟨2 5/7⟩ + ⟨2 5/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨19/7⟩ × 2","mis":"M5-2-u2-X05"},{"t":"2 × 2 + ⟨5/7⟩ × 2","mis":"M5-2-u2-X05"}],"explanation":["⟨2 5/7⟩ × 2 = ⟨19/7⟩ × 2 = ⟨38/7⟩ = ⟨5 3/7⟩이에요.","⟨2 5/7⟩ + ⟨2 5/7⟩, 2 × 2 + ⟨5/7⟩ × 2도 모두 ⟨5 3/7⟩이에요.","2 + ⟨5/7⟩ × 2는 자연수 부분 2에 2를 곱하지 않아 ⟨3 3/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#14','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C6',2,'mc','auto','⟨4/5⟩ × ⟨2/3⟩의 계산 결과와 ⟨4/5⟩의 크기를 바르게 견준 것은 어느 것인가요?',ARRAY['M5-2-u2-X08','M5-2-u2-X17']::text[],true,'{"seq":14,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"⟨4/5⟩ × ⟨2/3⟩의 계산 결과와 ⟨4/5⟩의 크기를 바르게 견준 것은 어느 것인가요?","options":[{"t":"⟨4/5⟩ × ⟨2/3⟩ < ⟨4/5⟩","correct":true},{"t":"⟨4/5⟩ × ⟨2/3⟩ > ⟨4/5⟩","mis":"M5-2-u2-X08"},{"t":"⟨4/5⟩ × ⟨2/3⟩ = ⟨4/5⟩","mis":"M5-2-u2-X08"},{"t":"견줄 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨4/5⟩ × ⟨2/3⟩ = ⟨8/15⟩이에요.","1보다 작은 ⟨2/3⟩를 곱했으니 ⟨4/5⟩보다 작아져요.","⟨8/15⟩ < ⟨4/5⟩예요."],"variant_rule":{"alt":[{"stem":"⟨3/8⟩ × ⟨5/9⟩의 계산 결과와 ⟨3/8⟩의 크기를 바르게 견준 것은 어느 것인가요?","options":[{"t":"⟨3/8⟩ × ⟨5/9⟩ < ⟨3/8⟩","correct":true},{"t":"⟨3/8⟩ × ⟨5/9⟩ > ⟨3/8⟩","mis":"M5-2-u2-X08"},{"t":"⟨3/8⟩ × ⟨5/9⟩ = ⟨3/8⟩","mis":"M5-2-u2-X08"},{"t":"견줄 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨3/8⟩ × ⟨5/9⟩ = ⟨5/24⟩예요.","1보다 작은 ⟨5/9⟩를 곱했으니 ⟨3/8⟩보다 작아져요.","⟨5/24⟩ < ⟨3/8⟩이에요."]},{"stem":"계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?","options":[{"t":"5 × ⟨1 1/9⟩","correct":true},{"t":"5 × ⟨2/3⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X08"},{"t":"5 × ⟨19/20⟩","mis":"M5-2-u2-X08"}],"explanation":["5에 1보다 작은 수를 곱하면 5보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨1 1/9⟩뿐이에요.","그래서 5보다 큰 것은 5 × ⟨1 1/9⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#15','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C7',2,'mc','auto','단원 평가예요. ⟨2 1/6⟩, ⟨1 4/5⟩, ⟨4 1/3⟩ 가운데 가장 큰 수와 가장 작은 수의 곱은 얼마인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X17','M5-2-u2-X15']::text[],true,'{"seq":15,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"단원 평가예요. ⟨2 1/6⟩, ⟨1 4/5⟩, ⟨4 1/3⟩ 가운데 가장 큰 수와 가장 작은 수의 곱은 얼마인가요?","options":[{"t":"⟨7 4/5⟩","correct":true},{"t":"⟨4 4/15⟩","mis":"M5-2-u2-X11"},{"t":"⟨9 7/18⟩","mis":"M5-2-u2-X17"},{"t":"⟨6 2/15⟩","mis":"M5-2-u2-X15"}],"explanation":["가장 큰 수는 ⟨4 1/3⟩, 가장 작은 수는 ⟨1 4/5⟩예요.","⟨4 1/3⟩ × ⟨1 4/5⟩ = ⟨13/3⟩ × ⟨9/5⟩ = ⟨117/15⟩ = ⟨39/5⟩ = ⟨7 4/5⟩예요.","대분수끼리는 가분수로 나타내어 곱해요."],"variant_rule":{"alt":[{"stem":"수학익힘 문제예요. 수 카드 5, 8, 9 가운데 2장을 골라 진분수를 만들어 6 × (진분수)의 계산 결과가 가장 작게 하려고 해요. 가장 작은 계산 결과는 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨5 1/3⟩","mis":"M5-2-u2-X17"},{"t":"⟨3 3/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨6 3/4⟩","mis":"M5-2-u2-X17"}],"explanation":["곱하는 진분수가 가장 작아야 해요 — ⟨5/8⟩, ⟨5/9⟩, ⟨8/9⟩ 가운데 ⟨5/9⟩예요.","6 × ⟨5/9⟩ = ⟨30/9⟩ = ⟨10/3⟩이에요.","가장 작은 계산 결과는 ⟨3 1/3⟩이에요."]},{"stem":"단원 평가예요. 계산 결과가 큰 것부터 차례로 기호를 쓴 것은 어느 것인가요? ㉠ ⟨1/5⟩ × ⟨1/7⟩ ㉡ ⟨1/9⟩ × ⟨1/3⟩ ㉢ ⟨1/6⟩ × ⟨1/6⟩ ㉣ ⟨1/11⟩ × ⟨1/2⟩","options":[{"t":"㉣, ㉡, ㉠, ㉢","correct":true},{"t":"㉢, ㉠, ㉡, ㉣","mis":"M5-2-u2-X17"},{"t":"㉠, ㉡, ㉢, ㉣","mis":"M5-2-u2-X17"},{"t":"㉣, ㉢, ㉡, ㉠","mis":"M5-2-u2-X10"}],"explanation":["㉠ ⟨1/35⟩, ㉡ ⟨1/27⟩, ㉢ ⟨1/36⟩, ㉣ ⟨1/22⟩이에요.","단위분수는 분모가 작을수록 커요.","22 < 27 < 35 < 36이라 ㉣, ㉡, ㉠, ㉢ 차례예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#16','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C5',2,'mc','auto','가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X15']::text[],true,'{"seq":16,"concept":"M5-2-u2-C5","difficulty":2,"kind":"mc","stem":"가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양 텃밭이 있어요. 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"⟨2 4/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 4/5⟩","mis":"M5-2-u2-X05"},{"t":"⟨6 4/5⟩","mis":"M5-2-u2-X15"}],"explanation":["직사각형의 넓이는 (가로) × (세로) — 2 × ⟨1 2/5⟩예요.","세로를 1과 ⟨2/5⟩로 갈라 더하면 2 × 1 + 2 × ⟨2/5⟩ = 2 + ⟨4/5⟩예요.","2 × ⟨1 2/5⟩ = 2 × ⟨7/5⟩ = ⟨14/5⟩ = ⟨2 4/5⟩ — ⟨2 4/5⟩ m²예요."],"variant_rule":{"alt":[{"stem":"재영이는 공원을 ⟨1 3/4⟩ km 걸었고, 하은이는 재영이가 걸은 거리의 ⟨1 3/7⟩배만큼 걸었어요. 하은이가 걸은 거리는 몇 km인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨1 9/28⟩","mis":"M5-2-u2-X11"},{"t":"⟨1 3/7⟩","mis":"M5-2-u2-X04"},{"t":"1","mis":"M5-2-u2-X04"}],"explanation":["⟨1 3/4⟩의 ⟨1 3/7⟩배이니 ⟨1 3/4⟩ × ⟨1 3/7⟩이에요.","⟨1 3/4⟩ × ⟨1 3/7⟩ = ⟨7/4⟩ × ⟨10/7⟩ = ⟨70/28⟩ = ⟨5/2⟩ = ⟨2 1/2⟩이에요.","하은이가 걸은 거리는 ⟨2 1/2⟩ km예요."]},{"stem":"사과 따기 체험에서 만든 사과주스를 ⟨1 1/4⟩ L짜리 병에 가득 담았더니 3병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨3 1/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["⟨1 1/4⟩ L씩 3병이니 ⟨1 1/4⟩ × 3이에요.","⟨1 1/4⟩ × 3 = ⟨5/4⟩ × 3 = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","모두 ⟨3 3/4⟩ L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#17','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C3',3,'mc','auto','한 변의 길이가 ⟨9 3/8⟩ cm인 정사각형 모양 거울의 둘레는 몇 cm인가요?',ARRAY['M5-2-u2-X20','M5-2-u2-X05']::text[],true,'{"seq":17,"concept":"M5-2-u2-C3","difficulty":3,"kind":"mc","stem":"한 변의 길이가 ⟨9 3/8⟩ cm인 정사각형 모양 거울의 둘레는 몇 cm인가요?","options":[{"t":"⟨37 1/2⟩","correct":true},{"t":"⟨87 57/64⟩","mis":"M5-2-u2-X20"},{"t":"⟨18 3/4⟩","mis":"M5-2-u2-X20"},{"t":"⟨36 3/8⟩","mis":"M5-2-u2-X05"}],"explanation":["정사각형은 네 변의 길이가 모두 같아요 — (둘레) = (한 변의 길이) × 4.","⟨9 3/8⟩ × 4 = ⟨75/8⟩ × 4 = ⟨300/8⟩ = ⟨75/2⟩ = ⟨37 1/2⟩이에요.","둘레는 ⟨37 1/2⟩ cm예요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 가로가 ⟨19 1/3⟩ cm, 세로가 12 cm인 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"232","correct":true},{"t":"⟨62 2/3⟩","mis":"M5-2-u2-X20"},{"t":"⟨228 1/3⟩","mis":"M5-2-u2-X05"},{"t":"23","mis":"M5-2-u2-X05"}],"explanation":["직사각형의 넓이는 (가로) × (세로)예요.","⟨19 1/3⟩ × 12 = ⟨58/3⟩ × 12 = ⟨696/3⟩ = 232예요.","넓이는 232 cm²예요 — 둘레와 헷갈리지 않아요."]},{"stem":"문제로 마무리예요. 한 변의 길이가 ⟨9 1/2⟩ m인 정사각형 모양의 수영장의 둘레는 몇 m인가요?","options":[{"t":"38","correct":true},{"t":"⟨90 1/4⟩","mis":"M5-2-u2-X20"},{"t":"19","mis":"M5-2-u2-X20"},{"t":"⟨36 1/2⟩","mis":"M5-2-u2-X05"}],"explanation":["정사각형은 네 변의 길이가 모두 같아요 — (둘레) = (한 변의 길이) × 4.","⟨9 1/2⟩ × 4 = ⟨19/2⟩ × 4 = ⟨76/2⟩ = 38이에요.","둘레는 38 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#18','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C3',3,'sa','auto','수학익힘 문제예요. ⟨3 7/10⟩ × 4 > □일 때 □ 안에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M5-2-u2-C3","difficulty":3,"kind":"sa","stem":"수학익힘 문제예요. ⟨3 7/10⟩ × 4 > □일 때 □ 안에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["먼저 곱을 구해요 — ⟨3 7/10⟩ × 4 = ⟨37/10⟩ × 4 = ⟨148/10⟩ = ⟨74/5⟩ = ⟨14 4/5⟩.","곱은 ⟨14 4/5⟩예요.","⟨14 4/5⟩보다 작은 자연수 가운데 가장 큰 수는 14예요."],"mis":"M5-2-u2-X17","variant_rule":{"alt":[{"stem":"수업 전 확인 문제예요. ⟨1 3/4⟩ × 6 < □일 때 □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["먼저 곱을 구해요 — ⟨1 3/4⟩ × 6 = ⟨7/4⟩ × 6 = ⟨42/4⟩ = ⟨21/2⟩ = ⟨10 1/2⟩.","곱은 ⟨10 1/2⟩이에요.","⟨10 1/2⟩보다 큰 자연수 가운데 가장 작은 수는 11이에요."]},{"stem":"단원 평가예요. 2 × ⟨3 1/2⟩ > □⟨4/5⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["2 × ⟨3 1/2⟩ = 2 × ⟨7/2⟩ = 7이에요.","□가 6이면 ⟨6 4/5⟩ < 7이에요.","□에는 1부터 6까지 — 모두 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#19','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C5',3,'mc','auto','「분수의 곱셈 카드 놀이」예요. 자연수 종이 2, 4, 9, 진분수 종이 ⟨1/3⟩, ⟨7/12⟩, ⟨5/6⟩, 대분수 종이 ⟨1 3/4⟩, ⟨3 1/2⟩, ⟨2 2/3⟩ 가운데 자연수 종이와 분수 종이를 1장씩 골라 (자연수)×(분수)를 만들어요. 계산 결과가 가장 큰 식은 어느 것인가요?',ARRAY['M5-2-u2-X17']::text[],true,'{"seq":19,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"「분수의 곱셈 카드 놀이」예요. 자연수 종이 2, 4, 9, 진분수 종이 ⟨1/3⟩, ⟨7/12⟩, ⟨5/6⟩, 대분수 종이 ⟨1 3/4⟩, ⟨3 1/2⟩, ⟨2 2/3⟩ 가운데 자연수 종이와 분수 종이를 1장씩 골라 (자연수)×(분수)를 만들어요. 계산 결과가 가장 큰 식은 어느 것인가요?","options":[{"t":"9 × ⟨3 1/2⟩","correct":true},{"t":"9 × ⟨5/6⟩","mis":"M5-2-u2-X17"},{"t":"4 × ⟨3 1/2⟩","mis":"M5-2-u2-X17"},{"t":"9 × ⟨2 2/3⟩","mis":"M5-2-u2-X17"}],"explanation":["계산 결과를 크게 하려면 자연수도 분수도 가장 큰 수를 골라요.","가장 큰 자연수는 9, 가장 큰 분수는 ⟨3 1/2⟩이에요.","9 × ⟨3 1/2⟩ = 9 × ⟨7/2⟩ = ⟨63/2⟩ = ⟨31 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"「분수의 곱셈 카드 놀이」예요. 자연수 종이 2, 4, 9, 진분수 종이 ⟨1/3⟩, ⟨7/12⟩, ⟨5/6⟩, 대분수 종이 ⟨1 3/4⟩, ⟨3 1/2⟩, ⟨2 2/3⟩ 가운데 자연수 종이와 분수 종이를 1장씩 골라 (자연수)×(분수)를 만들어요. 계산 결과가 가장 작은 식은 어느 것인가요?","options":[{"t":"2 × ⟨1/3⟩","correct":true},{"t":"2 × ⟨7/12⟩","mis":"M5-2-u2-X17"},{"t":"9 × ⟨1/3⟩","mis":"M5-2-u2-X17"},{"t":"2 × ⟨1 3/4⟩","mis":"M5-2-u2-X17"}],"explanation":["계산 결과를 작게 하려면 자연수도 분수도 가장 작은 수를 골라요.","가장 작은 자연수는 2, 가장 작은 분수는 ⟨1/3⟩이에요.","2 × ⟨1/3⟩ = ⟨2/3⟩예요."]},{"stem":"단원 평가예요. 수 카드 8, 3, 9를 한 번씩만 이용하여 만들 수 있는 가장 큰 대분수와 4의 곱은 얼마인가요?","options":[{"t":"⟨37 1/2⟩","correct":true},{"t":"⟨33 1/3⟩","mis":"M5-2-u2-X17"},{"t":"⟨15 5/9⟩","mis":"M5-2-u2-X17"},{"t":"⟨13 3/8⟩","mis":"M5-2-u2-X15"}],"explanation":["가장 큰 대분수는 자연수 부분에 가장 큰 수 9를 놓고 남은 두 수로 진분수 ⟨3/8⟩을 만든 ⟨9 3/8⟩이에요.","⟨9 3/8⟩ × 4 = ⟨75/8⟩ × 4 = ⟨300/8⟩ = ⟨75/2⟩ = ⟨37 1/2⟩이에요.","곱은 ⟨37 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#20','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C5',3,'mc','auto','수학익힘 문제예요. 이서는 밤 4 kg을 주웠고, 시하는 이서가 주운 밤 무게의 ⟨1 5/8⟩배를 주웠어요. 누가 주운 밤이 몇 kg 더 무거운가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X16','M5-2-u2-X15']::text[],true,'{"seq":20,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"수학익힘 문제예요. 이서는 밤 4 kg을 주웠고, 시하는 이서가 주운 밤 무게의 ⟨1 5/8⟩배를 주웠어요. 누가 주운 밤이 몇 kg 더 무거운가요?","options":[{"t":"시하, ⟨2 1/2⟩ kg","correct":true},{"t":"이서, ⟨2 1/2⟩ kg","mis":"M5-2-u2-X17"},{"t":"시하, ⟨6 1/2⟩ kg","mis":"M5-2-u2-X16"},{"t":"시하, ⟨1 5/8⟩ kg","mis":"M5-2-u2-X15"}],"explanation":["시하가 주운 밤은 4 × ⟨1 5/8⟩ = 4 × ⟨13/8⟩ = ⟨13/2⟩ = ⟨6 1/2⟩(kg)이에요.","⟨1 5/8⟩배는 1보다 크니 시하가 더 많이 주웠어요.","⟨6 1/2⟩ − 4 = ⟨2 1/2⟩ — 시하가 ⟨2 1/2⟩ kg 더 무거워요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 선아네 학교 도서관에 있는 책 300권 중에서 ⟨1/3⟩은 과학책이에요. 선아는 과학책 중에서 ⟨3/5⟩을 읽었다면 선아가 읽은 과학책은 몇 권인가요?","options":[{"t":"60","correct":true},{"t":"100","mis":"M5-2-u2-X17"},{"t":"180","mis":"M5-2-u2-X18"},{"t":"40","mis":"M5-2-u2-X17"}],"explanation":["과학책은 300 × ⟨1/3⟩ = 100(권)이에요.","선아가 읽은 과학책은 100 × ⟨3/5⟩ = 60(권)이에요.","300 × ⟨3/5⟩ = 180은 전체 책의 ⟨3/5⟩이에요 — 「과학책 중에서」를 놓치지 않아요."]},{"stem":"단원 평가예요. 은서는 집에서 ⟨14/15⟩ km 떨어진 서점에 가는데 전체 거리의 ⟨5/6⟩는 버스를 타고 나머지는 걸어서 갔어요. 은서가 걸어서 간 거리는 몇 km인가요?","options":[{"t":"⟨7/45⟩","correct":true},{"t":"⟨7/9⟩","mis":"M5-2-u2-X19"},{"t":"⟨1/10⟩","mis":"M5-2-u2-X15"},{"t":"⟨1/6⟩","mis":"M5-2-u2-X18"}],"explanation":["걸어서 간 거리는 전체 거리의 나머지 1 − ⟨5/6⟩ = ⟨1/6⟩이에요.","⟨14/15⟩ × ⟨1/6⟩ = ⟨14/90⟩ = ⟨7/45⟩이에요.","⟨5/6⟩를 곱하면 버스로 간 거리 ⟨7/9⟩ km예요 — 묻는 것은 걸어서 간 거리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#21','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C4',3,'mc','auto','수세미 열매를 1시간의 ⟨1/5⟩ 동안 데쳤고, 지한이는 하루 24시간의 ⟨1/8⟩만큼 책을 읽었어요. 두 시간을 바르게 견준 것은 어느 것인가요?',ARRAY['M5-2-u2-X18','M5-2-u2-X17']::text[],true,'{"seq":21,"concept":"M5-2-u2-C4","difficulty":3,"kind":"mc","stem":"수세미 열매를 1시간의 ⟨1/5⟩ 동안 데쳤고, 지한이는 하루 24시간의 ⟨1/8⟩만큼 책을 읽었어요. 두 시간을 바르게 견준 것은 어느 것인가요?","options":[{"t":"하루의 ⟨1/8⟩이 더 길다","correct":true},{"t":"1시간의 ⟨1/5⟩이 더 길다","mis":"M5-2-u2-X18"},{"t":"⟨1/5⟩이 ⟨1/8⟩보다 크니 두 시간은 같다","mis":"M5-2-u2-X18"},{"t":"두 시간은 같다","mis":"M5-2-u2-X17"}],"explanation":["1시간의 ⟨1/5⟩은 60 × ⟨1/5⟩ = 12(분)이에요.","하루의 ⟨1/8⟩은 24 × ⟨1/8⟩ = 3(시간) — 180분이에요.","전체(기준)가 다르면 분수만 견주어서는 안 돼요 — 하루의 ⟨1/8⟩이 더 길어요."],"variant_rule":{"alt":[{"stem":"수학익힘 문제예요. 혜지네 학교 5학년 전체 학생 160명 가운데 ⟨5/8⟩는 남학생이고, 그중 ⟨3/5⟩은 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요?","options":[{"t":"60","correct":true},{"t":"100","mis":"M5-2-u2-X17"},{"t":"96","mis":"M5-2-u2-X18"},{"t":"40","mis":"M5-2-u2-X17"}],"explanation":["남학생은 160 × ⟨5/8⟩ = 100(명)이에요.","그중 ⟨3/5⟩이니 100 × ⟨3/5⟩ = 60(명)이에요.","160 × ⟨5/8⟩ × ⟨3/5⟩ = 60 — 세 수를 한 번에 곱해도 같아요."]},{"stem":"수학익힘 문제예요. 1분에 ⟨4 2/3⟩ L씩 물이 일정하게 나오는 수도꼭지를 5분 30초 동안 틀어 놓았어요. 받을 수 있는 물은 몇 L인가요?","options":[{"t":"⟨25 2/3⟩","correct":true},{"t":"⟨24 11/15⟩","mis":"M5-2-u2-X21"},{"t":"⟨23 1/3⟩","mis":"M5-2-u2-X17"},{"t":"140","mis":"M5-2-u2-X21"}],"explanation":["1분은 60초이니 30초는 ⟨30/60⟩분 = ⟨1/2⟩분, 5분 30초는 ⟨5 1/2⟩분이에요.","⟨4 2/3⟩ × ⟨5 1/2⟩ = ⟨14/3⟩ × ⟨11/2⟩ = ⟨77/3⟩ = ⟨25 2/3⟩예요.","받을 수 있는 물은 ⟨25 2/3⟩ L예요 — 30초를 ⟨3/10⟩분으로 보지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#22','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C8',3,'sa','auto','서연이네 마을 전체 주민은 270명이에요. 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M5-2-u2-C8","difficulty":3,"kind":"sa","stem":"서연이네 마을 전체 주민은 270명이에요. 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["180"],"explanation":["전체 270명의 ⟨2/3⟩ 이상이에요.","270 × ⟨2/3⟩ = 180(명)이에요.","적어도 180명이 동의해야 해요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"준기네 마을 전체 주민은 430명이에요. 전체 주민의 ⟨3/5⟩ 이상이 동의해야 수영장을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["258"],"explanation":["전체 430명의 ⟨3/5⟩ 이상이에요.","430 × ⟨3/5⟩ = 258(명)이에요.","적어도 258명이 동의해야 해요."]},{"stem":"서연이네 마을 전체 주민은 270명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 158명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["22"],"explanation":["① 최소로 동의해야 하는 수: 270 × ⟨2/3⟩ = 180(명)이에요.","② 지금까지 158명이 동의했으니 180 − 158 = 22(명)이에요.","적어도 22명이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#23','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C2',4,'sa','auto','⟨2/5⟩ × □ = ⟨8/5⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M5-2-u2-C2","difficulty":4,"kind":"sa","stem":"⟨2/5⟩ × □ = ⟨8/5⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모는 그대로이고 분자만 2에서 8로 바뀌었어요.","분자와 □를 곱해 8이 되어야 해요 — 2 × 4 = 8.","그래서 □는 4예요."],"mis":"M5-2-u2-X01","variant_rule":{"alt":[{"stem":"72 × ⟨□/9⟩ = 40일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["5"],"explanation":["72를 똑같이 9로 나누면 한 묶음은 8이에요.","5묶음이 40이니 □ = 40 ÷ 8 = 5예요.","72 × ⟨5/9⟩ = 40 — 맞아요."]},{"stem":"⟨1/□⟩ × ⟨1/3⟩ = ⟨1/12⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["단위분수끼리 곱하면 분모끼리 곱해요.","□ × 3 = 12이어야 해요.","12 ÷ 3 = 4니 □는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#24','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C7',4,'essay','teacher','단원 평가예요. 어떤 친구가 ⟨2 1/10⟩ × ⟨1 2/7⟩를 「⟨11/5⟩ × ⟨8/7⟩ = ⟨88/35⟩ = ⟨2 18/35⟩」로 계산했어요. 이 친구는 10과 2를 먼저 약분했어요. 잘못 계산한 곳을 찾아 이유를 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u2-C7","difficulty":4,"kind":"essay","stem":"단원 평가예요. 어떤 친구가 ⟨2 1/10⟩ × ⟨1 2/7⟩를 「⟨11/5⟩ × ⟨8/7⟩ = ⟨88/35⟩ = ⟨2 18/35⟩」로 계산했어요. 이 친구는 10과 2를 먼저 약분했어요. 잘못 계산한 곳을 찾아 이유를 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 대분수를 가분수로 나타내기 전에 ⟨2 1/10⟩의 분모 10과 ⟨1 2/7⟩의 분자 2를 약분해서 틀렸다. 대분수를 가분수로 나타낸 다음 약분해야 한다. ⟨2 1/10⟩ × ⟨1 2/7⟩ = ⟨21/10⟩ × ⟨9/7⟩ = ⟨27/10⟩ = ⟨2 7/10⟩이다.","scoring_points":["대분수를 가분수로 나타내기 전에 약분했다고 썼는가","⟨21/10⟩ × ⟨9/7⟩로 나타냈는가","⟨2 7/10⟩을 구했는가"]},"explanation":["가분수로 나타내기 전에 약분하면 안 돼요.","⟨2 1/10⟩ = ⟨21/10⟩, ⟨1 2/7⟩ = ⟨9/7⟩예요.","⟨21/10⟩ × ⟨9/7⟩ = ⟨27/10⟩ = ⟨2 7/10⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_c#25','math',5,2,'u2','','tb_g5_2_math_u2_review_c','unit_review','M5-2-u2-C6',4,'essay','teacher','이사를 마치고 시루떡 전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩을 이웃집 친구에게 주었어요. 이웃집에 나누어 준 시루떡이 전체의 얼마인지 그림을 어떻게 나누어 생각하는지 설명하며 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u2-C6","difficulty":4,"kind":"essay","stem":"이사를 마치고 시루떡 전체의 ⟨1/4⟩ 중에서 ⟨1/3⟩을 이웃집 친구에게 주었어요. 이웃집에 나누어 준 시루떡이 전체의 얼마인지 그림을 어떻게 나누어 생각하는지 설명하며 구해 보세요.","answer_guide":{"answer":"예: 전체를 4등분 한 것 중의 1이 ⟨1/4⟩이다. 이것을 다시 각각 3등분 하면 전체는 4 × 3 = 12칸으로 나뉘고, ⟨1/4⟩의 ⟨1/3⟩은 그중의 1칸이다. 그래서 ⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩이고, 이웃집에 나누어 준 시루떡은 전체의 ⟨1/12⟩이다.","scoring_points":["전체를 4등분 한 뒤 다시 3등분 한다고 썼는가","전체 12칸 중 1칸임을 밝혔는가","⟨1/12⟩을 구했는가"]},"explanation":["전체를 4등분 한 뒤 다시 3등분 해요.","전체 12칸 중 1칸이에요.","⟨1/4⟩ × ⟨1/3⟩ = ⟨1/12⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#1','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C4',1,'mc','auto','단원 평가예요. 9 × ⟨4/7⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X07','M5-2-u2-X02']::text[],true,'{"seq":1,"concept":"M5-2-u2-C4","difficulty":1,"kind":"mc","stem":"단원 평가예요. 9 × ⟨4/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 1/7⟩","correct":true},{"t":"⟨36/63⟩","mis":"M5-2-u2-X01"},{"t":"⟨1 2/7⟩","mis":"M5-2-u2-X07"},{"t":"⟨4/63⟩","mis":"M5-2-u2-X02"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","9 × ⟨4/7⟩ = ⟨36/7⟩ = ⟨5 1/7⟩이에요.","계산 결과는 ⟨5 1/7⟩이에요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. ⟨4/7⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨1 5/7⟩","correct":true},{"t":"⟨12/21⟩","mis":"M5-2-u2-X01"},{"t":"⟨4/21⟩","mis":"M5-2-u2-X02"},{"t":"1","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨4/7⟩ × 3 = ⟨12/7⟩ = ⟨1 5/7⟩예요.","계산 결과는 ⟨1 5/7⟩예요."]},{"stem":"형성 평가예요. ⟨2/7⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨6/7⟩","correct":true},{"t":"⟨6/21⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/21⟩","mis":"M5-2-u2-X02"},{"t":"⟨5/7⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/7⟩ × 3 = ⟨6/7⟩이에요.","계산 결과는 ⟨6/7⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#2','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C3',1,'mc','auto','단원 평가예요. ⟨1 5/9⟩ × 12를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X04']::text[],true,'{"seq":2,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"단원 평가예요. ⟨1 5/9⟩ × 12를 계산하면 얼마인가요?","options":[{"t":"⟨18 2/3⟩","correct":true},{"t":"⟨12 5/9⟩","mis":"M5-2-u2-X05"},{"t":"⟨7 2/3⟩","mis":"M5-2-u2-X05"},{"t":"8","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨1 5/9⟩ × 12 = ⟨14/9⟩ × 12 = ⟨168/9⟩ = ⟨56/3⟩ = ⟨18 2/3⟩예요.","계산 결과는 ⟨18 2/3⟩예요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. 5 × ⟨1 2/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 1/9⟩","correct":true},{"t":"⟨5 2/9⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/9⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","5 × ⟨1 2/9⟩ = 5 × ⟨11/9⟩ = ⟨55/9⟩ = ⟨6 1/9⟩이에요.","계산 결과는 ⟨6 1/9⟩이에요."]},{"stem":"단원 평가예요. 6 × ⟨3 1/3⟩을 계산하면 얼마인가요?","options":[{"t":"20","correct":true},{"t":"⟨18 1/3⟩","mis":"M5-2-u2-X05"},{"t":"5","mis":"M5-2-u2-X05"},{"t":"8","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","6 × ⟨3 1/3⟩ = 6 × ⟨10/3⟩ = ⟨60/3⟩ = 20이에요.","계산 결과는 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#3','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C6',1,'mc','auto','문제로 마무리예요. ⟨2/3⟩ × ⟨9/14⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":3,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"문제로 마무리예요. ⟨2/3⟩ × ⟨9/14⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨18/3⟩","mis":"M5-2-u2-X09"},{"t":"⟨11/17⟩","mis":"M5-2-u2-X10"},{"t":"⟨28/27⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨2/3⟩ × ⟨9/14⟩ = ⟨18/42⟩ = ⟨3/7⟩이에요.","계산 결과는 ⟨3/7⟩이에요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. ⟨5/21⟩ × 7을 계산하면 얼마인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨35/147⟩","mis":"M5-2-u2-X01"},{"t":"⟨5/147⟩","mis":"M5-2-u2-X02"},{"t":"⟨4/7⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨5/21⟩ × 7 = ⟨35/21⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요.","계산 결과는 ⟨1 2/3⟩예요."]},{"stem":"문제로 마무리예요. ⟨1 9/11⟩ × 5를 계산하면 얼마인가요?","options":[{"t":"⟨9 1/11⟩","correct":true},{"t":"⟨5 9/11⟩","mis":"M5-2-u2-X05"},{"t":"⟨5 1/11⟩","mis":"M5-2-u2-X05"},{"t":"⟨4 6/11⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨1 9/11⟩ × 5 = ⟨20/11⟩ × 5 = ⟨100/11⟩ = ⟨9 1/11⟩이에요.","계산 결과는 ⟨9 1/11⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#4','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C1',1,'mc','auto','⟨56/70⟩을 기약분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X12']::text[],true,'{"seq":4,"concept":"M5-2-u2-C1","difficulty":1,"kind":"mc","stem":"⟨56/70⟩을 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨5/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨2/3⟩","mis":"M5-2-u2-X12"},{"t":"1","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","56과 70을 모두 14로 나눌 수 있어요 — 56 ÷ 14 = 4, 70 ÷ 14 = 5.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨56/70⟩ = ⟨4/5⟩."],"variant_rule":{"alt":[{"stem":"불꽃 축제 장소까지 전체 1 km예요. 지금까지 ⟨4/5⟩ km를 걸어왔다면 남은 길은 몇 km인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨4/5⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/4⟩","mis":"M5-2-u2-X01"},{"t":"⟨2/5⟩","mis":"M5-2-u2-X12"}],"explanation":["1은 ⟨5/5⟩와 같아요.","남은 길은 ⟨5/5⟩ − ⟨4/5⟩ = ⟨1/5⟩이에요.","분모가 같으면 뺄셈도 분자끼리 해요 — ⟨1/5⟩ km."]},{"stem":"⟨5/30⟩를 기약분수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨6/1⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/7⟩","mis":"M5-2-u2-X12"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X12"}],"explanation":["분모와 분자를 같은 수로 나누는 것이 약분이에요.","5와 30을 모두 5로 나눌 수 있어요 — 5 ÷ 5 = 1, 30 ÷ 5 = 6.","더 나눌 수 없을 때까지 줄인 분수가 기약분수예요 — ⟨5/30⟩ = ⟨1/6⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#5','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C4',1,'mc','auto','단원 평가예요. 3 × ⟨5/9⟩를 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X07','M5-2-u2-X02']::text[],true,'{"seq":5,"concept":"M5-2-u2-C4","difficulty":1,"kind":"mc","stem":"단원 평가예요. 3 × ⟨5/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨15/27⟩","mis":"M5-2-u2-X01"},{"t":"⟨1/3⟩","mis":"M5-2-u2-X07"},{"t":"⟨5/27⟩","mis":"M5-2-u2-X02"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","3 × ⟨5/9⟩ = ⟨15/9⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요.","계산 결과는 ⟨1 2/3⟩예요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. 빈칸에 알맞은 수를 써넣어요. 2에 ⟨5/8⟩를 곱한 수를 첫째 빈칸에, 그 수에 ⟨2 2/5⟩를 곱한 수를 둘째 빈칸에 써요. 둘째 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"3","correct":true},{"t":"⟨1 1/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨2 1/10⟩","mis":"M5-2-u2-X11"},{"t":"⟨3 13/20⟩","mis":"M5-2-u2-X15"}],"explanation":["첫째 빈칸: 2 × ⟨5/8⟩ = ⟨10/8⟩ = ⟨5/4⟩ = ⟨1 1/4⟩이에요.","둘째 빈칸: ⟨1 1/4⟩ × ⟨2 2/5⟩ = ⟨5/4⟩ × ⟨12/5⟩ = ⟨60/20⟩ = 3이에요.","대분수끼리는 가분수로 나타내어 곱해요 — 둘째 빈칸은 3이에요."]},{"stem":"단원 평가예요. ⟨3 1/2⟩ × ⟨2 3/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨8 1/2⟩","correct":true},{"t":"⟨6 3/14⟩","mis":"M5-2-u2-X11"},{"t":"⟨4 6/7⟩","mis":"M5-2-u2-X04"},{"t":"⟨2 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨3 1/2⟩ × ⟨2 3/7⟩ = ⟨7/2⟩ × ⟨17/7⟩ = ⟨119/14⟩ = ⟨17/2⟩ = ⟨8 1/2⟩이에요.","계산 결과는 ⟨8 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#6','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C6',1,'match','auto','단원 평가예요. 곱셈식과 계산 결과(기약분수)를 알맞게 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u2-C6","difficulty":1,"kind":"match","stem":"단원 평가예요. 곱셈식과 계산 결과(기약분수)를 알맞게 이으세요.","pairs":[{"l":"⟨1/5⟩ × ⟨1/7⟩","r":"⟨1/35⟩"},{"l":"⟨3/8⟩ × ⟨5/9⟩","r":"⟨5/24⟩"},{"l":"⟨5/6⟩ × ⟨3/7⟩","r":"⟨5/14⟩"}],"mis":"M5-2-u2-X10","explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨1/5⟩ × ⟨1/7⟩ = ⟨1/35⟩, ⟨3/8⟩ × ⟨5/9⟩ = ⟨15/72⟩ = ⟨5/24⟩, ⟨5/6⟩ × ⟨3/7⟩ = ⟨15/42⟩ = ⟨5/14⟩예요.","분모를 그대로 두지 않도록 해요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. 계산 결과가 같은 것끼리 이으세요.","pairs":[{"l":"6 × ⟨1 3/8⟩","r":"11 × ⟨3/4⟩"},{"l":"⟨5/36⟩ × 3","r":"⟨15/16⟩ × ⟨4/9⟩"},{"l":"⟨1/2⟩ × ⟨1/3⟩ × ⟨3/10⟩","r":"⟨1/4⟩ × ⟨1/5⟩"}],"explanation":["6 × ⟨1 3/8⟩ = ⟨33/4⟩ = ⟨8 1/4⟩, 11 × ⟨3/4⟩ = ⟨33/4⟩ = ⟨8 1/4⟩이에요.","⟨5/36⟩ × 3 = ⟨5/12⟩, ⟨15/16⟩ × ⟨4/9⟩ = ⟨5/12⟩예요.","⟨1/2⟩ × ⟨1/3⟩ × ⟨3/10⟩ = ⟨1/20⟩, ⟨1/4⟩ × ⟨1/5⟩ = ⟨1/20⟩ — 약분하거나 대분수로 나타내어 견줘요."]},{"stem":"형성 평가 「(분수)×(자연수)를 계산해요」예요. 곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"⟨2/7⟩ × 3","r":"⟨6/7⟩"},{"l":"⟨5/6⟩ × 8","r":"⟨6 2/3⟩"},{"l":"⟨3/5⟩ × 6","r":"⟨3 3/5⟩"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/7⟩ × 3 = ⟨6/7⟩, ⟨5/6⟩ × 8 = ⟨40/6⟩ = ⟨20/3⟩ = ⟨6 2/3⟩, ⟨3/5⟩ × 6 = ⟨18/5⟩ = ⟨3 3/5⟩이에요.","분모에 자연수를 곱하지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#7','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C4',1,'sa','auto','단원 평가예요. 떨어진 높이의 ⟨5/9⟩만큼 튀어 오르는 공을 높이가 72 cm인 곳에서 떨어뜨렸어요. 첫 번째로 튀어 오른 공의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u2-C4","difficulty":1,"kind":"sa","stem":"단원 평가예요. 떨어진 높이의 ⟨5/9⟩만큼 튀어 오르는 공을 높이가 72 cm인 곳에서 떨어뜨렸어요. 첫 번째로 튀어 오른 공의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["튀어 오른 높이는 72 cm의 ⟨5/9⟩예요.","72 × ⟨5/9⟩ = ⟨360/9⟩ = 40이에요.","튀어 오른 높이는 40 cm예요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"문제로 마무리예요. 지한이는 토요일에 하루 24시간의 ⟨1/8⟩만큼 책을 읽었어요. 지한이가 토요일에 책을 읽은 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["하루는 24시간이에요.","24 × ⟨1/8⟩ = ⟨24/8⟩ = 3이에요.","지한이가 책을 읽은 시간은 3시간이에요."]},{"stem":"형성 평가예요. 이안이는 여름 방학 동안 책 25권을 읽었는데 그중 ⟨2/5⟩가 위인전이었어요. 이안이가 읽은 위인전은 몇 권인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["25권의 ⟨2/5⟩는 25 × ⟨2/5⟩예요.","25 × ⟨2/5⟩ = ⟨50/5⟩ = 10이에요.","이안이가 읽은 위인전은 10권이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#8','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C6',1,'mc','auto','형성 평가예요. 전체를 4등분 한 것 중의 3만큼을 다시 5등분 한 것 중의 3만큼에 빗금을 쳤어요. 빗금 친 부분은 전체의 얼마인가요?',ARRAY['M5-2-u2-X18','M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":8,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"형성 평가예요. 전체를 4등분 한 것 중의 3만큼을 다시 5등분 한 것 중의 3만큼에 빗금을 쳤어요. 빗금 친 부분은 전체의 얼마인가요?","options":[{"t":"⟨9/20⟩","correct":true},{"t":"⟨3/5⟩","mis":"M5-2-u2-X18"},{"t":"⟨9/4⟩","mis":"M5-2-u2-X09"},{"t":"⟨6/9⟩","mis":"M5-2-u2-X10"}],"explanation":["전체의 ⟨3/4⟩ 중에서 ⟨3/5⟩이니 ⟨3/4⟩ × ⟨3/5⟩이에요.","⟨3/4⟩ × ⟨3/5⟩ = ⟨9/20⟩예요.","빗금 친 부분은 전체의 ⟨9/20⟩예요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. 피자의 ⟨3/5⟩은 감자피자이고, 태오는 그중에서 ⟨1/3⟩을 먹을 거예요. 태오가 먹을 피자는 피자 전체의 얼마인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-2-u2-X18"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨4/8⟩","mis":"M5-2-u2-X10"}],"explanation":["전체의 ⟨3/5⟩ 중에서 ⟨1/3⟩이니 ⟨3/5⟩ × ⟨1/3⟩이에요.","⟨3/5⟩ × ⟨1/3⟩ = ⟨3/15⟩ = ⟨1/5⟩이에요.","태오가 먹을 피자는 전체의 ⟨1/5⟩이에요."]},{"stem":"단원 평가예요. 현우네 학교 도서관에 있는 전체 책의 ⟨3/7⟩은 동화책이고, 현우는 그중 ⟨2/9⟩를 읽었어요. 현우가 읽은 동화책은 전체 책의 몇 분의 몇인가요?","options":[{"t":"⟨2/21⟩","correct":true},{"t":"⟨2/9⟩","mis":"M5-2-u2-X18"},{"t":"⟨6/7⟩","mis":"M5-2-u2-X09"},{"t":"⟨5/16⟩","mis":"M5-2-u2-X10"}],"explanation":["전체의 ⟨3/7⟩ 중에서 ⟨2/9⟩니 ⟨3/7⟩ × ⟨2/9⟩예요.","⟨3/7⟩ × ⟨2/9⟩ = ⟨6/63⟩ = ⟨2/21⟩예요.","현우가 읽은 동화책은 전체 책의 ⟨2/21⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#9','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C7',2,'error','auto','⟨2 1/10⟩ × ⟨1 2/7⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M5-2-u2-X06','M5-2-u2-X17']::text[],true,'{"seq":9,"concept":"M5-2-u2-C7","difficulty":2,"kind":"error","stem":"⟨2 1/10⟩ × ⟨1 2/7⟩를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「10과 2를 먼저 약분해 ⟨11/5⟩ × ⟨8/7⟩ = ⟨2 18/35⟩이야.」","correct":true,"mis_target":"M5-2-u2-X06"},{"t":"순달 — 「⟨21/10⟩ × ⟨9/7⟩ = ⟨27/10⟩ = ⟨2 7/10⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「가분수로 나타낸 뒤 21과 7, 9와 10을 살펴 약분하면 ⟨3/10⟩ × 9 = ⟨2 7/10⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수를 가분수로 나타내기 전에 약분하면 값이 달라져요.","⟨2 1/10⟩ × ⟨1 2/7⟩ = ⟨21/10⟩ × ⟨9/7⟩ = ⟨27/10⟩ = ⟨2 7/10⟩이에요.","여울이가 가분수로 나타내기 전에 약분해 틀렸어요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. 현주는 「⟨3 2/5⟩ × ⟨5/8⟩ = 3 × ⟨1/4⟩ = ⟨3/4⟩」으로, 태성이는 「⟨3/10⟩ × ⟨4/9⟩ = ⟨2/15⟩」로 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"현주 — 대분수를 가분수로 나타내지 않고 약분했어요.","correct":true,"mis_target":"M5-2-u2-X06"},{"t":"태성 — 분자 4와 분모 10을 약분하면 안 돼요.","mis":"M5-2-u2-X13"},{"t":"두 친구 모두 바르게 계산했어요.","mis":"M5-2-u2-X06"}],"explanation":["현주는 대분수 ⟨3 2/5⟩를 그대로 두고 5와 5, 2와 8을 약분해 틀렸어요.","바르게 하면 ⟨3 2/5⟩ × ⟨5/8⟩ = ⟨17/5⟩ × ⟨5/8⟩ = ⟨17/8⟩ = ⟨2 1/8⟩이에요.","태성이는 분자와 분모 사이에서 약분해 ⟨2/15⟩로 바르게 계산했어요."]},{"stem":"⟨1 1/6⟩ × 15를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"여울 — 「6과 15를 먼저 약분해 ⟨1 1/2⟩ × 5 = ⟨7 1/2⟩이야.」","correct":true,"mis_target":"M5-2-u2-X06"},{"t":"순달 — 「⟨7/6⟩ × 15 = ⟨35/2⟩ = ⟨17 1/2⟩이야.」","mis":"M5-2-u2-X17"},{"t":"달곰 — 「가분수로 나타낸 뒤 6과 15를 3으로 약분하면 ⟨7/2⟩ × 5 = ⟨17 1/2⟩이야.」","mis":"M5-2-u2-X17"}],"explanation":["대분수를 가분수로 나타내지 않고 먼저 약분하면 자연수 부분 1이 약분에서 빠져요.","⟨1 1/6⟩ × 15 = ⟨7/6⟩ × 15 = ⟨35/2⟩ = ⟨17 1/2⟩이에요.","여울이가 가분수로 나타내기 전에 약분해 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#10','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C2',2,'mc','auto','「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨4/5⟩ × 3을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X01','M5-2-u2-X02','M5-2-u2-X15']::text[],true,'{"seq":10,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨4/5⟩ × 3을 계산하면 얼마인가요?","options":[{"t":"⟨2 2/5⟩","correct":true},{"t":"⟨12/15⟩","mis":"M5-2-u2-X01"},{"t":"⟨4/15⟩","mis":"M5-2-u2-X02"},{"t":"⟨1 2/5⟩","mis":"M5-2-u2-X15"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨4/5⟩ × 3 = ⟨12/5⟩ = ⟨2 2/5⟩예요.","계산 결과는 ⟨2 2/5⟩예요."],"variant_rule":{"alt":[{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 12 × ⟨3/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 1/2⟩","correct":true},{"t":"⟨36/96⟩","mis":"M5-2-u2-X01"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X07"},{"t":"⟨3/96⟩","mis":"M5-2-u2-X02"}],"explanation":["분모는 그대로 두고 자연수와 분자를 곱해요.","12 × ⟨3/8⟩ = ⟨36/8⟩ = ⟨9/2⟩ = ⟨4 1/2⟩이에요.","계산 결과는 ⟨4 1/2⟩이에요."]},{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨5 2/3⟩ × 9를 계산하면 얼마인가요?","options":[{"t":"51","correct":true},{"t":"⟨45 2/3⟩","mis":"M5-2-u2-X05"},{"t":"11","mis":"M5-2-u2-X05"},{"t":"21","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨5 2/3⟩ × 9 = ⟨17/3⟩ × 9 = ⟨153/3⟩ = 51이에요.","계산 결과는 51이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#11','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C6',2,'mc','auto','「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨1/5⟩ × ⟨1/6⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X09','M5-2-u2-X10']::text[],true,'{"seq":11,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨1/5⟩ × ⟨1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/30⟩","correct":true},{"t":"⟨1/5⟩","mis":"M5-2-u2-X09"},{"t":"⟨2/11⟩","mis":"M5-2-u2-X10"},{"t":"⟨6/5⟩","mis":"M5-2-u2-X10"}],"explanation":["분모는 분모끼리, 분자는 분자끼리 곱해요.","⟨1/5⟩ × ⟨1/6⟩ = ⟨1/30⟩이에요.","계산 결과는 ⟨1/30⟩이에요."],"variant_rule":{"alt":[{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. ⟨3 5/6⟩ × 8을 계산하면 얼마인가요?","options":[{"t":"⟨30 2/3⟩","correct":true},{"t":"⟨24 5/6⟩","mis":"M5-2-u2-X05"},{"t":"⟨9 2/3⟩","mis":"M5-2-u2-X05"},{"t":"⟨10 2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 분자와 자연수를 곱해요.","⟨3 5/6⟩ × 8 = ⟨23/6⟩ × 8 = ⟨184/6⟩ = ⟨92/3⟩ = ⟨30 2/3⟩예요.","계산 결과는 ⟨30 2/3⟩예요."]},{"stem":"「너와 나의 모래성 만들기」 놀이판의 칸 문제예요. 5 × ⟨2 3/10⟩을 계산하면 얼마인가요?","options":[{"t":"⟨11 1/2⟩","correct":true},{"t":"⟨10 3/10⟩","mis":"M5-2-u2-X05"},{"t":"⟨3 1/2⟩","mis":"M5-2-u2-X05"},{"t":"⟨2 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["대분수를 가분수로 나타낸 다음 자연수와 분자를 곱해요.","5 × ⟨2 3/10⟩ = 5 × ⟨23/10⟩ = ⟨115/10⟩ = ⟨23/2⟩ = ⟨11 1/2⟩이에요.","계산 결과는 ⟨11 1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#12','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C2',2,'mc','auto','수업 전 확인 문제예요. ⟨3/5⟩ × 4 ○ ⟨3/4⟩ × 5 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X08','M5-2-u2-X17']::text[],true,'{"seq":12,"concept":"M5-2-u2-C2","difficulty":2,"kind":"mc","stem":"수업 전 확인 문제예요. ⟨3/5⟩ × 4 ○ ⟨3/4⟩ × 5 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["⟨3/5⟩ × 4 = ⟨12/5⟩ = ⟨2 2/5⟩예요.","⟨3/4⟩ × 5 = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","⟨2 2/5⟩ < ⟨3 3/4⟩ — 대분수로 나타내어 견줘요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 8 × ⟨3/4⟩ ○ 8 × ⟨1 1/10⟩ — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["8 × ⟨3/4⟩ = ⟨24/4⟩ = 6이에요.","8 × ⟨1 1/10⟩ = 8 × ⟨11/10⟩ = ⟨88/10⟩ = ⟨44/5⟩ = ⟨8 4/5⟩예요.","8에 1보다 작은 수를 곱하면 8보다 작고, 1보다 큰 수를 곱하면 8보다 커요."]},{"stem":"단원 평가예요. ⟨2 1/3⟩ × 2 ○ 5 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u2-X08"},{"t":"=","mis":"M5-2-u2-X17"}],"explanation":["⟨2 1/3⟩ × 2 = ⟨7/3⟩ × 2 = ⟨14/3⟩ = ⟨4 2/3⟩예요.","⟨4 2/3⟩ < 5예요.","⟨4 2/3⟩는 5보다 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#13','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C6',2,'mc','auto','단원 평가예요. 은정이는 ⟨2/3⟩ × ⟨1/9⟩, 준상이는 ⟨4/9⟩ × ⟨1/2⟩, 주원이는 ⟨5/6⟩ × ⟨4/15⟩를 계산했어요. 계산 결과가 다른 친구는 누구인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X09']::text[],true,'{"seq":13,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"단원 평가예요. 은정이는 ⟨2/3⟩ × ⟨1/9⟩, 준상이는 ⟨4/9⟩ × ⟨1/2⟩, 주원이는 ⟨5/6⟩ × ⟨4/15⟩를 계산했어요. 계산 결과가 다른 친구는 누구인가요?","options":[{"t":"은정","correct":true},{"t":"준상","mis":"M5-2-u2-X17"},{"t":"주원","mis":"M5-2-u2-X17"},{"t":"세 친구 모두 같다","mis":"M5-2-u2-X09"}],"explanation":["은정: ⟨2/3⟩ × ⟨1/9⟩ = ⟨2/27⟩예요.","준상: ⟨4/9⟩ × ⟨1/2⟩ = ⟨2/9⟩, 주원: ⟨5/6⟩ × ⟨4/15⟩ = ⟨2/9⟩예요.","결과가 다른 친구는 은정이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 계산 결과가 ⟨2 5/7⟩ × 2와 다른 것은 어느 것인가요?","options":[{"t":"2 + ⟨5/7⟩ × 2","correct":true},{"t":"⟨2 5/7⟩ + ⟨2 5/7⟩","mis":"M5-2-u2-X05"},{"t":"⟨19/7⟩ × 2","mis":"M5-2-u2-X05"},{"t":"2 × 2 + ⟨5/7⟩ × 2","mis":"M5-2-u2-X05"}],"explanation":["⟨2 5/7⟩ × 2 = ⟨19/7⟩ × 2 = ⟨38/7⟩ = ⟨5 3/7⟩이에요.","⟨2 5/7⟩ + ⟨2 5/7⟩, 2 × 2 + ⟨5/7⟩ × 2도 모두 ⟨5 3/7⟩이에요.","2 + ⟨5/7⟩ × 2는 자연수 부분 2에 2를 곱하지 않아 ⟨3 3/7⟩이에요."]},{"stem":"단원 평가예요. 계산 결과가 다른 것은 어느 것인가요?","options":[{"t":"⟨1 3/4⟩ + ⟨1 3/4⟩ + ⟨1 3/4⟩","correct":true},{"t":"⟨1 3/4⟩ × 2","mis":"M5-2-u2-X15"},{"t":"1 × 2 + ⟨3/4⟩ × 2","mis":"M5-2-u2-X15"},{"t":"⟨7/4⟩ × 2","mis":"M5-2-u2-X15"}],"explanation":["⟨1 3/4⟩ × 2 = ⟨7/4⟩ × 2 = ⟨7/2⟩ = ⟨3 1/2⟩이에요.","1 × 2 + ⟨3/4⟩ × 2 = 2 + ⟨3/2⟩ = ⟨3 1/2⟩도 같아요.","⟨1 3/4⟩을 세 번 더하면 ⟨5 1/4⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#14','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C6',2,'mc','auto','⟨3/8⟩ × ⟨5/9⟩의 계산 결과와 ⟨3/8⟩의 크기를 바르게 견준 것은 어느 것인가요?',ARRAY['M5-2-u2-X08','M5-2-u2-X17']::text[],true,'{"seq":14,"concept":"M5-2-u2-C6","difficulty":2,"kind":"mc","stem":"⟨3/8⟩ × ⟨5/9⟩의 계산 결과와 ⟨3/8⟩의 크기를 바르게 견준 것은 어느 것인가요?","options":[{"t":"⟨3/8⟩ × ⟨5/9⟩ < ⟨3/8⟩","correct":true},{"t":"⟨3/8⟩ × ⟨5/9⟩ > ⟨3/8⟩","mis":"M5-2-u2-X08"},{"t":"⟨3/8⟩ × ⟨5/9⟩ = ⟨3/8⟩","mis":"M5-2-u2-X08"},{"t":"견줄 수 없다","mis":"M5-2-u2-X17"}],"explanation":["⟨3/8⟩ × ⟨5/9⟩ = ⟨5/24⟩예요.","1보다 작은 ⟨5/9⟩를 곱했으니 ⟨3/8⟩보다 작아져요.","⟨5/24⟩ < ⟨3/8⟩이에요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?","options":[{"t":"5 × ⟨1 1/9⟩","correct":true},{"t":"5 × ⟨2/3⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X08"},{"t":"5 × ⟨19/20⟩","mis":"M5-2-u2-X08"}],"explanation":["5에 1보다 작은 수를 곱하면 5보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨1 1/9⟩뿐이에요.","그래서 5보다 큰 것은 5 × ⟨1 1/9⟩이에요."]},{"stem":"단원 평가예요. 계산하지 않고 어림했을 때, 계산 결과가 5보다 큰 것은 어느 것인가요?","options":[{"t":"5 × ⟨2 1/5⟩","correct":true},{"t":"5 × ⟨1/2⟩","mis":"M5-2-u2-X08"},{"t":"5 × 1","mis":"M5-2-u2-X08"},{"t":"5 × ⟨9/10⟩","mis":"M5-2-u2-X08"}],"explanation":["5에 1보다 작은 수를 곱하면 5보다 작아지고, 1을 곱하면 그대로, 1보다 큰 수를 곱하면 커져요.","곱하는 수 가운데 1보다 큰 수는 ⟨2 1/5⟩뿐이에요.","그래서 5보다 큰 것은 5 × ⟨2 1/5⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#15','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C4',2,'mc','auto','수학익힘 문제예요. 수 카드 5, 8, 9 가운데 2장을 골라 진분수를 만들어 6 × (진분수)의 계산 결과가 가장 작게 하려고 해요. 가장 작은 계산 결과는 얼마인가요?',ARRAY['M5-2-u2-X17']::text[],true,'{"seq":15,"concept":"M5-2-u2-C4","difficulty":2,"kind":"mc","stem":"수학익힘 문제예요. 수 카드 5, 8, 9 가운데 2장을 골라 진분수를 만들어 6 × (진분수)의 계산 결과가 가장 작게 하려고 해요. 가장 작은 계산 결과는 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨5 1/3⟩","mis":"M5-2-u2-X17"},{"t":"⟨3 3/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨6 3/4⟩","mis":"M5-2-u2-X17"}],"explanation":["곱하는 진분수가 가장 작아야 해요 — ⟨5/8⟩, ⟨5/9⟩, ⟨8/9⟩ 가운데 ⟨5/9⟩예요.","6 × ⟨5/9⟩ = ⟨30/9⟩ = ⟨10/3⟩이에요.","가장 작은 계산 결과는 ⟨3 1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 계산 결과가 큰 것부터 차례로 기호를 쓴 것은 어느 것인가요? ㉠ ⟨1/5⟩ × ⟨1/7⟩ ㉡ ⟨1/9⟩ × ⟨1/3⟩ ㉢ ⟨1/6⟩ × ⟨1/6⟩ ㉣ ⟨1/11⟩ × ⟨1/2⟩","options":[{"t":"㉣, ㉡, ㉠, ㉢","correct":true},{"t":"㉢, ㉠, ㉡, ㉣","mis":"M5-2-u2-X17"},{"t":"㉠, ㉡, ㉢, ㉣","mis":"M5-2-u2-X17"},{"t":"㉣, ㉢, ㉡, ㉠","mis":"M5-2-u2-X10"}],"explanation":["㉠ ⟨1/35⟩, ㉡ ⟨1/27⟩, ㉢ ⟨1/36⟩, ㉣ ⟨1/22⟩이에요.","단위분수는 분모가 작을수록 커요.","22 < 27 < 35 < 36이라 ㉣, ㉡, ㉠, ㉢ 차례예요."]},{"stem":"단원 평가예요. ⟨1/12⟩, ⟨1/4⟩, ⟨1/9⟩, ⟨1/6⟩ 가운데 가장 큰 수와 가장 작은 수의 곱은 얼마인가요?","options":[{"t":"⟨1/48⟩","correct":true},{"t":"⟨1/24⟩","mis":"M5-2-u2-X17"},{"t":"⟨1/16⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/108⟩","mis":"M5-2-u2-X17"}],"explanation":["가장 큰 수는 ⟨1/4⟩, 가장 작은 수는 ⟨1/12⟩이에요.","⟨1/4⟩ × ⟨1/12⟩ = ⟨1/48⟩이에요.","단위분수는 분모가 작을수록 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#16','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C7',2,'mc','auto','재영이는 공원을 ⟨1 3/4⟩ km 걸었고, 하은이는 재영이가 걸은 거리의 ⟨1 3/7⟩배만큼 걸었어요. 하은이가 걸은 거리는 몇 km인가요?',ARRAY['M5-2-u2-X11','M5-2-u2-X04']::text[],true,'{"seq":16,"concept":"M5-2-u2-C7","difficulty":2,"kind":"mc","stem":"재영이는 공원을 ⟨1 3/4⟩ km 걸었고, 하은이는 재영이가 걸은 거리의 ⟨1 3/7⟩배만큼 걸었어요. 하은이가 걸은 거리는 몇 km인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨1 9/28⟩","mis":"M5-2-u2-X11"},{"t":"⟨1 3/7⟩","mis":"M5-2-u2-X04"},{"t":"1","mis":"M5-2-u2-X04"}],"explanation":["⟨1 3/4⟩의 ⟨1 3/7⟩배이니 ⟨1 3/4⟩ × ⟨1 3/7⟩이에요.","⟨1 3/4⟩ × ⟨1 3/7⟩ = ⟨7/4⟩ × ⟨10/7⟩ = ⟨70/28⟩ = ⟨5/2⟩ = ⟨2 1/2⟩이에요.","하은이가 걸은 거리는 ⟨2 1/2⟩ km예요."],"variant_rule":{"alt":[{"stem":"사과 따기 체험에서 만든 사과주스를 ⟨1 1/4⟩ L짜리 병에 가득 담았더니 3병이 나왔어요. 만든 사과주스는 모두 몇 L인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨3 1/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 3/4⟩","mis":"M5-2-u2-X05"},{"t":"⟨1 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["⟨1 1/4⟩ L씩 3병이니 ⟨1 1/4⟩ × 3이에요.","⟨1 1/4⟩ × 3 = ⟨5/4⟩ × 3 = ⟨15/4⟩ = ⟨3 3/4⟩이에요.","모두 ⟨3 3/4⟩ L예요."]},{"stem":"들이가 4 L인 항아리에 간장이 ⟨5/12⟩만큼 들어 있어요. 항아리에 든 간장은 몇 L인가요?","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨1/3⟩","mis":"M5-2-u2-X07"},{"t":"⟨5/12⟩","mis":"M5-2-u2-X17"},{"t":"⟨20/48⟩","mis":"M5-2-u2-X01"}],"explanation":["4 L의 ⟨5/12⟩만큼이니 4 × ⟨5/12⟩예요.","4 × ⟨5/12⟩ = ⟨20/12⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요.","항아리에는 간장 ⟨1 2/3⟩ L가 들어 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#17','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C5',3,'mc','auto','단원 평가예요. 가로가 ⟨19 1/3⟩ cm, 세로가 12 cm인 직사각형의 넓이는 몇 cm²인가요?',ARRAY['M5-2-u2-X20','M5-2-u2-X05']::text[],true,'{"seq":17,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"단원 평가예요. 가로가 ⟨19 1/3⟩ cm, 세로가 12 cm인 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"232","correct":true},{"t":"⟨62 2/3⟩","mis":"M5-2-u2-X20"},{"t":"⟨228 1/3⟩","mis":"M5-2-u2-X05"},{"t":"23","mis":"M5-2-u2-X05"}],"explanation":["직사각형의 넓이는 (가로) × (세로)예요.","⟨19 1/3⟩ × 12 = ⟨58/3⟩ × 12 = ⟨696/3⟩ = 232예요.","넓이는 232 cm²예요 — 둘레와 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"문제로 마무리예요. 한 변의 길이가 ⟨9 1/2⟩ m인 정사각형 모양의 수영장의 둘레는 몇 m인가요?","options":[{"t":"38","correct":true},{"t":"⟨90 1/4⟩","mis":"M5-2-u2-X20"},{"t":"19","mis":"M5-2-u2-X20"},{"t":"⟨36 1/2⟩","mis":"M5-2-u2-X05"}],"explanation":["정사각형은 네 변의 길이가 모두 같아요 — (둘레) = (한 변의 길이) × 4.","⟨9 1/2⟩ × 4 = ⟨19/2⟩ × 4 = ⟨76/2⟩ = 38이에요.","둘레는 38 m예요."]},{"stem":"문제로 마무리예요. 한 변의 길이가 ⟨9 1/2⟩ m인 정사각형 모양의 수영장이 있어요. 수영장의 넓이는 몇 m²인가요?","options":[{"t":"⟨90 1/4⟩","correct":true},{"t":"38","mis":"M5-2-u2-X20"},{"t":"⟨81 1/4⟩","mis":"M5-2-u2-X11"},{"t":"⟨47 1/2⟩","mis":"M5-2-u2-X04"}],"explanation":["정사각형의 넓이는 (한 변의 길이) × (한 변의 길이)예요.","⟨9 1/2⟩ × ⟨9 1/2⟩ = ⟨19/2⟩ × ⟨19/2⟩ = ⟨361/4⟩ = ⟨90 1/4⟩이에요.","넓이는 ⟨90 1/4⟩ m²예요 — 둘레 38 m와 다른 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#18','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C3',3,'sa','auto','수업 전 확인 문제예요. ⟨1 3/4⟩ × 6 < □일 때 □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M5-2-u2-C3","difficulty":3,"kind":"sa","stem":"수업 전 확인 문제예요. ⟨1 3/4⟩ × 6 < □일 때 □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["먼저 곱을 구해요 — ⟨1 3/4⟩ × 6 = ⟨7/4⟩ × 6 = ⟨42/4⟩ = ⟨21/2⟩ = ⟨10 1/2⟩.","곱은 ⟨10 1/2⟩이에요.","⟨10 1/2⟩보다 큰 자연수 가운데 가장 작은 수는 11이에요."],"mis":"M5-2-u2-X17","variant_rule":{"alt":[{"stem":"단원 평가예요. 2 × ⟨3 1/2⟩ > □⟨4/5⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["2 × ⟨3 1/2⟩ = 2 × ⟨7/2⟩ = 7이에요.","□가 6이면 ⟨6 4/5⟩ < 7이에요.","□에는 1부터 6까지 — 모두 6개예요."]},{"stem":"단원 평가예요. ⟨1 3/5⟩ × ⟨4 1/6⟩ > □⟨1/3⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["⟨1 3/5⟩ × ⟨4 1/6⟩ = ⟨8/5⟩ × ⟨25/6⟩ = ⟨20/3⟩ = ⟨6 2/3⟩예요.","□가 6이면 ⟨6 1/3⟩ < ⟨6 2/3⟩예요.","□에는 1부터 6까지 — 모두 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#19','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C5',3,'mc','auto','「분수의 곱셈 카드 놀이」예요. 자연수 종이 2, 4, 9, 진분수 종이 ⟨1/3⟩, ⟨7/12⟩, ⟨5/6⟩, 대분수 종이 ⟨1 3/4⟩, ⟨3 1/2⟩, ⟨2 2/3⟩ 가운데 자연수 종이와 분수 종이를 1장씩 골라 (자연수)×(분수)를 만들어요. 계산 결과가 가장 작은 식은 어느 것인가요?',ARRAY['M5-2-u2-X17']::text[],true,'{"seq":19,"concept":"M5-2-u2-C5","difficulty":3,"kind":"mc","stem":"「분수의 곱셈 카드 놀이」예요. 자연수 종이 2, 4, 9, 진분수 종이 ⟨1/3⟩, ⟨7/12⟩, ⟨5/6⟩, 대분수 종이 ⟨1 3/4⟩, ⟨3 1/2⟩, ⟨2 2/3⟩ 가운데 자연수 종이와 분수 종이를 1장씩 골라 (자연수)×(분수)를 만들어요. 계산 결과가 가장 작은 식은 어느 것인가요?","options":[{"t":"2 × ⟨1/3⟩","correct":true},{"t":"2 × ⟨7/12⟩","mis":"M5-2-u2-X17"},{"t":"9 × ⟨1/3⟩","mis":"M5-2-u2-X17"},{"t":"2 × ⟨1 3/4⟩","mis":"M5-2-u2-X17"}],"explanation":["계산 결과를 작게 하려면 자연수도 분수도 가장 작은 수를 골라요.","가장 작은 자연수는 2, 가장 작은 분수는 ⟨1/3⟩이에요.","2 × ⟨1/3⟩ = ⟨2/3⟩예요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 수 카드 8, 3, 9를 한 번씩만 이용하여 만들 수 있는 가장 큰 대분수와 4의 곱은 얼마인가요?","options":[{"t":"⟨37 1/2⟩","correct":true},{"t":"⟨33 1/3⟩","mis":"M5-2-u2-X17"},{"t":"⟨15 5/9⟩","mis":"M5-2-u2-X17"},{"t":"⟨13 3/8⟩","mis":"M5-2-u2-X15"}],"explanation":["가장 큰 대분수는 자연수 부분에 가장 큰 수 9를 놓고 남은 두 수로 진분수 ⟨3/8⟩을 만든 ⟨9 3/8⟩이에요.","⟨9 3/8⟩ × 4 = ⟨75/8⟩ × 4 = ⟨300/8⟩ = ⟨75/2⟩ = ⟨37 1/2⟩이에요.","곱은 ⟨37 1/2⟩이에요."]},{"stem":"단원 평가예요. 수 카드 3, 4, 9를 한 번씩만 이용하여 대분수를 만들었어요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 곱은 얼마인가요?","options":[{"t":"⟨33 7/12⟩","correct":true},{"t":"⟨27 1/3⟩","mis":"M5-2-u2-X11"},{"t":"⟨42 1/4⟩","mis":"M5-2-u2-X17"},{"t":"⟨13 7/36⟩","mis":"M5-2-u2-X15"}],"explanation":["가장 큰 대분수는 ⟨9 3/4⟩, 가장 작은 대분수는 ⟨3 4/9⟩예요.","⟨9 3/4⟩ × ⟨3 4/9⟩ = ⟨39/4⟩ × ⟨31/9⟩ = ⟨1209/36⟩ = ⟨403/12⟩ = ⟨33 7/12⟩이에요.","곱은 ⟨33 7/12⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#20','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C7',3,'mc','auto','단원 평가예요. 선아네 학교 도서관에 있는 책 300권 중에서 ⟨1/3⟩은 과학책이에요. 선아는 과학책 중에서 ⟨3/5⟩을 읽었다면 선아가 읽은 과학책은 몇 권인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X18']::text[],true,'{"seq":20,"concept":"M5-2-u2-C7","difficulty":3,"kind":"mc","stem":"단원 평가예요. 선아네 학교 도서관에 있는 책 300권 중에서 ⟨1/3⟩은 과학책이에요. 선아는 과학책 중에서 ⟨3/5⟩을 읽었다면 선아가 읽은 과학책은 몇 권인가요?","options":[{"t":"60","correct":true},{"t":"100","mis":"M5-2-u2-X17"},{"t":"180","mis":"M5-2-u2-X18"},{"t":"40","mis":"M5-2-u2-X17"}],"explanation":["과학책은 300 × ⟨1/3⟩ = 100(권)이에요.","선아가 읽은 과학책은 100 × ⟨3/5⟩ = 60(권)이에요.","300 × ⟨3/5⟩ = 180은 전체 책의 ⟨3/5⟩이에요 — 「과학책 중에서」를 놓치지 않아요."],"variant_rule":{"alt":[{"stem":"단원 평가예요. 은서는 집에서 ⟨14/15⟩ km 떨어진 서점에 가는데 전체 거리의 ⟨5/6⟩는 버스를 타고 나머지는 걸어서 갔어요. 은서가 걸어서 간 거리는 몇 km인가요?","options":[{"t":"⟨7/45⟩","correct":true},{"t":"⟨7/9⟩","mis":"M5-2-u2-X19"},{"t":"⟨1/10⟩","mis":"M5-2-u2-X15"},{"t":"⟨1/6⟩","mis":"M5-2-u2-X18"}],"explanation":["걸어서 간 거리는 전체 거리의 나머지 1 − ⟨5/6⟩ = ⟨1/6⟩이에요.","⟨14/15⟩ × ⟨1/6⟩ = ⟨14/90⟩ = ⟨7/45⟩이에요.","⟨5/6⟩를 곱하면 버스로 간 거리 ⟨7/9⟩ km예요 — 묻는 것은 걸어서 간 거리예요."]},{"stem":"단원 평가예요. 태희는 색종이 50장 중에서 어제 ⟨1/5⟩을 사용했고, 오늘은 남은 색종이의 ⟨5/8⟩를 사용했어요. 태희가 어제와 오늘 사용한 색종이는 모두 몇 장인가요?","options":[{"t":"35","correct":true},{"t":"25","mis":"M5-2-u2-X17"},{"t":"15","mis":"M5-2-u2-X12"},{"t":"40","mis":"M5-2-u2-X17"}],"explanation":["어제: 50 × ⟨1/5⟩ = 10(장), 남은 색종이: 50 − 10 = 40(장)이에요.","오늘: 40 × ⟨5/8⟩ = 25(장)이에요.","모두 10 + 25 = 35(장)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#21','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C7',3,'mc','auto','수학익힘 문제예요. 혜지네 학교 5학년 전체 학생 160명 가운데 ⟨5/8⟩는 남학생이고, 그중 ⟨3/5⟩은 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X18']::text[],true,'{"seq":21,"concept":"M5-2-u2-C7","difficulty":3,"kind":"mc","stem":"수학익힘 문제예요. 혜지네 학교 5학년 전체 학생 160명 가운데 ⟨5/8⟩는 남학생이고, 그중 ⟨3/5⟩은 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요?","options":[{"t":"60","correct":true},{"t":"100","mis":"M5-2-u2-X17"},{"t":"96","mis":"M5-2-u2-X18"},{"t":"40","mis":"M5-2-u2-X17"}],"explanation":["남학생은 160 × ⟨5/8⟩ = 100(명)이에요.","그중 ⟨3/5⟩이니 100 × ⟨3/5⟩ = 60(명)이에요.","160 × ⟨5/8⟩ × ⟨3/5⟩ = 60 — 세 수를 한 번에 곱해도 같아요."],"variant_rule":{"alt":[{"stem":"수학익힘 문제예요. 1분에 ⟨4 2/3⟩ L씩 물이 일정하게 나오는 수도꼭지를 5분 30초 동안 틀어 놓았어요. 받을 수 있는 물은 몇 L인가요?","options":[{"t":"⟨25 2/3⟩","correct":true},{"t":"⟨24 11/15⟩","mis":"M5-2-u2-X21"},{"t":"⟨23 1/3⟩","mis":"M5-2-u2-X17"},{"t":"140","mis":"M5-2-u2-X21"}],"explanation":["1분은 60초이니 30초는 ⟨30/60⟩분 = ⟨1/2⟩분, 5분 30초는 ⟨5 1/2⟩분이에요.","⟨4 2/3⟩ × ⟨5 1/2⟩ = ⟨14/3⟩ × ⟨11/2⟩ = ⟨77/3⟩ = ⟨25 2/3⟩예요.","받을 수 있는 물은 ⟨25 2/3⟩ L예요 — 30초를 ⟨3/10⟩분으로 보지 않도록 해요."]},{"stem":"단원 평가예요. 일정한 빠르기로 한 시간에 80 km를 달리는 고속버스가 같은 빠르기로 3시간 30분 동안 쉬지 않고 달리면 몇 km를 달리나요?","options":[{"t":"280","correct":true},{"t":"264","mis":"M5-2-u2-X21"},{"t":"240","mis":"M5-2-u2-X17"},{"t":"2400","mis":"M5-2-u2-X21"}],"explanation":["1시간은 60분이니 30분은 ⟨1/2⟩시간, 3시간 30분은 ⟨3 1/2⟩시간이에요.","80 × ⟨3 1/2⟩ = 80 × ⟨7/2⟩ = 280이에요.","30분을 ⟨3/10⟩시간으로 보면 264 km가 되어 틀려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#22','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C8',3,'sa','auto','준기네 마을 전체 주민은 430명이에요. 전체 주민의 ⟨3/5⟩ 이상이 동의해야 수영장을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M5-2-u2-C8","difficulty":3,"kind":"sa","stem":"준기네 마을 전체 주민은 430명이에요. 전체 주민의 ⟨3/5⟩ 이상이 동의해야 수영장을 만들 수 있어요. 적어도 몇 명이 동의해야 하나요? 숫자로 쓰세요.","answer":["258"],"explanation":["전체 430명의 ⟨3/5⟩ 이상이에요.","430 × ⟨3/5⟩ = 258(명)이에요.","적어도 258명이 동의해야 해요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"서연이네 마을 전체 주민은 270명이고, 전체 주민의 ⟨2/3⟩ 이상이 동의해야 공공 도서관을 만들 수 있어요. 지금까지 158명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["22"],"explanation":["① 최소로 동의해야 하는 수: 270 × ⟨2/3⟩ = 180(명)이에요.","② 지금까지 158명이 동의했으니 180 − 158 = 22(명)이에요.","적어도 22명이 더 동의해야 해요."]},{"stem":"준기네 마을 전체 주민은 430명이고, 전체 주민의 ⟨3/5⟩ 이상이 동의해야 수영장을 만들 수 있어요. 지금까지 195명이 동의했다면 적어도 몇 명이 더 동의해야 하나요? 숫자로 쓰세요.","answer":["63"],"explanation":["① 최소로 동의해야 하는 수: 430 × ⟨3/5⟩ = 258(명)이에요.","② 지금까지 195명이 동의했으니 258 − 195 = 63(명)이에요.","적어도 63명이 더 동의해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#23','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C4',4,'sa','auto','72 × ⟨□/9⟩ = 40일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M5-2-u2-C4","difficulty":4,"kind":"sa","stem":"72 × ⟨□/9⟩ = 40일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["5"],"explanation":["72를 똑같이 9로 나누면 한 묶음은 8이에요.","5묶음이 40이니 □ = 40 ÷ 8 = 5예요.","72 × ⟨5/9⟩ = 40 — 맞아요."],"mis":"M5-2-u2-X07","variant_rule":{"alt":[{"stem":"⟨1/□⟩ × ⟨1/3⟩ = ⟨1/12⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["단위분수끼리 곱하면 분모끼리 곱해요.","□ × 3 = 12이어야 해요.","12 ÷ 3 = 4니 □는 4예요."]},{"stem":"16 × ⟨□/4⟩ = 12일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["3"],"explanation":["16을 똑같이 4로 나누면 한 묶음은 4예요.","3묶음이 12니 □ = 12 ÷ 4 = 3이에요.","16 × ⟨3/4⟩ = 12 — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#24','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C5',4,'essay','teacher','단원 평가예요. 일정한 빠르기로 한 시간에 80 km를 달리는 고속버스가 같은 빠르기로 3시간 30분 동안 쉬지 않고 달린다면 달리는 거리는 몇 km인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u2-C5","difficulty":4,"kind":"essay","stem":"단원 평가예요. 일정한 빠르기로 한 시간에 80 km를 달리는 고속버스가 같은 빠르기로 3시간 30분 동안 쉬지 않고 달린다면 달리는 거리는 몇 km인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 1시간은 60분이므로 30분은 ⟨30/60⟩ = ⟨1/2⟩시간이고, 3시간 30분은 ⟨3 1/2⟩시간이다. 한 시간에 80 km를 달리므로 달리는 거리는 80 × ⟨3 1/2⟩ = 80 × ⟨7/2⟩ = 280(km)이다.","scoring_points":["3시간 30분을 ⟨3 1/2⟩시간으로 나타냈는가","80 × ⟨3 1/2⟩로 식을 세웠는가","280 km를 구했는가"]},"explanation":["3시간 30분 = ⟨3 1/2⟩시간이에요.","80 × ⟨7/2⟩ = 280이에요.","달리는 거리는 280 km예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u2_review_d#25','math',5,2,'u2','','tb_g5_2_math_u2_review_d','unit_review','M5-2-u2-C7',4,'essay','teacher','준우, 지연, 시하가 2 × ⟨5/9⟩ × ⟨3/4⟩을 계산했어요. 준우는 앞의 두 수를 먼저, 지연이는 뒤의 두 수를 먼저 계산했고, 시하는 먼저 약분한 다음 한 번에 곱했어요. 세 친구의 방법을 식으로 쓰고, 결과를 견주어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u2-C7","difficulty":4,"kind":"essay","stem":"준우, 지연, 시하가 2 × ⟨5/9⟩ × ⟨3/4⟩을 계산했어요. 준우는 앞의 두 수를 먼저, 지연이는 뒤의 두 수를 먼저 계산했고, 시하는 먼저 약분한 다음 한 번에 곱했어요. 세 친구의 방법을 식으로 쓰고, 결과를 견주어 설명해 보세요.","answer_guide":{"answer":"예: 2를 분모가 1인 분수 ⟨2/1⟩로 나타낸다. 준우: 2 × ⟨5/9⟩ = ⟨10/9⟩, ⟨10/9⟩ × ⟨3/4⟩ = ⟨30/36⟩ = ⟨5/6⟩. 지연: ⟨5/9⟩ × ⟨3/4⟩ = ⟨15/36⟩ = ⟨5/12⟩, 2 × ⟨5/12⟩ = ⟨10/12⟩ = ⟨5/6⟩. 시하: 2와 4, 9와 3을 먼저 약분하면 ⟨1/1⟩ × ⟨5/3⟩ × ⟨1/2⟩ = ⟨5/6⟩. 세 결과가 모두 ⟨5/6⟩로 같으므로 곱하는 순서나 약분하는 때와 상관없이 결과는 같다.","scoring_points":["자연수 2를 ⟨2/1⟩로 볼 수 있음을 썼는가","세 친구의 계산을 식으로 바르게 썼는가","세 결과가 ⟨5/6⟩로 같다고 설명했는가"]},"explanation":["2 = ⟨2/1⟩예요.","앞에서부터, 뒤에서부터, 먼저 약분해도 모두 ⟨5/6⟩예요.","곱하는 순서가 달라도 결과는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
